  public :: refresh_parallel_block_trend_boundary_state
  public :: refresh_parallel_block_candidate_boundary_state
  public :: validate_candidate_block_scalar_wavelets
  public :: validate_candidate_block_outer_vector_wavelets
  public :: validate_candidate_block_velocity_restriction
  public :: prepare_block_native_wavelet_compression
  public :: activate_block_native_wavelet_compression
  public :: activate_block_native_inverse_transform
  public :: refresh_parallel_block_domain_prognostic_state
  public :: advance_block_domain_trend_euler
  public :: capture_block_domain_multistage_candidate_tendency
  public :: begin_block_scalar_divergence_capture
  public :: capture_block_scalar_divergence_level
  public :: finalize_block_scalar_divergence_capture
  public :: prepare_block_velocity_compatibility_remainder
  public :: begin_block_velocity_source_transport
  public :: capture_block_velocity_source_level
  public :: finalize_block_velocity_source_transport
  public :: begin_block_domain_multistage_candidate_stage
  public :: retain_block_native_multistage_candidate
  public :: prepare_block_native_multistage_wavelet_stage
  public :: prepare_block_native_multistage_wavelet_acceptance

contains


  subroutine clear_parallel_block_state
    ! Release persistent and staging block data before a checkpoint
    ! restart invalidates the geometric-domain state from which those
    ! blocks were constructed. Safe to call when nothing is allocated.

    implicit none

    call clear_block_adaptation_decisions
    call clear_block_velocity_source_transport
    call clear_block_vertical_remap_storage
    call clear_block_ghost_exchange_plan
    call clear_block_writeback_plan
    call clear_local_blocks
    call clear_block_staging
    production_block_inverse_active = .false.
    production_grid_change_pending = .false.

    if (allocated(block_catalog)) deallocate(block_catalog)

    if (local_block_store_ready()) then
       call fail("local block store remained ready after reset")
    end if

    if (allocated(block_catalog)) then
       call fail("block catalogue remained allocated after reset")
    end if
    if (ghost_exchange_plan%ready) then
       call fail("ghost exchange plan remained ready after reset")
    end if
    if (block_writeback_plan%ready) then
       call fail("writeback plan remained ready after reset")
    end if

  end subroutine clear_parallel_block_state


  subroutine clear_block_adaptation_decisions

    implicit none

    integer :: local_index

    if (allocated(block_adaptation_decision)) then
       do local_index = 1,size(block_adaptation_decision)
          if (allocated(block_adaptation_decision(local_index)%value)) &
               deallocate(block_adaptation_decision(local_index)%value)
       end do
       deallocate(block_adaptation_decision)
    end if
    if (allocated(block_adaptation_exchange%send_count)) &
         deallocate(block_adaptation_exchange%send_count)
    if (allocated(block_adaptation_exchange%send_displ)) &
         deallocate(block_adaptation_exchange%send_displ)
    if (allocated(block_adaptation_exchange%recv_count)) &
         deallocate(block_adaptation_exchange%recv_count)
    if (allocated(block_adaptation_exchange%recv_displ)) &
         deallocate(block_adaptation_exchange%recv_displ)
    if (allocated(block_adaptation_exchange%send_buffer)) &
         deallocate(block_adaptation_exchange%send_buffer)
    if (allocated(block_adaptation_exchange%recv_buffer)) &
         deallocate(block_adaptation_exchange%recv_buffer)
    if (allocated(block_adaptation_exchange%domain_stage)) &
         deallocate(block_adaptation_exchange%domain_stage)
    if (allocated(block_adaptation_exchange%domain_patch_covered)) &
         deallocate(block_adaptation_exchange%domain_patch_covered)
    block_adaptation_exchange%plan_generation = -1_int64
    block_adaptation_exchange%allocation_count = 0_int64
    block_adaptation_exchange%ready = .false.

  end subroutine clear_block_adaptation_decisions


  subroutine clear_block_vertical_remap_storage

    implicit none

    integer :: local_index

    if (allocated(block_vertical_remap)) then
       do local_index = 1,size(block_vertical_remap)
          if (allocated(block_vertical_remap(local_index)%old_mass)) &
               deallocate(block_vertical_remap(local_index)%old_mass)
          if (allocated(block_vertical_remap(local_index)%active)) &
               deallocate(block_vertical_remap(local_index)%active)
          if (allocated(block_vertical_remap(local_index)%source_start)) &
               deallocate(block_vertical_remap(local_index)%source_start)
       end do
       deallocate(block_vertical_remap)
    end if
    call clear_block_vertical_remap_exchange
    nullify(production_vertical_interpolator)
    block_vertical_remap_active = .false.

  end subroutine clear_block_vertical_remap_storage


  subroutine clear_block_vertical_remap_exchange
    ! Invalidate only the writeback-plan-dependent metadata route.  The
    ! old-mass workspace has a separate topology lifetime and remains valid.

    implicit none

    if (allocated(block_vertical_remap_exchange%send_count)) &
         deallocate(block_vertical_remap_exchange%send_count)
    if (allocated(block_vertical_remap_exchange%send_displ)) &
         deallocate(block_vertical_remap_exchange%send_displ)
    if (allocated(block_vertical_remap_exchange%recv_count)) &
         deallocate(block_vertical_remap_exchange%recv_count)
    if (allocated(block_vertical_remap_exchange%recv_displ)) &
         deallocate(block_vertical_remap_exchange%recv_displ)
    if (allocated(block_vertical_remap_exchange%send_buffer)) &
         deallocate(block_vertical_remap_exchange%send_buffer)
    if (allocated(block_vertical_remap_exchange%recv_buffer)) &
         deallocate(block_vertical_remap_exchange%recv_buffer)
    block_vertical_remap_exchange%plan_generation = -1_int64
    block_vertical_remap_exchange%ready = .false.

  end subroutine clear_block_vertical_remap_exchange


  logical function parallel_block_state_is_ready () result(ready)
    ! Report whether the installed store and both persistent communication
    ! plans form a complete state for stepping or lifecycle synchronization.

    implicit none

    logical :: local_store_ready
    logical :: writeback_ready

    local_store_ready = local_block_store_ready()
    writeback_ready = block_writeback_plan_is_ready()
    ready = allocated(block_catalog) .and. local_store_ready .and. &
         ghost_exchange_plan%ready .and. writeback_ready .and. &
         .not. production_grid_change_pending

  end function parallel_block_state_is_ready


  logical function parallel_block_grid_change_is_pending () result(pending)
    ! Expose the module-owned grid-change transaction state so the timestep
    ! driver does not rely on a local flag retained across physics calls.

    implicit none

    pending = production_grid_change_pending

  end function parallel_block_grid_change_is_pending


  subroutine complete_block_adaptation_lifecycle
    ! Close the accepted block timestep only after the authoritative
    ! compression, inverse reconstruction and adaptation have completed.
    ! This state transition remains the production sequencing guard.

    implicit none

    if (.not. production_adaptation_pending) then
       call fail("block adaptation lifecycle was not pending")
    end if
    if (production_block_wavelet_compression_ready) then
       call fail("block compression remained pending at adaptation")
    end if
    if (production_block_inverse_active) then
       call fail("block inverse remained active at adaptation")
    end if
    if (production_grid_change_pending) then
       call fail("block grid-change preview remained pending")
    end if
    production_adaptation_pending = .false.

  end subroutine complete_block_adaptation_lifecycle


  subroutine invalidate_parallel_block_domain_shadow
    ! The current production time integrator updates authoritative Domain
    ! fields directly. Discard any installed block copy before that update;
    ! otherwise a later block writeback could restore stale field values.
    ! This transition is intentionally idempotent.

    implicit none

    logical :: block_state_present
    logical :: local_store_ready

    local_store_ready = local_block_store_ready()
    block_state_present = allocated(block_catalog)
    if (local_store_ready) block_state_present = .true.
    if (ghost_exchange_plan%ready) block_state_present = .true.
    if (block_writeback_plan%ready) block_state_present = .true.
    if (.not. block_state_present) return

    call clear_parallel_block_state

  end subroutine invalidate_parallel_block_domain_shadow


  subroutine synchronize_parallel_block_solution_consumer
    ! Materialize only authoritative sol values for read-only Domain
    ! diagnostics and output.  Checkpoint serialization separately requests
    ! both sol and wav_coeff.

    implicit none

    integer(int64) :: allocation_before

    logical :: checkpoint_ready
    logical :: state_ready
    logical :: trial_active

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (trial_active) then
       call fail("solution-consumer synchronization during active trial")
    end if
    if (checkpoint_ready) then
       call fail("solution-consumer synchronization before step completion")
    end if

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("solution-consumer synchronization before block readiness")
    end if

    allocation_before = block_writeback_plan_allocation_count()
    call write_block_field_family_to_domains(BLOCK_PAYLOAD_SOL)
    compatibility_writeback_output = &
         compatibility_writeback_output + 1_int64
    if (block_writeback_plan_allocation_count() /= allocation_before) &
         call fail("solution-consumer synchronization reallocated buffers")

  end subroutine synchronize_parallel_block_solution_consumer


  subroutine synchronize_parallel_block_checkpoint (grid_change)
    ! In a block-authoritative integration, materialize both prognostic field
    ! families in Domain storage while retaining every persistent object.

    implicit none

    logical, optional, intent(in) :: grid_change

    logical :: checkpoint_ready
    logical :: grid_change_writeback
    logical :: state_ready
    logical :: trial_active

    grid_change_writeback = .false.
    if (present(grid_change)) grid_change_writeback = grid_change

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (trial_active) then
       call fail("checkpoint synchronization during active block trial")
    end if
    if (checkpoint_ready) then
       call fail("checkpoint synchronization before step completion")
    end if

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("checkpoint synchronization before block state is ready")
    end if

    call write_block_field_family_to_domains(BLOCK_PAYLOAD_SOL)
    call write_block_field_family_to_domains(BLOCK_PAYLOAD_WAV_COEFF)
    if (grid_change_writeback) then
       compatibility_writeback_grid_change = &
            compatibility_writeback_grid_change + 2_int64
    else
       compatibility_writeback_checkpoint = &
            compatibility_writeback_checkpoint + 2_int64
    end if

  end subroutine synchronize_parallel_block_checkpoint


  subroutine prepare_parallel_block_grid_change
    ! In a block-authoritative integration, synchronize the current fields,
    ! then retain the read-only compact wavelet image until the current
    ! adaptation thresholds have been applied. Production writes each field
    ! family exactly once; full block/Domain comparisons are an opt-in oracle.

    implicit none

    logical :: local_store_ready
    logical :: state_ready
    logical :: validate_oracle

    integer(int64) :: writeback_before

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("grid-change preparation before block state is ready")
    end if
    if (production_grid_change_pending) then
       call fail("grid-change preparation is already pending")
    end if

    validate_oracle = block_adaptation_validation_enabled()
    if (validate_oracle) then
       call block_profile_enter(BLOCK_PROFILE_ORACLE)
       call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)
       call assert_block_domain_field_family_match( &
            BLOCK_PAYLOAD_WAV_COEFF)
       call block_profile_leave(BLOCK_PROFILE_ORACLE)
    end if
    writeback_before = block_domain_production_writeback_count()
    call synchronize_parallel_block_checkpoint(.true.)
    if (block_domain_production_writeback_count() /= &
         writeback_before+2_int64) &
         call fail("grid-change compatibility writeback count is invalid")
    if (validate_oracle) then
       call block_profile_enter(BLOCK_PROFILE_ORACLE)
       call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)
       call assert_block_domain_field_family_match( &
            BLOCK_PAYLOAD_WAV_COEFF)
       call block_profile_leave(BLOCK_PROFILE_ORACLE)
    end if
    production_grid_change_pending = .true.

    state_ready = parallel_block_state_is_ready()
    local_store_ready = local_block_store_ready()
    if (state_ready .or. .not. local_store_ready) then
       call fail("grid-change preparation state transition is invalid")
    end if

  end subroutine prepare_parallel_block_grid_change


  subroutine refresh_pending_parallel_block_adaptation_wavelets
    ! A split Domain physics step may recompute atmospheric wav_coeff after
    ! the block grid-change transaction has been opened. Refresh only that
    ! adaptation input in the retained compact interiors. The topology and
    ! persistent communication plans are unchanged, and no Domain field is
    ! written by this reverse transport.

    implicit none

    integer(int64) :: stage_allocation_before
    integer(int64) :: writeback_allocation_before
    integer(int64) :: writeback_before

    logical :: local_store_ready
    logical :: validate_oracle
    logical :: writeback_ready

    local_store_ready = local_block_store_ready()
    writeback_ready = block_writeback_plan_is_ready()
    if (.not. production_grid_change_pending .or. &
         .not. local_store_ready .or. .not. writeback_ready) then
       call fail("post-physics adaptation refresh is not ready")
    end if
    if (parallel_block_state_is_ready()) then
       call fail("post-physics adaptation refresh has no pending state")
    end if

    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    stage_allocation_before = block_writeback_plan%stage_allocations
    writeback_before = block_domain_production_writeback_count()

    call import_domain_field_family_to_blocks(BLOCK_PAYLOAD_WAV_COEFF)

    validate_oracle = block_adaptation_validation_enabled()
    if (validate_oracle) then
       call block_profile_enter(BLOCK_PROFILE_ORACLE)
       call assert_block_domain_field_family_match( &
            BLOCK_PAYLOAD_WAV_COEFF)
       call block_profile_leave(BLOCK_PROFILE_ORACLE)
    end if

    if (.not. production_grid_change_pending) then
       call fail("post-physics adaptation refresh changed lifecycle")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before .or. &
         block_writeback_plan%stage_allocations /= &
         stage_allocation_before) then
       call fail("post-physics adaptation refresh reallocated storage")
    end if
    if (block_domain_production_writeback_count() /= writeback_before) then
       call fail("post-physics adaptation refresh modified Domain fields")
    end if

  end subroutine refresh_pending_parallel_block_adaptation_wavelets


  logical function block_adaptation_validation_enabled () result(enabled)
    ! The independent Domain significance calculation is an opt-in oracle.
    ! Production installs transported compact decisions without rereading
    ! Domain wavelet interiors.

    implicit none

    character(len=32) :: value
    integer :: enabled_count
    integer :: ierr
    integer :: length
    integer :: local_enabled
    integer :: status

    if (.not. block_adaptation_validation_initialized) then
       value = ""
       call get_environment_variable( &
            "WAVETRISK_VALIDATE_BLOCK_ADAPTATION",value,length,status)
       if (status == 0 .and. length > 0) then
          select case (trim(value(1:min(length,len(value)))))
          case ("1","true","TRUE","on","ON","yes","YES")
             block_adaptation_validation = .true.
          case ("0","false","FALSE","off","OFF","no","NO")
             block_adaptation_validation = .false.
          case default
             call fail("invalid block-adaptation validation option")
          end select
       else if (status /= 0 .and. status /= 1) then
          call fail("unable to read block-adaptation validation option")
       end if
       local_enabled = merge(1,0,block_adaptation_validation)
       call MPI_Allreduce(local_enabled,enabled_count,1,MPI_INTEGER, &
            MPI_SUM,comm,ierr)
       call check_mpi(ierr, &
            "MPI_Allreduce block-adaptation validation option")
       if (enabled_count /= 0 .and. enabled_count /= n_process) &
            call fail("inconsistent block-adaptation validation option")
       block_adaptation_validation_initialized = .true.
       if (block_adaptation_validation .and. rank == 0) write(6,'(a)') &
            "Block adaptation validation oracle enabled"
    end if
    enabled = block_adaptation_validation

  end function block_adaptation_validation_enabled


  logical function block_dynamics_validation_enabled () result(enabled)
    ! Expensive exact dynamics comparisons, repeated-refresh proofs and
    ! global coverage reductions are an opt-in oracle.  Production retains
    ! all numerical kernels, state transitions and allocation guards.

    implicit none

    character(len=32) :: value
    integer :: enabled_count
    integer :: ierr
    integer :: length
    integer :: local_enabled
    integer :: status

    if (.not. block_dynamics_validation_initialized) then
       value = ""
       call get_environment_variable( &
            "WAVETRISK_VALIDATE_BLOCK_DYNAMICS",value,length,status)
       if (status == 0 .and. length > 0) then
          select case (trim(value(1:min(length,len(value)))))
          case ("1","true","TRUE","on","ON","yes","YES")
             block_dynamics_validation = .true.
          case ("0","false","FALSE","off","OFF","no","NO")
             block_dynamics_validation = .false.
          case default
             call fail("invalid block-dynamics validation option")
          end select
       else if (status /= 0 .and. status /= 1) then
          call fail("unable to read block-dynamics validation option")
       end if
       local_enabled = merge(1,0,block_dynamics_validation)
       call MPI_Allreduce(local_enabled,enabled_count,1,MPI_INTEGER, &
            MPI_SUM,comm,ierr)
       call check_mpi(ierr, &
            "MPI_Allreduce block-dynamics validation option")
       if (enabled_count /= 0 .and. enabled_count /= n_process) &
            call fail("inconsistent block-dynamics validation option")
       block_dynamics_validation_initialized = .true.
       if (rank == 0) then
          if (block_dynamics_validation) then
             write(6,'(a)') &
                  "Block dynamics validation oracle enabled"
          else
             write(6,'(a)') &
                  "Block dynamics validation oracle disabled"
          end if
       end if
    end if
    enabled = block_dynamics_validation

  end function block_dynamics_validation_enabled


  logical function block_detailed_diagnostics_enabled () result(enabled)
    ! Detailed per-rank block reports are opt-in. Concise global validation
    ! summaries remain available independently through the exact oracles.

    implicit none

    character(len=32) :: value
    integer :: enabled_count
    integer :: ierr
    integer :: length
    integer :: local_enabled
    integer :: status

    if (.not. block_detailed_diagnostics_initialized) then
       value = ""
       call get_environment_variable( &
            "WAVETRISK_BLOCK_DETAILED_DIAGNOSTICS",value,length,status)
       if (status == 0 .and. length > 0) then
          select case (trim(value(1:min(length,len(value)))))
          case ("1","true","TRUE","on","ON","yes","YES")
             block_detailed_diagnostics = .true.
          case ("0","false","FALSE","off","OFF","no","NO")
             block_detailed_diagnostics = .false.
          case default
             call fail("invalid detailed block diagnostics option")
          end select
       else if (status /= 0 .and. status /= 1) then
          call fail("unable to read detailed block diagnostics option")
       end if
       local_enabled = merge(1,0,block_detailed_diagnostics)
       call MPI_Allreduce(local_enabled,enabled_count,1,MPI_INTEGER, &
            MPI_SUM,comm,ierr)
       call check_mpi(ierr, &
            "MPI_Allreduce detailed block diagnostics option")
       if (enabled_count /= 0 .and. enabled_count /= n_process) &
            call fail("inconsistent detailed block diagnostics option")
       block_detailed_diagnostics_initialized = .true.
       if (block_detailed_diagnostics .and. rank == 0) write(6,'(a)') &
            "Detailed per-rank parallel-block diagnostics enabled"
    end if
    enabled = block_detailed_diagnostics

  end function block_detailed_diagnostics_enabled


  logical function parallel_block_profile_enabled () result(enabled)
    ! Enable profiling collectively.  A mixed per-rank environment would
    ! otherwise make the eventual reductions unsafe and misleading.

    implicit none

    character(len=32) :: value
    integer :: enabled_count
    integer :: ierr
    integer :: length
    integer :: local_enabled
    integer :: status

    if (.not. block_profile_initialized) then
       value = ""
       call get_environment_variable( &
            "WAVETRISK_PROFILE_PARALLEL_BLOCKS",value,length,status)
       block_profile = .false.
       if (status == 0 .and. length > 0) then
          select case (trim(adjustl(value(1:min(length,len(value))))))
          case ("1","true","TRUE","yes","YES","on","ON")
             block_profile = .true.
          case default
             block_profile = .false.
          end select
       end if
       local_enabled = merge(1,0,block_profile)
       call MPI_Allreduce(local_enabled,enabled_count,1,MPI_INTEGER, &
            MPI_SUM,comm,ierr)
       call check_mpi(ierr,"MPI_Allreduce block profiling option")
       if (enabled_count /= 0 .and. enabled_count /= n_process) &
            call fail("inconsistent parallel-block profiling option")
       block_profile_initialized = .true.
       if (block_profile .and. rank == 0) write(6,'(a)') &
            "Parallel-block profiling enabled"
    end if
    enabled = block_profile

  end function parallel_block_profile_enabled


  real(dp) function parallel_block_profile_begin (phase) result(start_time)
    ! Return a timestamp only when profiling is active.  Phase validation is
    ! retained in optimized builds and catches mismatched instrumentation.

    implicit none

    integer, intent(in) :: phase

    if (phase < 1 .or. phase > BLOCK_PROFILE_PHASE_COUNT) &
         call fail("invalid parallel-block profile phase")
    start_time = 0.0_dp
    if (parallel_block_profile_enabled()) start_time = MPI_Wtime()

  end function parallel_block_profile_begin


  subroutine parallel_block_profile_end (phase,start_time,work)

    implicit none

    integer, intent(in) :: phase
    real(dp), intent(in) :: start_time
    integer(int64), optional, intent(in) :: work

    if (phase < 1 .or. phase > BLOCK_PROFILE_PHASE_COUNT) &
         call fail("invalid completed parallel-block profile phase")
    if (.not. parallel_block_profile_enabled()) return
    block_profile_seconds(phase) = block_profile_seconds(phase) + &
         max(0.0_dp,MPI_Wtime()-start_time)
    block_profile_calls(phase) = block_profile_calls(phase)+1_int64
    if (present(work)) &
         block_profile_work(phase) = block_profile_work(phase)+work

  end subroutine parallel_block_profile_end


  subroutine block_profile_enter (phase)

    implicit none

    integer, intent(in) :: phase

    if (phase < 1 .or. phase > BLOCK_PROFILE_PHASE_COUNT) &
         call fail("invalid entered parallel-block profile phase")
    if (.not. parallel_block_profile_enabled()) return
    if (block_profile_depth(phase) == 0) &
         block_profile_outer_start(phase) = MPI_Wtime()
    block_profile_depth(phase) = block_profile_depth(phase)+1

  end subroutine block_profile_enter


  subroutine block_profile_leave (phase,work)

    implicit none

    integer, intent(in) :: phase
    integer(int64), optional, intent(in) :: work

    if (phase < 1 .or. phase > BLOCK_PROFILE_PHASE_COUNT) &
         call fail("invalid exited parallel-block profile phase")
    if (.not. parallel_block_profile_enabled()) return
    if (block_profile_depth(phase) <= 0) &
         call fail("parallel-block profile phase is not active")
    block_profile_depth(phase) = block_profile_depth(phase)-1
    if (block_profile_depth(phase) == 0) then
       block_profile_seconds(phase) = block_profile_seconds(phase) + &
            max(0.0_dp,MPI_Wtime()-block_profile_outer_start(phase))
       block_profile_calls(phase) = block_profile_calls(phase)+1_int64
       block_profile_outer_start(phase) = 0.0_dp
    end if
    if (present(work)) &
         block_profile_work(phase) = block_profile_work(phase)+work

  end subroutine block_profile_leave


  subroutine record_parallel_block_profile_volume ( &
       phase,message_count,byte_count,work)

    implicit none

    integer, intent(in) :: phase
    integer(int64), intent(in) :: message_count
    integer(int64), intent(in) :: byte_count
    integer(int64), optional, intent(in) :: work

    if (phase < 1 .or. phase > BLOCK_PROFILE_PHASE_COUNT) &
         call fail("invalid parallel-block profile volume phase")
    if (.not. parallel_block_profile_enabled()) return
    if (message_count < 0_int64 .or. byte_count < 0_int64) &
         call fail("negative parallel-block profile volume")
    block_profile_messages(phase) = block_profile_messages(phase) + &
         message_count
    block_profile_bytes(phase) = block_profile_bytes(phase)+byte_count
    if (present(work)) &
         block_profile_work(phase) = block_profile_work(phase)+work

  end subroutine record_parallel_block_profile_volume


  subroutine record_parallel_block_topology (before_count,after_count)

    implicit none

    integer(int64), intent(in) :: before_count
    integer(int64), intent(in) :: after_count

    if (.not. parallel_block_profile_enabled()) return
    if (after_count > before_count) then
       block_profile_topology_events(2) = &
            block_profile_topology_events(2)+1_int64
    else if (after_count < before_count) then
       block_profile_topology_events(3) = &
            block_profile_topology_events(3)+1_int64
    else
       block_profile_topology_events(1) = &
            block_profile_topology_events(1)+1_int64
    end if

  end subroutine record_parallel_block_topology


  subroutine report_parallel_block_profile (reset)
    ! Perform the only profiling reductions.  Times are inclusive: this makes
    ! high-level driver cost and individual block-component cost visible in
    ! the same report without adding synchronization around timed regions.

    implicit none

    logical, optional, intent(in) :: reset

    integer :: ierr
    integer :: phase
    integer :: r
    integer(int64) :: allocation_local(BLOCK_PERSISTENT_ALLOCATION_COUNT)
    integer(int64) :: allocation_sum(BLOCK_PERSISTENT_ALLOCATION_COUNT)
    integer(int64) :: block_count_local
    integer(int64) :: block_count_rank(n_process)
    integer(int64) :: boundary_count_local
    integer(int64) :: boundary_count_sum
    integer(int64) :: bytes_sum(BLOCK_PROFILE_PHASE_COUNT)
    integer(int64) :: calls_sum(BLOCK_PROFILE_PHASE_COUNT)
    integer(int64) :: messages_sum(BLOCK_PROFILE_PHASE_COUNT)
    integer(int64) :: compatibility_local(5)
    integer(int64) :: compatibility_max(5)
    integer(int64) :: ghost_count_local
    integer(int64) :: ghost_count_sum
    integer(int64) :: plan_local(12)
    integer(int64) :: plan_sum(12)
    integer(int64) :: topology_max(3)
    integer(int64) :: work_sum(BLOCK_PROFILE_PHASE_COUNT)
    integer(int64) :: weight_local
    integer(int64) :: weight_max
    integer(int64) :: weight_min
    integer(int64) :: weight_sum
    logical :: clear_after
    logical :: state_ready
    real(dp) :: average_time
    real(dp) :: bridge_conservative
    real(dp) :: bridge_optimistic
    real(dp) :: imbalance
    real(dp) :: projection_local(4)
    real(dp) :: projection_max(4)
    real(dp) :: projection_min(4)
    real(dp) :: projection_sum(4)
    real(dp) :: seconds_max(BLOCK_PROFILE_PHASE_COUNT)
    real(dp) :: seconds_min(BLOCK_PROFILE_PHASE_COUNT)
    real(dp) :: seconds_sum(BLOCK_PROFILE_PHASE_COUNT)

    if (.not. parallel_block_profile_enabled()) return
    if (any(block_profile_depth /= 0)) &
         call fail("parallel-block profile report found an active phase")
    clear_after = .false.
    if (present(reset)) clear_after = reset
    state_ready = parallel_block_state_is_ready()

    call MPI_Allreduce(block_profile_seconds,seconds_min, &
         BLOCK_PROFILE_PHASE_COUNT,MPI_DOUBLE_PRECISION,MPI_MIN,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile minimum time")
    call MPI_Allreduce(block_profile_seconds,seconds_max, &
         BLOCK_PROFILE_PHASE_COUNT,MPI_DOUBLE_PRECISION,MPI_MAX,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile maximum time")
    call MPI_Allreduce(block_profile_seconds,seconds_sum, &
         BLOCK_PROFILE_PHASE_COUNT,MPI_DOUBLE_PRECISION,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile summed time")
    call MPI_Allreduce(block_profile_calls,calls_sum, &
         BLOCK_PROFILE_PHASE_COUNT,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile calls")
    call MPI_Allreduce(block_profile_work,work_sum, &
         BLOCK_PROFILE_PHASE_COUNT,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile work")
    call MPI_Allreduce(block_profile_messages,messages_sum, &
         BLOCK_PROFILE_PHASE_COUNT,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile messages")
    call MPI_Allreduce(block_profile_bytes,bytes_sum, &
         BLOCK_PROFILE_PHASE_COUNT,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile bytes")
    call MPI_Allreduce(block_profile_topology_events,topology_max,3, &
         MPI_INTEGER8,MPI_MAX,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile topology events")

    ! Per-rank critical-path projections for the architectural go/no-go
    ! decision.  The conservative bridge removes only representation copies;
    ! the optimistic bridge also removes legacy Domain boundary callbacks and
    ! repeated restriction bootstrap transport.  Essential block ghost MPI,
    ! native arithmetic and the final consumer installation remain charged.
    bridge_conservative = &
         block_profile_seconds(BLOCK_PROFILE_INVERSE_BDRY_WRITEBACK) + &
         block_profile_seconds(BLOCK_PROFILE_INVERSE_FULL_IMPORT) + &
         block_profile_seconds(BLOCK_PROFILE_INVERSE_BDRY_IMPORT) + &
         block_profile_seconds(BLOCK_PROFILE_RESTRICTION_CAPTURE)
    bridge_optimistic = bridge_conservative + &
         block_profile_seconds(BLOCK_PROFILE_INVERSE_BDRY_CALLBACK) + &
         block_profile_seconds(BLOCK_PROFILE_RESTRICTION_INITIAL)
    projection_local = [bridge_conservative,bridge_optimistic, &
         max(0.0_dp,block_profile_seconds(BLOCK_PROFILE_DYNAMICS)- &
         bridge_conservative), &
         max(0.0_dp,block_profile_seconds(BLOCK_PROFILE_DYNAMICS)- &
         bridge_optimistic)]
    call MPI_Allreduce(projection_local,projection_min,4, &
         MPI_DOUBLE_PRECISION,MPI_MIN,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile projection minimum")
    call MPI_Allreduce(projection_local,projection_max,4, &
         MPI_DOUBLE_PRECISION,MPI_MAX,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile projection maximum")
    call MPI_Allreduce(projection_local,projection_sum,4, &
         MPI_DOUBLE_PRECISION,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile projection sum")

    block_count_local = 0_int64
    boundary_count_local = 0_int64
    ghost_count_local = 0_int64
    weight_local = 0_int64
    if (state_ready) then
       block_count_local = int(n_local_blocks(),int64)
       do phase = 1,n_local_blocks()
          weight_local = weight_local + &
               int(block_catalog(local_block_catalog(phase))%weight,int64)
          boundary_count_local = boundary_count_local + int( &
               local_block_boundary_count(local_block_catalog(phase)), &
               int64)
          ghost_count_local = ghost_count_local + int( &
               local_block_ghost_count(local_block_catalog(phase)),int64)
       end do
    end if
    call MPI_Gather(block_count_local,1,MPI_INTEGER8,block_count_rank,1, &
         MPI_INTEGER8,0,comm,ierr)
    call check_mpi(ierr,"MPI_Gather profile block counts")
    call MPI_Allreduce(weight_local,weight_min,1,MPI_INTEGER8, &
         MPI_MIN,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile minimum load")
    call MPI_Allreduce(weight_local,weight_max,1,MPI_INTEGER8, &
         MPI_MAX,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile maximum load")
    call MPI_Allreduce(weight_local,weight_sum,1,MPI_INTEGER8, &
         MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile summed load")
    call MPI_Allreduce(boundary_count_local,boundary_count_sum,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile boundary records")
    call MPI_Allreduce(ghost_count_local,ghost_count_sum,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile ghost records")

    plan_local = [ghost_exchange_plan%build_count, &
         ghost_exchange_plan%reuse_count, &
         block_writeback_plan_generation, &
         block_writeback_plan_reuse_count, &
         block_scalar_restriction_exchange%exchanges, &
         block_adaptation_exchange%allocation_count, &
         block_vertical_remap_allocations, &
         local_block_hydrostatic_refresh_count(), &
         block_scalar_restriction_exchange%full_exchanges, &
         block_scalar_restriction_exchange%dynamic_exchanges, &
         block_scalar_restriction_exchange%full_values, &
         block_scalar_restriction_exchange%dynamic_values]
    call MPI_Allreduce(plan_local,plan_sum,size(plan_local), &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile plan counters")
    compatibility_local = [compatibility_writeback_total, &
         compatibility_writeback_output, &
         compatibility_writeback_checkpoint, &
         compatibility_writeback_grid_change, &
         compatibility_writeback_remap]
    call MPI_Allreduce(compatibility_local,compatibility_max, &
         size(compatibility_local),MPI_INTEGER8,MPI_MAX,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile writeback counters")

    call capture_parallel_block_allocation_snapshot(allocation_local)
    call MPI_Allreduce(allocation_local,allocation_sum, &
         BLOCK_PERSISTENT_ALLOCATION_COUNT,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce profile allocations")

    if (rank == 0) then
       write(6,'(/,a)') "Parallel-block profiling summary (inclusive):"
       write(6,'(a)',advance='no') "  final-owner blocks by rank ="
       do r = 1,n_process
          write(6,'(1x,i0)',advance='no') block_count_rank(r)
       end do
       write(6,'()')
       average_time = real(weight_sum,dp)/real(n_process,dp)
       imbalance = 0.0_dp
       if (average_time > 0.0_dp) &
            imbalance = real(weight_max,dp)/average_time
       write(6,'(a,i0,a,f12.2,a,i0,a,f8.3)') &
            "  weighted load min/avg/max = ",weight_min," / ", &
            average_time," / ",weight_max,"; max/avg = ",imbalance
       write(6,'(a,3(i0,1x))') &
            "  topology unchanged/refined/coarsened = ",topology_max
       write(6,'(a,i0,a,i0)') &
            "  compact boundary/ghost records = ",boundary_count_sum, &
            " / ",ghost_count_sum
       write(6,'(a)') &
            "  phase: calls | seconds min/avg/max | max/avg | work | messages | bytes"
       do phase = 1,BLOCK_PROFILE_PHASE_COUNT
          if (calls_sum(phase) == 0_int64 .and. &
               messages_sum(phase) == 0_int64) cycle
          average_time = seconds_sum(phase)/real(n_process,dp)
          imbalance = 0.0_dp
          if (average_time > 0.0_dp) &
               imbalance = seconds_max(phase)/average_time
          write(6,'(2x,a,": ",i0," | ",3(es11.4,1x),"| ",f7.3," | ",i0," | ",i0," | ",i0)') &
               trim(block_profile_phase_name(phase)), &
               calls_sum(phase)/int(n_process,int64), &
               seconds_min(phase),average_time,seconds_max(phase), &
               imbalance,work_sum(phase),messages_sum(phase), &
               bytes_sum(phase)
       end do
       write(6,'(a)') &
            "  block-native architectural projection (measured per rank):"
       write(6,'(a,3(es11.4,1x))') &
            "    conservative removable bridge min/avg/max = ", &
            projection_min(1),projection_sum(1)/real(n_process,dp), &
            projection_max(1)
       write(6,'(a,3(es11.4,1x))') &
            "    optimistic removable bridge min/avg/max = ", &
            projection_min(2),projection_sum(2)/real(n_process,dp), &
            projection_max(2)
       write(6,'(a,3(es11.4,1x))') &
            "    conservative projected dynamics min/avg/max = ", &
            projection_min(3),projection_sum(3)/real(n_process,dp), &
            projection_max(3)
       write(6,'(a,3(es11.4,1x))') &
            "    optimistic projected dynamics min/avg/max = ", &
            projection_min(4),projection_sum(4)/real(n_process,dp), &
            projection_max(4)
       if (projection_max(3) > 0.0_dp .and. &
            projection_max(4) > 0.0_dp) then
          write(6,'(a,2(f8.3,1x))') &
               "    projected dynamics speedup conservative/optimistic = ", &
               seconds_max(BLOCK_PROFILE_DYNAMICS)/projection_max(3), &
               seconds_max(BLOCK_PROFILE_DYNAMICS)/projection_max(4)
       end if
       write(6,'(a,9(i0,1x))') &
            "  persistent allocations ghost/writeback/stage/adapt/remap/tendency/import/accumulator/hydrostatic = ", &
            allocation_sum
       write(6,'(a,4(i0,1x))') &
            "  plan ghost builds/reuses; writeback builds/reuses = ", &
            plan_sum(1),plan_sum(2),plan_sum(3),plan_sum(4)
       write(6,'(a,4(i0,1x))') &
            "  restriction exchanges/adapt alloc/remap alloc/hydro refresh = ", &
            plan_sum(5),plan_sum(6),plan_sum(7),plan_sum(8)
       write(6,'(a,4(i0,1x))') &
            "  restriction ghost full/dynamic exchanges/values = ", &
            plan_sum(9),plan_sum(10),plan_sum(11),plan_sum(12)
       write(6,'(a,5(i0,1x),/)') &
            "  compatibility writebacks total/output/checkpoint/grid/remap = ", &
            compatibility_max
    end if

    if (clear_after) then
       block_profile_seconds = 0.0_dp
       block_profile_calls = 0_int64
       block_profile_work = 0_int64
       block_profile_messages = 0_int64
       block_profile_bytes = 0_int64
       block_profile_topology_events = 0_int64
       block_profile_depth = 0
       block_profile_outer_start = 0.0_dp
    end if

  end subroutine report_parallel_block_profile


  subroutine install_block_native_adaptation_mask_seed
    ! Install the compact block threshold decisions as the authoritative
    ! direct TOLRNZ seed.  Only one integer node/edge decision is transported
    ! per compact record.  The existing Domain mask routines retain boundary
    ! communication and parent/adjacency propagation after this callback.

    implicit none

    integer :: b
    integer :: d
    integer :: destination
    integer :: expected_patch_count
    integer :: ierr
    integer :: local_index
    integer :: local_patch
    integer :: n_patch
    integer :: p
    integer :: pos
    integer :: r
    integer :: slot
    integer :: start

    integer(int64) :: block_count_global(4)
    integer(int64) :: block_count_local(4)
    integer(int64) :: domain_count_global(4)
    integer(int64) :: domain_count_local(4)
    integer(int64) :: exchange_allocation_before

    logical :: local_store_ready
    logical :: validate_oracle
    logical :: writeback_ready

    type(Block_Adaptation_Significance_Context) :: statistics

    local_store_ready = local_block_store_ready()
    writeback_ready = block_writeback_plan_is_ready()
    validate_oracle = block_adaptation_validation_enabled()
    if (.not. production_grid_change_pending .or. &
         .not. local_store_ready .or. .not. writeback_ready .or. &
         .not. allocated(block_catalog)) then
       call fail("block adaptation decision cutover is not ready")
    end if
    if (.not. allocated(threshold)) then
       call fail("block adaptation thresholds are unavailable")
    end if

    call prepare_block_adaptation_decision_storage
    exchange_allocation_before = &
         block_adaptation_exchange%allocation_count
    call apply_local_block_field_consumer( &
         accumulate_block_adaptation_significance,statistics)
    block_count_local = [statistics%scalar_candidate_count, &
         statistics%scalar_active_count, &
         statistics%vector_candidate_count, &
         statistics%vector_active_count]

    ! Pack the already materialized per-record decisions using the persistent
    ! final-owner-to-Domain-owner block manifest.
    block_adaptation_exchange%send_buffer = 0
    do r = 1,n_process
       pos = block_adaptation_exchange%send_displ(r)+1
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r)+ &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          local_index = catalog_local_block(b)
          if (local_index < 1 .or. &
               block_adaptation_decision(local_index)%catalog_index /= b) &
               call fail("adaptation decision send block is stale")
          n_patch = block_adaptation_decision(local_index)%patch_count
          if (n_patch /= block_writeback_plan%send_patch_count(slot)) &
               call fail("adaptation decision send patch count differs")
          start = pos
          block_adaptation_exchange%send_buffer( &
               pos:pos+n_patch*BLOCK_ADAPTATION_PATCH_NVALUE-1) = &
               block_adaptation_decision(local_index)%value
          pos = pos+n_patch*BLOCK_ADAPTATION_PATCH_NVALUE
          if (pos-start /= n_patch*BLOCK_ADAPTATION_PATCH_NVALUE) &
               call fail("adaptation decision send extent differs")
       end do
       if (pos /= block_adaptation_exchange%send_displ(r)+ &
            block_adaptation_exchange%send_count(r)+1) &
            call fail("adaptation decision rank send extent differs")
    end do

    call MPI_Alltoallv( &
         block_adaptation_exchange%send_buffer, &
         block_adaptation_exchange%send_count, &
         block_adaptation_exchange%send_displ,MPI_INTEGER, &
         block_adaptation_exchange%recv_buffer, &
         block_adaptation_exchange%recv_count, &
         block_adaptation_exchange%recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv block adaptation decisions")

    block_adaptation_exchange%domain_stage = -2
    block_adaptation_exchange%domain_patch_covered = .false.

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       destination = source_rank(b)
       if (destination /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1)+1
       local_patch = 0
       n_patch = 0
       call stage_local_decision_subtree( &
            d,block_catalog(b)%root_patch,b,local_patch,n_patch)
       expected_patch_count = local_block_patch_count(b)
       if (local_patch /= expected_patch_count .or. &
            n_patch /= expected_patch_count) &
            call fail("retained adaptation decision extent differs")
    end do

    do r = 1,n_process
       pos = block_adaptation_exchange%recv_displ(r)+1
       do slot = block_writeback_plan%recv_displ(r)+1, &
            block_writeback_plan%recv_displ(r)+ &
            block_writeback_plan%recv_count(r)
          b = block_writeback_plan%recv_block(slot)
          d = loc_id(block_catalog(b)%root_domain+1)+1
          n_patch = 0
          start = pos
          call stage_received_decision_subtree( &
               d,block_catalog(b)%root_patch,pos,n_patch)
          if (n_patch /= block_writeback_plan%recv_patch_count(slot) .or. &
               pos-start /= n_patch*BLOCK_ADAPTATION_PATCH_NVALUE) &
               call fail("received adaptation decision extent differs")
       end do
       if (pos /= block_adaptation_exchange%recv_displ(r)+ &
            block_adaptation_exchange%recv_count(r)+1) &
            call fail("adaptation decision rank receive extent differs")
    end do

    ! Fixed scaffold patches outside the movable block catalogue remain an
    ! explicit compatibility exception. Catalogue-covered records are read
    ! directly from the compact decision image unless the oracle is enabled.
    domain_count_local = 0_int64
    do d = 1,size(grid)
       do p = 0,grid(d)%patch%length-1
          if (grid(d)%patch%elts(p+1)%deleted) cycle
          call validate_and_install_domain_patch_decisions( &
               d,p,validate_oracle,domain_count_local)
       end do
    end do

    call MPI_Allreduce(block_count_local,block_count_global, &
         4,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce block adaptation decisions")
    call MPI_Allreduce(domain_count_local,domain_count_global, &
         4,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce installed adaptation decisions")
    if (any(block_count_global /= domain_count_global)) then
       if (rank == 0) then
          write(error_unit,'(a,4(i0,1x))') &
               "Block adaptation decision counts = ",block_count_global
          write(error_unit,'(a,4(i0,1x))') &
               "Installed adaptation decision counts = ", &
               domain_count_global
       end if
       call fail("block/installed adaptation decision coverage differs")
    end if
    if (block_count_global(1) <= 0_int64 .or. &
         block_count_global(3) /= int(EDGE,int64)* &
         block_count_global(1) .or. &
         block_count_global(2) > block_count_global(1) .or. &
         block_count_global(4) > block_count_global(3)) &
         call fail("block adaptation decision coverage is invalid")
    if (block_adaptation_exchange%allocation_count /= &
         exchange_allocation_before) &
         call fail("adaptation decision exchange reallocated in flight")

    call record_parallel_block_profile_volume( &
         BLOCK_PROFILE_ADAPTATION, &
         int(count(block_adaptation_exchange%send_count > 0),int64), &
         int(sum(block_adaptation_exchange%send_count),int64)* &
         int(storage_size(0)/8,int64), &
         sum(block_count_local))

    call clear_parallel_block_state
    if (production_grid_change_pending .or. &
         local_block_store_ready() .or. allocated(block_catalog)) &
         call fail("adaptation decision cutover retained stale block state")

  contains

    subroutine claim_domain_decision_patch (d,p,stage_start)
      implicit none
      integer, intent(in) :: d,p
      integer, intent(out) :: stage_start
      integer :: patch_slot

      if (d < 1 .or. d > size(grid) .or. p < 0 .or. &
           p >= grid(d)%patch%length .or. &
           grid(d)%patch%elts(p+1)%deleted) &
           call fail("invalid adaptation decision destination patch")
      patch_slot = block_writeback_plan%domain_patch_displ(d)+p+1
      if (block_adaptation_exchange%domain_patch_covered(patch_slot)) &
           call fail("adaptation decision patch was claimed twice")
      block_adaptation_exchange%domain_patch_covered(patch_slot) = .true.
      stage_start = (patch_slot-1)*BLOCK_ADAPTATION_PATCH_NVALUE+1
    end subroutine claim_domain_decision_patch

    recursive subroutine stage_local_decision_subtree ( &
         d,p,b,local_patch,n_patch)
      implicit none
      integer, intent(in) :: d,p,b
      integer, intent(inout) :: local_patch,n_patch
      integer :: c,local_index,p_child,stage_start,value_start

      if (grid(d)%patch%elts(p+1)%deleted) return
      local_index = catalog_local_block(b)
      if (local_patch >= block_adaptation_decision(local_index)%patch_count) &
           call fail("retained adaptation decision traversal overflow")
      call claim_domain_decision_patch(d,p,stage_start)
      value_start = local_patch*BLOCK_ADAPTATION_PATCH_NVALUE+1
      block_adaptation_exchange%domain_stage( &
           stage_start:stage_start+BLOCK_ADAPTATION_PATCH_NVALUE-1) = &
           block_adaptation_decision(local_index)%value( &
           value_start:value_start+BLOCK_ADAPTATION_PATCH_NVALUE-1)
      local_patch = local_patch+1
      n_patch = n_patch+1
      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child > 0) call stage_local_decision_subtree( &
              d,p_child,b,local_patch,n_patch)
      end do
    end subroutine stage_local_decision_subtree

    recursive subroutine stage_received_decision_subtree (d,p,pos,n_patch)
      implicit none
      integer, intent(in) :: d,p
      integer, intent(inout) :: pos,n_patch
      integer :: c,p_child,stage_start

      if (grid(d)%patch%elts(p+1)%deleted) return
      if (pos+BLOCK_ADAPTATION_PATCH_NVALUE-1 > &
           size(block_adaptation_exchange%recv_buffer)) &
           call fail("received adaptation decision traversal overflow")
      call claim_domain_decision_patch(d,p,stage_start)
      block_adaptation_exchange%domain_stage( &
           stage_start:stage_start+BLOCK_ADAPTATION_PATCH_NVALUE-1) = &
           block_adaptation_exchange%recv_buffer( &
           pos:pos+BLOCK_ADAPTATION_PATCH_NVALUE-1)
      pos = pos+BLOCK_ADAPTATION_PATCH_NVALUE
      n_patch = n_patch+1
      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child > 0) call stage_received_decision_subtree( &
              d,p_child,pos,n_patch)
      end do
    end subroutine stage_received_decision_subtree

  end subroutine install_block_native_adaptation_mask_seed


  subroutine prepare_block_adaptation_decision_storage
    ! Allocate one topology-lifetime decision image and its narrow reverse
    ! exchange.  No allocation occurs while packing or transporting records.

    implicit none

    integer :: b
    integer :: local_index
    integer :: n_patch
    integer :: r
    integer :: slot

    integer(int64) :: rank_count
    integer(int64) :: total_patch

    if (block_adaptation_exchange%ready .and. &
         block_adaptation_exchange%plan_generation == &
         block_writeback_plan_generation) return
    if (.not. block_writeback_plan_is_ready()) &
         call fail("adaptation decision storage before writeback plan")

    ! Exhaustive lifecycle validation and a real topology transition both
    ! advance the writeback generation.  Rebuild its dependent route here;
    ! the same-generation steady-state path above remains allocation-free.
    call clear_block_adaptation_decisions
    allocate(block_adaptation_decision(max(1,n_local_blocks())))
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       n_patch = local_block_patch_count(b)
       if (n_patch <= 0) call fail("adaptation decision block is empty")
       block_adaptation_decision(local_index)%catalog_index = b
       block_adaptation_decision(local_index)%patch_count = n_patch
       allocate(block_adaptation_decision(local_index)%value( &
            n_patch*BLOCK_ADAPTATION_PATCH_NVALUE))
       block_adaptation_decision(local_index)%value = -2
    end do

    allocate(block_adaptation_exchange%send_count(n_process))
    allocate(block_adaptation_exchange%send_displ(n_process))
    allocate(block_adaptation_exchange%recv_count(n_process))
    allocate(block_adaptation_exchange%recv_displ(n_process))
    block_adaptation_exchange%send_count = 0
    block_adaptation_exchange%send_displ = 0
    block_adaptation_exchange%recv_count = 0
    block_adaptation_exchange%recv_displ = 0

    do r = 1,n_process
       rank_count = 0_int64
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r)+ &
            block_writeback_plan%send_count(r)
          rank_count = rank_count+int( &
               block_writeback_plan%send_patch_count(slot),int64)* &
               int(BLOCK_ADAPTATION_PATCH_NVALUE,int64)
       end do
       if (rank_count > int(huge(0),int64)) &
            call fail("adaptation decision send count exceeds range")
       block_adaptation_exchange%send_count(r) = int(rank_count)

       rank_count = 0_int64
       do slot = block_writeback_plan%recv_displ(r)+1, &
            block_writeback_plan%recv_displ(r)+ &
            block_writeback_plan%recv_count(r)
          rank_count = rank_count+int( &
               block_writeback_plan%recv_patch_count(slot),int64)* &
               int(BLOCK_ADAPTATION_PATCH_NVALUE,int64)
       end do
       if (rank_count > int(huge(0),int64)) &
            call fail("adaptation decision receive count exceeds range")
       block_adaptation_exchange%recv_count(r) = int(rank_count)
    end do
    do r = 2,n_process
       block_adaptation_exchange%send_displ(r) = &
            block_adaptation_exchange%send_displ(r-1)+ &
            block_adaptation_exchange%send_count(r-1)
       block_adaptation_exchange%recv_displ(r) = &
            block_adaptation_exchange%recv_displ(r-1)+ &
            block_adaptation_exchange%recv_count(r-1)
    end do

    allocate(block_adaptation_exchange%send_buffer( &
         max(1,sum(block_adaptation_exchange%send_count))))
    allocate(block_adaptation_exchange%recv_buffer( &
         max(1,sum(block_adaptation_exchange%recv_count))))
    total_patch = int(size( &
         block_writeback_plan%domain_patch_covered),int64)
    if (total_patch*int(BLOCK_ADAPTATION_PATCH_NVALUE,int64) > &
         int(huge(0),int64)) &
         call fail("adaptation decision Domain stage exceeds range")
    allocate(block_adaptation_exchange%domain_stage( &
         max(1,int(total_patch)*BLOCK_ADAPTATION_PATCH_NVALUE)))
    allocate(block_adaptation_exchange%domain_patch_covered( &
         max(1,int(total_patch))))
    block_adaptation_exchange%send_buffer = 0
    block_adaptation_exchange%recv_buffer = 0
    block_adaptation_exchange%domain_stage = -2
    block_adaptation_exchange%domain_patch_covered = .false.
    block_adaptation_exchange%allocation_count = &
         int(n_local_blocks()+9,int64)
    block_adaptation_exchange%plan_generation = &
         block_writeback_plan_generation
    block_adaptation_exchange%ready = .true.

  end subroutine prepare_block_adaptation_decision_storage


  subroutine validate_and_install_domain_patch_decisions ( &
       d,p,validate_oracle,statistics)
    ! Install catalogue-derived compact decisions into initialized Domain
    ! masks. The independent Domain calculation runs only when explicitly
    ! enabled; uncatalogued scaffold patches remain a compatibility exception.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    logical, intent(in) :: validate_oracle
    integer(int64), intent(inout) :: statistics(4)

    integer :: decision
    integer :: block_decision
    integer :: e
    integer :: field_index
    integer :: i
    integer :: id
    integer :: j
    integer :: k
    integer :: level
    integer :: maximum_level
    integer :: maximum_variable
    integer :: patch_slot
    integer :: patch_start
    integer :: q
    integer :: stage_start
    integer :: v

    logical :: active
    logical :: covered
    logical :: node_is_frozen

    real(dp) :: coefficient
    real(dp) :: coefficient_ratio
    real(dp) :: maximum_coefficient
    real(dp) :: maximum_ratio
    real(dp) :: maximum_threshold

    level = grid(d)%patch%elts(p+1)%level
    if (level < level_start .or. level > level_end) return
    patch_slot = block_writeback_plan%domain_patch_displ(d)+p+1
    covered = block_adaptation_exchange%domain_patch_covered(patch_slot)
    stage_start = (patch_slot-1)*BLOCK_ADAPTATION_PATCH_NVALUE+1
    patch_start = grid(d)%patch%elts(p+1)%elts_start

    do j = 0,PATCH_SIZE-1
       do i = 0,PATCH_SIZE-1
          q = PATCH_SIZE*j+i
          id = patch_start+q
          if (id < 0 .or. id >= grid(d)%node%length) &
               call fail("Domain adaptation oracle node is invalid")
          node_is_frozen = grid(d)%mask_n%elts(id+1) == FROZEN
          maximum_coefficient = 0.0_dp
          maximum_ratio = -huge(0.0_dp)
          maximum_threshold = 0.0_dp
          maximum_variable = 0
          maximum_level = 0

          if (covered .and. .not. validate_oracle) then
             decision = block_adaptation_exchange%domain_stage( &
                  stage_start+q)
             select case (decision)
             case (BLOCK_ADAPTATION_ACTIVE)
                if (node_is_frozen) &
                     call fail("active compact node has frozen Domain mask")
                statistics(1) = statistics(1)+1_int64
                statistics(2) = statistics(2)+1_int64
             case (BLOCK_ADAPTATION_INACTIVE)
                if (node_is_frozen) &
                     call fail("inactive compact node has frozen Domain mask")
                statistics(1) = statistics(1)+1_int64
             case (BLOCK_ADAPTATION_FROZEN)
                if (.not. node_is_frozen) &
                     call fail("frozen compact node has active Domain mask")
             case default
                call fail("invalid transported scalar adaptation decision")
             end select
          else
             if (node_is_frozen) then
                decision = BLOCK_ADAPTATION_FROZEN
             else
                statistics(1) = statistics(1)+1_int64
                active = level < level_fill
                do k = 1,zlevels
                   do v = scalars(1),scalars(2)
                      field_index = id+1
                      if (field_index > &
                           size(wav_coeff(v,k)%data(d)%elts)) &
                           call fail( &
                           "Domain scalar adaptation oracle is invalid")
                      coefficient = wav_coeff(v,k)%data(d)%elts( &
                           field_index)
                      if (threshold(v,k) > 0.0_dp) then
                         coefficient_ratio = &
                              abs(coefficient)/threshold(v,k)
                      else if (abs(coefficient) >= threshold(v,k)) then
                         coefficient_ratio = huge(0.0_dp)
                      else
                         coefficient_ratio = -huge(0.0_dp)
                      end if
                      if (coefficient_ratio > maximum_ratio) then
                         maximum_coefficient = coefficient
                         maximum_ratio = coefficient_ratio
                         maximum_threshold = threshold(v,k)
                         maximum_variable = v
                         maximum_level = k
                      end if
                      if (abs(coefficient) >= threshold(v,k)) &
                           active = .true.
                   end do
                end do
                if (active) then
                   decision = BLOCK_ADAPTATION_ACTIVE
                   statistics(2) = statistics(2)+1_int64
                else
                   decision = BLOCK_ADAPTATION_INACTIVE
                end if
             end if
             if (covered) then
                block_decision = &
                     block_adaptation_exchange%domain_stage(stage_start+q)
                if (block_decision /= decision) then
                   write(error_unit,'(/,a)') &
                        "Block/Domain scalar adaptation mismatch:"
                   write(error_unit,'(a,7(i0,1x))') &
                        "  global/local Domain, patch, level, i, j, id = ", &
                        glo_id(rank+1,d),d,p,level,i,j,id
                   write(error_unit,'(a,2(i0,1x),a,l1)') &
                        "  block/Domain decisions = ", &
                        block_decision,decision, &
                        "; level-fill forced = ",level < level_fill
                   write(error_unit,'(a,2(i0,1x))') &
                        "  controlling variable/physical level = ", &
                        maximum_variable,maximum_level
                   write(error_unit,'(a,4(es24.16,1x))') &
                        "  coefficient, abs, threshold, ratio = ", &
                        maximum_coefficient,abs(maximum_coefficient), &
                        maximum_threshold,maximum_ratio
                   call fail( &
                        "block/Domain scalar adaptation record differs")
                end if
             else
                block_adaptation_exchange%domain_stage(stage_start+q) = &
                     decision
             end if
          end if
          select case (decision)
          case (BLOCK_ADAPTATION_ACTIVE)
             grid(d)%mask_n%elts(id+1) = TOLRNZ
          case (BLOCK_ADAPTATION_INACTIVE)
             if (grid(d)%mask_n%elts(id+1) > ADJZONE) &
                  grid(d)%mask_n%elts(id+1) = ADJZONE
          case (BLOCK_ADAPTATION_FROZEN)
             continue
          case default
             call fail("invalid scalar adaptation decision")
          end select

          do e = RT,UP
             field_index = EDGE*id+e+1
             if (covered .and. .not. validate_oracle) then
                decision = block_adaptation_exchange%domain_stage( &
                     stage_start+PATCH_SIZE**2+EDGE*q+e)
                select case (decision)
                case (BLOCK_ADAPTATION_ACTIVE)
                   if (node_is_frozen) call fail( &
                        "active compact edge has frozen Domain node")
                   statistics(3) = statistics(3)+1_int64
                   statistics(4) = statistics(4)+1_int64
                case (BLOCK_ADAPTATION_INACTIVE)
                   if (node_is_frozen) call fail( &
                        "inactive compact edge has frozen Domain node")
                   statistics(3) = statistics(3)+1_int64
                case (BLOCK_ADAPTATION_FROZEN)
                   if (.not. node_is_frozen) call fail( &
                        "frozen compact edge has active Domain node")
                case default
                   call fail( &
                        "invalid transported vector adaptation decision")
                end select
             else
                if (node_is_frozen) then
                   decision = BLOCK_ADAPTATION_FROZEN
                else
                   statistics(3) = statistics(3)+1_int64
                   active = level < level_fill
                   do k = 1,zlevels
                      if (field_index > &
                           size(wav_coeff(S_VELO,k)%data(d)%elts)) &
                           call fail( &
                           "Domain vector adaptation oracle is invalid")
                      if (abs(wav_coeff(S_VELO,k)%data(d)%elts( &
                           field_index)) >= threshold(S_VELO,k)) &
                           active = .true.
                   end do
                   if (active) then
                      decision = BLOCK_ADAPTATION_ACTIVE
                      statistics(4) = statistics(4)+1_int64
                   else
                      decision = BLOCK_ADAPTATION_INACTIVE
                   end if
                end if
                if (covered) then
                   if (block_adaptation_exchange%domain_stage( &
                        stage_start+PATCH_SIZE**2+EDGE*q+e) /= decision) &
                        call fail( &
                        "block/Domain vector adaptation record differs")
                else
                   block_adaptation_exchange%domain_stage( &
                        stage_start+PATCH_SIZE**2+EDGE*q+e) = decision
                end if
             end if
             select case (decision)
             case (BLOCK_ADAPTATION_ACTIVE)
                grid(d)%mask_e%elts(field_index) = TOLRNZ
             case (BLOCK_ADAPTATION_INACTIVE)
                if (grid(d)%mask_e%elts(field_index) > ADJZONE) &
                     grid(d)%mask_e%elts(field_index) = ADJZONE
             case (BLOCK_ADAPTATION_FROZEN)
                continue
             case default
                call fail("invalid vector adaptation decision")
             end select
          end do
       end do
    end do
    if (.not. covered) &
         block_adaptation_exchange%domain_patch_covered(patch_slot) = .true.

  end subroutine validate_and_install_domain_patch_decisions




  subroutine accumulate_block_adaptation_significance ( &
       catalog_index,block,context)
    ! Apply mask_tol_vars threshold semantics to compact patch interiors.

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: decision_base
    integer :: e
    integer :: field_index
    integer :: field_level
    integer :: i
    integer :: j
    integer :: level_slot
    integer :: local_index
    integer :: mask_level_slot
    integer :: n_node
    integer :: node_index
    integer :: p
    integer :: q
    integer :: scalar_slot
    integer :: variable

    logical :: active

    real(dp) :: mask_value

    if (.not. allocated(block_scalar_tendency)) then
       call fail("block adaptation significance masks are unavailable")
    end if
    if (.not. allocated(block%wavelet_scalar) .or. &
         .not. allocated(block%wavelet_vector)) then
       call fail("block adaptation wavelets are unavailable")
    end if
    local_index = catalog_local_block(catalog_index)
    n_node = size(block%node)
    mask_level_slot = 1-block%field_level+1
    if (local_index < 1 .or. &
         local_index > size(block_scalar_tendency) .or. &
         n_node < 1 .or. mask_level_slot < 1 .or. &
         mask_level_slot > block%n_field_level) then
       call fail("block adaptation significance layout is invalid")
    end if
    if (.not. block_scalar_tendency(local_index)%ready .or. &
         block_scalar_tendency(local_index)%catalog_index /= &
         catalog_index) then
       call fail("block adaptation significance mask is stale")
    end if
    if (.not. allocated(block_adaptation_decision) .or. &
         local_index > size(block_adaptation_decision) .or. &
         block_adaptation_decision(local_index)%catalog_index /= &
         catalog_index .or. &
         block_adaptation_decision(local_index)%patch_count /= &
         size(block%patch) .or. &
         .not. allocated(block_adaptation_decision(local_index)%value)) then
       call fail("block adaptation decision storage is stale")
    end if

    select type (statistics => context)
    type is (Block_Adaptation_Significance_Context)
       do p = 1,size(block%patch)
          if (block%patch(p)%level < level_start .or. &
               block%patch(p)%level > level_end) cycle
          do j = 0,PATCH_SIZE-1
             do i = 0,PATCH_SIZE-1
                q = PATCH_SIZE*j+i
                decision_base = &
                     (p-1)*BLOCK_ADAPTATION_PATCH_NVALUE
                node_index = block%patch(p)%elts_start+PATCH_SIZE*j+i
                if (node_index < 0 .or. node_index >= n_node) then
                   call fail("block adaptation decision node is invalid")
                end if
                mask_value = block_scalar_record_value( &
                     block,local_index,p,0,mask_level_slot,i,j, &
                     BLOCK_SCALAR_WAVELET_MASK_INDEX)
                ! init_masks_zero has already reset every finer level.  Only
                ! the level_start FROZEN state survives into mask_tol_vars.
                if (block%patch(p)%level == level_start .and. &
                     nint(mask_value) == FROZEN) then
                   block_adaptation_decision(local_index)%value( &
                        decision_base+q+1) = BLOCK_ADAPTATION_FROZEN
                   do e = RT,UP
                      block_adaptation_decision(local_index)%value( &
                           decision_base+PATCH_SIZE**2+EDGE*q+e+1) = &
                           BLOCK_ADAPTATION_FROZEN
                   end do
                   cycle
                end if

                statistics%scalar_candidate_count = &
                     statistics%scalar_candidate_count+1_int64
                active = block%patch(p)%level < level_fill
                do level_slot = 1,block%n_field_level
                   field_level = block%field_level+level_slot-1
                   if (field_level < 1 .or. field_level > zlevels) cycle
                   do scalar_slot = 0,block%n_scalar_variable-1
                      variable = block%scalar_variable+scalar_slot
                      if (variable < scalars(1) .or. &
                           variable > scalars(2)) cycle
                      field_index = &
                           (scalar_slot*block%n_field_level+ &
                           level_slot-1)*n_node+node_index+1
                      if (field_index < 1 .or. field_index > &
                           size(block%wavelet_scalar)) then
                         call fail( &
                              "block scalar adaptation value is invalid")
                      end if
                      if (abs(block%wavelet_scalar(field_index)) >= &
                           threshold(variable,field_level)) active = .true.
                   end do
                end do
                if (active) statistics%scalar_active_count = &
                     statistics%scalar_active_count+1_int64
                if (active) then
                   block_adaptation_decision(local_index)%value( &
                        decision_base+q+1) = BLOCK_ADAPTATION_ACTIVE
                else
                   block_adaptation_decision(local_index)%value( &
                        decision_base+q+1) = BLOCK_ADAPTATION_INACTIVE
                end if

                do e = RT,UP
                   statistics%vector_candidate_count = &
                        statistics%vector_candidate_count+1_int64
                   active = block%patch(p)%level < level_fill
                   do level_slot = 1,block%n_field_level
                      field_level = block%field_level+level_slot-1
                      if (field_level < 1 .or. &
                           field_level > zlevels) cycle
                      field_index = (level_slot-1)*EDGE*n_node+ &
                           EDGE*node_index+e+1
                      if (field_index < 1 .or. field_index > &
                           size(block%wavelet_vector)) then
                         call fail( &
                              "block vector adaptation value is invalid")
                      end if
                      if (abs(block%wavelet_vector(field_index)) >= &
                           threshold(S_VELO,field_level)) active = .true.
                   end do
                   if (active) statistics%vector_active_count = &
                        statistics%vector_active_count+1_int64
                   if (active) then
                      block_adaptation_decision(local_index)%value( &
                           decision_base+PATCH_SIZE**2+EDGE*q+e+1) = &
                           BLOCK_ADAPTATION_ACTIVE
                   else
                      block_adaptation_decision(local_index)%value( &
                           decision_base+PATCH_SIZE**2+EDGE*q+e+1) = &
                           BLOCK_ADAPTATION_INACTIVE
                   end if
                end do
             end do
          end do
       end do
    class default
       call fail("block adaptation significance context is invalid")
    end select

  end subroutine accumulate_block_adaptation_significance


  subroutine retain_post_grid_change_block_reconstruction
    ! Validate one complete compact state rebuilt from the actual Domain
    ! image after physics and adaptation. It is retained across the optional
    ! native vertical remap and into the next production timestep.

    implicit none

    integer(int64) :: allocation_before
    integer(int64) :: accumulator_allocation_ready
    integer(int64) :: import_allocation_ready
    integer(int64) :: tendency_allocation_ready
    integer(int64) :: writeback_before

    logical :: accumulator_ready
    logical :: hydrostatic_ready
    logical :: checkpoint_ready
    logical :: import_active
    logical :: state_ready
    logical :: tendency_ready
    logical :: trial_active
    logical :: validate_oracle

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("post-grid-change reconstruction is not ready")
    end if

    allocation_before = block_writeback_plan_allocation_count()
    writeback_before = block_domain_production_writeback_count()
    hydrostatic_ready = .false.

    validate_oracle = block_dynamics_validation_enabled()
    if (validate_oracle) then
       call block_profile_enter(BLOCK_PROFILE_ORACLE)
       call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)
       call assert_block_domain_field_family_match( &
            BLOCK_PAYLOAD_WAV_COEFF)
       call block_profile_leave(BLOCK_PROFILE_ORACLE)
    end if

    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.true.)
    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_WAV_COEFF,.true.)

    call exchange_block_scalar_ghost_payloads( &
         BLOCK_PAYLOAD_SOL,.false.,.true.)
    call exchange_block_vector_ghost_payloads( &
         BLOCK_PAYLOAD_SOL,.false.,.true.)
    call exchange_block_scalar_ghost_payloads( &
         BLOCK_PAYLOAD_WAV_COEFF,.false.,.true.)
    call exchange_block_vector_ghost_payloads( &
         BLOCK_PAYLOAD_WAV_COEFF,.false.,.true.)

    if (compressible) then
       call ensure_local_block_hydrostatic_state
       hydrostatic_ready = local_block_hydrostatic_state_ready()
       if (.not. hydrostatic_ready) then
          call fail("post-grid-change hydrostatic state is not ready")
       end if
    end if

    call prepare_local_block_tendency_workspace
    tendency_allocation_ready = &
         local_block_tendency_allocation_count()
    accumulator_allocation_ready = &
         local_block_tendency_accumulator_allocation_count()
    import_allocation_ready = &
         local_block_tendency_import_allocation_count()
    call prepare_local_block_tendency_workspace
    if (local_block_tendency_allocation_count() /= &
         tendency_allocation_ready) then
       call fail("post-grid-change tendency workspace was reallocated")
    end if
    if (local_block_tendency_import_allocation_count() /= &
         import_allocation_ready) then
       call fail("post-grid-change import coverage was reallocated")
    end if
    if (local_block_tendency_accumulator_allocation_count() /= &
         accumulator_allocation_ready) then
       call fail("post-grid-change stage register was reallocated")
    end if

    if (block_writeback_plan_allocation_count() /= &
         allocation_before) then
       call fail("post-grid-change reconstruction reallocated buffers")
    end if
    if (block_domain_production_writeback_count() /= &
         writeback_before) then
       call fail("post-grid-change reconstruction modified Domain fields")
    end if

    state_ready = parallel_block_state_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    import_active = local_block_tendency_import_is_active()
    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (.not. state_ready) then
       call fail("post-grid-change production state was not retained")
    end if
    if (tendency_ready) then
       call fail("post-grid-change production state retained a tendency")
    end if
    if (accumulator_ready) then
       call fail("post-grid-change production state retained a stage register")
    end if
    if (import_active) then
       call fail("post-grid-change production state retained an import")
    end if
    if (trial_active) then
       call fail("post-grid-change production state retained a trial")
    end if
    if (checkpoint_ready) then
       call fail("post-grid-change production state retained a checkpoint")
    end if

  end subroutine retain_post_grid_change_block_reconstruction


  subroutine prepare_block_native_vertical_remap_boundary_state
    ! Refresh exactly the compact stencil state consumed by vertical remap.
    ! Unlike the trend-entry validation driver, this production path performs
    ! one boundary import and one ghost exchange, without reconstruction,
    ! repeated installation, stencil moments or diagnostic reductions.

    implicit none

    integer :: scalar_ghost_recv_size_before
    integer :: scalar_ghost_send_size_before
    integer :: vector_ghost_recv_size_before
    integer :: vector_ghost_send_size_before

    integer(int64) :: production_writeback_before
    integer(int64) :: writeback_allocation_before

    logical :: accumulator_ready
    logical :: checkpoint_ready
    logical :: state_ready
    logical :: tendency_ready
    logical :: trial_active

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("vertical remap boundary refresh before state is ready")
    end if
    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. checkpoint_ready .or. tendency_ready .or. &
         accumulator_ready) then
       call fail("vertical remap boundary refresh found pending state")
    end if

    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    production_writeback_before = &
         block_domain_production_writeback_count()
    scalar_ghost_send_size_before = &
         size(ghost_exchange_plan%scalar_send_buffer)
    scalar_ghost_recv_size_before = &
         size(ghost_exchange_plan%scalar_recv_buffer)
    vector_ghost_send_size_before = &
         size(ghost_exchange_plan%vector_send_buffer)
    vector_ghost_recv_size_before = &
         size(ghost_exchange_plan%vector_recv_buffer)

    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.false.,include_vector=.false.)
    call exchange_block_scalar_ghost_payloads( &
         BLOCK_PAYLOAD_SOL,.false.,.false.)

    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before) then
       call fail("vertical remap boundary refresh reallocated buffers")
    end if
    if (block_domain_production_writeback_count() /= &
         production_writeback_before) then
       call fail("vertical remap boundary refresh modified Domain fields")
    end if
    if (size(ghost_exchange_plan%scalar_send_buffer) /= &
         scalar_ghost_send_size_before .or. &
         size(ghost_exchange_plan%scalar_recv_buffer) /= &
         scalar_ghost_recv_size_before .or. &
         size(ghost_exchange_plan%vector_send_buffer) /= &
         vector_ghost_send_size_before .or. &
         size(ghost_exchange_plan%vector_recv_buffer) /= &
         vector_ghost_recv_size_before) then
       call fail("vertical remap boundary refresh resized ghost buffers")
    end if

  end subroutine prepare_block_native_vertical_remap_boundary_state


  subroutine prepare_block_native_vertical_remap (interpolate)
    ! Remap every authoritative compact atmospheric column while the Domain
    ! compatibility image remains unchanged. The compact old-mass image is
    ! retained because neighboring pressure coordinates must not observe an
    ! already remapped column. An optional legacy oracle may compare later.

    implicit none

    procedure(Block_Vertical_Interpolator) :: interpolate

    type(Block_Vertical_Remap_Context) :: statistics

    integer(int64) :: allocation_ready

    logical :: metadata_exchange_ready
    logical :: state_ready

    state_ready = parallel_block_state_is_ready()
    if (.not. compressible .or. .not. state_ready) then
       call fail("native vertical remap prerequisites are incomplete")
    end if
    if (block_vertical_remap_active .or. &
         associated(production_vertical_interpolator)) then
       call fail("native vertical remap transaction is already active")
    end if

    ! remap_vertical_coordinates has just refreshed the Domain SOL boundary.
    ! Mirror that exact pre-remap boundary in compact storage, then produce
    ! all inter-block ghosts before taking the immutable old-mass snapshot.
    call prepare_block_native_vertical_remap_boundary_state

    if (allocated(block_vertical_remap)) then
       if (size(block_vertical_remap) /= n_local_blocks()) then
          call clear_block_vertical_remap_storage
       end if
    end if
    if (.not. allocated(block_vertical_remap)) then
       allocate(block_vertical_remap(n_local_blocks()))
       block_vertical_remap_allocations = &
            block_vertical_remap_allocations+1_int64
    end if

    metadata_exchange_ready = block_vertical_remap_exchange%ready
    allocation_ready = block_vertical_remap_allocations
    call refresh_block_vertical_remap_masks
    if (metadata_exchange_ready .and. &
         block_vertical_remap_allocations /= allocation_ready) then
       call fail("vertical remap metadata exchange was reallocated")
    end if
    call apply_local_block_field_consumer( &
         snapshot_block_vertical_remap_mass,statistics)
    allocation_ready = block_vertical_remap_allocations
    production_vertical_interpolator => interpolate
    call apply_local_block_field_producer( &
         remap_block_vertical_columns,statistics)
    nullify(production_vertical_interpolator)

    if (block_vertical_remap_allocations /= allocation_ready) then
       call fail("native vertical remap allocated during production")
    end if
    call invalidate_local_block_hydrostatic_state
    call invalidate_local_block_tendency_products

    block_vertical_remap_active = .true.

  end subroutine prepare_block_native_vertical_remap


  real(dp) function block_native_minimum_relative_mass () &
       result(minimum_mass)
    ! Compute the remapping trigger from authoritative final-owner compact
    ! patch interiors. Fixed coarse scaffold patches are not represented by
    ! blocks, so retain their established Domain contribution explicitly.

    implicit none

    type(Block_Minimum_Mass_Context) :: statistics

    integer :: c
    integer :: d
    integer :: field_index
    integer :: i
    integer :: id
    integer :: ierr
    integer :: j
    integer :: k
    integer :: level
    integer :: p_current
    integer :: p_parent
    integer :: p
    integer :: patch_slot
    integer(int64) :: global_column_count
    logical :: state_ready

    integer :: dims(2,N_BDRY+1)
    integer :: offs(N_BDRY+1)

    real(dp) :: initial_mass
    real(dp) :: pressure_surface
    real(dp) :: ratio
    real(dp) :: rho_dz(1:zlevels)

    state_ready = parallel_block_state_is_ready()
    if (.not. compressible .or. .not. state_ready) then
       call fail("block minimum-mass prerequisites are incomplete")
    end if

    call apply_local_block_field_consumer( &
         accumulate_block_minimum_relative_mass,statistics)

    if (.not. allocated( &
         block_writeback_plan%domain_patch_reconstructed)) then
       call fail("block minimum-mass scaffold coverage is unavailable")
    end if
    do d = 1,size(grid)
       do p = 0,grid(d)%patch%length-1
          if (grid(d)%patch%elts(p+1)%deleted) cycle
          if (grid(d)%patch%elts(p+1)%level < level_start .or. &
               grid(d)%patch%elts(p+1)%level > level_end) cycle
          patch_slot = block_writeback_plan%domain_patch_displ(d)+p+1
          if (patch_slot < 1 .or. patch_slot > size( &
               block_writeback_plan%domain_patch_reconstructed)) then
             call fail("block minimum-mass scaffold patch is invalid")
          end if
          if (block_writeback_plan%domain_patch_reconstructed( &
               patch_slot)) cycle
          do j = 0,PATCH_SIZE-1
             do i = 0,PATCH_SIZE-1
                id = grid(d)%patch%elts(p+1)%elts_start+ &
                     PATCH_SIZE*j+i
                if (id < 0 .or. id >= grid(d)%node%length) then
                   call fail("block minimum-mass scaffold node is invalid")
                end if
                field_index = id+1
                do k = 1,zlevels
                   rho_dz(k) = &
                        sol(S_MASS,k)%data(d)%elts(field_index)+ &
                        sol_mean(S_MASS,k)%data(d)%elts(field_index)
                end do
                pressure_surface = grav_accel*sum(rho_dz)+p_top
                do k = 1,zlevels
                   initial_mass = a_vert_mass(k)+ &
                        b_vert_mass(k)*pressure_surface/grav_accel
                   if (abs(initial_mass) <= tiny(1.0_dp)) then
                      call fail("scaffold initial layer mass is zero")
                   end if
                   ratio = rho_dz(k)/abs(initial_mass)
                   if (.not. ieee_is_finite(ratio)) then
                      call fail("scaffold relative layer mass is non-finite")
                   end if
                   statistics%minimum = min(statistics%minimum,ratio)
                end do
                statistics%column_count = &
                     statistics%column_count+1_int64
             end do
          end do
       end do
    end do
    ! Pole nodes are visited separately by the legacy apply_no_bdry path and
    ! are not compact patch interiors. Follow the same two pole branches once
    ! and include the point represented at every active grid level.
    do d = 1,size(grid)
       do c = SOUTHEAST,NORTHWEST,2
          if (.not. grid(d)%penta(c)) cycle
          if (grid(d)%neigh(c) /= POLE) cycle
          p_current = 1
          do while (p_current > 0)
             p_parent = p_current
             p_current = grid(d)%patch%elts(p_parent+1)%children(c-4)
             level = grid(d)%patch%elts(p_parent+1)%level
             if (level < level_start) cycle
             if (level > level_end) exit
             call get_offs_Domain(grid(d),p_parent,offs,dims)
             select case (c)
             case (NORTHWEST)
                field_index = idx(0,PATCH_SIZE,offs,dims)+1
             case (SOUTHEAST)
                field_index = idx(PATCH_SIZE,0,offs,dims)+1
             case default
                call fail("block minimum-mass pole branch is invalid")
             end select
             if (field_index < 1 .or. &
                  field_index > grid(d)%node%length) then
                call fail("block minimum-mass pole address is invalid")
             end if
             do k = 1,zlevels
                rho_dz(k) = sol(S_MASS,k)%data(d)%elts(field_index)+ &
                     sol_mean(S_MASS,k)%data(d)%elts(field_index)
             end do
             pressure_surface = grav_accel*sum(rho_dz)+p_top
             do k = 1,zlevels
                initial_mass = a_vert_mass(k)+ &
                     b_vert_mass(k)*pressure_surface/grav_accel
                if (abs(initial_mass) <= tiny(1.0_dp)) then
                   call fail("pole initial layer mass is zero")
                end if
                ratio = rho_dz(k)/abs(initial_mass)
                if (.not. ieee_is_finite(ratio)) then
                   call fail("pole relative layer mass is non-finite")
                end if
                statistics%minimum = min(statistics%minimum,ratio)
             end do
             statistics%column_count = &
                  statistics%column_count+1_int64
          end do
       end do
    end do

    call MPI_Allreduce(statistics%minimum,minimum_mass,1, &
         MPI_DOUBLE_PRECISION,MPI_MIN,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce block minimum relative mass")
    call MPI_Allreduce(statistics%column_count,global_column_count,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce block minimum mass coverage")
    if (global_column_count <= 0_int64 .or. &
         .not. ieee_is_finite(minimum_mass)) then
       call fail("block minimum relative mass coverage is invalid")
    end if
    if (minimum_mass <= 0.0_dp) then
       call fail("a compact block layer has collapsed")
    end if

  end function block_native_minimum_relative_mass


  subroutine accumulate_block_minimum_relative_mass ( &
       catalog_index,block,context)

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: field_index
    integer :: i
    integer :: j
    integer :: k
    integer :: level_slot
    integer :: mass_slot
    integer :: n_node
    integer :: node_index
    integer :: p

    real(dp) :: initial_mass
    real(dp) :: pressure_surface
    real(dp) :: ratio
    real(dp) :: rho_dz(1:zlevels)

    if (catalog_index /= block%id+1) then
       call fail("block minimum-mass catalogue identity differs")
    end if
    mass_slot = S_MASS-block%scalar_variable
    n_node = size(block%node)
    if (mass_slot < 0 .or. mass_slot >= block%n_scalar_variable .or. &
         n_node < 1) then
       call fail("block minimum-mass field layout is invalid")
    end if

    select type (statistics => context)
    type is (Block_Minimum_Mass_Context)
       do p = 1,size(block%patch)
          if (block%patch(p)%level < level_start .or. &
               block%patch(p)%level > level_end) cycle
          do j = 0,PATCH_SIZE-1
             do i = 0,PATCH_SIZE-1
                node_index = block%patch(p)%elts_start+PATCH_SIZE*j+i
                if (node_index < 0 .or. node_index >= n_node) then
                   call fail("block minimum-mass node address is invalid")
                end if
                do k = 1,zlevels
                   level_slot = k-block%field_level+1
                   if (level_slot < 1 .or. &
                        level_slot > block%n_field_level) then
                      call fail("block minimum-mass level is invalid")
                   end if
                   field_index = &
                        (mass_slot*block%n_field_level+level_slot-1)* &
                        n_node+node_index+1
                   if (field_index < 1 .or. &
                        field_index > size(block%scalar) .or. &
                        field_index > size(block%scalar_mean)) then
                      call fail("block minimum-mass value address is invalid")
                   end if
                   rho_dz(k) = block%scalar(field_index) + &
                        block%scalar_mean(field_index)
                end do
                pressure_surface = grav_accel*sum(rho_dz)+p_top
                do k = 1,zlevels
                   initial_mass = a_vert_mass(k) + &
                        b_vert_mass(k)*pressure_surface/grav_accel
                   if (abs(initial_mass) <= tiny(1.0_dp)) then
                      call fail("block initial layer mass is zero")
                   end if
                   ratio = rho_dz(k)/abs(initial_mass)
                   if (.not. ieee_is_finite(ratio)) then
                      call fail("block relative layer mass is non-finite")
                   end if
                   statistics%minimum = min(statistics%minimum,ratio)
                end do
                statistics%column_count = &
                     statistics%column_count+1_int64
             end do
          end do
       end do
    class default
       call fail("block minimum-mass context is invalid")
    end select

  end subroutine accumulate_block_minimum_relative_mass


  subroutine validate_block_native_vertical_remap
    ! Compare compact remap interiors against the optional legacy oracle.

    implicit none

    if (.not. block_vertical_remap_active .or. &
         associated(production_vertical_interpolator)) then
       call fail("native vertical remap validation is out of sequence")
    end if
    call assert_block_domain_field_family_match( &
         BLOCK_PAYLOAD_SOL,comparison_name="vertical remap")

  end subroutine validate_block_native_vertical_remap


  subroutine write_block_native_vertical_remap_to_domains
    ! Materialize authoritative compact remap interiors once on Domain owners.

    implicit none

    integer(int64) :: allocation_before
    integer(int64) :: writeback_before

    if (.not. block_vertical_remap_active .or. &
         associated(production_vertical_interpolator)) then
       call fail("native vertical remap writeback is out of sequence")
    end if
    allocation_before = block_writeback_plan_allocation_count()
    writeback_before = block_domain_production_writeback_count()
    call write_block_field_family_to_domains(BLOCK_PAYLOAD_SOL)
    compatibility_writeback_remap = &
         compatibility_writeback_remap + 1_int64
    if (block_writeback_plan_allocation_count() /= allocation_before) then
       call fail("native vertical remap writeback reallocated buffers")
    end if
    if (block_domain_production_writeback_count() /= &
         writeback_before+1_int64) then
       call fail("native vertical remap writeback count differs")
    end if

  end subroutine write_block_native_vertical_remap_to_domains


  subroutine complete_block_native_vertical_remap
    ! Import Domain-computed pole and cross-root boundary aliases after the
    ! authoritative compact interiors have been written and refreshed.

    implicit none

    integer(int64) :: allocation_before
    integer(int64) :: hydrostatic_refresh_after
    integer(int64) :: hydrostatic_refresh_before
    integer(int64) :: writeback_before

    logical :: hydrostatic_ready
    logical :: state_ready

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready .or. .not. block_vertical_remap_active .or. &
         associated(production_vertical_interpolator)) then
       call fail("native vertical remap completion is out of sequence")
    end if
    allocation_before = block_writeback_plan_allocation_count()
    writeback_before = block_domain_production_writeback_count()

    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.false.)
    call refresh_block_sol_ghosts
    hydrostatic_refresh_before = &
         local_block_hydrostatic_refresh_count()
    call invalidate_local_block_hydrostatic_state
    call ensure_local_block_hydrostatic_state
    hydrostatic_refresh_after = &
         local_block_hydrostatic_refresh_count()
    hydrostatic_ready = local_block_hydrostatic_state_ready()
    if (.not. hydrostatic_ready) then
       call fail("native vertical remap hydrostatic state is not ready")
    end if
    if (hydrostatic_refresh_after-hydrostatic_refresh_before /= &
         int(n_local_blocks(),int64)) then
       call fail("native vertical remap hydrostatic refresh is incomplete")
    end if
    if (block_writeback_plan_allocation_count() /= allocation_before .or. &
         block_domain_production_writeback_count() /= writeback_before) then
       call fail("native vertical remap completion changed transport")
    end if

    block_vertical_remap_active = .false.

  end subroutine complete_block_native_vertical_remap


  subroutine snapshot_block_vertical_remap_mass ( &
       catalog_index,block,context)

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: field_start
    integer :: local_index
    integer :: mass_slot
    integer :: n_value

    local_index = catalog_local_block(catalog_index)
    mass_slot = S_MASS-block%scalar_variable
    n_value = block%n_field_level*size(block%node)
    if (local_index < 1 .or. &
         local_index > size(block_vertical_remap) .or. &
         mass_slot < 0 .or. mass_slot >= block%n_scalar_variable .or. &
         n_value < 1) then
       call fail("native vertical remap snapshot layout is invalid")
    end if
    if (allocated(block_vertical_remap(local_index)%old_mass)) then
       if (size(block_vertical_remap(local_index)%old_mass) /= n_value) then
          deallocate(block_vertical_remap(local_index)%old_mass)
       end if
    end if
    if (.not. allocated(block_vertical_remap(local_index)%old_mass)) then
       allocate(block_vertical_remap(local_index)%old_mass(n_value))
       block_vertical_remap_allocations = &
            block_vertical_remap_allocations+1_int64
    end if
    field_start = mass_slot*n_value+1
    if (field_start < 1 .or. &
         field_start+n_value-1 > size(block%scalar)) then
       call fail("native vertical remap mass snapshot is short")
    end if
    block_vertical_remap(local_index)%catalog_index = catalog_index
    block_vertical_remap(local_index)%old_mass = &
         block%scalar(field_start:field_start+n_value-1)

    select type (context)
    type is (Block_Vertical_Remap_Context)
       continue
    class default
       call fail("native vertical remap snapshot context is invalid")
    end select

  end subroutine snapshot_block_vertical_remap_mass


  subroutine prepare_block_vertical_remap_workspace
    ! Preallocate topology-lifetime remap masks, old-mass snapshots and the
    ! compact metadata route. Production remaps then reuse all storage.

    implicit none

    integer :: b
    integer :: field_level
    integer :: local_index
    integer :: n_field_level
    integer :: n_patch
    integer :: n_scalar_variable
    integer :: n_value
    integer :: scalar_mult
    integer :: scalar_variable
    integer :: vector_mult
    integer :: vector_variable

    if (allocated(block_vertical_remap)) then
       if (size(block_vertical_remap) /= n_local_blocks()) &
            call clear_block_vertical_remap_storage
    end if
    if (.not. allocated(block_vertical_remap)) then
       allocate(block_vertical_remap(n_local_blocks()))
       block_vertical_remap_allocations = &
            block_vertical_remap_allocations + 1_int64
    end if

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       n_patch = local_block_patch_count(b)
       call get_local_block_field_layout( &
            local_index,scalar_variable,n_scalar_variable, &
            vector_variable,field_level,n_field_level, &
            scalar_mult,vector_mult)
       if (n_patch < 1 .or. n_field_level < 1 .or. &
            scalar_mult /= 1 .or. vector_mult < 1 .or. &
            S_MASS < scalar_variable .or. &
            S_MASS >= scalar_variable+n_scalar_variable .or. &
            vector_variable < 1 .or. field_level > 1 .or. &
            field_level+n_field_level-1 < zlevels) &
            call fail("vertical remap workspace layout is invalid")
       n_value = n_patch*n_field_level*PATCH_SIZE**2

       if (allocated(block_vertical_remap(local_index)%old_mass)) then
          if (size(block_vertical_remap(local_index)%old_mass) /= n_value) &
               deallocate(block_vertical_remap(local_index)%old_mass)
       end if
       if (.not. allocated(block_vertical_remap(local_index)%old_mass)) then
          allocate(block_vertical_remap(local_index)%old_mass(n_value))
          block_vertical_remap_allocations = &
               block_vertical_remap_allocations + 1_int64
       end if

       if (allocated(block_vertical_remap(local_index)%active)) then
          if (size(block_vertical_remap(local_index)%active) /= &
               n_patch*PATCH_SIZE**2) &
               deallocate(block_vertical_remap(local_index)%active)
       end if
       if (.not. allocated(block_vertical_remap(local_index)%active)) then
          allocate(block_vertical_remap(local_index)% &
               active(n_patch*PATCH_SIZE**2))
          block_vertical_remap_allocations = &
               block_vertical_remap_allocations + 1_int64
       end if

       if (allocated(block_vertical_remap(local_index)%source_start)) then
          if (size(block_vertical_remap(local_index)%source_start) /= &
               n_patch) &
               deallocate(block_vertical_remap(local_index)%source_start)
       end if
       if (.not. allocated( &
            block_vertical_remap(local_index)%source_start)) then
          allocate(block_vertical_remap(local_index)%source_start(n_patch))
          block_vertical_remap_allocations = &
               block_vertical_remap_allocations + 1_int64
       end if

       block_vertical_remap(local_index)%catalog_index = b
       block_vertical_remap(local_index)%installed_patch_count = 0
       block_vertical_remap(local_index)%old_mass = 0.0_dp
       block_vertical_remap(local_index)%active = .false.
       block_vertical_remap(local_index)%source_start = -1
    end do

    call prepare_vertical_remap_metadata_exchange

  end subroutine prepare_block_vertical_remap_workspace


  subroutine prepare_vertical_remap_metadata_exchange

    implicit none

    integer :: expected_recv(n_process)
    integer :: metadata_count
    integer :: metadata_displ
    integer :: route
    integer :: route_slot
    integer :: status

    if (block_vertical_remap_exchange%ready .and. &
         block_vertical_remap_exchange%plan_generation == &
         block_writeback_plan_generation) return
    if (.not. block_writeback_plan_is_ready()) then
       call fail("vertical remap metadata route is unavailable")
    end if
    ! Preserve the topology-lifetime old-mass workspace while rebuilding
    ! only the metadata route invalidated by a writeback-plan generation.
    call clear_block_vertical_remap_exchange
    allocate(block_vertical_remap_exchange%send_count(n_process))
    allocate(block_vertical_remap_exchange%send_displ(n_process))
    allocate(block_vertical_remap_exchange%recv_count(n_process))
    allocate(block_vertical_remap_exchange%recv_displ(n_process))
    block_vertical_remap_exchange%send_count = 0
    block_vertical_remap_exchange%recv_count = 0

    do route = 1,n_process
       do route_slot = block_writeback_plan%recv_displ(route)+1, &
            block_writeback_plan%recv_displ(route) + &
            block_writeback_plan%recv_count(route)
          block_vertical_remap_exchange%send_count(route) = &
               block_vertical_remap_exchange%send_count(route) + &
               BLOCK_VERTICAL_REMAP_METADATA_COUNT* &
               block_writeback_plan%recv_patch_count(route_slot)
       end do
       do route_slot = block_writeback_plan%send_displ(route)+1, &
            block_writeback_plan%send_displ(route) + &
            block_writeback_plan%send_count(route)
          block_vertical_remap_exchange%recv_count(route) = &
               block_vertical_remap_exchange%recv_count(route) + &
               BLOCK_VERTICAL_REMAP_METADATA_COUNT* &
               block_writeback_plan%send_patch_count(route_slot)
       end do
    end do

    call MPI_Alltoall(block_vertical_remap_exchange%send_count,1, &
         MPI_INTEGER,expected_recv,1,MPI_INTEGER,comm,status)
    call check_mpi(status,"MPI_Alltoall vertical remap metadata counts")
    if (any(expected_recv /= &
         block_vertical_remap_exchange%recv_count)) then
       call fail("vertical remap metadata route counts differ")
    end if

    metadata_displ = 0
    do route = 1,n_process
       block_vertical_remap_exchange%send_displ(route) = &
            metadata_displ
       metadata_count = &
            block_vertical_remap_exchange%send_count(route)
       if (metadata_count < 0 .or. &
            metadata_displ > huge(metadata_displ)-metadata_count) then
          call fail("vertical remap metadata send count overflows")
       end if
       metadata_displ = metadata_displ+metadata_count
    end do
    allocate(block_vertical_remap_exchange% &
         send_buffer(max(1,metadata_displ)))

    metadata_displ = 0
    do route = 1,n_process
       block_vertical_remap_exchange%recv_displ(route) = &
            metadata_displ
       metadata_count = &
            block_vertical_remap_exchange%recv_count(route)
       if (metadata_count < 0 .or. &
            metadata_displ > huge(metadata_displ)-metadata_count) then
          call fail("vertical remap metadata receive count overflows")
       end if
       metadata_displ = metadata_displ+metadata_count
    end do
    allocate(block_vertical_remap_exchange% &
         recv_buffer(max(1,metadata_displ)))
    block_vertical_remap_exchange%send_buffer = 0
    block_vertical_remap_exchange%recv_buffer = 0
    block_vertical_remap_exchange%plan_generation = &
         block_writeback_plan_generation
    block_vertical_remap_exchange%ready = .true.
    block_vertical_remap_allocations = &
         block_vertical_remap_allocations+1_int64

  end subroutine prepare_vertical_remap_metadata_exchange


  subroutine refresh_block_vertical_remap_masks
    ! Transport only the current post-adaptation mask and Domain source start.
    ! The route follows the persistent reverse writeback plan, but its compact
    ! integer payload is independent of all prognostic field-family buffers.

    implicit none

    integer :: b
    integer :: d
    integer :: ierr
    integer :: local_index
    integer :: local_patch
    integer :: n_patch
    integer :: pos
    integer :: r
    integer :: source
    integer :: slot

    if (.not. allocated(block_vertical_remap)) then
       call fail("vertical remap mask storage is unavailable")
    end if
    if (size(block_vertical_remap) /= n_local_blocks()) then
       call fail("vertical remap mask storage extent differs")
    end if
    call prepare_vertical_remap_metadata_exchange

    block_vertical_remap_exchange%send_buffer = 0
    block_vertical_remap_exchange%recv_buffer = 0
    do r = 1,n_process
       pos = block_vertical_remap_exchange%send_displ(r)+1
       do slot = block_writeback_plan%recv_displ(r)+1, &
            block_writeback_plan%recv_displ(r) + &
            block_writeback_plan%recv_count(r)
          b = block_writeback_plan%recv_block(slot)
          source = source_rank(b)
          if (source /= rank .or. block_catalog(b)%owner /= r-1) then
             call fail("vertical remap metadata source route differs")
          end if
          d = loc_id(block_catalog(b)%root_domain+1)+1
          if (d < 1 .or. d > size(grid)) then
             call fail("vertical remap metadata Domain is invalid")
          end if
          n_patch = 0
          call pack_vertical_remap_metadata_subtree( &
               d,block_catalog(b)%root_patch, &
               block_vertical_remap_exchange%send_buffer,pos,n_patch)
          if (n_patch /= &
               block_writeback_plan%recv_patch_count(slot)) then
             call fail("vertical remap metadata patch coverage differs")
          end if
       end do
       if (pos /= block_vertical_remap_exchange%send_displ(r) + &
            block_vertical_remap_exchange%send_count(r)+1) then
          call fail("vertical remap metadata send extent differs")
       end if
    end do

    call MPI_Alltoallv( &
         block_vertical_remap_exchange%send_buffer, &
         block_vertical_remap_exchange%send_count, &
         block_vertical_remap_exchange%send_displ,MPI_INTEGER, &
         block_vertical_remap_exchange%recv_buffer, &
         block_vertical_remap_exchange%recv_count, &
         block_vertical_remap_exchange%recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv vertical remap metadata")
    call record_parallel_block_profile_volume( &
         BLOCK_PROFILE_REMAP, &
         int(count(block_vertical_remap_exchange%send_count > 0),int64), &
         int(sum(block_vertical_remap_exchange%send_count),int64)* &
         int(storage_size(0)/8,int64))

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       n_patch = local_block_patch_count(b)
       if (allocated(block_vertical_remap(local_index)%active)) then
          if (size(block_vertical_remap(local_index)%active) /= &
               n_patch*PATCH_SIZE**2) then
             deallocate(block_vertical_remap(local_index)%active)
          end if
       end if
       if (.not. allocated(block_vertical_remap(local_index)%active)) then
          allocate(block_vertical_remap(local_index)% &
               active(n_patch*PATCH_SIZE**2))
          block_vertical_remap_allocations = &
               block_vertical_remap_allocations+1_int64
       end if
       if (allocated(block_vertical_remap(local_index)%source_start)) then
          if (size(block_vertical_remap(local_index)%source_start) /= &
               n_patch) then
             deallocate(block_vertical_remap(local_index)%source_start)
          end if
       end if
       if (.not. allocated( &
            block_vertical_remap(local_index)%source_start)) then
          allocate(block_vertical_remap(local_index)% &
               source_start(n_patch))
          block_vertical_remap_allocations = &
               block_vertical_remap_allocations+1_int64
       end if
       block_vertical_remap(local_index)%catalog_index = b
       block_vertical_remap(local_index)%installed_patch_count = 0
       block_vertical_remap(local_index)%active = .false.
       block_vertical_remap(local_index)%source_start = -1
    end do

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       source = source_rank(b)
       if (source /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1)+1
       if (d < 1 .or. d > size(grid)) then
          call fail("retained vertical remap mask Domain is invalid")
       end if
       local_patch = 0
       call install_retained_mask_subtree( &
            d,block_catalog(b)%root_patch,b,local_patch)
       n_patch = local_block_patch_count(b)
       if (local_patch /= n_patch) then
          call fail("retained vertical remap mask coverage differs")
       end if
    end do

    do r = 1,n_process
       pos = block_vertical_remap_exchange%recv_displ(r)+1
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          source = source_rank(b)
          if (source /= r-1 .or. block_catalog(b)%owner /= rank) then
             call fail("vertical remap metadata destination route differs")
          end if
          n_patch = local_block_patch_count(b)
          if (n_patch /= &
               block_writeback_plan%send_patch_count(slot)) then
             call fail("vertical remap metadata destination changed")
          end if
          do local_patch = 0,n_patch-1
             if (pos < 1 .or. pos + &
                  BLOCK_VERTICAL_REMAP_METADATA_COUNT-1 > &
                  size(block_vertical_remap_exchange%recv_buffer)) then
                call fail("remote vertical remap mask payload is short")
             end if
             call install_vertical_remap_mask_patch( &
                  b,local_patch,block_vertical_remap_exchange%recv_buffer( &
                  pos:pos+BLOCK_VERTICAL_REMAP_METADATA_COUNT-1))
             pos = pos+BLOCK_VERTICAL_REMAP_METADATA_COUNT
          end do
       end do
       if (pos /= block_vertical_remap_exchange%recv_displ(r) + &
            block_vertical_remap_exchange%recv_count(r)+1) then
          call fail("remote vertical remap mask extent differs")
       end if
    end do

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       n_patch = local_block_patch_count(b)
       if (block_vertical_remap(local_index)%catalog_index /= b .or. &
            block_vertical_remap(local_index)%installed_patch_count /= &
            n_patch .or. any(block_vertical_remap(local_index)% &
            source_start < 0)) then
          call fail("vertical remap mask installation is incomplete")
       end if
    end do

  contains



    recursive subroutine pack_vertical_remap_metadata_subtree ( &
         d,p,value,pos,patch_count)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(inout) :: value(:)
      integer, intent(inout) :: pos
      integer, intent(inout) :: patch_count

      integer :: c
      integer :: child
      integer :: metadata(BLOCK_VERTICAL_REMAP_METADATA_COUNT)

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("vertical remap metadata patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return
      if (pos < 1 .or. pos+BLOCK_VERTICAL_REMAP_METADATA_COUNT-1 > &
           size(value)) then
         call fail("vertical remap metadata buffer is short")
      end if
      call fill_vertical_remap_metadata(d,p,metadata)
      value(pos:pos+BLOCK_VERTICAL_REMAP_METADATA_COUNT-1) = metadata
      pos = pos+BLOCK_VERTICAL_REMAP_METADATA_COUNT
      patch_count = patch_count+1
      do c = 1,N_CHDRN
         child = grid(d)%patch%elts(p+1)%children(c)
         if (child <= 0) cycle
         call pack_vertical_remap_metadata_subtree( &
              d,child,value,pos,patch_count)
      end do

    end subroutine pack_vertical_remap_metadata_subtree


    subroutine fill_vertical_remap_metadata (d,p,value)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(out) :: &
           value(BLOCK_VERTICAL_REMAP_METADATA_COUNT)

      integer :: source_start

      if (d < 1 .or. d > size(grid) .or. &
           p < 0 .or. p >= grid(d)%patch%length) then
         call fail("vertical remap metadata source is invalid")
      end if
      source_start = grid(d)%patch%elts(p+1)%elts_start
      if (source_start < 0 .or. &
           source_start+PATCH_SIZE**2 > size(grid(d)%mask_n%elts)) then
         call fail("vertical remap metadata mask extent is invalid")
      end if
      value(1:PATCH_SIZE**2) = grid(d)%mask_n%elts( &
           source_start+1:source_start+PATCH_SIZE**2)
      value(BLOCK_VERTICAL_REMAP_METADATA_COUNT) = source_start

    end subroutine fill_vertical_remap_metadata


    subroutine install_vertical_remap_mask_patch ( &
         catalog_index,patch_index,value)

      implicit none

      integer, intent(in) :: catalog_index
      integer, intent(in) :: patch_index
      integer, intent(in) :: value(:)

      integer :: first
      integer :: index
      integer :: n_patch
      integer :: source_start

      index = catalog_local_block(catalog_index)
      first = patch_index*PATCH_SIZE**2+1
      if (index < 1 .or. index > size(block_vertical_remap)) then
         call fail("vertical remap mask block address is invalid")
      end if
      if (.not. allocated(block_vertical_remap(index)%active)) then
         call fail("vertical remap mask block storage is absent")
      end if
      if (.not. allocated( &
           block_vertical_remap(index)%source_start)) then
         call fail("vertical remap source storage is absent")
      end if
      n_patch = local_block_patch_count(catalog_index)
      if (patch_index < 0 .or. &
           patch_index >= n_patch .or. &
           size(value) /= BLOCK_VERTICAL_REMAP_METADATA_COUNT .or. &
           first+PATCH_SIZE**2-1 > &
           size(block_vertical_remap(index)%active)) then
         call fail("vertical remap mask patch address is invalid")
      end if
      source_start = value(BLOCK_VERTICAL_REMAP_METADATA_COUNT)
      if (source_start < 0) then
         call fail("vertical remap patch source is invalid")
      end if
      block_vertical_remap(index)%active( &
           first:first+PATCH_SIZE**2-1) = &
           value(1:PATCH_SIZE**2) >= ADJZONE
      block_vertical_remap(index)%source_start(patch_index+1) = &
           source_start
      block_vertical_remap(index)%installed_patch_count = &
           block_vertical_remap(index)%installed_patch_count+1

    end subroutine install_vertical_remap_mask_patch


    recursive subroutine install_retained_mask_subtree ( &
         d,p,catalog_index,patch_index)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: catalog_index
      integer, intent(inout) :: patch_index

      integer :: c
      integer :: child
      integer :: metadata(BLOCK_VERTICAL_REMAP_METADATA_COUNT)

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("retained vertical remap mask patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return
      call fill_vertical_remap_metadata(d,p,metadata)
      call install_vertical_remap_mask_patch( &
           catalog_index,patch_index,metadata)
      patch_index = patch_index+1
      do c = 1,N_CHDRN
         child = grid(d)%patch%elts(p+1)%children(c)
         if (child <= 0) cycle
         call install_retained_mask_subtree( &
              d,child,catalog_index,patch_index)
      end do

    end subroutine install_retained_mask_subtree

  end subroutine refresh_block_vertical_remap_masks


  subroutine remap_block_vertical_columns (catalog_index,block,context)

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(inout) :: block
    class(*), intent(inout) :: context

    integer :: i
    integer :: j
    integer :: local_index
    integer :: p

    logical :: coordinate_needed(0:PATCH_SIZE,0:PATCH_SIZE)

    real(dp) :: patch_p_new(0:zlevels,0:PATCH_SIZE,0:PATCH_SIZE)
    real(dp) :: patch_p_old(0:zlevels,0:PATCH_SIZE,0:PATCH_SIZE)

    local_index = catalog_local_block(catalog_index)
    if (local_index < 1 .or. &
         local_index > size(block_vertical_remap)) then
       call fail("native vertical remap block index is invalid")
    end if
    if (block_vertical_remap(local_index)%catalog_index /= &
         catalog_index .or. .not. allocated( &
         block_vertical_remap(local_index)%active)) then
       call fail("native vertical remap block state is stale")
    end if
    if (.not. associated(production_vertical_interpolator)) then
       call fail("native vertical remap interpolator is unavailable")
    end if

    select type (context)
    type is (Block_Vertical_Remap_Context)
       do p = 1,size(block%patch)
          if (block%patch(p)%level < level_start .or. &
               block%patch(p)%level > level_end) cycle
          ! Cache every pressure column needed by an active center before any
          ! compact prognostic value is overwritten. Each shared coordinate
          ! is evaluated once instead of once per incident target column.
          coordinate_needed = .false.
          do j = 0,PATCH_SIZE-1
             do i = 0,PATCH_SIZE-1
                if (.not. block_vertical_remap(local_index)%active( &
                     (p-1)*PATCH_SIZE**2+PATCH_SIZE*j+i+1)) cycle
                coordinate_needed(i,j) = .true.
                coordinate_needed(i+1,j) = .true.
                coordinate_needed(i+1,j+1) = .true.
                coordinate_needed(i,j+1) = .true.
             end do
          end do
          do j = 0,PATCH_SIZE
             do i = 0,PATCH_SIZE
                if (.not. coordinate_needed(i,j)) cycle
                call block_remap_pressure_coordinates( &
                     block,local_index,p,i,j, &
                     patch_p_new(:,i,j),patch_p_old(:,i,j))
             end do
          end do
          do j = 0,PATCH_SIZE-1
             do i = 0,PATCH_SIZE-1
                if (.not. block_vertical_remap(local_index)%active( &
                     (p-1)*PATCH_SIZE**2+PATCH_SIZE*j+i+1)) cycle
                call remap_one_block_vertical_column( &
                     block,local_index,p,i,j,patch_p_new,patch_p_old)
             end do
          end do
       end do
    class default
       call fail("native vertical remap producer context is invalid")
    end select

  end subroutine remap_block_vertical_columns


  subroutine remap_one_block_vertical_column ( &
       block,local_index,p,i,j,patch_p_new,patch_p_old)

    implicit none

    type(Block_Data), intent(inout) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: i
    integer, intent(in) :: j
    real(dp), intent(in) :: &
         patch_p_new(0:zlevels,0:PATCH_SIZE,0:PATCH_SIZE)
    real(dp), intent(in) :: &
         patch_p_old(0:zlevels,0:PATCH_SIZE,0:PATCH_SIZE)
    integer :: e
    integer :: mass_field_index
    integer :: k
    integer :: level_slot
    integer :: mass_slot
    integer :: n_node
    integer :: node_index
    integer :: old_mass_index
    integer :: temp_field_index
    integer :: temp_slot
    integer :: vector_field_index

    real(dp) :: flux_new(1:zlevels,RT:UP)
    real(dp) :: flux_old(1:zlevels,RT:UP)
    real(dp) :: p_edge_new(0:zlevels,RT:UP)
    real(dp) :: p_edge_old(0:zlevels,RT:UP)
    real(dp) :: p_neighbor_new(0:zlevels)
    real(dp) :: p_neighbor_old(0:zlevels)
    real(dp) :: p_new(0:zlevels)
    real(dp) :: p_old(0:zlevels)
    real(dp) :: mass_mean(1:zlevels)
    real(dp) :: rho_dz
    real(dp) :: rho_dz_new(1:zlevels)
    real(dp) :: rho_dz_theta
    real(dp) :: temp_mean(1:zlevels)
    real(dp) :: theta_new(1:zlevels)
    real(dp) :: theta_old(1:zlevels)

    mass_slot = S_MASS-block%scalar_variable
    temp_slot = S_TEMP-block%scalar_variable
    if (mass_slot < 0 .or. mass_slot >= block%n_scalar_variable .or. &
         temp_slot < 0 .or. temp_slot >= block%n_scalar_variable) then
       call fail("native vertical remap scalar layout is invalid")
    end if
    n_node = size(block%node)
    node_index = block%patch(p)%elts_start+PATCH_SIZE*j+i
    if (node_index < 0 .or. node_index >= n_node .or. &
         .not. allocated(block_vertical_remap(local_index)%old_mass)) then
       call fail("native vertical remap direct column is invalid")
    end if

    p_new = patch_p_new(:,i,j)
    p_old = patch_p_old(:,i,j)
    do e = RT,UP
       select case (e)
       case (RT)
          p_neighbor_new = patch_p_new(:,i+1,j)
          p_neighbor_old = patch_p_old(:,i+1,j)
       case (DG)
          p_neighbor_new = patch_p_new(:,i+1,j+1)
          p_neighbor_old = patch_p_old(:,i+1,j+1)
       case (UP)
          p_neighbor_new = patch_p_new(:,i,j+1)
          p_neighbor_old = patch_p_old(:,i,j+1)
       end select
       p_edge_new(:,e) = 0.5_dp*(p_new+p_neighbor_new)
       p_edge_old(:,e) = 0.5_dp*(p_old+p_neighbor_old)
    end do

    do k = 1,zlevels
       level_slot = k-block%field_level+1
       if (level_slot < 1 .or. level_slot > block%n_field_level) then
          call fail("native vertical remap atmospheric level is invalid")
       end if
       old_mass_index = (level_slot-1)*n_node+node_index+1
       mass_field_index = &
            (mass_slot*block%n_field_level+level_slot-1)* &
            n_node+node_index+1
       temp_field_index = &
            (temp_slot*block%n_field_level+level_slot-1)* &
            n_node+node_index+1
       if (old_mass_index < 1 .or. old_mass_index > size( &
            block_vertical_remap(local_index)%old_mass) .or. &
            mass_field_index < 1 .or. &
            mass_field_index > size(block%scalar) .or. &
            mass_field_index > size(block%scalar_mean) .or. &
            temp_field_index < 1 .or. &
            temp_field_index > size(block%scalar) .or. &
            temp_field_index > size(block%scalar_mean)) then
          call fail("native vertical remap direct scalar address is invalid")
       end if
       mass_mean(k) = block%scalar_mean(mass_field_index)
       temp_mean(k) = block%scalar_mean(temp_field_index)
       rho_dz = block_vertical_remap(local_index)% &
            old_mass(old_mass_index)+mass_mean(k)
       rho_dz_theta = block%scalar(temp_field_index)+temp_mean(k)
       if (abs(rho_dz) <= tiny(1.0_dp)) then
          call fail("native vertical remap column has zero mass")
       end if
       if (.not. ieee_is_finite(rho_dz) .or. &
            .not. ieee_is_finite(rho_dz_theta)) then
          call fail("native vertical remap direct scalar is non-finite")
       end if
       theta_old(zlevels-k+1) = rho_dz_theta/rho_dz
       do e = RT,UP
          vector_field_index = (level_slot-1)*EDGE*n_node + &
               EDGE*node_index+e+1
          if (vector_field_index < 1 .or. &
               vector_field_index > size(block%vector)) then
             call fail("native vertical remap direct vector address is invalid")
          end if
          flux_old(zlevels-k+1,e) = block%vector(vector_field_index)
          if (.not. ieee_is_finite(flux_old(zlevels-k+1,e))) then
             call fail("native vertical remap direct vector is non-finite")
          end if
       end do
    end do

    rho_dz_new = (p_new(zlevels:1:-1)- &
         p_new(zlevels-1:0:-1))/grav_accel
    call production_vertical_interpolator( &
         zlevels,theta_new,p_new,theta_old,p_old)
    do e = RT,UP
       call production_vertical_interpolator( &
            zlevels,flux_new(:,e),p_edge_new(:,e), &
            flux_old(:,e),p_edge_old(:,e))
    end do

    do k = 1,zlevels
       level_slot = k-block%field_level+1
       mass_field_index = &
            (mass_slot*block%n_field_level+level_slot-1)* &
            n_node+node_index+1
       temp_field_index = &
            (temp_slot*block%n_field_level+level_slot-1)* &
            n_node+node_index+1
       block%scalar(mass_field_index) = rho_dz_new(k)-mass_mean(k)
       block%scalar(temp_field_index) = &
            rho_dz_new(k)*theta_new(zlevels-k+1)-temp_mean(k)
       if (.not. ieee_is_finite(block%scalar(mass_field_index)) .or. &
            .not. ieee_is_finite(block%scalar(temp_field_index))) then
          call fail("native vertical remap scalar output is non-finite")
       end if
       do e = RT,UP
          vector_field_index = (level_slot-1)*EDGE*n_node + &
               EDGE*node_index+e+1
          block%vector(vector_field_index) = flux_new(zlevels-k+1,e)
          if (.not. ieee_is_finite(block%vector(vector_field_index))) then
             call fail("native vertical remap vector output is non-finite")
          end if
       end do
    end do

  end subroutine remap_one_block_vertical_column


  subroutine block_remap_pressure_coordinates ( &
       block,local_index,p,i,j,p_new,p_old)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: i
    integer, intent(in) :: j
    real(dp), intent(out) :: p_new(0:zlevels)
    real(dp), intent(out) :: p_old(0:zlevels)

    integer :: k
    integer :: level_slot
    integer :: mass_field_index
    integer :: mass_slot
    integer :: n_node
    integer :: node_index
    integer :: old_mass_index

    real(dp) :: rho_dz

    mass_slot = S_MASS-block%scalar_variable
    if (mass_slot < 0 .or. mass_slot >= block%n_scalar_variable) then
       call fail("vertical remap pressure scalar layout is invalid")
    end if
    p_old(0) = p_top
    if (i >= 0 .and. i < PATCH_SIZE .and. &
         j >= 0 .and. j < PATCH_SIZE) then
       if (local_index < 1 .or. &
            local_index > size(block_vertical_remap) .or. &
            .not. allocated( &
            block_vertical_remap(local_index)%old_mass)) then
          call fail("vertical remap direct pressure storage is invalid")
       end if
       n_node = size(block%node)
       node_index = block%patch(p)%elts_start+PATCH_SIZE*j+i
       if (node_index < 0 .or. node_index >= n_node) then
          call fail("vertical remap direct pressure node is invalid")
       end if
       do k = 1,zlevels
          level_slot = zlevels-k+1-block%field_level+1
          old_mass_index = (level_slot-1)*n_node+node_index+1
          mass_field_index = &
               (mass_slot*block%n_field_level+level_slot-1)* &
               n_node+node_index+1
          if (old_mass_index < 1 .or. old_mass_index > size( &
               block_vertical_remap(local_index)%old_mass) .or. &
               mass_field_index < 1 .or. &
               mass_field_index > size(block%scalar_mean)) then
             call fail("vertical remap direct pressure address is invalid")
          end if
          rho_dz = block_vertical_remap(local_index)% &
               old_mass(old_mass_index)+ &
               block%scalar_mean(mass_field_index)
          if (.not. ieee_is_finite(rho_dz)) then
             call fail("vertical remap direct pressure mass is non-finite")
          end if
          p_old(k) = p_old(k-1)+grav_accel*rho_dz
       end do
    else
       do k = 1,zlevels
          level_slot = zlevels-k+1-block%field_level+1
          rho_dz = block_remap_old_mass_value( &
               block,local_index,p,i,j,level_slot) + &
               block_remap_mean_scalar_value( &
               block,local_index,p,mass_slot,level_slot,i,j)
          p_old(k) = p_old(k-1)+grav_accel*rho_dz
       end do
    end if
    p_new = a_vert(zlevels:0:-1) + &
         b_vert(zlevels:0:-1)*p_old(zlevels)

  end subroutine block_remap_pressure_coordinates


  real(dp) function block_remap_old_mass_value ( &
       block,local_index,p,i,j,level_slot) result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: level_slot

    integer :: node
    integer :: record
    integer :: storage_class

    integer :: value_index

    if (level_slot < 1 .or. level_slot > block%n_field_level) then
       call fail("native vertical remap old-mass level is invalid")
    end if
    call locate_block_scalar_record( &
         block,local_index,p,i,j,storage_class,record,node,.true.)
    if (storage_class == STORE_PATCH) then
       value_index = (level_slot-1)*size(block%node) + &
            block%patch(record+1)%elts_start+node+1
       if (value_index < 1 .or. value_index > size( &
            block_vertical_remap(local_index)%old_mass)) then
          call fail("native vertical remap old-mass address is invalid")
       end if
       value = block_vertical_remap(local_index)%old_mass(value_index)
    else
       value = block_scalar_family_value( &
            block,local_index,p,S_MASS-block%scalar_variable, &
            level_slot,i,j,BLOCK_PAYLOAD_SOL,.true.)
    end if
    if (.not. ieee_is_finite(value)) then
       call fail("native vertical remap old mass is non-finite")
    end if

  end function block_remap_old_mass_value


  real(dp) function block_remap_mean_scalar_value ( &
       block,local_index,p,scalar_slot,level_slot,i,j) result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j

    integer :: field_index
    integer :: n_storage_node
    integer :: node
    integer :: node_index
    integer :: record
    integer :: storage_class

    value = 0.0_dp
    if (scalar_slot < 0 .or. &
         scalar_slot >= block%n_scalar_variable .or. &
         level_slot < 1 .or. level_slot > block%n_field_level) then
       call fail("native vertical remap mean field is invalid")
    end if
    call locate_block_scalar_record( &
         block,local_index,p,i,j,storage_class,record,node,.true.)
    select case (storage_class)
    case (STORE_PATCH)
       n_storage_node = size(block%node)
       node_index = block%patch(record+1)%elts_start+node
       field_index = &
            (scalar_slot*block%n_field_level+level_slot-1)* &
            n_storage_node+node_index+1
       if (field_index < 1 .or. &
            field_index > size(block%scalar_mean)) then
          call fail("native vertical remap patch mean is invalid")
       end if
       value = block%scalar_mean(field_index)
    case (STORE_BDRY)
       n_storage_node = size(block%bdry_node)
       field_index = &
            (scalar_slot*block%n_field_level+level_slot-1)* &
            n_storage_node+node+1
       if (field_index < 1 .or. &
            field_index > size(block%bdry_scalar_mean)) then
          call fail("native vertical remap boundary mean is invalid")
       end if
       value = block%bdry_scalar_mean(field_index)
    case (STORE_GHOST)
       n_storage_node = size(block%ghost_node)
       field_index = &
            (scalar_slot*block%n_field_level+level_slot-1)* &
            n_storage_node+node+1
       if (field_index < 1 .or. &
            field_index > size(block%ghost_scalar_mean)) then
          call fail("native vertical remap ghost mean is invalid")
       end if
       value = block%ghost_scalar_mean(field_index)
    case default
       call fail("native vertical remap mean storage is invalid")
    end select
    if (.not. ieee_is_finite(value)) then
       call fail("native vertical remap mean value is non-finite")
    end if

  end function block_remap_mean_scalar_value


  subroutine build_parallel_block_catalog
  ! Construct the parallel-block decomposition of all locally owned
  ! geometric root domains, build the replicated global block catalogue,
  ! and assign the target block owners using load balancing.
  !
  ! Rule:
  !   - if root patch 1 has all four children, use those four child
  !     subtrees as candidate blocks;
  !   - otherwise keep the whole root domain as one candidate block.
  !
  ! This routine does not modify the active geometric-domain storage.

  implicit none

  integer, parameter :: N_BLOCK_DATA = 6

  integer :: b, c, d, i, k, p, p_chd, r
  integer :: n_block_local, n_block_before, n_block_total
  integer :: n_data_local, n_data_total
  integer :: n_assigned, n_changed
  integer :: ierr

  integer, allocatable :: block_count(:)
  integer, allocatable :: recv_count(:)
  integer, allocatable :: recv_disp(:)
  integer, allocatable :: send_data(:)
  integer, allocatable :: recv_data(:)
  integer, allocatable :: domain_count(:)

  integer, allocatable :: block_owner_new(:)
  integer, allocatable :: load_current(:)
  integer, allocatable :: load_proposed(:)

  real(dp) :: balanced_weight
  real(dp) :: imbalance_goal

  logical :: detailed_diagnostics

  real(dp), parameter :: init_goal = 0.05_dp
  real(dp), parameter :: incr_goal = 1.20_dp

  type(Parallel_Block), allocatable :: block_loc(:)

  if (local_block_store_ready()) then
     call fail("existing local block store was not reset")
  end if

  !
  ! Count local candidate blocks.
  !
  n_block_local = 0

  do d = 1, size(grid)

     p = 1

     if (all(grid(d)%patch%elts(p+1)%children > 0)) then
        n_block_local = n_block_local + N_CHDRN
     else
        n_block_local = n_block_local + 1
     end if

  end do

  allocate(block_loc(n_block_local))

  !
  ! Construct local candidate block descriptors.
  !
  i = 0

  do d = 1, size(grid)

     p = 1

     if (all(grid(d)%patch%elts(p+1)%children > 0)) then

        do c = 1, N_CHDRN

           p_chd = grid(d)%patch%elts(p+1)%children(c)

           i = i + 1

           block_loc(i)%root_domain = glo_id(rank+1,d)
           block_loc(i)%root_patch  = p_chd
           block_loc(i)%level       = grid(d)%patch%elts(p_chd+1)%level
           block_loc(i)%owner       = rank
           block_loc(i)%weight      = &
                subtree_weight_Domain(grid(d), p_chd)

        end do

     else

        i = i + 1

        block_loc(i)%root_domain = glo_id(rank+1,d)
        block_loc(i)%root_patch  = p
        block_loc(i)%level       = grid(d)%patch%elts(p+1)%level
        block_loc(i)%owner       = rank
        block_loc(i)%weight      = &
             subtree_weight_Domain(grid(d), p)

     end if

  end do

  if (i /= n_block_local) then
     error stop &
          "build_parallel_block_catalog: local block count mismatch"
  end if

  !
  ! Determine the number of candidate blocks preceding those on
  ! this rank. This gives globally unique contiguous block IDs.
  !
  n_block_before = 0

  call MPI_Exscan( &
       n_block_local, n_block_before, &
       1, MPI_INTEGER, MPI_SUM, comm, ierr)

  if (ierr /= MPI_SUCCESS) then
     error stop "build_parallel_block_catalog: MPI_Exscan failed"
  end if

  if (rank == 0) n_block_before = 0

  !
  ! Determine the total number of candidate blocks.
  !
  call MPI_Allreduce( &
       n_block_local, n_block_total, &
       1, MPI_INTEGER, MPI_SUM, comm, ierr)

  if (ierr /= MPI_SUCCESS) then
     error stop "build_parallel_block_catalog: MPI_Allreduce failed"
  end if

  !
  ! Assign global candidate-block IDs.
  !
  do i = 1, n_block_local
     block_loc(i)%id = n_block_before + i - 1
  end do

  !
  ! Determine how many candidate blocks are contributed by every rank.
  !
  allocate(block_count(n_process))

  call MPI_Allgather( &
       n_block_local, 1, MPI_INTEGER, &
       block_count, 1, MPI_INTEGER, comm, ierr)

  if (ierr /= MPI_SUCCESS) then
     error stop "build_parallel_block_catalog: MPI_Allgather failed"
  end if

  if (sum(block_count) /= n_block_total) then
     error stop &
          "build_parallel_block_catalog: inconsistent global block count"
  end if

  !
  ! Pack each local candidate block as six integers:
  !
  !   id, root_domain, root_patch, level, owner, weight
  !
  n_data_local = N_BLOCK_DATA * n_block_local

  allocate(send_data(n_data_local))

  k = 0

  do i = 1, n_block_local

     send_data(k+1:k+N_BLOCK_DATA) = [ &
          block_loc(i)%id, &
          block_loc(i)%root_domain, &
          block_loc(i)%root_patch, &
          block_loc(i)%level, &
          block_loc(i)%owner, &
          block_loc(i)%weight ]

     k = k + N_BLOCK_DATA

  end do

  if (k /= n_data_local) then
     error stop &
          "build_parallel_block_catalog: local packing count mismatch"
  end if

  !
  ! Construct Allgatherv receive counts and displacements.
  !
  allocate(recv_count(n_process))
  allocate(recv_disp(n_process))

  recv_count = N_BLOCK_DATA * block_count

  recv_disp(1) = 0

  do i = 2, n_process
     recv_disp(i) = recv_disp(i-1) + recv_count(i-1)
  end do

  n_data_total = N_BLOCK_DATA * n_block_total

  allocate(recv_data(n_data_total))

  !
  ! Every rank receives the complete packed candidate-block catalogue.
  !
  call MPI_Allgatherv( &
       send_data, n_data_local, MPI_INTEGER, &
       recv_data, recv_count, recv_disp, MPI_INTEGER, &
       comm, ierr)

  if (ierr /= MPI_SUCCESS) then
     error stop "build_parallel_block_catalog: MPI_Allgatherv failed"
  end if

  !
  ! Construct the global Parallel_Block catalogue on every rank.
  !
  if (allocated(block_catalog)) deallocate(block_catalog)

  allocate(block_catalog(n_block_total))

  do i = 1, n_block_total

     k = N_BLOCK_DATA * (i-1)

     block_catalog(i)%id          = recv_data(k+1)
     block_catalog(i)%root_domain = recv_data(k+2)
     block_catalog(i)%root_patch  = recv_data(k+3)
     block_catalog(i)%level       = recv_data(k+4)
     block_catalog(i)%owner       = recv_data(k+5)
     block_catalog(i)%weight      = recv_data(k+6)

  end do

  !
  ! Validate global block IDs and owners.
  !
  do i = 1, n_block_total

     if (block_catalog(i)%id /= i-1) then
        error stop &
             "build_parallel_block_catalog: invalid global block ID ordering"
     end if

     if (block_catalog(i)%owner < 0 .or. &
          block_catalog(i)%owner >= n_process) then
        error stop &
             "build_parallel_block_catalog: invalid block owner"
     end if

  end do

  !
  ! Verify that every geometric root domain occurs in the catalogue.
  ! With the current one-level split rule, each domain should occur
  ! either once or four times.
  !
  allocate(domain_count(N_GLO_DOMAIN))
  domain_count = 0

  do i = 1, n_block_total

     if (block_catalog(i)%root_domain < 0 .or. &
          block_catalog(i)%root_domain >= N_GLO_DOMAIN) then
        error stop &
             "build_parallel_block_catalog: invalid root domain"
     end if

     domain_count(block_catalog(i)%root_domain+1) = &
          domain_count(block_catalog(i)%root_domain+1) + 1

  end do

  if (any(domain_count == 0)) then
     error stop &
          "build_parallel_block_catalog: one or more root domains missing"
  end if

  if (any(domain_count /= 1 .and. domain_count /= N_CHDRN)) then
     error stop &
          "build_parallel_block_catalog: invalid number of blocks per root domain"
  end if

  !
  ! ---------------------------------------------------------------
  ! Compute the target load balancing of candidate parallel blocks.
  ! ---------------------------------------------------------------
  !
  ! This does not change actual ownership.
  !
  allocate(block_owner_new(n_block_total))
  allocate(load_current(n_process))
  allocate(load_proposed(n_process))

  block_owner_new = -1
  load_current     = 0
  load_proposed    = 0

  !
  ! Current load implied by the existing domain decomposition.
  !
  do b = 1, n_block_total

     r = block_catalog(b)%owner + 1

     if (r < 1 .or. r > n_process) then
        error stop &
             "build_parallel_block_catalog: invalid current block owner"
     end if

     load_current(r) = load_current(r) + block_catalog(b)%weight

  end do

  !
  ! Ideal average load per MPI rank.
  !
  balanced_weight = &
       real(sum(block_catalog%weight), kind=dp) / &
       real(n_process, kind=dp)

  !
  ! Use the same next-fit strategy as distribute_grid(), but apply it
  ! only to the prospective candidate blocks.
  !
  n_assigned     = 0
  imbalance_goal = init_goal

  do while (n_assigned < n_block_total)

     n_assigned      = 0
     load_proposed   = 0
     block_owner_new = -1

     do r = 1, n_process

        do while ( &
             real(load_proposed(r),kind=dp) < balanced_weight .and. &
             n_block_total - n_assigned > n_process - r)

           block_owner_new(n_assigned+1) = r - 1

           load_proposed(r) = load_proposed(r) + &
                block_catalog(n_assigned+1)%weight

           n_assigned = n_assigned + 1

        end do

        !
        ! If the final block makes this rank too heavy,
        ! move that block to the next rank.
        !
        if (n_assigned > 0) then

           if (real(load_proposed(r),kind=dp) > &
                balanced_weight * (1.0_dp + imbalance_goal)) then

              load_proposed(r) = load_proposed(r) - &
                   block_catalog(n_assigned)%weight

              block_owner_new(n_assigned) = -1

              n_assigned = n_assigned - 1

           end if

        end if

     end do

     !
     ! If all blocks could not be assigned, relax the allowed imbalance.
     !
     if (n_assigned < n_block_total) then
        imbalance_goal = imbalance_goal * incr_goal
     end if

  end do

  if (any(block_owner_new < 0)) then
     error stop &
          "build_parallel_block_catalog: one or more candidate blocks unassigned"
  end if

  !
  ! Independently reconstruct proposed rank loads from the owner map.
  !
  load_proposed = 0

  do b = 1, n_block_total

     r = block_owner_new(b) + 1

     if (r < 1 .or. r > n_process) then
        error stop &
             "build_parallel_block_catalog: invalid proposed block owner"
     end if

     load_proposed(r) = load_proposed(r) + block_catalog(b)%weight

  end do

  n_changed = count(block_owner_new /= block_catalog%owner)

  !
  ! Commit the prospective balanced ownership to the global block
  ! catalogue. The current source-domain owner remains available through
  ! owner(root_domain+1).
  !
  block_catalog%owner = block_owner_new

  !
  ! Validate the committed target owners.
  !
  if (any(block_catalog%owner < 0) .or. &
       any(block_catalog%owner >= n_process)) then

     error stop &
          "build_parallel_block_catalog: invalid committed block owner"

  end if

  !
  ! Print the detailed load-balancing report only when explicitly requested.
  !
  detailed_diagnostics = block_detailed_diagnostics_enabled()
  if (detailed_diagnostics .and. rank == 0) then

     write(6,'(/,a,i0)') &
          "Total candidate parallel blocks = ", n_block_total

     write(6,'(a,i0)') &
          "Unsplit root domains = ", count(domain_count == 1)

     write(6,'(a,i0)') &
          "Split root domains   = ", count(domain_count == N_CHDRN)

     write(6,'(/,a)') &
          "Current candidate-block load:"

     write(6,'(a,i0)') &
          "  minimum = ", minval(load_current)

     write(6,'(a,f10.2)') &
          "  average = ", balanced_weight

     write(6,'(a,i0)') &
          "  maximum = ", maxval(load_current)

     write(6,'(a,f10.4)') &
          "  max/avg = ", &
          real(maxval(load_current),kind=dp) / balanced_weight

     write(6,'(/,a)') &
          "Prospective balanced block load:"

     write(6,'(a,i0)') &
          "  minimum = ", minval(load_proposed)

     write(6,'(a,f10.2)') &
          "  average = ", balanced_weight

     write(6,'(a,i0)') &
          "  maximum = ", maxval(load_proposed)

     write(6,'(a,f10.4)') &
          "  max/avg = ", &
          real(maxval(load_proposed),kind=dp) / balanced_weight

     write(6,'(a,i0,a,i0,/)') &
          "Blocks changing owner = ", n_changed, &
          " / ", n_block_total

  end if

  !
  ! Cleanup temporary arrays.
  !
  deallocate(block_loc)
  deallocate(block_count)
  deallocate(recv_count)
  deallocate(recv_disp)
  deallocate(send_data)
  deallocate(recv_data)
  deallocate(domain_count)

  deallocate(block_owner_new)
  deallocate(load_current)
  deallocate(load_proposed)

end subroutine build_parallel_block_catalog


  subroutine capture_parallel_block_allocation_snapshot (snapshot)

    implicit none

    integer(int64), intent(out) :: snapshot( &
         BLOCK_PERSISTENT_ALLOCATION_COUNT)

    snapshot(1) = ghost_exchange_plan%allocation_count
    snapshot(2) = block_writeback_plan_allocation_count()
    snapshot(3) = block_writeback_plan%stage_allocations
    snapshot(4) = block_adaptation_exchange%allocation_count
    snapshot(5) = block_vertical_remap_allocations
    snapshot(6) = local_block_tendency_allocation_count()
    snapshot(7) = local_block_tendency_import_allocation_count()
    snapshot(8) = local_block_tendency_accumulator_allocation_count()
    snapshot(9) = local_block_hydrostatic_allocation_count()

  end subroutine capture_parallel_block_allocation_snapshot


  subroutine assert_parallel_block_allocation_stability
    ! Enforce allocation-free steady timesteps. Every topology transition
    ! establishes a new baseline during production-state preparation.

    implicit none

    integer(int64) :: current(BLOCK_PERSISTENT_ALLOCATION_COUNT)

    logical :: state_ready

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) &
         call fail("allocation stability check before block readiness")
    if (.not. block_allocation_baseline_ready) &
         call fail("allocation stability baseline is unavailable")
    if (block_allocation_baseline_generation /= &
         block_writeback_plan_generation) &
         call fail("allocation stability baseline is stale")

    call capture_parallel_block_allocation_snapshot(current)
    if (any(current /= block_allocation_baseline)) &
         call fail("persistent workspace reallocated without topology change")

  end subroutine assert_parallel_block_allocation_stability


  subroutine prepare_parallel_block_production_state (report)
    ! Establish the non-optional state required by the first production
    ! tendency independently of the exhaustive migration validation suite.
    ! A repeated call proves that unchanged topology reuses every persistent
    ! tendency workspace and the hydrostatic cache.

    implicit none

    logical, optional, intent(in) :: report

    integer(int64) :: accumulator_allocations
    integer(int64) :: accumulator_allocations_after
    integer(int64) :: adaptation_allocations
    integer(int64) :: adaptation_allocations_after
    integer(int64) :: ghost_allocations
    integer(int64) :: ghost_allocations_after
    integer(int64) :: hydrostatic_allocations
    integer(int64) :: hydrostatic_allocations_after
    integer(int64) :: hydrostatic_refreshes
    integer(int64) :: hydrostatic_refreshes_after
    integer(int64) :: import_allocations
    integer(int64) :: import_allocations_after
    integer(int64) :: remap_allocations
    integer(int64) :: remap_allocations_after
    integer(int64) :: tendency_allocations
    integer(int64) :: tendency_allocations_after
    integer(int64) :: writeback_allocations
    integer(int64) :: writeback_allocations_after

    logical :: hydrostatic_ready
    logical :: print_summary
    logical :: state_ready

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) &
         call fail("production preparation before block state is ready")

    if (compressible) then
       call ensure_local_block_hydrostatic_state
       hydrostatic_ready = local_block_hydrostatic_state_ready()
       if (.not. hydrostatic_ready) &
            call fail("production hydrostatic state is not ready")
    end if

    call prepare_local_block_tendency_workspace
    call prepare_block_adaptation_decision_storage
    if (compressible) call prepare_block_vertical_remap_workspace

    hydrostatic_allocations = &
         local_block_hydrostatic_allocation_count()
    hydrostatic_refreshes = local_block_hydrostatic_refresh_count()
    tendency_allocations = local_block_tendency_allocation_count()
    import_allocations = &
         local_block_tendency_import_allocation_count()
    accumulator_allocations = &
         local_block_tendency_accumulator_allocation_count()
    ghost_allocations = ghost_exchange_plan%allocation_count
    writeback_allocations = block_writeback_plan_allocation_count()
    adaptation_allocations = block_adaptation_exchange%allocation_count
    remap_allocations = block_vertical_remap_allocations

    call build_block_ghost_exchange_plan
    call build_block_writeback_plan
    call prepare_block_adaptation_decision_storage
    if (compressible) then
       call ensure_local_block_hydrostatic_state
       call prepare_block_vertical_remap_workspace
    end if
    call prepare_local_block_tendency_workspace

    hydrostatic_allocations_after = &
         local_block_hydrostatic_allocation_count()
    hydrostatic_refreshes_after = &
         local_block_hydrostatic_refresh_count()
    tendency_allocations_after = local_block_tendency_allocation_count()
    import_allocations_after = &
         local_block_tendency_import_allocation_count()
    accumulator_allocations_after = &
         local_block_tendency_accumulator_allocation_count()
    ghost_allocations_after = ghost_exchange_plan%allocation_count
    writeback_allocations_after = block_writeback_plan_allocation_count()
    adaptation_allocations_after = &
         block_adaptation_exchange%allocation_count
    remap_allocations_after = block_vertical_remap_allocations

    if (hydrostatic_allocations_after /= hydrostatic_allocations .or. &
         hydrostatic_refreshes_after /= hydrostatic_refreshes) &
         call fail("production hydrostatic workspace was not reusable")
    if (tendency_allocations_after /= tendency_allocations .or. &
         import_allocations_after /= import_allocations .or. &
         accumulator_allocations_after /= accumulator_allocations) &
         call fail("production tendency workspace was not reusable")
    if (ghost_allocations_after /= ghost_allocations .or. &
         writeback_allocations_after /= writeback_allocations .or. &
         adaptation_allocations_after /= adaptation_allocations .or. &
         remap_allocations_after /= remap_allocations) &
         call fail("production communication workspace was not reusable")

    call capture_parallel_block_allocation_snapshot( &
         block_allocation_baseline)
    block_allocation_baseline_generation = &
         block_writeback_plan_generation
    block_allocation_baseline_ready = .true.

    print_summary = .false.
    if (present(report)) print_summary = report
    if (print_summary .and. &
         .not. production_state_preparation_reported .and. rank == 0) then
       write(6,'(a)') "Parallel-block production state preparation passed"
       if (compressible) &
            write(6,'(a)') "  hydrostatic cache prepared and reused"
       write(6,'(a)') &
            "  tendency/import/accumulator workspaces prepared and reused"
       write(6,'(a)') &
            "  ghost/writeback/adaptation/remap storage prepared and reused"
    end if
    if (print_summary) production_state_preparation_reported = .true.

  end subroutine prepare_parallel_block_production_state


  subroutine migrate_blocks (verbose,full_validation)
    ! Migrate the source-local blocks to their final catalogue owners,
    ! install a self-contained local block store, and release all
    ! source, receive and MPI migration staging storage. The complete
    ! diagnostic suite remains the default; production reconstruction may
    ! request only the checks required to establish a ready persistent state.

    implicit none

    logical, optional, intent(in) :: full_validation
    logical, optional, intent(in) :: verbose

    type(Block_Migration_Manifest) :: manifest

    integer :: b
    integer :: expected_local
    integer :: i
    integer :: ib
    integer :: n_recv_byte
    integer :: n_received
    integer :: n_send_byte
    integer :: n_sent
    integer :: nbyte
    integer :: pos

    integer, allocatable :: local_seen(:)
    integer, allocatable :: seen_catalog(:)
    integer, allocatable :: seen_source(:)
    integer, allocatable :: send_nbyte(:)

    integer(int8), allocatable :: block_buffer(:)
    integer(int8), allocatable :: send_payload(:)

    logical :: print_local
    logical :: run_full_validation

    print_local = .true.
    if (present(verbose)) print_local = verbose
    run_full_validation = .true.
    if (present(full_validation)) then
       run_full_validation = full_validation
    end if

    if (.not. allocated(block_source) .or. &
         .not. allocated(block_source_catalog_index) .or. &
         .not. allocated(block_migrating_source_index)) then
       call fail("source block store is incomplete")
    end if

    if (size(block_source_catalog_index) /= size(block_source)) then
       call fail("source block catalogue map has the wrong extent")
    end if

    call build_block_migration_manifest(manifest)
    call check_block_migration_manifest(manifest,print_local)

    if (manifest%n_send /= size(block_migrating_source_index)) then
       call fail("manifest and source migration counts differ")
    end if

    allocate(send_nbyte(manifest%n_send))
    allocate(seen_source(size(block_source)))

    send_nbyte = 0
    seen_source = 0

    do i = 1, manifest%n_send

       b = manifest%send_block(i)
       ib = findloc(block_source_catalog_index,b,dim=1)

       if (ib < 1 .or. ib > size(block_source)) then
          call fail("manifest source block was not constructed locally")
       end if

       if (findloc(block_migrating_source_index,ib,dim=1) < 1) then
          call fail("manifest source block is not marked for migration")
       end if

       if (seen_source(ib) /= 0) then
          call fail("source block occurs more than once in manifest")
       end if

       send_nbyte(i) = packed_block_nbyte(block_source(ib))

       if (send_nbyte(i) <= 0) then
          call fail("source block has an invalid packed byte count")
       end if

       seen_source(ib) = 1

    end do

    do i = 1, size(block_migrating_source_index)

       ib = block_migrating_source_index(i)

       if (ib < 1 .or. ib > size(block_source)) then
          call fail("migrating source index is invalid")
       end if

       if (seen_source(ib) /= 1) then
          call fail("migrating source block is absent from manifest")
       end if

    end do

    call exchange_block_migration_sizes( &
         manifest,send_nbyte,print_local)

    if (manifest%total_send_nbyte > int(huge(0),int64) .or. &
         manifest%total_recv_nbyte > int(huge(0),int64)) then
       call fail("packed migration size exceeds default integer range")
    end if

    n_send_byte = int(manifest%total_send_nbyte)
    n_recv_byte = int(manifest%total_recv_nbyte)

    allocate(send_payload(max(1,n_send_byte)))
    send_payload = 0_int8
    pos = 0

    do i = 1, manifest%n_send

       b = manifest%send_block(i)
       ib = findloc(block_source_catalog_index,b,dim=1)

       if (ib < 1 .or. ib > size(block_source)) then
          call fail("source block disappeared before packing")
       end if

       call pack_block(block_source(ib),block_buffer)

       if (size(block_buffer) /= manifest%send_nbyte(i)) then
          call fail("source block packed size changed")
       end if

       nbyte = size(block_buffer)

       if (pos+nbyte > n_send_byte) then
          call fail("outgoing packed payload exceeds its buffer")
       end if

       send_payload(pos+1:pos+nbyte) = block_buffer
       pos = pos + nbyte

    end do

    if (pos /= n_send_byte) then
       call fail("outgoing packed payload has the wrong extent")
    end if

    call exchange_block_migration_payloads( &
         manifest,send_payload,print_local)

    if (allocated(block_received)) deallocate(block_received)
    if (allocated(block_received_catalog_index)) then
       deallocate(block_received_catalog_index)
    end if

    allocate(block_received(manifest%n_recv))
    allocate(block_received_catalog_index(manifest%n_recv))
    allocate(seen_catalog(size(block_catalog)))

    block_received_catalog_index = -1
    seen_catalog = 0
    pos = 0

    do i = 1, manifest%n_recv

       b = manifest%recv_block(i)
       nbyte = manifest%recv_nbyte(i)

       if (b < 1 .or. b > size(block_catalog)) then
          call fail("received block catalogue index is invalid")
       end if

       if (seen_catalog(b) /= 0) then
          call fail("received block occurs more than once")
       end if

       if (block_catalog(b)%owner /= rank) then
          call fail("received block has the wrong final owner")
       end if

       if (nbyte <= 0 .or. pos+nbyte > n_recv_byte) then
          call fail("received packed block extent is invalid")
       end if

       call unpack_block( &
            manifest%recv_payload(pos+1:pos+nbyte), &
            block_received(i))

       if (block_received(i)%id /= block_catalog(b)%id .or. &
            block_received(i)%root_domain /= &
            block_catalog(b)%root_domain .or. &
            block_received(i)%root_patch /= &
            block_catalog(b)%root_patch .or. &
            block_received(i)%level /= block_catalog(b)%level) then
          call fail("received block identity does not match catalogue")
       end if

       call check_block_storage(block_received(i),.true.)

       block_received_catalog_index(i) = b
       seen_catalog(b) = 1
       pos = pos + nbyte

    end do

    if (pos /= n_recv_byte) then
       call fail("received packed payload has the wrong extent")
    end if

    if (count(seen_catalog /= 0) /= manifest%n_recv) then
       call fail("received block inventory is incomplete")
    end if

    call install_local_blocks(size(block_catalog),local_seen)

    expected_local = 0

    do b = 1, size(block_catalog)
       if (block_catalog(b)%owner == rank) then
          expected_local = expected_local + 1
          if (local_seen(b) /= 1) then
             call fail("owned block is absent from installed store")
          end if
       else
          if (local_seen(b) /= 0) then
             call fail("nonlocal block appears in installed store")
          end if
       end if
    end do

    if (n_local_blocks() /= expected_local) then
       call fail("installed block count does not match final ownership")
    end if

    if (run_full_validation) then
       call check_block_boundary_routes(print_local)
       call check_block_ghost_source_addresses(print_local)
       call check_block_ghost_request_manifest(print_local)
       call build_block_ghost_exchange_plan
       call check_block_ghost_exchange_plan(print_local)
       call build_block_writeback_plan
       call check_block_writeback_plan(print_local)
       call check_block_writeback_payload_exchange(print_local)
       call check_block_scalar_ghost_payload_exchange(print_local)
       call check_block_vector_ghost_payload_exchange(print_local)
       call check_production_block_ghost_refresh(print_local)
    else
       call build_block_ghost_exchange_plan
       call build_block_writeback_plan
    end if

    n_sent     = manifest%n_send
    n_received = manifest%n_recv
    migration_send_peer_count = &
         int(count(manifest%send_count > 0),int64)
    migration_recv_peer_count = &
         int(count(manifest%recv_count > 0),int64)
    migration_send_block_count = int(n_sent,int64)
    migration_recv_block_count = int(n_received,int64)
    migration_send_byte_count = manifest%total_send_nbyte
    migration_recv_byte_count = manifest%total_recv_nbyte
    call record_parallel_block_profile_volume( &
         BLOCK_PROFILE_TOPOLOGY,migration_send_peer_count, &
         migration_send_byte_count,migration_send_block_count)

    call clear_block_staging
    call clear_block_migration_manifest(manifest)

    if (print_local) then
       write(6,'(/,a,i0,a)') &
            "Completed block migration for rank ", rank, ":"
       write(6,'(a,i0)') "  blocks sent      = ", n_sent
       write(6,'(a,i0)') "  blocks received  = ", n_received
       write(6,'(a,i0)') &
            "  blocks installed = ", n_local_blocks()
       write(6,'(a,/)') &
            "  migration staging storage released"
    end if

    deallocate(local_seen)
    deallocate(seen_catalog)
    deallocate(seen_source)
    deallocate(send_nbyte)
    deallocate(send_payload)

    call prepare_parallel_block_production_state(.false.)

    if (run_full_validation) then
       call check_local_blocks(print_local)
       call check_block_field_inventory(print_local)
       call check_parallel_block_lifecycle(print_local)
       if (compressible) call ensure_local_block_hydrostatic_state
       call check_block_hydrostatic_reconstruction(print_local)

       ! Validation routines deliberately exercise invalidation and rollback.
       ! Restore the same clean production state before returning to the
       ! timestep driver. Production-equivalent runs need no second preparation.
       call prepare_parallel_block_production_state(print_local)
    end if
    if (run_full_validation .or. print_local) &
         call check_parallel_block_scaling(print_local)

  end subroutine migrate_blocks


  subroutine check_block_scalar_stencil_consumer (verbose)
    ! Compare a read-only traversal of every scalar compact-stencil window
    ! before migration with the installed final-owner block store. This is
    ! the first persistent-store consumer of patch, boundary and ghost
    ! addressing across every scalar variable and represented level.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: field_kind
    integer :: ierr

    integer(int64) :: source_address_local(3)
    integer(int64) :: source_address_global(3)
    integer(int64) :: local_address_local(3)
    integer(int64) :: local_address_global(3)
    integer(int64) :: source_value_local
    integer(int64) :: source_value_global
    integer(int64) :: local_value_local
    integer(int64) :: local_value_global

    real(dp) :: source_moment_local(3,3)
    real(dp) :: source_moment_global(3,3)
    real(dp) :: local_moment_local(3,3)
    real(dp) :: local_moment_global(3,3)

    logical :: print_summary

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    call source_block_scalar_stencil_statistics( &
         source_address_local,source_value_local,source_moment_local)

    call local_block_scalar_stencil_statistics( &
         local_address_local,local_value_local,local_moment_local)

    call MPI_Allreduce( &
         source_address_local,source_address_global,3, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce source stencil addresses")

    call MPI_Allreduce( &
         local_address_local,local_address_global,3, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce final stencil addresses")

    call MPI_Allreduce( &
         source_value_local,source_value_global,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce source stencil values")

    call MPI_Allreduce( &
         local_value_local,local_value_global,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce final stencil values")

    call MPI_Allreduce( &
         source_moment_local,source_moment_global,9, &
         MPI_DOUBLE_PRECISION,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce source stencil moments")

    call MPI_Allreduce( &
         local_moment_local,local_moment_global,9, &
         MPI_DOUBLE_PRECISION,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce final stencil moments")

    if (any(source_address_global /= local_address_global)) then
       if (rank == 0) then
          write(error_unit,'(/,a)') &
               "Source/final scalar-stencil-address mismatch:"
          write(error_unit,'(a,3(i0,1x))') &
               "  source patch/boundary/ghost = ", &
               source_address_global
          write(error_unit,'(a,3(i0,1x))') &
               "  final  patch/boundary/ghost = ", &
               local_address_global
       end if
       call fail("source and final scalar stencil addresses differ")
    end if

    if (source_value_global /= local_value_global) then
       call fail("source and final scalar stencil value counts differ")
    end if

    do field_kind = 1, 3
       if (.not. field_moments_match( &
            source_moment_global(:,field_kind), &
            local_moment_global(:,field_kind), &
            source_value_global)) then

          if (rank == 0) then
             write(error_unit,'(/,a,i0,a)') &
                  "Source/final scalar-stencil moments for field kind ", &
                  field_kind,":"
             write(error_unit,'(a,3(es24.16,1x))') &
                  "  source moments = ", &
                  source_moment_global(:,field_kind)
             write(error_unit,'(a,3(es24.16,1x))') &
                  "  final moments  = ", &
                  local_moment_global(:,field_kind)
          end if

          call fail("source and final scalar stencil moments differ")
       end if
    end do

    if (any(local_address_global <= 0_int64) .or. &
         local_value_global <= 0_int64) then
       call fail("incomplete final-owner scalar stencil inventory")
    end if

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Final-owner scalar stencil consumer for rank ",rank,":"
       write(6,'(a,3(i0,1x))') &
            "  local patch/boundary/ghost addresses = ", &
            local_address_local
       write(6,'(a,i0)') &
            "  local scalar field samples = ",local_value_local
       write(6,'(a,/)') &
            "  source/final scalar stencil checks passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,3(i0,1x))') &
            "Global patch/boundary/ghost stencil addresses = ", &
            local_address_global
       write(6,'(a,i0)') &
            "Global scalar stencil field samples verified = ", &
            local_value_global
       write(6,'(a,3(es24.16,1x))') &
            "Global sol stencil moments verified = ", &
            local_moment_global(:,1)
       write(6,'(a,3(es24.16,1x))') &
            "Global sol_mean stencil moments verified = ", &
            local_moment_global(:,2)
       write(6,'(a,3(es24.16,1x))') &
            "Global wav_coeff stencil moments verified = ", &
            local_moment_global(:,3)
       write(6,'(a,/)') &
            "Final-owner scalar stencil consumer matches source blocks"
    end if

  end subroutine check_block_scalar_stencil_consumer


  subroutine check_block_vector_stencil_consumer (verbose)
    ! Compare a read-only traversal of every vector compact-stencil window
    ! before migration with the installed final-owner block store. Every
    ! stored edge component and represented level is included.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: field_kind
    integer :: ierr

    integer(int64) :: source_address_local(3)
    integer(int64) :: source_address_global(3)
    integer(int64) :: local_address_local(3)
    integer(int64) :: local_address_global(3)
    integer(int64) :: source_value_local
    integer(int64) :: source_value_global
    integer(int64) :: local_value_local
    integer(int64) :: local_value_global

    real(dp) :: source_moment_local(3,3)
    real(dp) :: source_moment_global(3,3)
    real(dp) :: local_moment_local(3,3)
    real(dp) :: local_moment_global(3,3)

    logical :: print_summary

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    call source_block_vector_stencil_statistics( &
         source_address_local,source_value_local,source_moment_local)

    call local_block_vector_stencil_statistics( &
         local_address_local,local_value_local,local_moment_local)

    call MPI_Allreduce( &
         source_address_local,source_address_global,3, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce source vector addresses")

    call MPI_Allreduce( &
         local_address_local,local_address_global,3, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce final vector addresses")

    call MPI_Allreduce( &
         source_value_local,source_value_global,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce source vector values")

    call MPI_Allreduce( &
         local_value_local,local_value_global,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce final vector values")

    call MPI_Allreduce( &
         source_moment_local,source_moment_global,9, &
         MPI_DOUBLE_PRECISION,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce source vector moments")

    call MPI_Allreduce( &
         local_moment_local,local_moment_global,9, &
         MPI_DOUBLE_PRECISION,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce final vector moments")

    if (any(source_address_global /= local_address_global)) then
       if (rank == 0) then
          write(error_unit,'(/,a)') &
               "Source/final vector-stencil-address mismatch:"
          write(error_unit,'(a,3(i0,1x))') &
               "  source patch/boundary/ghost = ", &
               source_address_global
          write(error_unit,'(a,3(i0,1x))') &
               "  final  patch/boundary/ghost = ", &
               local_address_global
       end if
       call fail("source and final vector stencil addresses differ")
    end if

    if (source_value_global /= local_value_global) then
       call fail("source and final vector stencil value counts differ")
    end if

    do field_kind = 1, 3
       if (.not. field_moments_match( &
            source_moment_global(:,field_kind), &
            local_moment_global(:,field_kind), &
            source_value_global)) then

          if (rank == 0) then
             write(error_unit,'(/,a,i0,a)') &
                  "Source/final vector-stencil moments for field kind ", &
                  field_kind,":"
             write(error_unit,'(a,3(es24.16,1x))') &
                  "  source moments = ", &
                  source_moment_global(:,field_kind)
             write(error_unit,'(a,3(es24.16,1x))') &
                  "  final moments  = ", &
                  local_moment_global(:,field_kind)
          end if

          call fail("source and final vector stencil moments differ")
       end if
    end do

    if (any(local_address_global <= 0_int64) .or. &
         local_value_global <= 0_int64) then
       call fail("incomplete final-owner vector stencil inventory")
    end if

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Final-owner vector stencil consumer for rank ",rank,":"
       write(6,'(a,3(i0,1x))') &
            "  local patch/boundary/ghost addresses = ", &
            local_address_local
       write(6,'(a,i0)') &
            "  local vector field samples = ",local_value_local
       write(6,'(a,/)') &
            "  source/final vector stencil checks passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,3(i0,1x))') &
            "Global vector patch/boundary/ghost addresses = ", &
            local_address_global
       write(6,'(a,i0)') &
            "Global vector stencil field samples verified = ", &
            local_value_global
       write(6,'(a,3(es24.16,1x))') &
            "Global velocity stencil moments verified = ", &
            local_moment_global(:,1)
       write(6,'(a,3(es24.16,1x))') &
            "Global mean-velocity stencil moments verified = ", &
            local_moment_global(:,2)
       write(6,'(a,3(es24.16,1x))') &
            "Global wavelet-velocity stencil moments verified = ", &
            local_moment_global(:,3)
       write(6,'(a,/)') &
            "Final-owner vector stencil consumer matches source blocks"
    end if

  end subroutine check_block_vector_stencil_consumer


  subroutine check_refreshed_block_stencil_consumers (verbose)
    ! Both ghost-payload exchanges deliberately poison their destination
    ! storage before installing the requested sol and wav_coeff values.
    ! Re-run the scalar and vector compact-stencil consumers only after
    ! both installations have completed. This verifies that the refreshed
    ! ghost payloads are immediately usable through the same explicit
    ! addressing paths used by block-local numerical kernels.

    implicit none

    logical, optional, intent(in) :: verbose

    logical :: print_summary

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    call check_block_scalar_stencil_consumer(.false.)
    call check_block_vector_stencil_consumer(.false.)

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Refreshed ghost stencil consumers for rank ",rank,":"
       write(6,'(a)') &
            "  scalar compact-stencil reads passed"
       write(6,'(a,/)') &
            "  vector compact-stencil reads passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,/)') &
            "Installed sol/wav_coeff ghost stencil-read checks passed"
    end if

  end subroutine check_refreshed_block_stencil_consumers


  subroutine check_block_boundary_routes (verbose)
    ! Validate the common route catalogue used by update_bdry for scalar,
    ! rank-one and rank-two Float_Field arguments. AT_NODE uses one value
    ! per stored node; AT_EDGE uses EDGE values and the signed receive rule.
    ! This stage validates topology and payload extents but performs no
    ! production boundary exchange and changes no field values.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: ierr

    integer(int64) :: source_link_local(3)
    integer(int64) :: source_link_global(3)
    integer(int64) :: local_link_local(3)
    integer(int64) :: local_link_global(3)
    integer(int64) :: source_storage_local(2)
    integer(int64) :: source_storage_global(2)
    integer(int64) :: local_storage_local(2)
    integer(int64) :: local_storage_global(2)
    integer(int64) :: source_node_local(2)
    integer(int64) :: source_node_global(2)
    integer(int64) :: local_node_local(2)
    integer(int64) :: local_node_global(2)
    integer(int64) :: node_payload_local
    integer(int64) :: node_payload_global
    integer(int64) :: edge_payload_local
    integer(int64) :: edge_payload_global

    logical :: print_summary

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    call source_block_boundary_route_statistics( &
         source_link_local,source_storage_local,source_node_local)
    call local_block_boundary_route_statistics( &
         local_link_local,local_storage_local,local_node_local)

    call MPI_Allreduce( &
         source_link_local,source_link_global,3, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce source boundary links")

    call MPI_Allreduce( &
         local_link_local,local_link_global,3, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce final boundary links")

    call MPI_Allreduce( &
         source_storage_local,source_storage_global,2, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce source boundary storage")

    call MPI_Allreduce( &
         local_storage_local,local_storage_global,2, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce final boundary storage")

    call MPI_Allreduce( &
         source_node_local,source_node_global,2, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce source boundary nodes")

    call MPI_Allreduce( &
         local_node_local,local_node_global,2, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce final boundary nodes")

    if (any(source_link_global /= local_link_global)) then
       call fail("source and final boundary link counts differ")
    end if
    if (any(source_storage_global /= local_storage_global)) then
       call fail("source and final boundary storage counts differ")
    end if
    if (any(source_node_global /= local_node_global)) then
       call fail("source and final boundary node counts differ")
    end if

    if (sum(local_link_global) <= 0_int64 .or. &
         local_link_global(1) <= 0_int64 .or. &
         sum(local_storage_global) <= 0_int64 .or. &
         sum(local_node_global) <= 0_int64) then
       call fail("incomplete final-owner boundary route inventory")
    end if

    node_payload_local  = sum(local_node_local)
    node_payload_global = sum(local_node_global)
    edge_payload_local  = int(EDGE,int64)*node_payload_local
    edge_payload_global = int(EDGE,int64)*node_payload_global

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Generic Float_Field boundary routes for rank ",rank,":"
       write(6,'(a,3(i0,1x))') &
            "  local block/domain/adaptive links = ",local_link_local
       write(6,'(a,2(i0,1x))') &
            "  local ghost/boundary records      = ",local_storage_local
       write(6,'(a,i0)') &
            "  local AT_NODE values per field    = ",node_payload_local
       write(6,'(a,i0)') &
            "  local AT_EDGE values per field    = ",edge_payload_local
       write(6,'(a,/)') &
            "  field-independent boundary route checks passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,3(i0,1x))') &
            "Global block/domain/adaptive boundary links = ", &
            local_link_global
       write(6,'(a,2(i0,1x))') &
            "Global ghost/boundary storage records       = ", &
            local_storage_global
       write(6,'(a,i0)') &
            "Global AT_NODE values per Float_Field       = ", &
            node_payload_global
       write(6,'(a,i0)') &
            "Global AT_EDGE values per Float_Field       = ", &
            edge_payload_global
       write(6,'(a,/)') &
            "Generic Float_Field boundary catalogue matches source blocks"
    end if

  end subroutine check_block_boundary_routes


  subroutine check_block_ghost_source_addresses (verbose)
    ! Validate the compact source patch used to pack every NGB_BLOCK
    ! ghost dynamically. The same address applies to any Float_Field;
    ! field rank controls repetition and field position controls the
    ! one-versus-EDGE value multiplier.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: b
    integer :: i
    integer :: ierr

    integer(int64) :: source_ghost_local
    integer(int64) :: source_ghost_global
    integer(int64) :: local_ghost_local
    integer(int64) :: local_ghost_global
    integer(int64) :: source_value_local(2)
    integer(int64) :: source_value_global(2)
    integer(int64) :: local_value_local(2)
    integer(int64) :: local_value_global(2)
    integer(int64) :: source_sum_local(6)
    integer(int64) :: source_sum_global(6)
    integer(int64) :: local_sum_local(6)
    integer(int64) :: local_sum_global(6)

    integer, allocatable :: catalog_domain(:)
    integer, allocatable :: catalog_id(:)
    integer, allocatable :: catalog_owner(:)
    integer, allocatable :: patch_count_global(:)
    integer, allocatable :: patch_count_local(:)

    logical :: print_summary

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    allocate(catalog_domain(size(block_catalog)))
    allocate(catalog_id(size(block_catalog)))
    allocate(catalog_owner(size(block_catalog)))
    allocate(patch_count_global(size(block_catalog)))
    allocate(patch_count_local(size(block_catalog)))

    patch_count_local = 0

    do b = 1, size(block_catalog)
       catalog_domain(b) = block_catalog(b)%root_domain
       catalog_id(b)     = block_catalog(b)%id
       catalog_owner(b)  = block_catalog(b)%owner
    end do

    do i = 1, size(block_source)
       b = block_source_catalog_index(i)
       if (b < 1 .or. b > size(block_catalog)) then
          call fail("invalid source block catalogue index")
       end if
       if (patch_count_local(b) /= 0) then
          call fail("duplicate source block patch count")
       end if
       patch_count_local(b) = size(block_source(i)%patch)
    end do

    call MPI_Allreduce( &
         patch_count_local,patch_count_global,size(block_catalog), &
         MPI_INTEGER,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce source block patch counts")

    if (any(patch_count_global <= 0)) then
       call fail("incomplete global source block patch counts")
    end if

    call validate_local_block_ghost_sources( &
         patch_count_global,catalog_owner,catalog_id,catalog_domain)

    call source_block_ghost_source_statistics( &
         source_ghost_local,source_value_local,source_sum_local)
    call local_block_ghost_source_statistics( &
         local_ghost_local,local_value_local,local_sum_local)

    call MPI_Allreduce( &
         source_ghost_local,source_ghost_global,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce source ghost count")

    call MPI_Allreduce( &
         local_ghost_local,local_ghost_global,1, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce final ghost count")

    call MPI_Allreduce( &
         source_value_local,source_value_global,2, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce source ghost values")

    call MPI_Allreduce( &
         local_value_local,local_value_global,2, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce final ghost values")

    call MPI_Allreduce( &
         source_sum_local,source_sum_global,6, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce source ghost addresses")

    call MPI_Allreduce( &
         local_sum_local,local_sum_global,6, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce final ghost addresses")

    if (source_ghost_global /= local_ghost_global .or. &
         any(source_value_global /= local_value_global) .or. &
         any(source_sum_global /= local_sum_global)) then
       call fail("source and final ghost source mappings differ")
    end if

    if (local_ghost_global <= 0_int64 .or. &
         local_value_global(1) /= &
         int(PATCH_SIZE**2,int64)*local_ghost_global .or. &
         local_value_global(2) /= &
         int(EDGE,int64)*local_value_global(1)) then
       call fail("invalid dynamic ghost source payload extent")
    end if

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Dynamic Float_Field ghost sources for rank ",rank,":"
       write(6,'(a,i0)') &
            "  local compact source patches = ",local_ghost_local
       write(6,'(a,i0)') &
            "  local AT_NODE values per field = ",local_value_local(1)
       write(6,'(a,i0)') &
            "  local AT_EDGE values per field = ",local_value_local(2)
       write(6,'(a,/)') &
            "  source catalogue and compact-patch checks passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,i0)') &
            "Global dynamically addressable ghost patches = ", &
            local_ghost_global
       write(6,'(a,i0)') &
            "Global AT_NODE inter-block values per field   = ", &
            local_value_global(1)
       write(6,'(a,i0)') &
            "Global AT_EDGE inter-block values per field   = ", &
            local_value_global(2)
       write(6,'(a,/)') &
            "Dynamic Float_Field ghost source mappings match source blocks"
    end if

    deallocate(catalog_domain)
    deallocate(catalog_id)
    deallocate(catalog_owner)
    deallocate(patch_count_global)
    deallocate(patch_count_local)

  end subroutine check_block_ghost_source_addresses


  subroutine clear_block_ghost_exchange_plan
    ! Release field-independent block-ghost routing metadata. The plan is
    ! invalid whenever a checkpoint restart replaces the installed blocks.

    implicit none

    if (allocated(ghost_exchange_plan%source_block)) then
       deallocate(ghost_exchange_plan%source_block)
    end if
    if (allocated(ghost_exchange_plan%source_local_patch)) then
       deallocate(ghost_exchange_plan%source_local_patch)
    end if
    if (allocated(ghost_exchange_plan%source_patch_level)) then
       deallocate(ghost_exchange_plan%source_patch_level)
    end if
    if (allocated(ghost_exchange_plan%source_owner)) then
       deallocate(ghost_exchange_plan%source_owner)
    end if
    if (allocated(ghost_exchange_plan%destination_block)) then
       deallocate(ghost_exchange_plan%destination_block)
    end if
    if (allocated(ghost_exchange_plan%destination_ghost)) then
       deallocate(ghost_exchange_plan%destination_ghost)
    end if
    if (allocated(ghost_exchange_plan%send_record_count)) then
       deallocate(ghost_exchange_plan%send_record_count)
    end if
    if (allocated(ghost_exchange_plan%recv_record_count)) then
       deallocate(ghost_exchange_plan%recv_record_count)
    end if
    if (allocated(ghost_exchange_plan%send_record_displ)) then
       deallocate(ghost_exchange_plan%send_record_displ)
    end if
    if (allocated(ghost_exchange_plan%recv_record_displ)) then
       deallocate(ghost_exchange_plan%recv_record_displ)
    end if
    if (allocated(ghost_exchange_plan%send_data)) then
       deallocate(ghost_exchange_plan%send_data)
    end if
    if (allocated(ghost_exchange_plan%recv_data)) then
       deallocate(ghost_exchange_plan%recv_data)
    end if
    if (allocated(ghost_exchange_plan%request_index)) then
       deallocate(ghost_exchange_plan%request_index)
    end if
    if (allocated(ghost_exchange_plan%local_level_count)) &
         deallocate(ghost_exchange_plan%local_level_count)
    if (allocated(ghost_exchange_plan%local_level_displ)) &
         deallocate(ghost_exchange_plan%local_level_displ)
    if (allocated(ghost_exchange_plan%local_level_request)) &
         deallocate(ghost_exchange_plan%local_level_request)
    if (allocated(ghost_exchange_plan%send_level_count)) &
         deallocate(ghost_exchange_plan%send_level_count)
    if (allocated(ghost_exchange_plan%send_level_displ)) &
         deallocate(ghost_exchange_plan%send_level_displ)
    if (allocated(ghost_exchange_plan%send_level_base)) &
         deallocate(ghost_exchange_plan%send_level_base)
    if (allocated(ghost_exchange_plan%send_level_record)) &
         deallocate(ghost_exchange_plan%send_level_record)
    if (allocated(ghost_exchange_plan%recv_level_count)) &
         deallocate(ghost_exchange_plan%recv_level_count)
    if (allocated(ghost_exchange_plan%recv_level_displ)) &
         deallocate(ghost_exchange_plan%recv_level_displ)
    if (allocated(ghost_exchange_plan%recv_level_base)) &
         deallocate(ghost_exchange_plan%recv_level_base)
    if (allocated(ghost_exchange_plan%recv_level_record)) &
         deallocate(ghost_exchange_plan%recv_level_record)
    if (allocated(ghost_exchange_plan%scalar_send_count)) then
       deallocate(ghost_exchange_plan%scalar_send_count)
    end if
    if (allocated(ghost_exchange_plan%scalar_recv_count)) then
       deallocate(ghost_exchange_plan%scalar_recv_count)
    end if
    if (allocated(ghost_exchange_plan%scalar_send_displ)) then
       deallocate(ghost_exchange_plan%scalar_send_displ)
    end if
    if (allocated(ghost_exchange_plan%scalar_recv_displ)) then
       deallocate(ghost_exchange_plan%scalar_recv_displ)
    end if
    if (allocated(ghost_exchange_plan%vector_send_count)) then
       deallocate(ghost_exchange_plan%vector_send_count)
    end if
    if (allocated(ghost_exchange_plan%vector_recv_count)) then
       deallocate(ghost_exchange_plan%vector_recv_count)
    end if
    if (allocated(ghost_exchange_plan%vector_send_displ)) then
       deallocate(ghost_exchange_plan%vector_send_displ)
    end if
    if (allocated(ghost_exchange_plan%vector_recv_displ)) then
       deallocate(ghost_exchange_plan%vector_recv_displ)
    end if
    if (allocated(ghost_exchange_plan%scalar_send_buffer)) then
       deallocate(ghost_exchange_plan%scalar_send_buffer)
    end if
    if (allocated(ghost_exchange_plan%scalar_recv_buffer)) then
       deallocate(ghost_exchange_plan%scalar_recv_buffer)
    end if
    if (allocated(ghost_exchange_plan%scalar_patch_buffer)) then
       deallocate(ghost_exchange_plan%scalar_patch_buffer)
    end if
    if (allocated(ghost_exchange_plan%vector_send_buffer)) then
       deallocate(ghost_exchange_plan%vector_send_buffer)
    end if
    if (allocated(ghost_exchange_plan%vector_recv_buffer)) then
       deallocate(ghost_exchange_plan%vector_recv_buffer)
    end if
    if (allocated(ghost_exchange_plan%vector_patch_buffer)) then
       deallocate(ghost_exchange_plan%vector_patch_buffer)
    end if

    ghost_exchange_plan%n_request = 0
    ghost_exchange_plan%n_local_request = 0
    ghost_exchange_plan%n_remote_send = 0
    ghost_exchange_plan%n_remote_recv = 0
    ghost_exchange_plan%route_level_start = -1
    ghost_exchange_plan%route_level_count = 0
    ghost_exchange_plan%scalar_n_value = 0
    ghost_exchange_plan%vector_n_value = 0
    ghost_exchange_plan%ready = .false.

  end subroutine clear_block_ghost_exchange_plan


  subroutine build_block_ghost_exchange_plan
    ! Build the request routing once for the installed final-owner block
    ! store. Subsequent scalar and vector field-family refreshes reuse this
    ! plan, its MPI payload buffers and one-patch packing workspaces.

    implicit none

    integer :: destination
    integer :: destination_nghost
    integer :: field_level
    integer :: fill_record
    integer :: i
    integer :: ierr
    integer :: level_count
    integer :: pos
    integer :: r
    integer :: scalar_count
    integer :: scalar_mult
    integer :: scalar_variable
    integer :: source
    integer :: source_npatch
    integer :: vector_mult
    integer :: vector_variable

    integer, allocatable :: fill(:)
    integer, allocatable :: recv_count(:)
    integer, allocatable :: recv_displ(:)
    integer, allocatable :: send_count(:)
    integer, allocatable :: send_displ(:)

    if (ghost_exchange_plan%ready) then
       if (.not. local_block_store_ready()) &
            call fail("ready ghost plan without installed blocks")
       if (.not. allocated(block_catalog)) &
            call fail("ready ghost plan without block catalogue")
       ghost_exchange_plan%reuse_count = &
            ghost_exchange_plan%reuse_count + 1_int64
       return
    end if

    call clear_block_ghost_exchange_plan

    if (.not. local_block_store_ready()) then
       call fail("block ghost exchange plan before block installation")
    end if
    if (.not. allocated(block_catalog)) then
       call fail("block ghost exchange plan without block catalogue")
    end if

    call get_local_block_ghost_requests( &
         ghost_exchange_plan%source_block, &
         ghost_exchange_plan%source_local_patch, &
         ghost_exchange_plan%source_patch_level, &
         ghost_exchange_plan%source_owner, &
         ghost_exchange_plan%destination_block, &
         ghost_exchange_plan%destination_ghost)

    ghost_exchange_plan%n_request = &
         size(ghost_exchange_plan%source_block)

    if (size(ghost_exchange_plan%source_local_patch) /= &
         ghost_exchange_plan%n_request .or. &
         size(ghost_exchange_plan%source_patch_level) /= &
         ghost_exchange_plan%n_request .or. &
         size(ghost_exchange_plan%source_owner) /= &
         ghost_exchange_plan%n_request .or. &
         size(ghost_exchange_plan%destination_block) /= &
         ghost_exchange_plan%n_request .or. &
         size(ghost_exchange_plan%destination_ghost) /= &
         ghost_exchange_plan%n_request) then
       call fail("inconsistent block ghost exchange plan arrays")
    end if
    allocate(ghost_exchange_plan%send_record_count(n_process))
    allocate(ghost_exchange_plan%recv_record_count(n_process))
    allocate(ghost_exchange_plan%send_record_displ(n_process))
    allocate(ghost_exchange_plan%recv_record_displ(n_process))
    allocate(fill(n_process))

    ghost_exchange_plan%send_record_count = 0
    ghost_exchange_plan%n_local_request = 0

    do i = 1, ghost_exchange_plan%n_request
       source = ghost_exchange_plan%source_block(i)
       destination = ghost_exchange_plan%destination_block(i)

       if (source < 1 .or. source > size(block_catalog)) then
          call fail("invalid source block in ghost exchange plan")
       end if
       if (destination < 1 .or. &
            destination > size(block_catalog)) then
          call fail("invalid destination block in ghost exchange plan")
       end if
       if (ghost_exchange_plan%source_owner(i) /= &
            block_catalog(source)%owner) then
          call fail("stale source owner in ghost exchange plan")
       end if
       if (block_catalog(destination)%owner /= rank) then
          call fail("nonlocal destination in ghost exchange plan")
       end if

       destination_nghost = local_block_ghost_count(destination)
       if (ghost_exchange_plan%destination_ghost(i) < 1 .or. &
            ghost_exchange_plan%destination_ghost(i) > &
            destination_nghost) then
          call fail("invalid destination ghost in exchange plan")
       end if

       if (ghost_exchange_plan%source_owner(i) == rank) then
          if (catalog_local_block(source) < 1) then
             call fail("local source block absent from ghost plan")
          end if
          source_npatch = local_block_patch_count(source)
          if (ghost_exchange_plan%source_local_patch(i) < 0 .or. &
               ghost_exchange_plan%source_local_patch(i) >= &
               source_npatch) then
             call fail("invalid local source patch in ghost plan")
          end if
          ghost_exchange_plan%n_local_request = &
               ghost_exchange_plan%n_local_request + 1
          if (ghost_exchange_plan%source_patch_level(i) /= &
               local_block_patch_level( &
               source,ghost_exchange_plan%source_local_patch(i))) then
             call fail("local ghost source patch level differs")
          end if
       else
          r = ghost_exchange_plan%source_owner(i) + 1
          ghost_exchange_plan%send_record_count(r) = &
               ghost_exchange_plan%send_record_count(r) + 1
       end if
    end do

    call MPI_Alltoall( &
         ghost_exchange_plan%send_record_count,1,MPI_INTEGER, &
         ghost_exchange_plan%recv_record_count,1,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoall persistent ghost request counts")

    ghost_exchange_plan%n_remote_send = &
         sum(ghost_exchange_plan%send_record_count)
    ghost_exchange_plan%n_remote_recv = &
         sum(ghost_exchange_plan%recv_record_count)

    ghost_exchange_plan%send_record_displ(1) = 0
    ghost_exchange_plan%recv_record_displ(1) = 0

    do r = 2, n_process
       ghost_exchange_plan%send_record_displ(r) = &
            ghost_exchange_plan%send_record_displ(r-1) + &
            ghost_exchange_plan%send_record_count(r-1)
       ghost_exchange_plan%recv_record_displ(r) = &
            ghost_exchange_plan%recv_record_displ(r-1) + &
            ghost_exchange_plan%recv_record_count(r-1)
    end do

    allocate(ghost_exchange_plan%send_data( &
         BLOCK_GHOST_REQUEST_SIZE*ghost_exchange_plan%n_remote_send))
    allocate(ghost_exchange_plan%recv_data( &
         BLOCK_GHOST_REQUEST_SIZE*ghost_exchange_plan%n_remote_recv))
    allocate(ghost_exchange_plan%request_index( &
         ghost_exchange_plan%n_remote_send))

    fill = 0

    do i = 1, ghost_exchange_plan%n_request
       if (ghost_exchange_plan%source_owner(i) == rank) cycle

       r = ghost_exchange_plan%source_owner(i) + 1
       pos = BLOCK_GHOST_REQUEST_SIZE*( &
            ghost_exchange_plan%send_record_displ(r)+fill(r))
       ghost_exchange_plan%send_data( &
            pos+1:pos+BLOCK_GHOST_REQUEST_SIZE) = [ &
            ghost_exchange_plan%source_block(i), &
            ghost_exchange_plan%source_local_patch(i), &
            ghost_exchange_plan%destination_block(i), &
            ghost_exchange_plan%destination_ghost(i), &
            ghost_exchange_plan%source_patch_level(i) ]
       fill_record = ghost_exchange_plan%send_record_displ(r) + &
            fill(r) + 1
       ghost_exchange_plan%request_index(fill_record) = i
       fill(r) = fill(r) + 1
    end do

    if (any(fill /= ghost_exchange_plan%send_record_count)) then
       call fail("persistent ghost request packing count mismatch")
    end if

    allocate(send_count(n_process))
    allocate(recv_count(n_process))
    allocate(send_displ(n_process))
    allocate(recv_displ(n_process))

    send_count = BLOCK_GHOST_REQUEST_SIZE* &
         ghost_exchange_plan%send_record_count
    recv_count = BLOCK_GHOST_REQUEST_SIZE* &
         ghost_exchange_plan%recv_record_count
    send_displ = BLOCK_GHOST_REQUEST_SIZE* &
         ghost_exchange_plan%send_record_displ
    recv_displ = BLOCK_GHOST_REQUEST_SIZE* &
         ghost_exchange_plan%recv_record_displ

    call MPI_Alltoallv( &
         ghost_exchange_plan%send_data,send_count,send_displ,MPI_INTEGER, &
         ghost_exchange_plan%recv_data,recv_count,recv_displ,MPI_INTEGER, &
         comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv persistent ghost requests")

    do r = 1, n_process
       do i = 0, ghost_exchange_plan%recv_record_count(r)-1
          pos = BLOCK_GHOST_REQUEST_SIZE*( &
               ghost_exchange_plan%recv_record_displ(r)+i)
          source = ghost_exchange_plan%recv_data(pos+1)

          if (source < 1 .or. source > size(block_catalog)) then
             call fail("received persistent ghost source is invalid")
          end if
          if (block_catalog(source)%owner /= rank) then
             call fail("received persistent ghost source is not local")
          end if
          if (catalog_local_block(source) < 1) then
             call fail("received persistent ghost source is absent")
          end if

          source_npatch = local_block_patch_count(source)
          if (ghost_exchange_plan%recv_data(pos+2) < 0 .or. &
               ghost_exchange_plan%recv_data(pos+2) >= &
               source_npatch) then
             call fail("received persistent source patch is invalid")
          end if

          destination = ghost_exchange_plan%recv_data(pos+3)
          if (destination < 1 .or. &
               destination > size(block_catalog)) then
             call fail("received persistent destination is invalid")
          end if
          if (block_catalog(destination)%owner /= r-1) then
             call fail("received persistent destination owner mismatch")
          end if
          if (ghost_exchange_plan%recv_data(pos+4) < 1) then
             call fail("received persistent ghost index is invalid")
          end if
          if (ghost_exchange_plan%recv_data(pos+5) /= &
               local_block_patch_level( &
               source,ghost_exchange_plan%recv_data(pos+2))) then
             call fail("received persistent ghost patch level differs")
          end if
       end do
    end do

    call build_block_ghost_level_subplans

    call get_block_field_layout( &
         scalar_variable,scalar_count,vector_variable,field_level, &
         level_count,scalar_mult,vector_mult)

    if (scalar_count < 1 .or. level_count < 1 .or. &
         scalar_mult < 1 .or. vector_mult < 1) then
       call fail("invalid persistent ghost payload layout")
    end if

    ghost_exchange_plan%scalar_n_value = &
         scalar_count*level_count*scalar_mult*PATCH_SIZE**2
    ghost_exchange_plan%vector_n_value = &
         level_count*vector_mult*PATCH_SIZE**2

    allocate(ghost_exchange_plan%scalar_send_count(n_process))
    allocate(ghost_exchange_plan%scalar_recv_count(n_process))
    allocate(ghost_exchange_plan%scalar_send_displ(n_process))
    allocate(ghost_exchange_plan%scalar_recv_displ(n_process))
    allocate(ghost_exchange_plan%vector_send_count(n_process))
    allocate(ghost_exchange_plan%vector_recv_count(n_process))
    allocate(ghost_exchange_plan%vector_send_displ(n_process))
    allocate(ghost_exchange_plan%vector_recv_displ(n_process))

    ghost_exchange_plan%scalar_send_count = &
         ghost_exchange_plan%scalar_n_value* &
         ghost_exchange_plan%recv_record_count
    ghost_exchange_plan%scalar_recv_count = &
         ghost_exchange_plan%scalar_n_value* &
         ghost_exchange_plan%send_record_count
    ghost_exchange_plan%vector_send_count = &
         ghost_exchange_plan%vector_n_value* &
         ghost_exchange_plan%recv_record_count
    ghost_exchange_plan%vector_recv_count = &
         ghost_exchange_plan%vector_n_value* &
         ghost_exchange_plan%send_record_count

    ghost_exchange_plan%scalar_send_displ(1) = 0
    ghost_exchange_plan%scalar_recv_displ(1) = 0
    ghost_exchange_plan%vector_send_displ(1) = 0
    ghost_exchange_plan%vector_recv_displ(1) = 0

    do r = 2, n_process
       ghost_exchange_plan%scalar_send_displ(r) = &
            ghost_exchange_plan%scalar_send_displ(r-1) + &
            ghost_exchange_plan%scalar_send_count(r-1)
       ghost_exchange_plan%scalar_recv_displ(r) = &
            ghost_exchange_plan%scalar_recv_displ(r-1) + &
            ghost_exchange_plan%scalar_recv_count(r-1)
       ghost_exchange_plan%vector_send_displ(r) = &
            ghost_exchange_plan%vector_send_displ(r-1) + &
            ghost_exchange_plan%vector_send_count(r-1)
       ghost_exchange_plan%vector_recv_displ(r) = &
            ghost_exchange_plan%vector_recv_displ(r-1) + &
            ghost_exchange_plan%vector_recv_count(r-1)
    end do

    allocate(ghost_exchange_plan%scalar_send_buffer( &
         ghost_exchange_plan%scalar_n_value* &
         ghost_exchange_plan%n_remote_recv))
    allocate(ghost_exchange_plan%scalar_recv_buffer( &
         ghost_exchange_plan%scalar_n_value* &
         ghost_exchange_plan%n_remote_send))
    allocate(ghost_exchange_plan%scalar_patch_buffer( &
         ghost_exchange_plan%scalar_n_value))
    allocate(ghost_exchange_plan%vector_send_buffer( &
         ghost_exchange_plan%vector_n_value* &
         ghost_exchange_plan%n_remote_recv))
    allocate(ghost_exchange_plan%vector_recv_buffer( &
         ghost_exchange_plan%vector_n_value* &
         ghost_exchange_plan%n_remote_send))
    allocate(ghost_exchange_plan%vector_patch_buffer( &
         ghost_exchange_plan%vector_n_value))

    ghost_exchange_plan%scalar_send_buffer = 0.0_dp
    ghost_exchange_plan%scalar_recv_buffer = 0.0_dp
    ghost_exchange_plan%scalar_patch_buffer = 0.0_dp
    ghost_exchange_plan%vector_send_buffer = 0.0_dp
    ghost_exchange_plan%vector_recv_buffer = 0.0_dp
    ghost_exchange_plan%vector_patch_buffer = 0.0_dp

    ghost_exchange_plan%ready = .true.
    ghost_exchange_plan%allocation_count = &
         ghost_exchange_plan%allocation_count + 1_int64
    ghost_exchange_plan%build_count = &
         ghost_exchange_plan%build_count + 1_int64

    deallocate(fill)
    deallocate(recv_count)
    deallocate(recv_displ)
    deallocate(send_count)
    deallocate(send_displ)

  end subroutine build_block_ghost_exchange_plan


  subroutine build_block_ghost_level_subplans
    ! Partition the persistent ghost manifest once by source grid level.
    ! Request metadata already carries the level, so no reverse collective is
    ! needed and replay can visit only the records used by its current level.

    implicit none

    integer :: i
    integer :: level_slot
    integer :: list_index
    integer :: pos
    integer :: r
    integer :: record
    integer :: request
    integer :: route_level

    integer, allocatable :: fill(:,:)
    integer, allocatable :: local_fill(:)

    ghost_exchange_plan%route_level_start = level_start
    ghost_exchange_plan%route_level_count = level_end-level_start+1
    if (ghost_exchange_plan%route_level_count < 1) then
       call fail("persistent ghost route level range is invalid")
    end if

    allocate(ghost_exchange_plan%local_level_count( &
         ghost_exchange_plan%route_level_count))
    allocate(ghost_exchange_plan%local_level_displ( &
         ghost_exchange_plan%route_level_count))
    allocate(ghost_exchange_plan%send_level_count( &
         n_process,ghost_exchange_plan%route_level_count))
    allocate(ghost_exchange_plan%send_level_displ( &
         n_process,ghost_exchange_plan%route_level_count))
    allocate(ghost_exchange_plan%send_level_base( &
         ghost_exchange_plan%route_level_count))
    allocate(ghost_exchange_plan%recv_level_count( &
         n_process,ghost_exchange_plan%route_level_count))
    allocate(ghost_exchange_plan%recv_level_displ( &
         n_process,ghost_exchange_plan%route_level_count))
    allocate(ghost_exchange_plan%recv_level_base( &
         ghost_exchange_plan%route_level_count))

    ghost_exchange_plan%local_level_count = 0
    ghost_exchange_plan%send_level_count = 0
    ghost_exchange_plan%recv_level_count = 0

    do request = 1,ghost_exchange_plan%n_request
       route_level = ghost_exchange_plan%source_patch_level(request)
       level_slot = route_level-level_start+1
       if (level_slot < 1 .or. &
            level_slot > ghost_exchange_plan%route_level_count) then
          call fail("persistent ghost source level is outside grid range")
       end if
       if (ghost_exchange_plan%source_owner(request) == rank) then
          ghost_exchange_plan%local_level_count(level_slot) = &
               ghost_exchange_plan%local_level_count(level_slot) + 1
       end if
    end do

    do r = 1,n_process
       do i = 0,ghost_exchange_plan%send_record_count(r)-1
          record = ghost_exchange_plan%send_record_displ(r)+i+1
          request = ghost_exchange_plan%request_index(record)
          level_slot = ghost_exchange_plan%source_patch_level(request) - &
               level_start + 1
          ghost_exchange_plan%send_level_count(r,level_slot) = &
               ghost_exchange_plan%send_level_count(r,level_slot) + 1
       end do
       do i = 0,ghost_exchange_plan%recv_record_count(r)-1
          record = ghost_exchange_plan%recv_record_displ(r)+i+1
          pos = BLOCK_GHOST_REQUEST_SIZE*(record-1)
          level_slot = ghost_exchange_plan%recv_data(pos+5) - &
               level_start + 1
          if (level_slot < 1 .or. &
               level_slot > ghost_exchange_plan%route_level_count) then
             call fail("received ghost source level is outside grid range")
          end if
          ghost_exchange_plan%recv_level_count(r,level_slot) = &
               ghost_exchange_plan%recv_level_count(r,level_slot) + 1
       end do
    end do

    if (sum(ghost_exchange_plan%local_level_count) /= &
         ghost_exchange_plan%n_local_request .or. &
         sum(ghost_exchange_plan%send_level_count) /= &
         ghost_exchange_plan%n_remote_send .or. &
         sum(ghost_exchange_plan%recv_level_count) /= &
         ghost_exchange_plan%n_remote_recv) then
       call fail("persistent ghost level subplan inventory differs")
    end if

    ghost_exchange_plan%local_level_displ(1) = 0
    ghost_exchange_plan%send_level_base(1) = 0
    ghost_exchange_plan%recv_level_base(1) = 0
    do level_slot = 2,ghost_exchange_plan%route_level_count
       ghost_exchange_plan%local_level_displ(level_slot) = &
            ghost_exchange_plan%local_level_displ(level_slot-1) + &
            ghost_exchange_plan%local_level_count(level_slot-1)
       ghost_exchange_plan%send_level_base(level_slot) = &
            ghost_exchange_plan%send_level_base(level_slot-1) + &
            sum(ghost_exchange_plan%send_level_count(:,level_slot-1))
       ghost_exchange_plan%recv_level_base(level_slot) = &
            ghost_exchange_plan%recv_level_base(level_slot-1) + &
            sum(ghost_exchange_plan%recv_level_count(:,level_slot-1))
    end do
    ghost_exchange_plan%send_level_displ(1,:) = 0
    ghost_exchange_plan%recv_level_displ(1,:) = 0
    do r = 2,n_process
       ghost_exchange_plan%send_level_displ(r,:) = &
            ghost_exchange_plan%send_level_displ(r-1,:) + &
            ghost_exchange_plan%send_level_count(r-1,:)
       ghost_exchange_plan%recv_level_displ(r,:) = &
            ghost_exchange_plan%recv_level_displ(r-1,:) + &
            ghost_exchange_plan%recv_level_count(r-1,:)
    end do

    allocate(ghost_exchange_plan%local_level_request( &
         ghost_exchange_plan%n_local_request))
    allocate(ghost_exchange_plan%send_level_record( &
         ghost_exchange_plan%n_remote_send))
    allocate(ghost_exchange_plan%recv_level_record( &
         ghost_exchange_plan%n_remote_recv))
    allocate(local_fill(ghost_exchange_plan%route_level_count))
    allocate(fill(n_process,ghost_exchange_plan%route_level_count))

    local_fill = 0
    do request = 1,ghost_exchange_plan%n_request
       if (ghost_exchange_plan%source_owner(request) /= rank) cycle
       level_slot = ghost_exchange_plan%source_patch_level(request) - &
            level_start + 1
       list_index = ghost_exchange_plan%local_level_displ(level_slot) + &
            local_fill(level_slot) + 1
       ghost_exchange_plan%local_level_request(list_index) = request
       local_fill(level_slot) = local_fill(level_slot) + 1
    end do
    if (any(local_fill /= ghost_exchange_plan%local_level_count)) then
       call fail("local ghost level subplan fill differs")
    end if

    fill = 0
    do r = 1,n_process
       do i = 0,ghost_exchange_plan%send_record_count(r)-1
          record = ghost_exchange_plan%send_record_displ(r)+i+1
          request = ghost_exchange_plan%request_index(record)
          level_slot = ghost_exchange_plan%source_patch_level(request) - &
               level_start + 1
          list_index = ghost_exchange_plan%send_level_base(level_slot) + &
               ghost_exchange_plan%send_level_displ(r,level_slot) + &
               fill(r,level_slot) + 1
          ghost_exchange_plan%send_level_record(list_index) = record
          fill(r,level_slot) = fill(r,level_slot) + 1
       end do
    end do
    if (any(fill /= ghost_exchange_plan%send_level_count)) then
       call fail("sent ghost level subplan fill differs")
    end if

    fill = 0
    do r = 1,n_process
       do i = 0,ghost_exchange_plan%recv_record_count(r)-1
          record = ghost_exchange_plan%recv_record_displ(r)+i+1
          pos = BLOCK_GHOST_REQUEST_SIZE*(record-1)
          level_slot = ghost_exchange_plan%recv_data(pos+5) - &
               level_start + 1
          list_index = ghost_exchange_plan%recv_level_base(level_slot) + &
               ghost_exchange_plan%recv_level_displ(r,level_slot) + &
               fill(r,level_slot) + 1
          ghost_exchange_plan%recv_level_record(list_index) = record
          fill(r,level_slot) = fill(r,level_slot) + 1
       end do
    end do
    if (any(fill /= ghost_exchange_plan%recv_level_count)) then
       call fail("received ghost level subplan fill differs")
    end if

    deallocate(fill)
    deallocate(local_fill)

  end subroutine build_block_ghost_level_subplans


  subroutine check_block_ghost_exchange_plan (verbose)
    ! Compare the cached plan with a fresh local inventory and verify the
    ! global request counts and request-record checksums.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: ierr
    integer :: n_request
    integer :: r

    integer(int64) :: count_global(3)
    integer(int64) :: count_local(3)
    integer(int64) :: buffer_count_global(4)
    integer(int64) :: buffer_count_local(4)
    integer(int64) :: recv_sum_global(BLOCK_GHOST_REQUEST_SIZE)
    integer(int64) :: recv_sum_local(BLOCK_GHOST_REQUEST_SIZE)
    integer(int64) :: send_sum_global(BLOCK_GHOST_REQUEST_SIZE)
    integer(int64) :: send_sum_local(BLOCK_GHOST_REQUEST_SIZE)

    integer, allocatable :: destination_block(:)
    integer, allocatable :: destination_ghost(:)
    integer, allocatable :: source_block(:)
    integer, allocatable :: source_local_patch(:)
    integer, allocatable :: source_patch_level(:)
    integer, allocatable :: source_owner(:)

    logical :: print_summary

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    if (.not. ghost_exchange_plan%ready) then
       call fail("persistent block ghost exchange plan is not ready")
    end if

    if (.not. allocated(ghost_exchange_plan%scalar_send_count)) then
       call fail("persistent scalar send counts are absent")
    end if
    if (.not. allocated(ghost_exchange_plan%scalar_recv_count)) then
       call fail("persistent scalar receive counts are absent")
    end if
    if (.not. allocated(ghost_exchange_plan%scalar_send_displ)) then
       call fail("persistent scalar send displacements are absent")
    end if
    if (.not. allocated(ghost_exchange_plan%scalar_recv_displ)) then
       call fail("persistent scalar receive displacements are absent")
    end if
    if (.not. allocated(ghost_exchange_plan%vector_send_count)) then
       call fail("persistent vector send counts are absent")
    end if
    if (.not. allocated(ghost_exchange_plan%vector_recv_count)) then
       call fail("persistent vector receive counts are absent")
    end if
    if (.not. allocated(ghost_exchange_plan%vector_send_displ)) then
       call fail("persistent vector send displacements are absent")
    end if
    if (.not. allocated(ghost_exchange_plan%vector_recv_displ)) then
       call fail("persistent vector receive displacements are absent")
    end if
    if (.not. allocated(ghost_exchange_plan%scalar_send_buffer)) then
       call fail("persistent scalar send buffer is absent")
    end if
    if (.not. allocated(ghost_exchange_plan%scalar_recv_buffer)) then
       call fail("persistent scalar receive buffer is absent")
    end if
    if (.not. allocated(ghost_exchange_plan%scalar_patch_buffer)) then
       call fail("persistent scalar patch buffer is absent")
    end if
    if (.not. allocated(ghost_exchange_plan%vector_send_buffer)) then
       call fail("persistent vector send buffer is absent")
    end if
    if (.not. allocated(ghost_exchange_plan%vector_recv_buffer)) then
       call fail("persistent vector receive buffer is absent")
    end if
    if (.not. allocated(ghost_exchange_plan%vector_patch_buffer)) then
       call fail("persistent vector patch buffer is absent")
    end if

    if (ghost_exchange_plan%scalar_n_value <= 0 .or. &
         ghost_exchange_plan%vector_n_value <= 0) then
       call fail("persistent ghost payload size is invalid")
    end if

    if (size(ghost_exchange_plan%scalar_send_count) /= n_process .or. &
         size(ghost_exchange_plan%scalar_recv_count) /= n_process .or. &
         size(ghost_exchange_plan%scalar_send_displ) /= n_process .or. &
         size(ghost_exchange_plan%scalar_recv_displ) /= n_process .or. &
         size(ghost_exchange_plan%vector_send_count) /= n_process .or. &
         size(ghost_exchange_plan%vector_recv_count) /= n_process .or. &
         size(ghost_exchange_plan%vector_send_displ) /= n_process .or. &
         size(ghost_exchange_plan%vector_recv_displ) /= n_process) then
       call fail("persistent ghost payload process layout mismatch")
    end if

    if (any(ghost_exchange_plan%scalar_send_count /= &
         ghost_exchange_plan%scalar_n_value* &
         ghost_exchange_plan%recv_record_count) .or. &
         any(ghost_exchange_plan%scalar_recv_count /= &
         ghost_exchange_plan%scalar_n_value* &
         ghost_exchange_plan%send_record_count) .or. &
         any(ghost_exchange_plan%vector_send_count /= &
         ghost_exchange_plan%vector_n_value* &
         ghost_exchange_plan%recv_record_count) .or. &
         any(ghost_exchange_plan%vector_recv_count /= &
         ghost_exchange_plan%vector_n_value* &
         ghost_exchange_plan%send_record_count)) then
       call fail("persistent ghost payload counts are invalid")
    end if

    if (ghost_exchange_plan%scalar_send_displ(1) /= 0 .or. &
         ghost_exchange_plan%scalar_recv_displ(1) /= 0 .or. &
         ghost_exchange_plan%vector_send_displ(1) /= 0 .or. &
         ghost_exchange_plan%vector_recv_displ(1) /= 0) then
       call fail("persistent ghost payload displacement origin mismatch")
    end if

    do r = 2, n_process
       if (ghost_exchange_plan%scalar_send_displ(r) /= &
            ghost_exchange_plan%scalar_send_displ(r-1) + &
            ghost_exchange_plan%scalar_send_count(r-1)) then
          call fail("persistent scalar send displacement mismatch")
       end if
       if (ghost_exchange_plan%scalar_recv_displ(r) /= &
            ghost_exchange_plan%scalar_recv_displ(r-1) + &
            ghost_exchange_plan%scalar_recv_count(r-1)) then
          call fail("persistent scalar receive displacement mismatch")
       end if
       if (ghost_exchange_plan%vector_send_displ(r) /= &
            ghost_exchange_plan%vector_send_displ(r-1) + &
            ghost_exchange_plan%vector_send_count(r-1)) then
          call fail("persistent vector send displacement mismatch")
       end if
       if (ghost_exchange_plan%vector_recv_displ(r) /= &
            ghost_exchange_plan%vector_recv_displ(r-1) + &
            ghost_exchange_plan%vector_recv_count(r-1)) then
          call fail("persistent vector receive displacement mismatch")
       end if
    end do

    if (size(ghost_exchange_plan%scalar_send_buffer) /= &
         ghost_exchange_plan%scalar_n_value* &
         ghost_exchange_plan%n_remote_recv .or. &
         size(ghost_exchange_plan%scalar_recv_buffer) /= &
         ghost_exchange_plan%scalar_n_value* &
         ghost_exchange_plan%n_remote_send .or. &
         size(ghost_exchange_plan%vector_send_buffer) /= &
         ghost_exchange_plan%vector_n_value* &
         ghost_exchange_plan%n_remote_recv .or. &
         size(ghost_exchange_plan%vector_recv_buffer) /= &
         ghost_exchange_plan%vector_n_value* &
         ghost_exchange_plan%n_remote_send .or. &
         size(ghost_exchange_plan%scalar_patch_buffer) /= &
         ghost_exchange_plan%scalar_n_value .or. &
         size(ghost_exchange_plan%vector_patch_buffer) /= &
         ghost_exchange_plan%vector_n_value) then
       call fail("persistent ghost payload buffer extent mismatch")
    end if

    call get_local_block_ghost_requests( &
         source_block,source_local_patch,source_patch_level,source_owner, &
         destination_block,destination_ghost)

    n_request = size(source_block)

    if (n_request /= ghost_exchange_plan%n_request) then
       call fail("persistent ghost plan request count changed")
    end if
    if (any(source_block /= ghost_exchange_plan%source_block) .or. &
         any(source_local_patch /= &
         ghost_exchange_plan%source_local_patch) .or. &
         any(source_patch_level /= &
         ghost_exchange_plan%source_patch_level) .or. &
         any(source_owner /= ghost_exchange_plan%source_owner) .or. &
         any(destination_block /= &
         ghost_exchange_plan%destination_block) .or. &
         any(destination_ghost /= &
         ghost_exchange_plan%destination_ghost)) then
       call fail("persistent ghost plan differs from block inventory")
    end if

    count_local = int([ &
         ghost_exchange_plan%n_local_request, &
         ghost_exchange_plan%n_remote_send, &
         ghost_exchange_plan%n_remote_recv ],int64)

    send_sum_local = 0_int64
    recv_sum_local = 0_int64

    if (ghost_exchange_plan%n_remote_send > 0) then
       send_sum_local = sum(reshape(int( &
            ghost_exchange_plan%send_data,int64), &
            [BLOCK_GHOST_REQUEST_SIZE, &
            ghost_exchange_plan%n_remote_send]),dim=2)
    end if
    if (ghost_exchange_plan%n_remote_recv > 0) then
       recv_sum_local = sum(reshape(int( &
            ghost_exchange_plan%recv_data,int64), &
            [BLOCK_GHOST_REQUEST_SIZE, &
            ghost_exchange_plan%n_remote_recv]),dim=2)
    end if

    call MPI_Allreduce( &
         count_local,count_global,3,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce persistent ghost request totals")

    buffer_count_local = int([ &
         size(ghost_exchange_plan%scalar_send_buffer), &
         size(ghost_exchange_plan%scalar_recv_buffer), &
         size(ghost_exchange_plan%vector_send_buffer), &
         size(ghost_exchange_plan%vector_recv_buffer) ],int64)

    call MPI_Allreduce( &
         buffer_count_local,buffer_count_global,4, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce persistent payload buffer totals")

    call MPI_Allreduce( &
         send_sum_local,send_sum_global,BLOCK_GHOST_REQUEST_SIZE, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce persistent ghost send checksum")

    call MPI_Allreduce( &
         recv_sum_local,recv_sum_global,BLOCK_GHOST_REQUEST_SIZE, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce persistent ghost recv checksum")

    if (count_global(2) /= count_global(3) .or. &
         any(send_sum_global /= recv_sum_global)) then
       call fail("persistent ghost plan global routing mismatch")
    end if

    if (buffer_count_global(1) /= buffer_count_global(2) .or. &
         buffer_count_global(3) /= buffer_count_global(4)) then
       call fail("persistent ghost payload global buffer mismatch")
    end if
    if (buffer_count_global(1) /= &
         int(ghost_exchange_plan%scalar_n_value,int64)* &
         count_global(2) .or. &
         buffer_count_global(3) /= &
         int(ghost_exchange_plan%vector_n_value,int64)* &
         count_global(2)) then
       call fail("persistent ghost payload global extent mismatch")
    end if

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Persistent block ghost exchange plan for rank ",rank,":"
       write(6,'(a,i0)') &
            "  local-source requests    = ", &
            ghost_exchange_plan%n_local_request
       write(6,'(a,i0)') &
            "  remote requests sent     = ", &
            ghost_exchange_plan%n_remote_send
       write(6,'(a,i0)') &
            "  remote requests received = ", &
            ghost_exchange_plan%n_remote_recv
       write(6,'(a,i0)') &
            "  reusable scalar send values = ", &
            size(ghost_exchange_plan%scalar_send_buffer)
       write(6,'(a,i0)') &
            "  reusable scalar receive values = ", &
            size(ghost_exchange_plan%scalar_recv_buffer)
       write(6,'(a,i0)') &
            "  reusable scalar patch values = ", &
            size(ghost_exchange_plan%scalar_patch_buffer)
       write(6,'(a,i0)') &
            "  reusable vector send values = ", &
            size(ghost_exchange_plan%vector_send_buffer)
       write(6,'(a,i0)') &
            "  reusable vector receive values = ", &
            size(ghost_exchange_plan%vector_recv_buffer)
       write(6,'(a,i0)') &
            "  reusable vector patch values = ", &
            size(ghost_exchange_plan%vector_patch_buffer)
       write(6,'(a,/)') &
            "  reusable request and payload buffer checks passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,i0)') &
            "Global persistent block ghost requests = ", &
            count_global(1)+count_global(2)
       write(6,'(a,i0)') &
            "Global reusable scalar send values = ", &
            buffer_count_global(1)
       write(6,'(a,i0)') &
            "Global reusable scalar receive values = ", &
            buffer_count_global(2)
       write(6,'(a,i0)') &
            "Global reusable vector send values = ", &
            buffer_count_global(3)
       write(6,'(a,i0)') &
            "Global reusable vector receive values = ", &
            buffer_count_global(4)
       write(6,'(a,/)') &
            "Persistent block ghost exchange buffers passed"
    end if

    deallocate(destination_block)
    deallocate(destination_ghost)
    deallocate(source_block)
    deallocate(source_local_patch)
    deallocate(source_patch_level)
    deallocate(source_owner)

  end subroutine check_block_ghost_exchange_plan


