         BLOCK_SCALAR_RESTRICTION_DYNAMIC_COUNT* &
         ghost_exchange_plan%scalar_n_value* &
         ghost_exchange_plan%send_record_displ(2:n_process)
    n_ghost_send = sum( &
         block_scalar_restriction_exchange%ghost_send_count)
    n_ghost_recv = sum( &
         block_scalar_restriction_exchange%ghost_recv_count)
    allocate(block_scalar_restriction_exchange% &
         ghost_send_buffer(max(1,n_ghost_send)))
    allocate(block_scalar_restriction_exchange% &
         ghost_recv_buffer(max(1,n_ghost_recv)))
    allocate(block_scalar_restriction_exchange%ghost_patch_buffer( &
         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
         ghost_exchange_plan%scalar_n_value))
    allocate(block_scalar_restriction_exchange%sparse_request( &
         max(1,2*n_process)))

    call prepare_block_scalar_boundary_provenance

    required_ghost_send = n_ghost_send
    required_ghost_recv = n_ghost_recv
    do level_slot = 1, &
         block_scalar_boundary_final_plan%route_level_count
       required_ghost_send = max(required_ghost_send, &
            ghost_exchange_plan%scalar_n_value*sum( &
            ghost_exchange_plan%recv_level_count(:,level_slot)) + &
            block_scalar_boundary_final_plan%field_count*sum( &
            block_scalar_boundary_final_plan% &
            service_level_count(:,level_slot)))
       required_ghost_recv = max(required_ghost_recv, &
            ghost_exchange_plan%scalar_n_value*sum( &
            ghost_exchange_plan%send_level_count(:,level_slot)) + &
            block_scalar_boundary_final_plan%field_count*sum( &
            block_scalar_boundary_final_plan% &
            request_level_count(:,level_slot)))
    end do
    if (size(block_scalar_restriction_exchange%ghost_send_buffer) < &
         max(1,required_ghost_send)) then
       deallocate(block_scalar_restriction_exchange%ghost_send_buffer)
       allocate(block_scalar_restriction_exchange%ghost_send_buffer( &
            max(1,required_ghost_send)))
    end if
    if (size(block_scalar_restriction_exchange%ghost_recv_buffer) < &
         max(1,required_ghost_recv)) then
       deallocate(block_scalar_restriction_exchange%ghost_recv_buffer)
       allocate(block_scalar_restriction_exchange%ghost_recv_buffer( &
            max(1,required_ghost_recv)))
    end if

    block_scalar_restriction_exchange%boundary_send_buffer = &
         BLOCK_BOUNDARY_POISON
    block_scalar_restriction_exchange%boundary_recv_buffer = &
         BLOCK_BOUNDARY_POISON
    block_scalar_restriction_exchange%boundary_owner_send_buffer = 0
    block_scalar_restriction_exchange%boundary_owner_recv_buffer = 0
    block_scalar_restriction_exchange%boundary_owner_domain_send_buffer = -3
    block_scalar_restriction_exchange%boundary_owner_domain_recv_buffer = -3
    block_scalar_restriction_exchange%boundary_owner_node_send_buffer = -3
    block_scalar_restriction_exchange%boundary_owner_node_recv_buffer = -3
    block_scalar_boundary_owner_block_send = -3
    block_scalar_boundary_owner_block_recv = -3
    block_scalar_boundary_owner_block_patch_send = -3
    block_scalar_boundary_owner_block_patch_recv = -3
    block_scalar_boundary_owner_block_level_send = -3
    block_scalar_boundary_owner_block_level_recv = -3
    block_scalar_boundary_owner_rank_send = -3
    block_scalar_boundary_owner_rank_recv = -3
    block_scalar_boundary_owner_patch_send = -3
    block_scalar_boundary_owner_patch_recv = -3
    block_scalar_boundary_owner_patch_node_send = -3
    block_scalar_boundary_owner_patch_node_recv = -3
    block_scalar_boundary_owner_block = -3
    block_scalar_boundary_owner_block_patch = -3
    block_scalar_boundary_owner_block_level = -3
    block_scalar_boundary_owner_block_send = -3
    block_scalar_boundary_owner_block_recv = -3
    block_scalar_boundary_owner_block_patch_send = -3
    block_scalar_boundary_owner_block_patch_recv = -3
    block_scalar_restriction_exchange%ghost_send_buffer = &
         BLOCK_GHOST_POISON
    block_scalar_restriction_exchange%ghost_recv_buffer = &
         BLOCK_GHOST_POISON
    block_scalar_restriction_exchange%ghost_patch_buffer = &
         BLOCK_GHOST_POISON
    block_scalar_restriction_exchange%allocations = &
         block_scalar_restriction_exchange%allocations + 68_int64
    block_scalar_restriction_exchange%generation = &
         block_writeback_plan_generation
    block_scalar_restriction_exchange%ready = .true.
    block_scalar_restriction_exchange%production_ghost_cache_ready = &
         .false.

  end subroutine prepare_block_scalar_restriction_exchange


  subroutine prepare_block_scalar_boundary_provenance
    ! Stage 166A: retain a canonical topology key for every compact scalar
    ! boundary node. Boundary storage has its own address space, so numerical
    ! ownership must later be resolved through the Domain communication graph,
    ! not by comparing boundary and patch element indices.

    implicit none

    integer :: b
    integer :: boundary_index
    integer :: cache_slot
    integer :: d
    integer :: d_source
    integer :: destination_global
    integer :: elts_start
    integer :: field_value_slot
    integer :: ierr
    integer :: i
    integer :: local_index
    integer :: metadata_pos
    integer :: n_field_value
    integer :: n_cache
    integer :: n_local
    integer :: n_node
    integer :: next_patch
    integer :: node
    integer :: node_key_pos
    integer :: owner_class
    integer :: owner_pos
    integer :: pos
    integer :: pos_sample
    integer :: q
    integer :: r
    integer :: route_index
    integer :: sample
    integer :: slot
    integer :: source
    integer :: source_global
    integer :: source_id
    integer :: source_patch
    integer :: source_patch_node
    integer :: source_block
    integer :: source_block_level
    integer :: source_block_patch
    integer :: source_bdry
    integer :: source_level
    integer :: source_owner_rank
    integer :: target_id
    integer :: total_domain_node
    integer :: total_domain_patch
    integer :: total_node

    integer, allocatable :: domain_node_displ(:)
    integer, allocatable :: domain_node_patch(:)
    integer, allocatable :: domain_node_patch_node(:)
    integer, allocatable :: domain_patch_block(:)
    integer, allocatable :: domain_patch_block_patch(:)
    integer, allocatable :: domain_patch_displ(:)
    integer, allocatable :: node_key_expected_recv_count(:)
    integer, allocatable :: node_key_patch_recv_buffer(:)
    integer, allocatable :: node_key_patch_send_buffer(:)
    integer, allocatable :: node_key_patch_node_recv_buffer(:)
    integer, allocatable :: node_key_patch_node_send_buffer(:)
    integer, allocatable :: node_key_block_recv_buffer(:)
    integer, allocatable :: node_key_block_send_buffer(:)
    integer, allocatable :: node_key_block_level_recv_buffer(:)
    integer, allocatable :: node_key_block_level_send_buffer(:)
    integer, allocatable :: node_key_block_patch_recv_buffer(:)
    integer, allocatable :: node_key_block_patch_send_buffer(:)
    integer, allocatable :: node_key_recv_buffer(:)
    integer, allocatable :: node_key_recv_count(:)
    integer, allocatable :: node_key_recv_displ(:)
    integer, allocatable :: node_key_send_buffer(:)
    integer, allocatable :: node_key_send_count(:)
    integer, allocatable :: node_key_send_displ(:)
    integer, allocatable :: route_count(:)
    integer, allocatable :: route_source_domain(:)
    integer, allocatable :: route_source_node(:)
    integer, allocatable :: route_source_patch(:)
    integer, allocatable :: route_source_patch_node(:)
    integer, allocatable :: route_source_block(:)
    integer, allocatable :: route_source_block_level(:)
    integer, allocatable :: route_source_block_patch(:)
    integer, allocatable :: route_owner_rank(:)

    integer(int64) :: count_global
    integer(int64) :: count_local
    integer(int64) :: owner_count_global(BLOCK_BOUNDARY_OWNER_CLASS_COUNT)
    integer(int64) :: owner_count_local(BLOCK_BOUNDARY_OWNER_CLASS_COUNT)
    integer(int64) :: patch_key_count_global(4)
    integer(int64) :: patch_key_count_local(4)
    integer(int64) :: block_key_count_global(4)
    integer(int64) :: block_key_count_local(4)
    integer(int64) :: cache_count_global(5)
    integer(int64) :: cache_count_local(5)
    integer(int64) :: cache_request_count_global(3)
    integer(int64) :: cache_request_count_local(3)
    integer(int64) :: final_request_count_global(3)
    integer(int64) :: final_request_count_local(3)
    integer(int64) :: source_key_count_global(4)
    integer(int64) :: source_key_count_local(4)

    n_local = n_local_blocks()
    allocate(block_scalar_restriction_exchange% &
         boundary_source_displ(n_local+1))
    block_scalar_restriction_exchange%boundary_source_displ(1) = 0
    do local_index = 1,n_local
       b = local_block_catalog(local_index)
       total_node = 0
       do boundary_index = 1,local_block_boundary_count(b)
          call get_local_block_boundary_source( &
               b,boundary_index,source_bdry,elts_start,n_node, &
               source_level)
          if (source_bdry < 0 .or. elts_start < 0 .or. &
               n_node < 1 .or. source_level < 0) then
             call fail("scalar boundary provenance source is invalid")
          end if
          total_node = total_node+n_node
       end do
       block_scalar_restriction_exchange% &
            boundary_source_displ(local_index+1) = &
            block_scalar_restriction_exchange% &
            boundary_source_displ(local_index)+total_node
    end do
    total_node = block_scalar_restriction_exchange% &
         boundary_source_displ(n_local+1)
    ! Owner metadata is indexed by the complete local boundary-source stream,
    ! including retained local blocks, so incoming migrated-block count alone
    ! is insufficient for its allocation.
    deallocate(block_scalar_boundary_owner_block)
    deallocate(block_scalar_boundary_owner_block_patch)
    deallocate(block_scalar_boundary_owner_block_level)
    allocate(block_scalar_boundary_owner_block(max(1,total_node)))
    allocate(block_scalar_boundary_owner_block_patch(max(1,total_node)))
    allocate(block_scalar_boundary_owner_block_level(max(1,total_node)))
    allocate(block_scalar_boundary_owner_rank(max(1,total_node)))
    allocate(block_scalar_boundary_cache_slot(max(1,total_node)))
    allocate(block_scalar_boundary_cache_domain(max(1,total_node)))
    allocate(block_scalar_boundary_cache_node(max(1,total_node)))
    allocate(block_scalar_boundary_cache_rank(max(1,total_node)))
    allocate(block_scalar_boundary_final_plan%cache_block( &
         max(1,total_node)))
    allocate(block_scalar_boundary_final_plan%cache_patch( &
         max(1,total_node)))
    allocate(block_scalar_boundary_final_plan%cache_node( &
         max(1,total_node)))
    allocate(block_scalar_boundary_final_plan%cache_rank( &
         max(1,total_node)))
    allocate(block_scalar_boundary_final_plan%cache_level( &
         max(1,total_node)))
    allocate(block_scalar_restriction_exchange% &
         boundary_source_domain(max(1,total_node)))
    allocate(block_scalar_restriction_exchange% &
         boundary_source_record(max(1,total_node)))
    allocate(block_scalar_restriction_exchange% &
         boundary_source_node(max(1,total_node)))
    allocate(block_scalar_restriction_exchange% &
         boundary_source_level(max(1,total_node)))
    allocate(block_scalar_restriction_exchange% &
         boundary_source_owner_class(max(1,total_node)))
    allocate(block_scalar_restriction_exchange% &
         boundary_source_owner_domain(max(1,total_node)))
    allocate(block_scalar_restriction_exchange% &
         boundary_source_owner_node(max(1,total_node)))
    allocate(block_scalar_boundary_owner_patch(max(1,total_node)))
    allocate(block_scalar_boundary_owner_patch_node(max(1,total_node)))
    block_scalar_restriction_exchange%boundary_source_domain = -1
    block_scalar_restriction_exchange%boundary_source_record = -1
    block_scalar_restriction_exchange%boundary_source_node = -1
    block_scalar_restriction_exchange%boundary_source_level = -1
    block_scalar_restriction_exchange%boundary_source_owner_class = 0
    block_scalar_restriction_exchange%boundary_source_owner_domain = -3
    block_scalar_restriction_exchange%boundary_source_owner_node = -3
    block_scalar_boundary_owner_patch = -3
    block_scalar_boundary_owner_patch_node = -3
    block_scalar_boundary_owner_block_level = -3
    block_scalar_boundary_owner_rank = -3
    block_scalar_boundary_cache_slot = -3
    block_scalar_boundary_cache_domain = -3
    block_scalar_boundary_cache_node = -3
    block_scalar_boundary_cache_rank = -3
    block_scalar_boundary_final_plan%cache_block = -3
    block_scalar_boundary_final_plan%cache_patch = -3
    block_scalar_boundary_final_plan%cache_node = -3
    block_scalar_boundary_final_plan%cache_rank = -3
    block_scalar_boundary_final_plan%cache_level = -3
    block_scalar_boundary_cache_count = 0

    do local_index = 1,n_local
       b = local_block_catalog(local_index)
       pos = block_scalar_restriction_exchange% &
            boundary_source_displ(local_index)+1
       do boundary_index = 1,local_block_boundary_count(b)
          call get_local_block_boundary_source( &
               b,boundary_index,source_bdry,elts_start,n_node, &
               source_level)
          do node = 0,n_node-1
             if (pos < 1 .or. pos > max(1,total_node)) then
                call fail("scalar boundary provenance extent is invalid")
             end if
             block_scalar_restriction_exchange% &
                  boundary_source_domain(pos) = &
                  block_catalog(b)%root_domain
             block_scalar_restriction_exchange% &
                  boundary_source_record(pos) = source_bdry
             block_scalar_restriction_exchange% &
                  boundary_source_node(pos) = node
             block_scalar_restriction_exchange% &
                  boundary_source_level(pos) = source_level
             pos = pos+1
          end do
       end do
       if (pos /= block_scalar_restriction_exchange% &
            boundary_source_displ(local_index+1)+1) then
          call fail("scalar boundary provenance coverage differs")
       end if
    end do
    if (total_node > 0) then
       if (any(block_scalar_restriction_exchange% &
            boundary_source_domain(1:total_node) < 0) .or. &
            any(block_scalar_restriction_exchange% &
            boundary_source_record(1:total_node) < 0) .or. &
            any(block_scalar_restriction_exchange% &
            boundary_source_node(1:total_node) < 0) .or. &
            any(block_scalar_restriction_exchange% &
            boundary_source_level(1:total_node) < 0)) then
          call fail("scalar boundary provenance map is incomplete")
       end if
    end if

    ! Stage 166C: resolve each retained Domain-boundary address against the
    ! established AT_NODE receive graph. The aligned pack/unpack position is
    ! the only canonical ownership relation; boundary and patch indices are
    ! deliberately not compared. Multiple routes are retained as an explicit
    ! ambiguous class instead of selecting an arbitrary owner.
    allocate(domain_node_displ(size(grid)+1))
    domain_node_displ(1) = 0
    do d = 1,size(grid)
       domain_node_displ(d+1) = domain_node_displ(d) + &
            grid(d)%node%length
    end do
    total_domain_node = domain_node_displ(size(grid)+1)
    ! Stage 166F: establish a canonical active-patch address for each Domain
    ! node. This metadata is shadow-only and is the compact-storage key that
    ! the later owner-value transport stage will consume.
    allocate(domain_node_patch(max(1,total_domain_node)))
    allocate(domain_node_patch_node(max(1,total_domain_node)))
    domain_node_patch = -1
    domain_node_patch_node = -1
    do d = 1,size(grid)
       do source_patch = 0,grid(d)%patch%length-1
          if (grid(d)%patch%elts(source_patch+1)%deleted) cycle
          source_id = grid(d)%patch%elts(source_patch+1)%elts_start
          do q = 0,PATCH_SIZE**2-1
             route_index = domain_node_displ(d)+source_id+q+1
             if (route_index < 1 .or. &
                  route_index > max(1,total_domain_node)) then
                call fail("scalar boundary Domain patch map is invalid")
             end if
             if (domain_node_patch(route_index) >= 0) cycle
             domain_node_patch(route_index) = source_patch
             domain_node_patch_node(route_index) = q
          end do
       end do
    end do
    ! Resolve every resident source patch to its unique global block and
    ! extraction-preorder index once.  Boundary source nodes repeatedly name
    ! the same patches, so this table avoids a subtree search per node and is
    ! the persistent key required by the final-owner transport stage.
    allocate(domain_patch_displ(size(grid)+1))
    domain_patch_displ(1) = 0
    do d = 1,size(grid)
       domain_patch_displ(d+1) = domain_patch_displ(d) + &
            grid(d)%patch%length
    end do
    total_domain_patch = domain_patch_displ(size(grid)+1)
    allocate(domain_patch_block(max(1,total_domain_patch)))
    allocate(domain_patch_block_patch(max(1,total_domain_patch)))
    domain_patch_block = -1
    domain_patch_block_patch = -1
    do b = 1,size(block_catalog)
       if (source_rank(b) /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1)+1
       if (d < 1 .or. d > size(grid)) then
          call fail("scalar boundary source block Domain is invalid")
       end if
       next_patch = 0
       call map_source_block_subtree( &
            d,block_catalog(b)%root_patch,b,next_patch)
    end do
    allocate(route_count(max(1,total_domain_node)))
    allocate(route_owner_rank(max(1,total_domain_node)))
    allocate(route_source_domain(max(1,total_domain_node)))
    allocate(route_source_node(max(1,total_domain_node)))
    allocate(route_source_patch(max(1,total_domain_node)))
    allocate(route_source_patch_node(max(1,total_domain_node)))
    allocate(route_source_block(max(1,total_domain_node)))
    allocate(route_source_block_patch(max(1,total_domain_node)))
    allocate(route_source_block_level(max(1,total_domain_node)))
    route_count = 0
    route_owner_rank = -1
    route_source_domain = -3
    route_source_node = -3
    route_source_patch = -3
    route_source_patch_node = -3
    route_source_block = -3
    route_source_block_patch = -3
    route_source_block_level = -3

    ! Stage 166E: exchange the source-node side of every remote AT_NODE route
    ! once per topology generation. Packing and unpacking deliberately mirror
    ! comm_nodes3_mpi: peer, source Domain, destination Domain, then node.
    ! This converts the remote Domain-only keys retained by Stage 166D into
    ! exact (source Domain, source node) keys without touching field data.
    allocate(node_key_send_count(n_process))
    allocate(node_key_recv_count(n_process))
    allocate(node_key_expected_recv_count(n_process))
    allocate(node_key_send_displ(n_process))
    allocate(node_key_recv_displ(n_process))
    node_key_send_count = 0
    node_key_expected_recv_count = 0
    do r = 1,n_process
       if (r == rank+1) cycle
       do d_source = 1,size(grid)
          do d = 1,n_domain(r)
             destination_global = glo_id(r,d)+1
             node_key_send_count(r) = node_key_send_count(r) + &
                  grid(d_source)% &
                  pack(AT_NODE,destination_global)%length
          end do
       end do
       do d_source = 1,n_domain(r)
          source_global = glo_id(r,d_source)+1
          do d = 1,size(grid)
             node_key_expected_recv_count(r) = &
                  node_key_expected_recv_count(r) + &
                  grid(d)%unpk(AT_NODE,source_global)%length
          end do
       end do
    end do
    call MPI_Alltoall(node_key_send_count,1,MPI_INTEGER, &
         node_key_recv_count,1,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoall scalar boundary source-node counts")
    if (any(node_key_recv_count /= node_key_expected_recv_count)) then
       call fail("scalar boundary source-node route counts differ")
    end if
    node_key_send_displ(1) = 0
    node_key_recv_displ(1) = 0
    node_key_send_displ(2:n_process) = &
         [(sum(node_key_send_count(1:r)),r=1,n_process-1)]
    node_key_recv_displ(2:n_process) = &
         [(sum(node_key_recv_count(1:r)),r=1,n_process-1)]
    allocate(node_key_send_buffer(max(1,sum(node_key_send_count))))
    allocate(node_key_recv_buffer(max(1,sum(node_key_recv_count))))
    allocate(node_key_patch_send_buffer( &
         max(1,sum(node_key_send_count))))
    allocate(node_key_patch_recv_buffer( &
         max(1,sum(node_key_recv_count))))
    allocate(node_key_patch_node_send_buffer( &
         max(1,sum(node_key_send_count))))
    allocate(node_key_patch_node_recv_buffer( &
         max(1,sum(node_key_recv_count))))
    allocate(node_key_block_send_buffer( &
         max(1,sum(node_key_send_count))))
    allocate(node_key_block_recv_buffer( &
         max(1,sum(node_key_recv_count))))
    allocate(node_key_block_patch_send_buffer( &
         max(1,sum(node_key_send_count))))
    allocate(node_key_block_patch_recv_buffer( &
         max(1,sum(node_key_recv_count))))
    allocate(node_key_block_level_send_buffer( &
         max(1,sum(node_key_send_count))))
    allocate(node_key_block_level_recv_buffer( &
         max(1,sum(node_key_recv_count))))
    node_key_send_buffer = -1
    node_key_recv_buffer = -1
    node_key_patch_send_buffer = -1
    node_key_patch_recv_buffer = -1
    node_key_patch_node_send_buffer = -1
    node_key_patch_node_recv_buffer = -1
    node_key_block_send_buffer = -1
    node_key_block_recv_buffer = -1
    node_key_block_patch_send_buffer = -1
    node_key_block_patch_recv_buffer = -1
    node_key_block_level_send_buffer = -1
    node_key_block_level_recv_buffer = -1
    do r = 1,n_process
       node_key_pos = node_key_send_displ(r)+1
       if (r /= rank+1) then
          do d_source = 1,size(grid)
             do d = 1,n_domain(r)
                destination_global = glo_id(r,d)+1
                do i = 1,grid(d_source)% &
                     pack(AT_NODE,destination_global)%length
                   source_id = grid(d_source)% &
                        pack(AT_NODE,destination_global)%elts(i)
                   if (source_id < 0 .or. &
                        source_id >= grid(d_source)%node%length) then
                      call fail( &
                           "scalar boundary source-node send is invalid")
                   end if
                   call domain_node_patch_key( &
                        d_source,source_id,source_patch,source_patch_node)
                   call source_patch_block_key( &
                        d_source,source_patch,source_block,source_block_patch)
                   source_block_level = grid(d_source)% &
                        patch%elts(source_patch+1)%level
                   node_key_send_buffer(node_key_pos) = source_id
                   node_key_patch_send_buffer(node_key_pos) = source_patch
                   node_key_patch_node_send_buffer(node_key_pos) = &
                        source_patch_node
                   node_key_block_send_buffer(node_key_pos) = source_block
                   node_key_block_patch_send_buffer(node_key_pos) = &
                        source_block_patch
                   node_key_block_level_send_buffer(node_key_pos) = &
                        source_block_level
                   node_key_pos = node_key_pos+1
                end do
             end do
          end do
       end if
       if (node_key_pos /= node_key_send_displ(r) + &
            node_key_send_count(r)+1) then
          call fail("scalar boundary source-node send extent differs")
       end if
    end do
    call MPI_Alltoallv(node_key_send_buffer,node_key_send_count, &
         node_key_send_displ,MPI_INTEGER,node_key_recv_buffer, &
         node_key_recv_count,node_key_recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar boundary source nodes")
    call MPI_Alltoallv(node_key_patch_send_buffer,node_key_send_count, &
         node_key_send_displ,MPI_INTEGER,node_key_patch_recv_buffer, &
         node_key_recv_count,node_key_recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar boundary source patches")
    call MPI_Alltoallv(node_key_patch_node_send_buffer, &
         node_key_send_count,node_key_send_displ,MPI_INTEGER, &
         node_key_patch_node_recv_buffer,node_key_recv_count, &
         node_key_recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr, &
         "MPI_Alltoallv scalar boundary source patch nodes")
    call MPI_Alltoallv(node_key_block_send_buffer,node_key_send_count, &
         node_key_send_displ,MPI_INTEGER,node_key_block_recv_buffer, &
         node_key_recv_count,node_key_recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar boundary source blocks")
    call MPI_Alltoallv(node_key_block_patch_send_buffer, &
         node_key_send_count,node_key_send_displ,MPI_INTEGER, &
         node_key_block_patch_recv_buffer,node_key_recv_count, &
         node_key_recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr, &
         "MPI_Alltoallv scalar boundary source block patches")
    call MPI_Alltoallv(node_key_block_level_send_buffer, &
         node_key_send_count,node_key_send_displ,MPI_INTEGER, &
         node_key_block_level_recv_buffer,node_key_recv_count, &
         node_key_recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr, &
         "MPI_Alltoallv scalar boundary source block levels")

    do r = 1,n_process
       node_key_pos = node_key_recv_displ(r)+1
       do d_source = 1,n_domain(r)
          source_global = glo_id(r,d_source)+1
          do d = 1,size(grid)
             destination_global = glo_id(rank+1,d)+1
             if (r == rank+1) then
                if (grid(d_source)% &
                     pack(AT_NODE,destination_global)%length /= &
                     grid(d)%unpk(AT_NODE,source_global)%length) then
                   call fail("scalar boundary local source routes differ")
                end if
             end if
             do i = 1,grid(d)%unpk(AT_NODE,source_global)%length
                if (r == rank+1) then
                   source_id = grid(d_source)% &
                        pack(AT_NODE,destination_global)%elts(i)
                   if (source_id < 0 .or. &
                        source_id >= grid(d_source)%node%length) then
                      call fail( &
                           "scalar boundary local source is invalid")
                   end if
                   call domain_node_patch_key( &
                        d_source,source_id,source_patch,source_patch_node)
                   call source_patch_block_key( &
                        d_source,source_patch,source_block,source_block_patch)
                   source_block_level = grid(d_source)% &
                        patch%elts(source_patch+1)%level
                else
                   if (node_key_pos > node_key_recv_displ(r) + &
                        node_key_recv_count(r)) then
                      call fail( &
                           "scalar boundary source-node receive overruns")
                   end if
                   source_id = node_key_recv_buffer(node_key_pos)
                   source_patch = &
                        node_key_patch_recv_buffer(node_key_pos)
                   source_patch_node = &
                        node_key_patch_node_recv_buffer(node_key_pos)
                   source_block = node_key_block_recv_buffer(node_key_pos)
                   source_block_patch = &
                        node_key_block_patch_recv_buffer(node_key_pos)
                   source_block_level = &
                        node_key_block_level_recv_buffer(node_key_pos)
                   node_key_pos = node_key_pos+1
                   if (source_id < 0 .or. source_patch < 0 .or. &
                        source_patch_node < 0 .or. &
                        source_patch_node >= PATCH_SIZE**2 .or. &
                        source_block_level < 0 .or. &
                        source_block_level > level_end .or. &
                        (source_block == -1 .and. &
                        (source_block_patch /= -1 .or. &
                        source_block_level >= level_start)) .or. &
                        (source_block /= -1 .and. &
                        (source_block < 1 .or. &
                        source_block > size(block_catalog) .or. &
                        source_block_patch < 0 .or. &
                        source_block_level < level_start))) then
                      call fail( &
                           "scalar boundary remote patch key is invalid")
                   end if
                end if
                target_id = abs( &
                     grid(d)%unpk(AT_NODE,source_global)%elts(i))
                if (target_id < 0 .or. &
                     target_id >= grid(d)%node%length) then
                   call fail("scalar boundary owner target is invalid")
                end if
                route_index = domain_node_displ(d)+target_id+1
                route_count(route_index) = route_count(route_index)+1
                if (route_count(route_index) == 1) then
                   route_owner_rank(route_index) = r-1
                   route_source_domain(route_index) = source_global-1
                   route_source_node(route_index) = source_id
                   route_source_patch(route_index) = source_patch
                   route_source_patch_node(route_index) = &
                        source_patch_node
                   route_source_block(route_index) = source_block
                   route_source_block_patch(route_index) = &
                        source_block_patch
                   route_source_block_level(route_index) = &
                        source_block_level
                else if (route_owner_rank(route_index) /= r-1) then
                   route_owner_rank(route_index) = -2
                   route_source_domain(route_index) = -2
                   route_source_node(route_index) = -2
                   route_source_patch(route_index) = -2
                   route_source_patch_node(route_index) = -2
                   route_source_block(route_index) = -2
                   route_source_block_patch(route_index) = -2
                   route_source_block_level(route_index) = -2
                else
                   route_source_domain(route_index) = -2
                   route_source_node(route_index) = -2
                   route_source_patch(route_index) = -2
                   route_source_patch_node(route_index) = -2
                   route_source_block(route_index) = -2
                   route_source_block_patch(route_index) = -2
                   route_source_block_level(route_index) = -2
                end if
             end do
          end do
       end do
       if (r /= rank+1 .and. &
            node_key_pos /= node_key_recv_displ(r) + &
            node_key_recv_count(r)+1) then
          call fail("scalar boundary source-node receive extent differs")
       end if
    end do
    deallocate(node_key_patch_node_recv_buffer)
    deallocate(node_key_patch_node_send_buffer)
    deallocate(node_key_patch_recv_buffer)
    deallocate(node_key_patch_send_buffer)
    deallocate(node_key_block_patch_recv_buffer)
    deallocate(node_key_block_patch_send_buffer)
    deallocate(node_key_block_level_recv_buffer)
    deallocate(node_key_block_level_send_buffer)
    deallocate(node_key_block_recv_buffer)
    deallocate(node_key_block_send_buffer)
    deallocate(node_key_recv_buffer)
    deallocate(node_key_send_buffer)
    deallocate(node_key_recv_displ)
    deallocate(node_key_send_displ)
    deallocate(node_key_expected_recv_count)
    deallocate(node_key_recv_count)
    deallocate(node_key_send_count)

    ! Stage 166G: carry canonical source block identities alongside the exact
    ! source keys from resident target Domains to migrated final blocks. This
    ! remains metadata-only; field values and ownership decisions are unchanged.
    ! Carry the exact source keys from resident target Domains to migrated
    ! final blocks in the already validated scalar-boundary stream.
    if (mod(block_writeback_plan%scalar_patch_nvalue, &
         PATCH_SIZE**2) /= 0) then
       call fail("scalar boundary owner field layout is invalid")
    end if
    n_field_value = block_writeback_plan%scalar_patch_nvalue / &
         PATCH_SIZE**2
    if (n_field_value < 1) then
       call fail("scalar boundary owner field count is invalid")
    end if
    block_scalar_restriction_exchange%boundary_owner_send_buffer = 0
    block_scalar_restriction_exchange%boundary_owner_recv_buffer = 0
    block_scalar_restriction_exchange%boundary_owner_domain_send_buffer = -3
    block_scalar_restriction_exchange%boundary_owner_domain_recv_buffer = -3
    block_scalar_restriction_exchange%boundary_owner_node_send_buffer = -3
    block_scalar_restriction_exchange%boundary_owner_node_recv_buffer = -3
    do r = 1,n_process
       pos_sample = block_writeback_plan% &
            boundary_scalar_domain_send_displ(r)+1
       do slot = block_writeback_plan%recv_displ(r)+1, &
            block_writeback_plan%recv_displ(r) + &
            block_writeback_plan%recv_count(r)
          b = block_writeback_plan%recv_block(slot)
          source = source_rank(b)
          d = loc_id(block_catalog(b)%root_domain+1)+1
          if (source /= rank .or. d < 1 .or. d > size(grid) .or. &
               block_catalog(b)%owner /= r-1) then
             call fail("scalar boundary owner send route is invalid")
          end if
          do boundary_index = 1, &
               block_writeback_plan%recv_boundary_count(slot)
             metadata_pos = block_writeback_plan% &
                  recv_boundary_displ(slot)+boundary_index
             source_bdry = block_writeback_plan% &
                  recv_boundary_source(metadata_pos)
             n_node = block_writeback_plan% &
                  recv_boundary_nnode(metadata_pos)
             do field_value_slot = 1,n_field_value
                do node = 0,n_node-1
                   sample = pos_sample-1 + &
                        (field_value_slot-1)*n_node + node
                   call domain_boundary_owner_key( &
                        d,source_bdry,node,owner_class, &
                        source_global,source_id,source_patch, &
                        source_patch_node,source_block,source_block_patch, &
                        source_block_level,source_owner_rank)
                   block_scalar_restriction_exchange% &
                        boundary_owner_send_buffer(sample+1) = &
                        owner_class
                   block_scalar_restriction_exchange% &
                        boundary_owner_domain_send_buffer(sample+1) = &
                        source_global
                   block_scalar_restriction_exchange% &
                        boundary_owner_node_send_buffer(sample+1) = &
                        source_id
                   block_scalar_boundary_owner_patch_send(sample+1) = &
                        source_patch
                   block_scalar_boundary_owner_patch_node_send(sample+1) = &
                        source_patch_node
                   block_scalar_boundary_owner_block_send(sample+1) = &
                        source_block
                   block_scalar_boundary_owner_block_patch_send(sample+1) = &
                        source_block_patch
                   block_scalar_boundary_owner_block_level_send(sample+1) = &
                        source_block_level
                   block_scalar_boundary_owner_rank_send(sample+1) = &
                        source_owner_rank
                end do
             end do
             pos_sample = pos_sample + &
                  n_node*n_field_value
          end do
       end do
       if (pos_sample /= block_writeback_plan% &
            boundary_scalar_domain_send_displ(r) + &
            block_writeback_plan% &
            boundary_scalar_domain_send_count(r)+1) then
          call fail("scalar boundary owner send extent differs")
       end if
    end do

    call MPI_Alltoallv( &
         block_scalar_restriction_exchange%boundary_owner_send_buffer, &
         block_writeback_plan%boundary_scalar_domain_send_count, &
         block_writeback_plan%boundary_scalar_domain_send_displ, &
         MPI_INTEGER, &
         block_scalar_restriction_exchange%boundary_owner_recv_buffer, &
         block_writeback_plan%boundary_scalar_block_recv_count, &
         block_writeback_plan%boundary_scalar_block_recv_displ, &
         MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar boundary owner classes")
    call MPI_Alltoallv( &
         block_scalar_restriction_exchange% &
         boundary_owner_domain_send_buffer, &
         block_writeback_plan%boundary_scalar_domain_send_count, &
         block_writeback_plan%boundary_scalar_domain_send_displ, &
         MPI_INTEGER, &
         block_scalar_restriction_exchange% &
         boundary_owner_domain_recv_buffer, &
         block_writeback_plan%boundary_scalar_block_recv_count, &
         block_writeback_plan%boundary_scalar_block_recv_displ, &
         MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar boundary owner Domains")
    call MPI_Alltoallv( &
         block_scalar_restriction_exchange% &
         boundary_owner_node_send_buffer, &
         block_writeback_plan%boundary_scalar_domain_send_count, &
         block_writeback_plan%boundary_scalar_domain_send_displ, &
         MPI_INTEGER, &
         block_scalar_restriction_exchange% &
         boundary_owner_node_recv_buffer, &
         block_writeback_plan%boundary_scalar_block_recv_count, &
         block_writeback_plan%boundary_scalar_block_recv_displ, &
         MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar boundary owner nodes")
    call MPI_Alltoallv( &
         block_scalar_boundary_owner_patch_send, &
         block_writeback_plan%boundary_scalar_domain_send_count, &
         block_writeback_plan%boundary_scalar_domain_send_displ, &
         MPI_INTEGER, &
         block_scalar_boundary_owner_patch_recv, &
         block_writeback_plan%boundary_scalar_block_recv_count, &
         block_writeback_plan%boundary_scalar_block_recv_displ, &
         MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar boundary owner patches")
    call MPI_Alltoallv( &
         block_scalar_boundary_owner_patch_node_send, &
         block_writeback_plan%boundary_scalar_domain_send_count, &
         block_writeback_plan%boundary_scalar_domain_send_displ, &
         MPI_INTEGER, &
         block_scalar_boundary_owner_patch_node_recv, &
         block_writeback_plan%boundary_scalar_block_recv_count, &
         block_writeback_plan%boundary_scalar_block_recv_displ, &
         MPI_INTEGER,comm,ierr)
    call check_mpi(ierr, &
         "MPI_Alltoallv scalar boundary owner patch nodes")
    call MPI_Alltoallv( &
         block_scalar_boundary_owner_block_send, &
         block_writeback_plan%boundary_scalar_domain_send_count, &
         block_writeback_plan%boundary_scalar_domain_send_displ, &
         MPI_INTEGER, block_scalar_boundary_owner_block_recv, &
         block_writeback_plan%boundary_scalar_block_recv_count, &
         block_writeback_plan%boundary_scalar_block_recv_displ, &
         MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar boundary owner blocks")
    call MPI_Alltoallv( &
         block_scalar_boundary_owner_block_patch_send, &
         block_writeback_plan%boundary_scalar_domain_send_count, &
         block_writeback_plan%boundary_scalar_domain_send_displ, &
         MPI_INTEGER, block_scalar_boundary_owner_block_patch_recv, &
         block_writeback_plan%boundary_scalar_block_recv_count, &
         block_writeback_plan%boundary_scalar_block_recv_displ, &
         MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar boundary owner block patches")
    call MPI_Alltoallv( &
         block_scalar_boundary_owner_block_level_send, &
         block_writeback_plan%boundary_scalar_domain_send_count, &
         block_writeback_plan%boundary_scalar_domain_send_displ, &
         MPI_INTEGER, block_scalar_boundary_owner_block_level_recv, &
         block_writeback_plan%boundary_scalar_block_recv_count, &
         block_writeback_plan%boundary_scalar_block_recv_displ, &
         MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar boundary owner block levels")
    call MPI_Alltoallv( &
         block_scalar_boundary_owner_rank_send, &
         block_writeback_plan%boundary_scalar_domain_send_count, &
         block_writeback_plan%boundary_scalar_domain_send_displ, &
         MPI_INTEGER, block_scalar_boundary_owner_rank_recv, &
         block_writeback_plan%boundary_scalar_block_recv_count, &
         block_writeback_plan%boundary_scalar_block_recv_displ, &
         MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar boundary owner ranks")

    do r = 1,n_process
       pos_sample = block_writeback_plan% &
            boundary_scalar_block_recv_displ(r)+1
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          local_index = catalog_local_block(b)
          source = source_rank(b)
          if (local_index < 1 .or. local_index > n_local .or. &
               source /= r-1) then
             call fail("scalar boundary owner receive route is invalid")
          end if
          owner_pos = block_scalar_restriction_exchange% &
               boundary_source_displ(local_index)+1
          do boundary_index = 1,local_block_boundary_count(b)
             call get_local_block_boundary_source( &
                  b,boundary_index,source_bdry,elts_start,n_node)
             do node = 0,n_node-1
                owner_class = block_scalar_restriction_exchange% &
                     boundary_owner_recv_buffer(pos_sample+node)
                source_global = block_scalar_restriction_exchange% &
                     boundary_owner_domain_recv_buffer(pos_sample+node)
                source_id = block_scalar_restriction_exchange% &
                     boundary_owner_node_recv_buffer(pos_sample+node)
                source_patch = block_scalar_boundary_owner_patch_recv( &
                     pos_sample+node)
                source_patch_node = block_scalar_boundary_owner_patch_node_recv( &
                     pos_sample+node)
                source_block = block_scalar_boundary_owner_block_recv( &
                     pos_sample+node)
                source_block_patch = block_scalar_boundary_owner_block_patch_recv( &
                     pos_sample+node)
                source_block_level = block_scalar_boundary_owner_block_level_recv( &
                     pos_sample+node)
                source_owner_rank = block_scalar_boundary_owner_rank_recv( &
                     pos_sample+node)
                do field_value_slot = 1,n_field_value
                   sample = pos_sample-1 + &
                        (field_value_slot-1)*n_node + node
                   if (block_scalar_restriction_exchange% &
                        boundary_owner_recv_buffer(sample+1) /= &
                        owner_class .or. &
                        block_scalar_restriction_exchange% &
                        boundary_owner_domain_recv_buffer(sample+1) /= &
                        source_global .or. &
                        block_scalar_restriction_exchange% &
                        boundary_owner_node_recv_buffer(sample+1) /= &
                        source_id .or. &
                        block_scalar_boundary_owner_patch_recv(sample+1) /= &
                        source_patch .or. &
                        block_scalar_boundary_owner_patch_node_recv(sample+1) /= &
                        source_patch_node .or. &
                        block_scalar_boundary_owner_block_recv(sample+1) /= &
                        source_block .or. &
                        block_scalar_boundary_owner_block_patch_recv(sample+1) /= &
                        source_block_patch .or. &
                        block_scalar_boundary_owner_block_level_recv(sample+1) /= &
                        source_block_level .or. &
                        block_scalar_boundary_owner_rank_recv(sample+1) /= &
                        source_owner_rank) then
                      call fail( &
                           "scalar boundary owner replicas differ")
                   end if
                end do
                block_scalar_restriction_exchange% &
                     boundary_source_owner_class(owner_pos+node) = &
                     owner_class
                block_scalar_restriction_exchange% &
                     boundary_source_owner_domain(owner_pos+node) = &
                     source_global
                block_scalar_restriction_exchange% &
                     boundary_source_owner_node(owner_pos+node) = &
                     source_id
                block_scalar_boundary_owner_patch(owner_pos+node) = &
                     source_patch
                block_scalar_boundary_owner_patch_node(owner_pos+node) = &
                     source_patch_node
                block_scalar_boundary_owner_block(owner_pos+node) = source_block
                block_scalar_boundary_owner_block_patch(owner_pos+node) = &
                     source_block_patch
                block_scalar_boundary_owner_block_level(owner_pos+node) = &
                     source_block_level
                block_scalar_boundary_owner_rank(owner_pos+node) = &
                     source_owner_rank
             end do
             owner_pos = owner_pos+n_node
             pos_sample = pos_sample + &
                  n_node*n_field_value
          end do
          if (owner_pos /= block_scalar_restriction_exchange% &
               boundary_source_displ(local_index+1)+1) then
             call fail("scalar boundary owner receive coverage differs")
          end if
       end do
       if (pos_sample /= block_writeback_plan% &
            boundary_scalar_block_recv_displ(r) + &
            block_writeback_plan% &
            boundary_scalar_block_recv_count(r)+1) then
          call fail("scalar boundary owner receive extent differs")
       end if
    end do

    do local_index = 1,n_local
       b = local_block_catalog(local_index)
       if (source_rank(b) /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1)+1
       if (d < 1 .or. d > size(grid)) then
          call fail("retained scalar boundary owner Domain is invalid")
       end if
       owner_pos = block_scalar_restriction_exchange% &
            boundary_source_displ(local_index)+1
       do boundary_index = 1,local_block_boundary_count(b)
          call get_local_block_boundary_source( &
               b,boundary_index,source_bdry,elts_start,n_node)
          do node = 0,n_node-1
             call domain_boundary_owner_key( &
                  d,source_bdry,node,owner_class, &
                  source_global,source_id,source_patch,source_patch_node, &
                  source_block,source_block_patch,source_block_level, &
                  source_owner_rank)
             block_scalar_restriction_exchange% &
                  boundary_source_owner_class(owner_pos+node) = &
                  owner_class
             block_scalar_restriction_exchange% &
                  boundary_source_owner_domain(owner_pos+node) = &
                  source_global
             block_scalar_restriction_exchange% &
                  boundary_source_owner_node(owner_pos+node) = source_id
             block_scalar_boundary_owner_patch(owner_pos+node) = &
                  source_patch
             block_scalar_boundary_owner_patch_node(owner_pos+node) = &
                  source_patch_node
             block_scalar_boundary_owner_block(owner_pos+node) = source_block
             block_scalar_boundary_owner_block_patch(owner_pos+node) = &
                  source_block_patch
             block_scalar_boundary_owner_block_level(owner_pos+node) = &
                  source_block_level
             block_scalar_boundary_owner_rank(owner_pos+node) = &
                  source_owner_rank
          end do
          owner_pos = owner_pos+n_node
       end do
       if (owner_pos /= block_scalar_restriction_exchange% &
            boundary_source_displ(local_index+1)+1) then
          call fail("retained scalar boundary owner coverage differs")
       end if
    end do
    deallocate(route_source_patch_node)
    deallocate(route_source_block_level)
    deallocate(route_source_block_patch)
    deallocate(route_source_block)
    deallocate(route_source_patch)
    deallocate(route_source_node)
    deallocate(route_source_domain)
    deallocate(route_owner_rank)
    deallocate(route_count)
    deallocate(domain_patch_block_patch)
    deallocate(domain_patch_block)
    deallocate(domain_patch_displ)
    deallocate(domain_node_patch_node)
    deallocate(domain_node_patch)
    deallocate(domain_node_displ)

    owner_count_local = 0_int64
    do pos = 1,total_node
       r = block_scalar_restriction_exchange% &
            boundary_source_owner_class(pos)
       if (r < 1 .or. r > BLOCK_BOUNDARY_OWNER_CLASS_COUNT) then
          call fail("scalar boundary owner class is invalid")
       end if
       owner_count_local(r) = owner_count_local(r)+1_int64
    end do
    if (sum(owner_count_local) /= int(total_node,int64)) then
       call fail("scalar boundary owner coverage differs")
    end if
    source_key_count_local = 0_int64
    patch_key_count_local = 0_int64
    block_key_count_local = 0_int64
    cache_count_local = 0_int64
    n_cache = 0
    do pos = 1,total_node
       owner_class = block_scalar_restriction_exchange% &
            boundary_source_owner_class(pos)
       source_global = block_scalar_restriction_exchange% &
            boundary_source_owner_domain(pos)
       source_id = block_scalar_restriction_exchange% &
            boundary_source_owner_node(pos)
       source_patch = block_scalar_boundary_owner_patch(pos)
       source_patch_node = block_scalar_boundary_owner_patch_node(pos)
       source_block = block_scalar_boundary_owner_block(pos)
       source_block_patch = block_scalar_boundary_owner_block_patch(pos)
       source_block_level = block_scalar_boundary_owner_block_level(pos)
       source_owner_rank = block_scalar_boundary_owner_rank(pos)
       select case (owner_class)
       case (BLOCK_BOUNDARY_OWNER_LOCAL)
          if (source_global < 0 .or. source_id < 0 .or. &
               source_owner_rank < 0 .or. &
               source_owner_rank >= n_process) then
             call fail("local scalar boundary source key is incomplete")
          end if
          source_key_count_local(1) = source_key_count_local(1)+1_int64
          call assign_boundary_cache_slot(pos,n_cache)
          cache_count_local(1) = cache_count_local(1)+1_int64
          if (source_patch < 0 .or. source_patch_node < 0 .or. &
               source_patch_node >= PATCH_SIZE**2) then
             call fail("local scalar boundary patch key is incomplete")
          end if
          patch_key_count_local(1) = patch_key_count_local(1)+1_int64
          if (source_block >= 1 .and. &
               source_block <= size(block_catalog) .and. &
               source_block_patch >= 0 .and. &
               source_block_level >= level_start .and. &
               source_block_level <= level_end) then
             if (block_catalog(source_block)%root_domain /= source_global) &
                  call fail("local scalar boundary block Domain differs")
             if (block_catalog(source_block)%owner == rank) then
                block_key_count_local(1) = &
                     block_key_count_local(1)+1_int64
             else
                block_key_count_local(2) = &
                     block_key_count_local(2)+1_int64
             end if
          else if (source_block == -1 .and. source_block_patch == -1 .and. &
               source_block_level >= 0 .and. &
               source_block_level < level_start) then
             block_key_count_local(3) = block_key_count_local(3)+1_int64
          else
             call fail("local scalar boundary block key is invalid")
          end if
       case (BLOCK_BOUNDARY_OWNER_REMOTE)
          if (source_global < 0 .or. source_id < 0 .or. &
               source_owner_rank < 0 .or. &
               source_owner_rank >= n_process) then
             call fail("remote scalar boundary source key is incomplete")
          end if
          source_key_count_local(2) = source_key_count_local(2)+1_int64
          call assign_boundary_cache_slot(pos,n_cache)
          cache_count_local(2) = cache_count_local(2)+1_int64
          if (source_patch < 0 .or. source_patch_node < 0 .or. &
               source_patch_node >= PATCH_SIZE**2) then
             call fail("remote scalar boundary patch key is incomplete")
          end if
          patch_key_count_local(2) = patch_key_count_local(2)+1_int64
          if (source_block >= 1 .and. &
               source_block <= size(block_catalog) .and. &
               source_block_patch >= 0 .and. &
               source_block_level >= level_start .and. &
               source_block_level <= level_end) then
             if (block_catalog(source_block)%root_domain /= source_global) &
                  call fail("remote scalar boundary block Domain differs")
             if (block_catalog(source_block)%owner == rank) then
                block_key_count_local(1) = &
                     block_key_count_local(1)+1_int64
             else
                block_key_count_local(2) = &
                     block_key_count_local(2)+1_int64
             end if
          else if (source_block == -1 .and. source_block_patch == -1 .and. &
               source_block_level >= 0 .and. &
               source_block_level < level_start) then
             block_key_count_local(3) = block_key_count_local(3)+1_int64
          else
             call fail("remote scalar boundary block key is invalid")
          end if
       case (BLOCK_BOUNDARY_OWNER_SCAFFOLD)
          if (source_global /= -1 .or. source_id /= -1 .or. &
               source_owner_rank /= -1 .or. &
               source_patch /= -1 .or. source_patch_node /= -1) then
             call fail("scaffold scalar boundary source key is invalid")
          end if
          source_key_count_local(3) = source_key_count_local(3)+1_int64
          patch_key_count_local(3) = patch_key_count_local(3)+1_int64
          block_scalar_boundary_cache_slot(pos) = -1
          if (source_block /= -1 .or. source_block_patch /= -1 .or. &
               source_block_level /= -1) then
             call fail("scaffold scalar boundary block key is invalid")
          end if
       case (BLOCK_BOUNDARY_OWNER_AMBIGUOUS)
          if (source_global /= -2 .or. source_id /= -2 .or. &
               source_owner_rank /= -2 .or. &
               source_patch /= -2 .or. source_patch_node /= -2) then
             call fail("ambiguous scalar boundary source key is invalid")
          end if
          source_key_count_local(4) = source_key_count_local(4)+1_int64
          patch_key_count_local(4) = patch_key_count_local(4)+1_int64
          if (source_block /= -2 .or. source_block_patch /= -2 .or. &
               source_block_level /= -2) then
             call fail("ambiguous scalar boundary block key is invalid")
          end if
          block_key_count_local(4) = block_key_count_local(4)+1_int64
          block_scalar_boundary_cache_slot(pos) = -2
       case default
          call fail("scalar boundary source key class is invalid")
       end select
    end do
    if (sum(source_key_count_local) /= int(total_node,int64)) then
       call fail("scalar boundary source key coverage differs")
    end if
    if (any(patch_key_count_local /= source_key_count_local)) then
       call fail("scalar boundary patch key coverage differs")
    end if
    if (sum(block_key_count_local) /= &
         source_key_count_local(1)+source_key_count_local(2)+ &
         source_key_count_local(4)) then
       call fail("scalar boundary final-owner block coverage differs")
    end if
    block_scalar_boundary_cache_count = n_cache
    block_scalar_boundary_cache_field_count = n_field_value
    allocate(block_scalar_boundary_cache_value(max(1, &
         n_cache*n_field_value)))
    allocate(block_scalar_boundary_cache_covered(max(1, &
         n_cache*n_field_value)))
    block_scalar_boundary_cache_value = BLOCK_BOUNDARY_POISON
    block_scalar_boundary_cache_covered = .false.
    do cache_slot = 1,n_cache
       if (block_scalar_boundary_cache_rank(cache_slot) == rank) then
          cache_count_local(3) = cache_count_local(3)+1_int64
       else
          cache_count_local(4) = cache_count_local(4)+1_int64
       end if
    end do
    cache_count_local(5) = cache_count_local(1)+cache_count_local(2) - &
         cache_count_local(3)-cache_count_local(4)
    if (cache_count_local(5) < 0_int64 .or. &
         n_cache /= int(cache_count_local(3)+cache_count_local(4))) then
       call fail("scalar boundary cache coverage differs")
    end if
    call prepare_boundary_cache_request_plan( &
         n_cache,cache_request_count_local)
    if (cache_request_count_local(1) /= cache_count_local(3) .or. &
         cache_request_count_local(2) /= cache_count_local(4)) then
       call fail("scalar boundary cache request coverage differs")
    end if
    call prepare_final_boundary_plan( &
         n_cache,n_field_value,total_node,final_request_count_local)

    if (block_dynamics_validation_enabled()) then
       call MPI_Allreduce(owner_count_local,owner_count_global, &
            BLOCK_BOUNDARY_OWNER_CLASS_COUNT,MPI_INTEGER8,MPI_SUM, &
            comm,ierr)
       call check_mpi(ierr,"MPI_Allreduce scalar boundary owner classes")
       call MPI_Allreduce(source_key_count_local,source_key_count_global, &
            4,MPI_INTEGER8,MPI_SUM,comm,ierr)
       call check_mpi(ierr,"MPI_Allreduce scalar boundary source keys")
       call MPI_Allreduce(patch_key_count_local,patch_key_count_global, &
            4,MPI_INTEGER8,MPI_SUM,comm,ierr)
       call check_mpi(ierr,"MPI_Allreduce scalar boundary patch keys")
       call MPI_Allreduce(block_key_count_local,block_key_count_global, &
            4,MPI_INTEGER8,MPI_SUM,comm,ierr)
       call check_mpi(ierr,"MPI_Allreduce scalar boundary block keys")
       call MPI_Allreduce(cache_count_local,cache_count_global, &
            5,MPI_INTEGER8,MPI_SUM,comm,ierr)
       call check_mpi(ierr,"MPI_Allreduce scalar boundary cache slots")
       call MPI_Allreduce(cache_request_count_local, &
            cache_request_count_global,3,MPI_INTEGER8,MPI_SUM,comm,ierr)
       call check_mpi(ierr,"MPI_Allreduce scalar boundary cache requests")
       call MPI_Allreduce(final_request_count_local, &
            final_request_count_global,3,MPI_INTEGER8,MPI_SUM,comm,ierr)
       call check_mpi(ierr,"MPI_Allreduce scalar boundary final requests")
       if (cache_request_count_global(2) /= &
            cache_request_count_global(3)) then
          call fail("scalar boundary cache global requests differ")
       end if
       if (sum(owner_count_global) <= 0_int64) then
          call fail("scalar boundary owner coverage is empty")
       end if
       count_local = int(total_node,int64)
       call MPI_Allreduce(count_local,count_global,1,MPI_INTEGER8, &
            MPI_SUM,comm,ierr)
       call check_mpi(ierr,"MPI_Allreduce scalar boundary provenance")
       if (count_global <= 0_int64) then
          call fail("scalar boundary provenance coverage is empty")
       end if
       if (rank == 0) write(6,'(a,i0)') &
            "Block scalar boundary provenance nodes = ",count_global
       if (rank == 0) write(6,'(a,4(i0,1x))') &
            "Block scalar boundary owner classes: " // &
            "local remote scaffold ambiguous = ",owner_count_global
       if (rank == 0) write(6,'(a,4(i0,1x))') &
            "Block scalar boundary source keys: " // &
            "exact-local exact-remote scaffold ambiguous = ", &
            source_key_count_global
       if (rank == 0) write(6,'(a,4(i0,1x))') &
            "Block scalar boundary patch keys: " // &
            "exact-local exact-remote scaffold ambiguous = ", &
            patch_key_count_global
       if (rank == 0) write(6,'(a,4(i0,1x))') &
            "Block scalar boundary block keys: " // &
            "final-local final-remote uncatalogued ambiguous = ", &
            block_key_count_global
       if (rank == 0) write(6,'(a,5(i0,1x))') &
            "Block scalar boundary cache: " // &
            "route-local route-remote cache-local cache-remote reused = ", &
            cache_count_global
       if (rank == 0) write(6,'(a,3(i0,1x))') &
            "Block scalar boundary cache requests: " // &
            "local remote-send remote-service = ", &
            cache_request_count_global
       if (rank == 0) write(6,'(a,3(i0,1x))') &
            "Block scalar boundary final requests: " // &
            "local remote-send remote-service = ", &
            final_request_count_global
    end if

  contains

    subroutine prepare_final_boundary_plan ( &
         n_cache,n_field_value,total_boundary_node,request_count)
      ! Build the final-block-owner route once. Requests are ordered by peer
      ! and source level, so every replay level can append its scalar values
      ! to the existing sparse ghost message without rebuilding a manifest.

      implicit none

      integer, parameter :: REQUEST_SIZE = 4

      integer, intent(in) :: n_cache
      integer, intent(in) :: n_field_value
      integer, intent(in) :: total_boundary_node
      integer(int64), intent(out) :: request_count(3)

      integer :: b
      integer :: boundary_count
      integer :: cache_slot
      integer :: field_count
      integer :: i
      integer :: ierr
      integer :: level_slot
      integer :: local_index
      integer :: n_level
      integer :: node_offset
      integer :: patch_count
      integer :: pos
      integer :: r
      integer :: record
      integer :: route_level
      integer :: routed_cache_count

      integer, allocatable :: cursor(:,:)
      integer, allocatable :: fill(:)
      integer, allocatable :: recv_count(:)
      integer, allocatable :: recv_data(:)
      integer, allocatable :: recv_displ(:)
      integer, allocatable :: send_count(:)
      integer, allocatable :: send_data(:)
      integer, allocatable :: send_displ(:)

      n_level = level_end-level_start+1
      if (n_cache < 0 .or. n_field_value < 1 .or. n_level < 1) then
         call fail("scalar boundary final route layout is invalid")
      end if
      block_scalar_boundary_final_plan%route_level_start = level_start
      block_scalar_boundary_final_plan%route_level_count = n_level
      block_scalar_boundary_final_plan%cache_count = n_cache
      block_scalar_boundary_final_plan%field_count = n_field_value

      allocate(block_scalar_boundary_final_plan% &
           local_level_count(n_level))
      allocate(block_scalar_boundary_final_plan% &
           local_level_displ(n_level))
      allocate(block_scalar_boundary_final_plan%request_count(n_process))
      allocate(block_scalar_boundary_final_plan%request_displ(n_process))
      allocate(block_scalar_boundary_final_plan% &
           request_level_count(n_process,n_level))
      allocate(block_scalar_boundary_final_plan% &
           request_level_displ(n_process,n_level))
      allocate(block_scalar_boundary_final_plan%service_count(n_process))
      allocate(block_scalar_boundary_final_plan%service_displ(n_process))
      allocate(block_scalar_boundary_final_plan% &
           service_level_count(n_process,n_level))
      allocate(block_scalar_boundary_final_plan% &
           service_level_displ(n_process,n_level))
      allocate(block_scalar_boundary_final_plan% &
           boundary_level_count(n_level))
      allocate(block_scalar_boundary_final_plan% &
           boundary_level_displ(n_level))

      block_scalar_boundary_final_plan%local_level_count = 0
      block_scalar_boundary_final_plan%request_count = 0
      block_scalar_boundary_final_plan%request_level_count = 0
      block_scalar_boundary_final_plan%service_level_count = 0
      block_scalar_boundary_final_plan%boundary_level_count = 0
      routed_cache_count = 0
      do cache_slot = 1,n_cache
         route_level = block_scalar_boundary_final_plan% &
              cache_level(cache_slot)
         if (block_scalar_boundary_final_plan% &
              cache_rank(cache_slot) < 0 .or. &
              route_level <= level_start) cycle
         level_slot = route_level-level_start+1
         r = block_scalar_boundary_final_plan%cache_rank(cache_slot)+1
         if (level_slot < 1 .or. level_slot > n_level .or. &
              r < 1 .or. r > n_process) then
            call fail("scalar boundary final cache route is invalid")
         end if
         if (r == rank+1) then
            block_scalar_boundary_final_plan% &
                 local_level_count(level_slot) = &
                 block_scalar_boundary_final_plan% &
                 local_level_count(level_slot)+1
         else
            block_scalar_boundary_final_plan%request_count(r) = &
                 block_scalar_boundary_final_plan%request_count(r)+1
            block_scalar_boundary_final_plan% &
                 request_level_count(r,level_slot) = &
                 block_scalar_boundary_final_plan% &
                 request_level_count(r,level_slot)+1
         end if
         routed_cache_count = routed_cache_count+1
      end do

      call MPI_Alltoall(block_scalar_boundary_final_plan%request_count,1, &
           MPI_INTEGER,block_scalar_boundary_final_plan%service_count,1, &
           MPI_INTEGER,comm,ierr)
      call check_mpi(ierr,"MPI_Alltoall scalar boundary final requests")
      block_scalar_boundary_final_plan%request_displ(1) = 0
      block_scalar_boundary_final_plan%service_displ(1) = 0
      do r = 2,n_process
         block_scalar_boundary_final_plan%request_displ(r) = &
              block_scalar_boundary_final_plan%request_displ(r-1) + &
              block_scalar_boundary_final_plan%request_count(r-1)
         block_scalar_boundary_final_plan%service_displ(r) = &
              block_scalar_boundary_final_plan%service_displ(r-1) + &
              block_scalar_boundary_final_plan%service_count(r-1)
      end do
      block_scalar_boundary_final_plan%request_level_displ(:,1) = 0
      do level_slot = 2,n_level
         block_scalar_boundary_final_plan% &
              request_level_displ(:,level_slot) = &
              block_scalar_boundary_final_plan% &
              request_level_displ(:,level_slot-1) + &
              block_scalar_boundary_final_plan% &
              request_level_count(:,level_slot-1)
      end do

      allocate(block_scalar_boundary_final_plan%request_cache_slot( &
           max(1,sum(block_scalar_boundary_final_plan%request_count))))
      allocate(send_data(max(1,REQUEST_SIZE*sum( &
           block_scalar_boundary_final_plan%request_count))))
      allocate(recv_data(max(1,REQUEST_SIZE*sum( &
           block_scalar_boundary_final_plan%service_count))))
      allocate(cursor(n_process,n_level))
      cursor = 0
      send_data = -1
      block_scalar_boundary_final_plan%request_cache_slot = -1
      do cache_slot = 1,n_cache
         if (block_scalar_boundary_final_plan% &
              cache_rank(cache_slot) < 0 .or. &
              block_scalar_boundary_final_plan% &
              cache_level(cache_slot) <= level_start) cycle
         r = block_scalar_boundary_final_plan%cache_rank(cache_slot)+1
         if (r == rank+1) cycle
         level_slot = block_scalar_boundary_final_plan% &
              cache_level(cache_slot)-level_start+1
         record = block_scalar_boundary_final_plan%request_displ(r) + &
              block_scalar_boundary_final_plan% &
              request_level_displ(r,level_slot) + &
              cursor(r,level_slot)+1
         pos = REQUEST_SIZE*(record-1)
         send_data(pos+1:pos+REQUEST_SIZE) = [ &
              block_scalar_boundary_final_plan%cache_block(cache_slot), &
              block_scalar_boundary_final_plan%cache_patch(cache_slot), &
              block_scalar_boundary_final_plan%cache_node(cache_slot), &
              block_scalar_boundary_final_plan%cache_level(cache_slot) ]
         block_scalar_boundary_final_plan%request_cache_slot(record) = &
              cache_slot
         cursor(r,level_slot) = cursor(r,level_slot)+1
      end do
      if (any(cursor /= &
           block_scalar_boundary_final_plan%request_level_count)) then
         call fail("scalar boundary final request fill differs")
      end if
      deallocate(cursor)

      allocate(send_count(n_process))
      allocate(recv_count(n_process))
      allocate(send_displ(n_process))
      allocate(recv_displ(n_process))
      send_count = REQUEST_SIZE* &
           block_scalar_boundary_final_plan%request_count
      recv_count = REQUEST_SIZE* &
           block_scalar_boundary_final_plan%service_count
      send_displ = REQUEST_SIZE* &
           block_scalar_boundary_final_plan%request_displ
      recv_displ = REQUEST_SIZE* &
           block_scalar_boundary_final_plan%service_displ
      call MPI_Alltoallv(send_data,send_count,send_displ,MPI_INTEGER, &
           recv_data,recv_count,recv_displ,MPI_INTEGER,comm,ierr)
      call check_mpi(ierr,"MPI_Alltoallv scalar boundary final manifest")
      deallocate(recv_displ)
      deallocate(send_displ)
      deallocate(recv_count)
      deallocate(send_count)
      deallocate(send_data)

      allocate(block_scalar_boundary_final_plan%service_block( &
           max(1,sum(block_scalar_boundary_final_plan%service_count))))
      allocate(block_scalar_boundary_final_plan%service_patch( &
           max(1,sum(block_scalar_boundary_final_plan%service_count))))
      allocate(block_scalar_boundary_final_plan%service_node( &
           max(1,sum(block_scalar_boundary_final_plan%service_count))))
      allocate(block_scalar_boundary_final_plan%service_level( &
           max(1,sum(block_scalar_boundary_final_plan%service_count))))
      block_scalar_boundary_final_plan%service_block = -1
      block_scalar_boundary_final_plan%service_patch = -1
      block_scalar_boundary_final_plan%service_node = -1
      block_scalar_boundary_final_plan%service_level = -1
      do record = 1, &
           sum(block_scalar_boundary_final_plan%service_count)
         pos = REQUEST_SIZE*(record-1)
         block_scalar_boundary_final_plan%service_block(record) = &
              recv_data(pos+1)
         block_scalar_boundary_final_plan%service_patch(record) = &
              recv_data(pos+2)
         block_scalar_boundary_final_plan%service_node(record) = &
              recv_data(pos+3)
         block_scalar_boundary_final_plan%service_level(record) = &
              recv_data(pos+4)
      end do
      deallocate(recv_data)

      do r = 1,n_process
         do i = 0,block_scalar_boundary_final_plan%service_count(r)-1
            record = block_scalar_boundary_final_plan%service_displ(r)+i+1
            route_level = block_scalar_boundary_final_plan% &
                 service_level(record)
            level_slot = route_level-level_start+1
            b = block_scalar_boundary_final_plan%service_block(record)
            if (level_slot < 1 .or. level_slot > n_level .or. &
                 b < 1 .or. b > size(block_catalog)) &
                 call fail("scalar boundary final service key is invalid")
            local_index = catalog_local_block(b)
            if (block_catalog(b)%owner /= rank .or. &
                 local_index < 1 .or. &
                 local_index > n_local) then
               call fail("scalar boundary final service key is invalid")
            end if
            patch_count = local_block_patch_count(b)
            if (block_scalar_boundary_final_plan% &
                 service_patch(record) < 0 .or. &
                 block_scalar_boundary_final_plan% &
                 service_patch(record) >= patch_count) &
                 call fail("scalar boundary final service patch is invalid")
            if (block_scalar_boundary_final_plan% &
                 service_node(record) < 0 .or. &
                 block_scalar_boundary_final_plan% &
                 service_node(record) >= PATCH_SIZE**2) &
                 call fail("scalar boundary final service node is invalid")
            if (local_block_patch_level( &
                 b,block_scalar_boundary_final_plan% &
                 service_patch(record)) /= route_level) then
               call fail("scalar boundary final service level differs")
            end if
            block_scalar_boundary_final_plan% &
                 service_level_count(r,level_slot) = &
                 block_scalar_boundary_final_plan% &
                 service_level_count(r,level_slot)+1
         end do
      end do
      block_scalar_boundary_final_plan%service_level_displ(:,1) = 0
      do level_slot = 2,n_level
         block_scalar_boundary_final_plan% &
              service_level_displ(:,level_slot) = &
              block_scalar_boundary_final_plan% &
              service_level_displ(:,level_slot-1) + &
              block_scalar_boundary_final_plan% &
              service_level_count(:,level_slot-1)
      end do
      do r = 1,n_process
         do level_slot = 1,n_level
            do i = 0,block_scalar_boundary_final_plan% &
                 service_level_count(r,level_slot)-1
               record = block_scalar_boundary_final_plan% &
                    service_displ(r) + &
                    block_scalar_boundary_final_plan% &
                    service_level_displ(r,level_slot)+i+1
               if (block_scalar_boundary_final_plan% &
                    service_level(record) /= &
                    level_start+level_slot-1) then
                  call fail("scalar boundary final service order differs")
               end if
            end do
         end do
      end do

      block_scalar_boundary_final_plan%local_level_displ(1) = 0
      block_scalar_boundary_final_plan%boundary_level_displ(1) = 0
      do level_slot = 2,n_level
         block_scalar_boundary_final_plan%local_level_displ(level_slot) = &
              block_scalar_boundary_final_plan% &
              local_level_displ(level_slot-1) + &
              block_scalar_boundary_final_plan% &
              local_level_count(level_slot-1)
         block_scalar_boundary_final_plan% &
              boundary_level_displ(level_slot) = &
              block_scalar_boundary_final_plan% &
              boundary_level_displ(level_slot-1) + &
              block_scalar_boundary_final_plan% &
              boundary_level_count(level_slot-1)
      end do
      allocate(block_scalar_boundary_final_plan%local_cache_slot( &
           max(1,sum(block_scalar_boundary_final_plan% &
           local_level_count))))
      allocate(fill(n_level))
      fill = 0
      do cache_slot = 1,n_cache
         if (block_scalar_boundary_final_plan% &
              cache_rank(cache_slot) < 0 .or. &
              block_scalar_boundary_final_plan% &
              cache_level(cache_slot) <= level_start) cycle
         if (block_scalar_boundary_final_plan%cache_rank(cache_slot) /= &
              rank) cycle
         level_slot = block_scalar_boundary_final_plan% &
              cache_level(cache_slot)-level_start+1
         pos = block_scalar_boundary_final_plan% &
              local_level_displ(level_slot)+fill(level_slot)+1
         block_scalar_boundary_final_plan%local_cache_slot(pos) = &
              cache_slot
         fill(level_slot) = fill(level_slot)+1
      end do
      if (any(fill /= &
           block_scalar_boundary_final_plan%local_level_count)) then
         call fail("scalar boundary final local fill differs")
      end if

      do pos = 1,total_boundary_node
         cache_slot = block_scalar_boundary_cache_slot(pos)+1
         if (cache_slot < 1) cycle
         if (block_scalar_boundary_final_plan% &
              cache_rank(cache_slot) < 0 .or. &
              block_scalar_boundary_final_plan% &
              cache_level(cache_slot) <= level_start) cycle
         level_slot = block_scalar_boundary_final_plan% &
              cache_level(cache_slot)-level_start+1
         if (level_slot < 1 .or. level_slot > n_level) then
            call fail("scalar boundary final scatter level differs")
         end if
         block_scalar_boundary_final_plan% &
              boundary_level_count(level_slot) = &
              block_scalar_boundary_final_plan% &
              boundary_level_count(level_slot)+1
      end do
      block_scalar_boundary_final_plan%boundary_level_displ(1) = 0
      do level_slot = 2,n_level
         block_scalar_boundary_final_plan% &
              boundary_level_displ(level_slot) = &
              block_scalar_boundary_final_plan% &
              boundary_level_displ(level_slot-1) + &
              block_scalar_boundary_final_plan% &
              boundary_level_count(level_slot-1)
      end do
      boundary_count = sum( &
           block_scalar_boundary_final_plan%boundary_level_count)
      allocate(block_scalar_boundary_final_plan% &
           boundary_local_index(max(1,boundary_count)))
      allocate(block_scalar_boundary_final_plan% &
           boundary_node(max(1,boundary_count)))
      allocate(block_scalar_boundary_final_plan% &
           boundary_cache_slot(max(1,boundary_count)))
      fill = 0
      do local_index = 1,n_local_blocks()
         do pos = block_scalar_restriction_exchange% &
              boundary_source_displ(local_index)+1, &
              block_scalar_restriction_exchange% &
              boundary_source_displ(local_index+1)
            cache_slot = block_scalar_boundary_cache_slot(pos)+1
            if (cache_slot < 1) cycle
            if (block_scalar_boundary_final_plan% &
                 cache_rank(cache_slot) < 0 .or. &
                 block_scalar_boundary_final_plan% &
                 cache_level(cache_slot) <= level_start) cycle
            level_slot = block_scalar_boundary_final_plan% &
                 cache_level(cache_slot)-level_start+1
            record = block_scalar_boundary_final_plan% &
                 boundary_level_displ(level_slot)+fill(level_slot)+1
            node_offset = pos-block_scalar_restriction_exchange% &
                 boundary_source_displ(local_index)-1
            block_scalar_boundary_final_plan% &
                 boundary_local_index(record) = local_index
            block_scalar_boundary_final_plan%boundary_node(record) = &
                 node_offset
            block_scalar_boundary_final_plan% &
                 boundary_cache_slot(record) = cache_slot
            fill(level_slot) = fill(level_slot)+1
         end do
      end do
      if (any(fill /= &
           block_scalar_boundary_final_plan%boundary_level_count)) then
         call fail("scalar boundary final scatter fill differs")
      end if
      deallocate(fill)

      field_count = max(1,n_cache*n_field_value)
      allocate(block_scalar_boundary_final_plan%value(field_count))
      allocate(block_scalar_boundary_final_plan%covered(field_count))
      block_scalar_boundary_final_plan%value = BLOCK_BOUNDARY_POISON
      block_scalar_boundary_final_plan%covered = .false.
      block_scalar_boundary_final_plan%ready = .true.

      request_count(1) = int(sum( &
           block_scalar_boundary_final_plan%local_level_count),int64)
      request_count(2) = int(sum( &
           block_scalar_boundary_final_plan%request_count),int64)
      request_count(3) = int(sum( &
           block_scalar_boundary_final_plan%service_count),int64)
      if (request_count(1)+request_count(2) /= &
           int(routed_cache_count,int64)) then
         call fail("scalar boundary final request coverage differs")
      end if

    end subroutine prepare_final_boundary_plan

    subroutine prepare_boundary_cache_request_plan ( &
         n_cache,request_count)
      ! Stage 166J: request each unique remote source node once from its
      ! authoritative AT_NODE rank.  Values remain unpopulated until the
      ! following shadow-transport stage.

      implicit none

      integer, intent(in) :: n_cache
      integer(int64), intent(out) :: request_count(3)

      integer :: cache_slot
      integer :: d_source
      integer :: ierr
      integer :: pos
      integer :: r
      integer :: source_domain
      integer :: source_node

      integer, allocatable :: cursor(:)

      allocate(block_scalar_boundary_cache_send_count(n_process))
      allocate(block_scalar_boundary_cache_recv_count(n_process))
      allocate(block_scalar_boundary_cache_send_displ(n_process))
      allocate(block_scalar_boundary_cache_recv_displ(n_process))
      block_scalar_boundary_cache_send_count = 0
      do cache_slot = 1,n_cache
         r = block_scalar_boundary_cache_rank(cache_slot)+1
         if (r < 1 .or. r > n_process) then
            call fail("scalar boundary cache request rank is invalid")
         end if
         if (r == rank+1) cycle
         block_scalar_boundary_cache_send_count(r) = &
              block_scalar_boundary_cache_send_count(r)+1
      end do
      call MPI_Alltoall(block_scalar_boundary_cache_send_count,1, &
           MPI_INTEGER,block_scalar_boundary_cache_recv_count,1, &
           MPI_INTEGER,comm,ierr)
      call check_mpi(ierr,"MPI_Alltoall scalar boundary cache requests")
      block_scalar_boundary_cache_send_displ(1) = 0
      block_scalar_boundary_cache_recv_displ(1) = 0
      do r = 2,n_process
         block_scalar_boundary_cache_send_displ(r) = &
              block_scalar_boundary_cache_send_displ(r-1) + &
              block_scalar_boundary_cache_send_count(r-1)
         block_scalar_boundary_cache_recv_displ(r) = &
              block_scalar_boundary_cache_recv_displ(r-1) + &
              block_scalar_boundary_cache_recv_count(r-1)
      end do

      allocate(block_scalar_boundary_cache_domain_send(max(1, &
           sum(block_scalar_boundary_cache_send_count))))
      allocate(block_scalar_boundary_cache_domain_recv(max(1, &
           sum(block_scalar_boundary_cache_recv_count))))
      allocate(block_scalar_boundary_cache_node_send(max(1, &
           sum(block_scalar_boundary_cache_send_count))))
      allocate(block_scalar_boundary_cache_node_recv(max(1, &
           sum(block_scalar_boundary_cache_recv_count))))
      allocate(block_scalar_boundary_cache_slot_send(max(1, &
           sum(block_scalar_boundary_cache_send_count))))
      allocate(block_scalar_boundary_cache_value_send(max(1, &
           sum(block_scalar_boundary_cache_recv_count))))
      allocate(block_scalar_boundary_cache_value_recv(max(1, &
           sum(block_scalar_boundary_cache_send_count))))
      block_scalar_boundary_cache_domain_send = -1
      block_scalar_boundary_cache_domain_recv = -1
      block_scalar_boundary_cache_node_send = -1
      block_scalar_boundary_cache_node_recv = -1
      block_scalar_boundary_cache_slot_send = -1
      block_scalar_boundary_cache_value_send = BLOCK_BOUNDARY_POISON
      block_scalar_boundary_cache_value_recv = BLOCK_BOUNDARY_POISON

      allocate(cursor(n_process))
      cursor = block_scalar_boundary_cache_send_displ+1
      do cache_slot = 1,n_cache
         r = block_scalar_boundary_cache_rank(cache_slot)+1
         if (r == rank+1) cycle
         pos = cursor(r)
         if (pos < 1 .or. pos > &
              sum(block_scalar_boundary_cache_send_count)) then
            call fail("scalar boundary cache request packing overruns")
         end if
         block_scalar_boundary_cache_domain_send(pos) = &
              block_scalar_boundary_cache_domain(cache_slot)
         block_scalar_boundary_cache_node_send(pos) = &
              block_scalar_boundary_cache_node(cache_slot)
         block_scalar_boundary_cache_slot_send(pos) = cache_slot-1
         cursor(r) = pos+1
      end do
      do r = 1,n_process
         if (cursor(r) /= block_scalar_boundary_cache_send_displ(r) + &
              block_scalar_boundary_cache_send_count(r)+1) then
            call fail("scalar boundary cache request extent differs")
         end if
      end do
      deallocate(cursor)

      call MPI_Alltoallv(block_scalar_boundary_cache_domain_send, &
           block_scalar_boundary_cache_send_count, &
           block_scalar_boundary_cache_send_displ,MPI_INTEGER, &
           block_scalar_boundary_cache_domain_recv, &
           block_scalar_boundary_cache_recv_count, &
           block_scalar_boundary_cache_recv_displ,MPI_INTEGER,comm,ierr)
      call check_mpi(ierr,"MPI_Alltoallv scalar boundary cache Domains")
      call MPI_Alltoallv(block_scalar_boundary_cache_node_send, &
           block_scalar_boundary_cache_send_count, &
           block_scalar_boundary_cache_send_displ,MPI_INTEGER, &
           block_scalar_boundary_cache_node_recv, &
           block_scalar_boundary_cache_recv_count, &
           block_scalar_boundary_cache_recv_displ,MPI_INTEGER,comm,ierr)
      call check_mpi(ierr,"MPI_Alltoallv scalar boundary cache nodes")

      do pos = 1,sum(block_scalar_boundary_cache_recv_count)
         source_domain = block_scalar_boundary_cache_domain_recv(pos)
         source_node = block_scalar_boundary_cache_node_recv(pos)
         if (source_domain < 0 .or. source_domain >= N_GLO_DOMAIN .or. &
              owner(source_domain+1) /= rank) then
            call fail("scalar boundary cache service Domain is invalid")
         end if
         d_source = loc_id(source_domain+1)+1
         if (d_source < 1 .or. d_source > size(grid) .or. &
              source_node < 0 .or. &
              source_node >= grid(d_source)%node%length) then
            call fail("scalar boundary cache service node is invalid")
         end if
      end do

      request_count(1) = int(n_cache - &
           sum(block_scalar_boundary_cache_send_count),int64)
      request_count(2) = int( &
           sum(block_scalar_boundary_cache_send_count),int64)
      request_count(3) = int( &
           sum(block_scalar_boundary_cache_recv_count),int64)
      if (request_count(1) < 0_int64) then
         call fail("scalar boundary cache local request count is invalid")
      end if

    end subroutine prepare_boundary_cache_request_plan

    subroutine assign_boundary_cache_slot (boundary_pos,n_cache)
      ! Stage 166I: deduplicate exact source-node keys on the final block
      ! owner.  The resulting slots are topology-only scaffolding for a later
      ! value exchange; production continues to consume captured boundaries.

      implicit none

      integer, intent(in) :: boundary_pos
      integer, intent(inout) :: n_cache

      integer :: cache_slot
      integer :: final_rank
      integer :: i
      integer :: owner_rank
      integer :: source_block
      integer :: source_block_patch
      integer :: source_domain
      integer :: source_level
      integer :: source_node
      integer :: source_patch_node

      if (boundary_pos < 1 .or. boundary_pos > total_node) then
         call fail("scalar boundary cache position is invalid")
      end if
      source_domain = block_scalar_restriction_exchange% &
           boundary_source_owner_domain(boundary_pos)
      source_node = block_scalar_restriction_exchange% &
           boundary_source_owner_node(boundary_pos)
      if (source_domain < 0 .or. source_domain >= N_GLO_DOMAIN .or. &
           source_node < 0) then
         call fail("scalar boundary cache source is invalid")
      end if
      owner_rank = block_scalar_boundary_owner_rank(boundary_pos)
      if (owner_rank < 0 .or. owner_rank >= n_process) then
         call fail("scalar boundary cache owner rank is invalid")
      end if
      source_block = block_scalar_boundary_owner_block(boundary_pos)
      source_block_patch = &
           block_scalar_boundary_owner_block_patch(boundary_pos)
      source_patch_node = &
           block_scalar_boundary_owner_patch_node(boundary_pos)
      source_level = block_scalar_boundary_owner_block_level(boundary_pos)
      if (source_patch_node < 0 .or. &
           source_patch_node >= PATCH_SIZE**2 .or. &
           source_level < 0 .or. source_level > level_end .or. &
           (source_block == -1 .and. &
           (source_block_patch /= -1 .or. &
           source_level >= level_start)) .or. &
           (source_block /= -1 .and. &
           (source_block < 1 .or. &
           source_block > size(block_catalog) .or. &
           source_block_patch < 0 .or. &
           source_level < level_start))) then
         call fail("scalar boundary final source key is invalid")
      end if
      final_rank = -1
      if (source_block >= 1) then
         final_rank = block_catalog(source_block)%owner
         if (final_rank < 0 .or. final_rank >= n_process) then
            call fail("scalar boundary final owner is invalid")
         end if
      end if

      cache_slot = 0
      do i = 1,n_cache
         if (block_scalar_boundary_cache_domain(i) == source_domain .and. &
              block_scalar_boundary_cache_node(i) == source_node) then
            cache_slot = i
            exit
         end if
      end do
      if (cache_slot == 0) then
         n_cache = n_cache+1
         if (n_cache > size(block_scalar_boundary_cache_domain)) then
            call fail("scalar boundary cache catalogue overruns")
         end if
         cache_slot = n_cache
         block_scalar_boundary_cache_domain(cache_slot) = source_domain
         block_scalar_boundary_cache_node(cache_slot) = source_node
         block_scalar_boundary_cache_rank(cache_slot) = owner_rank
         block_scalar_boundary_final_plan%cache_block(cache_slot) = &
              source_block
         block_scalar_boundary_final_plan%cache_patch(cache_slot) = &
              source_block_patch
         block_scalar_boundary_final_plan%cache_node(cache_slot) = &
              source_patch_node
         block_scalar_boundary_final_plan%cache_rank(cache_slot) = &
              final_rank
         block_scalar_boundary_final_plan%cache_level(cache_slot) = &
              source_level
      else if (block_scalar_boundary_cache_rank(cache_slot) /= owner_rank) &
           then
         call fail("scalar boundary cache owner differs")
      else if (block_scalar_boundary_final_plan%cache_block(cache_slot) /= &
           source_block .or. &
           block_scalar_boundary_final_plan%cache_patch(cache_slot) /= &
           source_block_patch .or. &
           block_scalar_boundary_final_plan%cache_node(cache_slot) /= &
           source_patch_node .or. &
           block_scalar_boundary_final_plan%cache_rank(cache_slot) /= &
           final_rank .or. &
           block_scalar_boundary_final_plan%cache_level(cache_slot) /= &
           source_level) then
         call fail("scalar boundary final source differs")
      end if
      block_scalar_boundary_cache_slot(boundary_pos) = cache_slot-1

    end subroutine assign_boundary_cache_slot

    subroutine source_patch_block_key ( &
         d_source,source_patch,source_block,source_block_patch)
      ! Resolve the canonical Domain patch against the global block catalogue.
      ! Source-block staging has already been consumed when this plan is built,
      ! so consulting block_source here leaves every otherwise exact key
      ! uncatalogued.  Reproduce the extraction preorder directly from the
      ! resident source Domain instead.

      implicit none

      integer, intent(in) :: d_source
      integer, intent(in) :: source_patch
      integer, intent(out) :: source_block
      integer, intent(out) :: source_block_patch

      integer :: patch_index
      integer :: source_global

      source_block = -1
      source_block_patch = -1
      if (d_source < 1 .or. d_source > size(grid) .or. &
           source_patch < 0 .or. &
           source_patch >= grid(d_source)%patch%length .or. &
           grid(d_source)%patch%elts(source_patch+1)%deleted) then
         call fail("scalar boundary source block address is invalid")
      end if
      source_global = glo_id(rank+1,d_source)
      patch_index = domain_patch_displ(d_source)+source_patch+1
      if (patch_index < 1 .or. &
           patch_index > max(1,total_domain_patch)) then
         call fail("scalar boundary source block lookup is invalid")
      end if
      source_block = domain_patch_block(patch_index)
      source_block_patch = domain_patch_block_patch(patch_index)
      if (source_block == -1 .and. source_block_patch == -1) return
      if (source_block < 1 .or. source_block > size(block_catalog) .or. &
           source_block_patch < 0) then
         call fail("scalar boundary source block key is invalid")
      end if
      if (block_catalog(source_block)%root_domain /= source_global .or. &
           block_catalog(source_block)%owner < 0 .or. &
           block_catalog(source_block)%owner >= n_process) then
         call fail("scalar boundary source block key is invalid")
      end if

    end subroutine source_patch_block_key


    recursive subroutine map_source_block_subtree ( &
         d_source,p,source_block,next_index)

      implicit none

      integer, intent(in) :: d_source
      integer, intent(in) :: p
      integer, intent(in) :: source_block
      integer, intent(inout) :: next_index

      integer :: c
      integer :: child
      integer :: patch_index

      if (d_source < 1 .or. d_source > size(grid) .or. &
           p < 0 .or. p >= grid(d_source)%patch%length) then
         call fail("scalar boundary source subtree patch is invalid")
      end if
      if (grid(d_source)%patch%elts(p+1)%deleted) return
      patch_index = domain_patch_displ(d_source)+p+1
      if (patch_index < 1 .or. &
           patch_index > max(1,total_domain_patch) .or. &
           domain_patch_block(patch_index) /= -1 .or. &
           domain_patch_block_patch(patch_index) /= -1) then
         call fail("scalar boundary source block map is ambiguous")
      end if
      domain_patch_block(patch_index) = source_block
      domain_patch_block_patch(patch_index) = next_index
      next_index = next_index+1
      do c = 1,N_CHDRN
         child = grid(d_source)%patch%elts(p+1)%children(c)
         if (child <= 0) cycle
         call map_source_block_subtree( &
              d_source,child,source_block,next_index)
      end do

    end subroutine map_source_block_subtree

    subroutine domain_node_patch_key ( &
         d_source,source_node,source_patch,source_patch_node)

      implicit none

      integer, intent(in) :: d_source
      integer, intent(in) :: source_node
      integer, intent(out) :: source_patch
      integer, intent(out) :: source_patch_node

      integer :: source_index

      source_patch = -1
      source_patch_node = -1
      if (d_source < 1 .or. d_source > size(grid) .or. &
           source_node < 0 .or. &
           source_node >= grid(d_source)%node%length) then
         call fail("scalar boundary source patch address is invalid")
      end if
      source_index = domain_node_displ(d_source)+source_node+1
      if (source_index < 1 .or. &
           source_index > max(1,total_domain_node)) then
         call fail("scalar boundary source patch index is invalid")
      end if
      source_patch = domain_node_patch(source_index)
      source_patch_node = domain_node_patch_node(source_index)
      if (source_patch < 0 .or. &
           source_patch_node < 0 .or. &
           source_patch_node >= PATCH_SIZE**2) then
         call fail("scalar boundary source patch key is incomplete")
      end if

    end subroutine domain_node_patch_key

    subroutine domain_boundary_owner_key ( &
         d_boundary,boundary_record,boundary_node,owner_class, &
         owner_domain,owner_node,owner_patch,owner_patch_node, &
         owner_block,owner_block_patch,owner_block_level,owner_rank)

      implicit none

      integer, intent(in) :: d_boundary
      integer, intent(in) :: boundary_record
      integer, intent(in) :: boundary_node
      integer, intent(out) :: owner_class
      integer, intent(out) :: owner_domain
      integer, intent(out) :: owner_node
      integer, intent(out) :: owner_patch
      integer, intent(out) :: owner_patch_node
      integer, intent(out) :: owner_block
      integer, intent(out) :: owner_block_patch
      integer, intent(out) :: owner_block_level
      integer, intent(out) :: owner_rank

      integer :: domain_route_index
      integer :: domain_target_id

      if (d_boundary < 1 .or. d_boundary > size(grid) .or. &
           boundary_record < 0 .or. &
           boundary_record >= grid(d_boundary)%bdry_patch%length .or. &
           boundary_node < 0) then
         call fail("scalar boundary owner provenance is invalid")
      end if
      domain_target_id = grid(d_boundary)% &
           bdry_patch%elts(boundary_record+1)%elts_start + boundary_node
      if (domain_target_id < 0 .or. &
           domain_target_id >= grid(d_boundary)%node%length) then
         call fail("scalar boundary owner address is invalid")
      end if
      domain_route_index = domain_node_displ(d_boundary) + &
           domain_target_id+1
      select case (route_count(domain_route_index))
      case (0)
         owner_class = BLOCK_BOUNDARY_OWNER_SCAFFOLD
         owner_domain = -1
         owner_node = -1
         owner_patch = -1
         owner_patch_node = -1
         owner_block = -1
         owner_block_patch = -1
         owner_block_level = -1
         owner_rank = -1
      case (1)
         if (route_owner_rank(domain_route_index) == rank) then
            owner_class = BLOCK_BOUNDARY_OWNER_LOCAL
         else
            owner_class = BLOCK_BOUNDARY_OWNER_REMOTE
         end if
         owner_domain = route_source_domain(domain_route_index)
         owner_node = route_source_node(domain_route_index)
         owner_patch = route_source_patch(domain_route_index)
         owner_patch_node = route_source_patch_node(domain_route_index)
         owner_block = route_source_block(domain_route_index)
         owner_block_patch = route_source_block_patch(domain_route_index)
         owner_block_level = route_source_block_level(domain_route_index)
         owner_rank = route_owner_rank(domain_route_index)
         if (owner_domain < 0 .or. owner_node < 0 .or. &
              owner_patch < 0 .or. owner_patch_node < 0 .or. &
              owner_patch_node >= PATCH_SIZE**2 .or. owner_rank < 0 .or. &
              owner_rank >= n_process .or. &
              owner_block_level < 0 .or. &
              owner_block_level > level_end .or. &
              (owner_block == -1 .and. &
              (owner_block_patch /= -1 .or. &
              owner_block_level >= level_start)) .or. &
              (owner_block /= -1 .and. &
              (owner_block < 1 .or. &
              owner_block > size(block_catalog) .or. &
              owner_block_patch < 0 .or. &
              owner_block_level < level_start))) then
            call fail("scalar boundary owner source key is invalid")
         end if
      case default
         owner_class = BLOCK_BOUNDARY_OWNER_AMBIGUOUS
         owner_domain = -2
         owner_node = -2
         owner_patch = -2
         owner_patch_node = -2
         owner_block = -2
         owner_block_patch = -2
         owner_block_level = -2
         owner_rank = -2
      end select

    end subroutine domain_boundary_owner_key

  end subroutine prepare_block_scalar_boundary_provenance


  subroutine capture_block_scalar_divergence_level ( &
       domain_sol,physics_flux,scalar_id,field_level,grid_level, &
       direct_flux,domain_tendency,dscalar_only)
    ! Before hierarchy restriction, capture the three directly evaluated
    ! positive-edge fluxes and their immutable production inputs. After
    ! restriction and boundary refresh, capture the authoritative six-edge
    ! stencil used by scalar divergence.

    implicit none

    type(Float_Field), intent(inout) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    procedure(Block_Scalar_Physics_Flux) :: physics_flux
    integer, intent(in) :: scalar_id
    integer, intent(in) :: field_level
    integer, intent(in) :: grid_level
    logical, optional, intent(in) :: direct_flux
    type(Float_Field), optional, intent(in) :: &
         domain_tendency(1:N_VARIABLE,1:zlevels)
    logical, optional, intent(in) :: dscalar_only

    integer :: b
    integer :: d
    integer :: first_field_level
    integer :: level_slot
    integer :: local_index
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: patch_index
    integer :: r
    integer :: sample_start
    integer :: scalar_slot
    integer :: scalar_slot_first
    integer :: scalar_slot_last
    integer :: slot
    integer :: v_scalar
    integer :: v_vector

    logical :: capture_direct
    logical :: capture_dscalar
    logical :: capture_interior
    logical :: validate_oracle

    if (.not. block_scalar_divergence_plan%active) return
    call block_profile_enter(BLOCK_PROFILE_RESTRICTION)
    call block_profile_enter(BLOCK_PROFILE_RESTRICTION_CAPTURE)
    capture_direct = .false.
    if (present(direct_flux)) capture_direct = direct_flux
    capture_dscalar = .false.
    if (present(dscalar_only)) capture_dscalar = dscalar_only
    validate_oracle = block_dynamics_validation_enabled()
    if (capture_direct .and. capture_dscalar) then
       call fail("scalar-divergence capture mode is invalid")
    end if
    if (capture_dscalar .and. .not. present(domain_tendency)) then
       call fail("scalar-divergence tendency input is absent")
    end if

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    scalar_slot = scalar_id-v_scalar+1
    scalar_slot_first = scalar_slot
    scalar_slot_last = scalar_slot
    if (scalar_id == 0) then
       scalar_slot_first = 1
       scalar_slot_last = n_scalar_variable
    end if
    level_slot = field_level-first_field_level+1
    if (scalar_slot_first < 1 .or. &
         scalar_slot_last > n_scalar_variable .or. &
         level_slot < 1 .or. level_slot > n_field_level .or. &
         mult_scalar /= 1 .or. mult_vector /= EDGE) then
       call fail("scalar-divergence capture field layout is invalid")
    end if

    ! After the first immutable record has been cached, production omits only
    ! the Domain reference dscalar traversal.  The block replay produces that
    ! value before activation.  Current-stage restricted flux must still be
    ! captured: the complete physical recomposition consumes it before the
    ! native restriction replay, including while forming the velocity path.
    ! The exact oracle continues to rebuild the reference dscalar as well.
    capture_interior = validate_oracle .or. .not. capture_dscalar
    if (capture_interior) then
       do local_index = 1,n_local_blocks()
          b = local_block_catalog(local_index)
          if (source_rank(b) /= rank) cycle
          d = loc_id(block_catalog(b)%root_domain+1) + 1
          if (d < 1 .or. d > size(grid)) then
             call fail("retained scalar-divergence Domain is invalid")
          end if
          patch_index = 0
          call capture_subtree( &
               d,block_catalog(b)%root_patch,b,patch_index,1,local_index)
          if (patch_index /= local_block_patch_count(b)) then
             call fail("retained scalar-divergence traversal is incomplete")
          end if
       end do

       do r = 1,n_process
          sample_start = block_writeback_plan%scalar_recv_displ(r) + 1
          do slot = block_writeback_plan%recv_displ(r)+1, &
               block_writeback_plan%recv_displ(r) + &
               block_writeback_plan%recv_count(r)
             b = block_writeback_plan%recv_block(slot)
             if (source_rank(b) /= rank) then
                call fail("remote scalar-divergence source is invalid")
             end if
             d = loc_id(block_catalog(b)%root_domain+1) + 1
             if (d < 1 .or. d > size(grid)) then
                call fail("remote scalar-divergence Domain is invalid")
             end if
             patch_index = 0
             call capture_subtree( &
                  d,block_catalog(b)%root_patch,b,patch_index, &
                  sample_start,0)
             if (patch_index /= &
                  block_writeback_plan%recv_patch_count(slot)) then
                call fail("remote scalar-divergence traversal is incomplete")
             end if
             sample_start = sample_start + &
                  block_writeback_plan%recv_scalar_nvalue(slot)
          end do
          if (sample_start /= &
               block_writeback_plan%scalar_recv_displ(r) + &
               block_writeback_plan%scalar_recv_count(r) + 1) then
             call fail("scalar-divergence capture extent mismatch")
          end if
       end do
    end if

    call capture_block_scalar_restriction_boundaries( &
         scalar_id,field_level,grid_level,capture_direct, &
         domain_tendency,capture_dscalar)
    call block_profile_leave(BLOCK_PROFILE_RESTRICTION_CAPTURE)
    call block_profile_leave(BLOCK_PROFILE_RESTRICTION)

  contains

    recursive subroutine capture_subtree ( &
         d,p,b,patch_index,block_sample_start,storage_index)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(inout) :: patch_index
      integer, intent(in) :: block_sample_start
      integer, intent(in) :: storage_index

      integer :: c
      integer :: child

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("scalar-divergence capture patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return

      if (grid(d)%patch%elts(p+1)%level == grid_level) then
         call capture_patch( &
              d,p,b,patch_index,block_sample_start,storage_index)
      end if
      patch_index = patch_index + 1

      do c = 1,N_CHDRN
         child = grid(d)%patch%elts(p+1)%children(c)
         if (child <= 0) cycle
         call capture_subtree( &
              d,child,b,patch_index,block_sample_start,storage_index)
      end do

    end subroutine capture_subtree


    subroutine capture_patch ( &
         d,p,b,patch_index,block_sample_start,storage_index)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(in) :: patch_index
      integer, intent(in) :: block_sample_start
      integer, intent(in) :: storage_index

      integer :: data_start
      integer :: dims(2,N_BDRY+1)
      integer :: i
      integer :: id
      integer :: id_e
      integer :: id_n
      integer :: id_ne
      integer :: id_s
      integer :: id_sw
      integer :: id_w
      integer :: j
      integer :: offs(N_BDRY+1)
      integer :: q
      integer :: sample
      integer :: scalar_capture_id
      integer :: scalar_capture_slot
      integer :: source_start

      real(dp) :: physics_positive(EDGE)
      real(dp) :: value(BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT)

      call get_offs_Domain(grid(d),p,offs,dims)
      source_start = grid(d)%patch%elts(p+1)%elts_start
      do scalar_capture_slot = scalar_slot_first,scalar_slot_last
         scalar_capture_id = v_scalar + scalar_capture_slot - 1
         do q = 0,PATCH_SIZE**2-1
         i = mod(q,PATCH_SIZE)
         j = q/PATCH_SIZE
         id = idx(i,j,offs,dims)
         if (id /= source_start+q) then
            call fail("scalar-divergence centre index differs")
         end if
         value = 0.0_dp
         if (capture_dscalar) then
            value(BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX) = &
                 domain_tendency(scalar_capture_id,field_level)% &
                 data(d)%elts(id+1)
         else if (capture_direct) then
            id_e = idx(i+1,j,offs,dims)
            id_ne = idx(i+1,j+1,offs,dims)
            id_n = idx(i,j+1,offs,dims)
            physics_positive = physics_flux( &
                 domain_sol,grid(d),id,id_e,id_ne,id_n, &
                 scalar_capture_id,field_level)
            value(BLOCK_SCALAR_DIRECT_FLUX_START: &
                 BLOCK_SCALAR_DIRECT_FLUX_START+EDGE-1) = &
                 horiz_flux(scalar_capture_id)%data(d)%elts( &
                 EDGE*id+RT+1:EDGE*id+UP+1)
            value(BLOCK_SCALAR_PEDLEN_START: &
                 BLOCK_SCALAR_PEDLEN_START+EDGE-1) = &
                 grid(d)%pedlen%elts(EDGE*id+RT+1:EDGE*id+UP+1)
            value(BLOCK_SCALAR_PHYSICS_START: &
                 BLOCK_SCALAR_PHYSICS_START+EDGE-1) = physics_positive
         else
            id_w = idx(i-1,j,offs,dims)
            id_sw = idx(i-1,j-1,offs,dims)
            id_s = idx(i,j-1,offs,dims)
            value(1:BLOCK_SCALAR_FLUX_COUNT) = [ &
                 horiz_flux(scalar_capture_id)%data(d)%elts( &
                 EDGE*id+RT+1), &
                 horiz_flux(scalar_capture_id)%data(d)%elts( &
                 EDGE*id_w+RT+1), &
                 horiz_flux(scalar_capture_id)%data(d)%elts( &
                 EDGE*id_sw+DG+1), &
                 horiz_flux(scalar_capture_id)%data(d)%elts( &
                 EDGE*id+DG+1), &
                 horiz_flux(scalar_capture_id)%data(d)%elts( &
                 EDGE*id+UP+1), &
                 horiz_flux(scalar_capture_id)%data(d)%elts( &
                 EDGE*id_s+UP+1)]
            value(BLOCK_SCALAR_AREA_INDEX) = &
                 grid(d)%areas%elts(id+1)%hex_inv
            value(BLOCK_SCALAR_ACTIVE_INDEX) = merge( &
                 1.0_dp,0.0_dp,grid(d)%mask_n%elts(id+1) >= TRSK)
            value(BLOCK_SCALAR_WAVELET_MASK_INDEX) = &
                 real(grid(d)%mask_n%elts(id+1),dp)
            value(BLOCK_VECTOR_WAVELET_WEIGHT_START: &
                 BLOCK_VECTOR_WAVELET_WEIGHT_START+8) = &
                 real(grid(d)%I_u_wgt%elts(id+1)%enc,dp)
            value(BLOCK_SCALAR_EDGE_LENGTH_START: &
                 BLOCK_SCALAR_EDGE_LENGTH_START+EDGE-1) = &
                 grid(d)%len%elts(EDGE*id+RT+1:EDGE*id+UP+1)
            value(BLOCK_SCALAR_TRIANGLE_AREA_START: &
                 BLOCK_SCALAR_TRIANGLE_AREA_START+1) = &
                 grid(d)%triarea%elts( &
                 TRIAG*id+LORT+1:TRIAG*id+UPLT+1)
            value(BLOCK_SCALAR_RESTRICTED_FLUX_START: &
                 BLOCK_SCALAR_RESTRICTED_FLUX_START+EDGE-1) = &
                 horiz_flux(scalar_capture_id)%data(d)%elts( &
                 EDGE*id+RT+1:EDGE*id+UP+1)
            value(BLOCK_SCALAR_EDGE_MASK_START: &
                 BLOCK_SCALAR_EDGE_MASK_START+EDGE-1) = real( &
                 grid(d)%mask_e%elts(EDGE*id+RT+1:EDGE*id+UP+1),dp)
            value(BLOCK_SCALAR_RESTRICTION_WEIGHT_START: &
                 BLOCK_SCALAR_RESTRICTION_WEIGHT_START+EDGE-1) = &
                 grid(d)%R_F_wgt%elts(id+1)%enc
            value(BLOCK_SCALAR_OVERLAP_START: &
                 BLOCK_SCALAR_OVERLAP_START+3) = &
                 grid(d)%overl_areas%elts(id+1)%a
            value(BLOCK_SCALAR_OVERLAP_START+4: &
                 BLOCK_SCALAR_OVERLAP_START+5) = &
                 grid(d)%overl_areas%elts(id+1)%split
         end if
         value(BLOCK_SCALAR_SOURCE_INDEX) = real(id,dp)
         sample = block_sample_start + &
              patch_index*block_writeback_plan%scalar_patch_nvalue + &
              ((scalar_capture_slot-1)*n_field_level + level_slot-1)* &
              PATCH_SIZE**2 + q
         if (storage_index > 0) then
            if (storage_index > size(block_scalar_tendency) .or. &
                 sample < 1 .or. sample > &
                 size(block_scalar_tendency(storage_index)%covered)) then
               call fail("retained scalar-divergence index is invalid")
            end if
            data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                 (sample-1) + 1
            if (capture_dscalar) then
               block_scalar_tendency(storage_index)%patch( &
                    data_start+BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX-1) = &
                    value(BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX)
            else if (capture_direct) then
               block_scalar_tendency(storage_index)%patch( &
                    data_start+BLOCK_SCALAR_DIRECT_FLUX_START-1: &
                    data_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                    value(BLOCK_SCALAR_DIRECT_FLUX_START: &
                    BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT)
            else
               block_scalar_tendency(storage_index)%patch( &
                    data_start:data_start+BLOCK_SCALAR_ACTIVE_INDEX-1) = &
                    value(1:BLOCK_SCALAR_ACTIVE_INDEX)
               block_scalar_tendency(storage_index)%patch( &
                    data_start+BLOCK_SCALAR_RESTRICTED_FLUX_START-1: &
                    data_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                    value(BLOCK_SCALAR_RESTRICTED_FLUX_START: &
                    BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT)
               block_scalar_tendency(storage_index)%covered(sample) = .true.
            end if
         else
            if (sample < 1 .or. &
                 sample > size(block_scalar_divergence_plan%recv_covered)) &
                 then
               call fail("remote scalar-divergence index is invalid")
            end if
            data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                 (sample-1) + 1
            if (capture_dscalar) then
               block_scalar_divergence_plan%recv_buffer( &
                    data_start+BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX-1) = &
                    value(BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX)
            else if (capture_direct) then
               block_scalar_divergence_plan%recv_buffer( &
                    data_start+BLOCK_SCALAR_DIRECT_FLUX_START-1: &
                    data_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                    value(BLOCK_SCALAR_DIRECT_FLUX_START: &
                    BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT)
            else
               block_scalar_divergence_plan%recv_buffer( &
                    data_start:data_start+BLOCK_SCALAR_ACTIVE_INDEX-1) = &
                    value(1:BLOCK_SCALAR_ACTIVE_INDEX)
               block_scalar_divergence_plan%recv_buffer( &
                    data_start+BLOCK_SCALAR_RESTRICTED_FLUX_START-1: &
                    data_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                    value(BLOCK_SCALAR_RESTRICTED_FLUX_START: &
                    BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT)
               block_scalar_divergence_plan%recv_covered(sample) = .true.
            end if
         end if

         end do
      end do

    end subroutine capture_patch

  end subroutine capture_block_scalar_divergence_level


  subroutine capture_block_scalar_restriction_boundaries ( &
       scalar_id,field_level,grid_level,capture_direct, &
       domain_tendency,capture_dscalar)
    ! Capture positive scalar flux and immutable restriction geometry for
    ! compact Domain-boundary records. Production dscalar is supplied by the
    ! final-owner route or reconstructed from these fluxes; the Domain value
    ! is retained only by the validation oracle.

    implicit none

    integer, intent(in) :: scalar_id
    integer, intent(in) :: field_level
    integer, intent(in) :: grid_level
    logical, intent(in) :: capture_direct
    type(Float_Field), optional, intent(in) :: &
         domain_tendency(1:N_VARIABLE,1:zlevels)
    logical, intent(in) :: capture_dscalar

    integer :: b
    integer :: boundary_index
    integer :: d
    integer :: first_field_level
    integer :: field_sample
    integer :: level_slot
    integer :: local_index
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_boundary_node
    integer :: n_field_level
    integer :: n_node
    integer :: n_scalar
    integer :: n_scalar_variable
    integer :: node_start
    integer :: pos_sample
    integer :: r
    integer :: scalar_slot
    integer :: scalar_slot_first
    integer :: scalar_slot_last
    integer :: slot
    integer :: source
    integer :: source_bdry
    integer :: source_level
    integer :: v_scalar
    integer :: v_vector
    logical :: validate_oracle

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    scalar_slot = scalar_id-v_scalar+1
    scalar_slot_first = scalar_slot
    scalar_slot_last = scalar_slot
    if (scalar_id == 0) then
       scalar_slot_first = 1
       scalar_slot_last = n_scalar_variable
    end if
    level_slot = field_level-first_field_level+1
    if (scalar_slot_first < 1 .or. &
         scalar_slot_last > n_scalar_variable .or. &
         level_slot < 1 .or. level_slot > n_field_level .or. &
         mult_scalar /= 1 .or. mult_vector /= EDGE) then
       call fail("scalar-restriction boundary layout is invalid")
    end if
    validate_oracle = block_dynamics_validation_enabled()
    if (capture_dscalar .and. .not. validate_oracle) return

    do r = 1,n_process
       pos_sample = block_writeback_plan% &
            boundary_scalar_domain_send_displ(r) + 1
       do slot = block_writeback_plan%recv_displ(r)+1, &
            block_writeback_plan%recv_displ(r) + &
            block_writeback_plan%recv_count(r)
          b = block_writeback_plan%recv_block(slot)
          d = loc_id(block_catalog(b)%root_domain+1) + 1
          source = source_rank(b)
          if (source /= rank .or. d < 1 .or. &
               d > size(grid)) then
             call fail("scalar-restriction boundary route is invalid")
          end if
          do boundary_index = 1, &
               block_writeback_plan%recv_boundary_count(slot)
             source_bdry = block_writeback_plan%recv_boundary_source( &
                  block_writeback_plan%recv_boundary_displ(slot) + &
                  boundary_index)
             source_level = block_writeback_plan%recv_boundary_level( &
                  block_writeback_plan%recv_boundary_displ(slot) + &
                  boundary_index)
             n_node = block_writeback_plan%recv_boundary_nnode( &
                  block_writeback_plan%recv_boundary_displ(slot) + &
                  boundary_index)
             n_scalar = n_node*n_scalar_variable*n_field_level
             do scalar_slot = scalar_slot_first,scalar_slot_last
                call fill_domain_boundary_record( &
                     d,source_bdry,source_level,n_node,scalar_slot, &
                     level_slot,grid_level,capture_direct, &
                     block_scalar_restriction_exchange% &
                     boundary_send_buffer, &
                     BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                     (pos_sample-1)+1)
             end do
             pos_sample = pos_sample + n_scalar
          end do
       end do
       if (pos_sample /= block_writeback_plan% &
            boundary_scalar_domain_send_displ(r) + &
            block_writeback_plan% &
            boundary_scalar_domain_send_count(r) + 1) then
          call fail("scalar-restriction boundary packed extent differs")
       end if
    end do

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       if (source_rank(b) /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1) + 1
       if (d < 1 .or. d > size(grid)) then
          call fail("retained scalar-restriction Domain is invalid")
       end if
       n_boundary_node = size( &
            block_scalar_tendency(local_index)%bdry)/ &
            (BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
            n_scalar_variable*n_field_level)
       node_start = 0
       do boundary_index = 1,local_block_boundary_count(b)
          call get_local_block_boundary_source( &
               b,boundary_index,source_bdry,slot,n_node,source_level)
          do scalar_slot = scalar_slot_first,scalar_slot_last
             call fill_retained_boundary_record( &
                  d,source_bdry,source_level,n_node,scalar_slot, &
                  level_slot,grid_level,capture_direct,local_index, &
                  n_boundary_node,node_start)
          end do
          node_start = node_start + n_node
       end do
       if (node_start /= n_boundary_node) then
          call fail("retained scalar-restriction boundary extent differs")
       end if
    end do

    if (capture_dscalar .and. validate_oracle) then
       if (.not. present(domain_tendency)) then
          call fail("scalar boundary cache tendency is absent")
       end if
       do scalar_slot = scalar_slot_first,scalar_slot_last
          field_sample = (scalar_slot-1)*n_field_level+level_slot
          call exchange_block_scalar_boundary_cache( &
               domain_tendency,v_scalar+scalar_slot-1,field_level, &
               field_sample)
       end do
    end if

  contains

    subroutine fill_domain_boundary_record ( &
         d,source_bdry,boundary_level,n_node,scalar_slot,level_slot,grid_level, &
         capture_direct,buffer,data_start)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: source_bdry
      integer, intent(in) :: boundary_level
      integer, intent(in) :: n_node
      integer, intent(in) :: scalar_slot
      integer, intent(in) :: level_slot
      integer, intent(in) :: grid_level
      logical, intent(in) :: capture_direct
      real(dp), intent(inout) :: buffer(:)
      integer, intent(in) :: data_start

      integer :: id
      integer :: node
      integer :: record_start
      integer :: sample

      if (boundary_level /= grid_level) return
      id = grid(d)%bdry_patch%elts(source_bdry+1)%elts_start
      do node = 0,n_node-1
         sample = ((scalar_slot-1)*n_field_level + level_slot-1)* &
              n_node + node
         record_start = data_start + &
              BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample
         call fill_boundary_node( &
              d,id+node,v_scalar+scalar_slot-1,capture_direct, &
              buffer(record_start: &
              record_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1))
      end do

    end subroutine fill_domain_boundary_record


    subroutine fill_retained_boundary_record ( &
         d,source_bdry,boundary_level,n_node,scalar_slot,level_slot,grid_level, &
         capture_direct,local_index,n_boundary_node,node_start)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: source_bdry
      integer, intent(in) :: boundary_level
      integer, intent(in) :: n_node
      integer, intent(in) :: scalar_slot
      integer, intent(in) :: level_slot
      integer, intent(in) :: grid_level
      logical, intent(in) :: capture_direct
      integer, intent(in) :: local_index
      integer, intent(in) :: n_boundary_node
      integer, intent(in) :: node_start

      integer :: data_start
      integer :: id
      integer :: node
      integer :: sample

      if (boundary_level /= grid_level) return
      id = grid(d)%bdry_patch%elts(source_bdry+1)%elts_start
      do node = 0,n_node-1
         sample = ((scalar_slot-1)*n_field_level + level_slot-1)* &
              n_boundary_node + node_start + node
         data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
         call fill_boundary_node( &
              d,id+node,v_scalar+scalar_slot-1,capture_direct, &
              block_scalar_tendency(local_index)%bdry(data_start: &
              data_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1))
      end do

    end subroutine fill_retained_boundary_record


    subroutine fill_boundary_node ( &
         d,id,scalar_capture_id,capture_direct,value)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: id
      integer, intent(in) :: scalar_capture_id
      logical, intent(in) :: capture_direct
      real(dp), intent(inout) :: &
           value(BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT)

      if (capture_dscalar) then
         value(BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX) = &
              domain_tendency(scalar_capture_id,field_level)% &
              data(d)%elts(id+1)
      else if (capture_direct) then
         value(BLOCK_SCALAR_DIRECT_FLUX_START: &
              BLOCK_SCALAR_DIRECT_FLUX_START+EDGE-1) = &
              horiz_flux(scalar_capture_id)%data(d)%elts( &
              EDGE*id+RT+1:EDGE*id+UP+1)
      else
         value(BLOCK_SCALAR_AREA_INDEX) = &
              grid(d)%areas%elts(id+1)%hex_inv
         value(BLOCK_SCALAR_ACTIVE_INDEX) = merge( &
              1.0_dp,0.0_dp,grid(d)%mask_n%elts(id+1) >= TRSK)
         value(BLOCK_SCALAR_WAVELET_MASK_INDEX) = &
              real(grid(d)%mask_n%elts(id+1),dp)
         value(BLOCK_VECTOR_WAVELET_WEIGHT_START: &
              BLOCK_VECTOR_WAVELET_WEIGHT_START+8) = &
              real(grid(d)%I_u_wgt%elts(id+1)%enc,dp)
         value(BLOCK_SCALAR_EDGE_LENGTH_START: &
              BLOCK_SCALAR_EDGE_LENGTH_START+EDGE-1) = &
              grid(d)%len%elts(EDGE*id+RT+1:EDGE*id+UP+1)
         value(BLOCK_SCALAR_TRIANGLE_AREA_START: &
              BLOCK_SCALAR_TRIANGLE_AREA_START+1) = &
              grid(d)%triarea%elts( &
              TRIAG*id+LORT+1:TRIAG*id+UPLT+1)
         value(BLOCK_SCALAR_RESTRICTED_FLUX_START: &
              BLOCK_SCALAR_RESTRICTED_FLUX_START+EDGE-1) = &
              horiz_flux(scalar_capture_id)%data(d)%elts( &
              EDGE*id+RT+1:EDGE*id+UP+1)
         value(BLOCK_SCALAR_EDGE_MASK_START: &
              BLOCK_SCALAR_EDGE_MASK_START+EDGE-1) = real( &
              grid(d)%mask_e%elts(EDGE*id+RT+1:EDGE*id+UP+1),dp)
         value(BLOCK_SCALAR_RESTRICTION_WEIGHT_START: &
              BLOCK_SCALAR_RESTRICTION_WEIGHT_START+EDGE-1) = &
              grid(d)%R_F_wgt%elts(id+1)%enc
         value(BLOCK_SCALAR_OVERLAP_START: &
              BLOCK_SCALAR_OVERLAP_START+3) = &
              grid(d)%overl_areas%elts(id+1)%a
         value(BLOCK_SCALAR_OVERLAP_START+4: &
              BLOCK_SCALAR_OVERLAP_START+5) = &
              grid(d)%overl_areas%elts(id+1)%split
      end if
      value(BLOCK_SCALAR_SOURCE_INDEX) = real(id,dp)

    end subroutine fill_boundary_node


  end subroutine capture_block_scalar_restriction_boundaries


  subroutine exchange_block_scalar_boundary_cache ( &
       domain_tendency,scalar_id,field_level,field_sample)
    ! Oracle-only Domain shadow transport. Populate one value per unique
    ! exact source-node slot for independent final-owner validation.

    implicit none

    type(Float_Field), intent(in) :: &
         domain_tendency(1:N_VARIABLE,1:zlevels)
    integer, intent(in) :: scalar_id
    integer, intent(in) :: field_level
    integer, intent(in) :: field_sample

    integer :: cache_index
    integer :: cache_slot
    integer :: d_source
    integer :: ierr
    integer :: pos
    integer :: source_domain
    integer :: source_node
    integer :: value_start

    if (scalar_id < 1 .or. scalar_id > N_VARIABLE .or. &
         field_level < 1 .or. field_level > zlevels .or. &
         field_sample < 1 .or. &
         field_sample > block_scalar_boundary_cache_field_count .or. &
         block_scalar_boundary_cache_count < 0) then
       call fail("scalar boundary cache field is invalid")
    end if
    value_start = (field_sample-1)*block_scalar_boundary_cache_count
    if (block_scalar_boundary_cache_count > 0) then
       block_scalar_boundary_cache_covered( &
            value_start+1:value_start+ &
            block_scalar_boundary_cache_count) = .false.
    end if
    block_scalar_boundary_cache_value_send = BLOCK_BOUNDARY_POISON
    block_scalar_boundary_cache_value_recv = BLOCK_BOUNDARY_POISON

    do cache_slot = 1,block_scalar_boundary_cache_count
       if (block_scalar_boundary_cache_rank(cache_slot) /= rank) cycle
       source_domain = block_scalar_boundary_cache_domain(cache_slot)
       source_node = block_scalar_boundary_cache_node(cache_slot)
       if (source_domain < 0 .or. source_domain >= N_GLO_DOMAIN .or. &
            owner(source_domain+1) /= rank) then
          call fail("local scalar boundary cache Domain is invalid")
       end if
       d_source = loc_id(source_domain+1)+1
       if (d_source < 1 .or. d_source > size(grid) .or. &
            source_node < 0 .or. &
            source_node >= grid(d_source)%node%length) then
          call fail("local scalar boundary cache node is invalid")
       end if
       cache_index = value_start+cache_slot
       block_scalar_boundary_cache_value(cache_index) = &
            domain_tendency(scalar_id,field_level)% &
            data(d_source)%elts(source_node+1)
       block_scalar_boundary_cache_covered(cache_index) = .true.
    end do

    do pos = 1,sum(block_scalar_boundary_cache_recv_count)
       source_domain = block_scalar_boundary_cache_domain_recv(pos)
       source_node = block_scalar_boundary_cache_node_recv(pos)
       if (source_domain < 0 .or. source_domain >= N_GLO_DOMAIN .or. &
            owner(source_domain+1) /= rank) then
          call fail("remote scalar boundary cache Domain is invalid")
       end if
       d_source = loc_id(source_domain+1)+1
       if (d_source < 1 .or. d_source > size(grid) .or. &
            source_node < 0 .or. &
            source_node >= grid(d_source)%node%length) then
          call fail("remote scalar boundary cache node is invalid")
       end if
       block_scalar_boundary_cache_value_send(pos) = &
            domain_tendency(scalar_id,field_level)% &
            data(d_source)%elts(source_node+1)
    end do

    call MPI_Alltoallv(block_scalar_boundary_cache_value_send, &
         block_scalar_boundary_cache_recv_count, &
         block_scalar_boundary_cache_recv_displ,MPI_DOUBLE_PRECISION, &
         block_scalar_boundary_cache_value_recv, &
         block_scalar_boundary_cache_send_count, &
         block_scalar_boundary_cache_send_displ,MPI_DOUBLE_PRECISION, &
         comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar boundary cache values")

    do pos = 1,sum(block_scalar_boundary_cache_send_count)
       cache_slot = block_scalar_boundary_cache_slot_send(pos)+1
       if (cache_slot < 1 .or. &
            cache_slot > block_scalar_boundary_cache_count .or. &
            block_scalar_boundary_cache_rank(cache_slot) == rank) then
          call fail("scalar boundary cache value slot is invalid")
       end if
       cache_index = value_start+cache_slot
       if (block_scalar_boundary_cache_covered(cache_index)) then
          call fail("scalar boundary cache value is duplicated")
       end if
       block_scalar_boundary_cache_value(cache_index) = &
            block_scalar_boundary_cache_value_recv(pos)
       block_scalar_boundary_cache_covered(cache_index) = .true.
    end do
    if (block_scalar_boundary_cache_count > 0) then
       if (.not. all(block_scalar_boundary_cache_covered( &
            value_start+1:value_start+ &
            block_scalar_boundary_cache_count))) then
          call fail("scalar boundary cache value coverage is incomplete")
       end if
    end if

  end subroutine exchange_block_scalar_boundary_cache


  subroutine finalize_block_scalar_divergence_capture
    ! Transfer the pre-restriction native-flux shadow and the authoritative
    ! restricted divergence stencil once, then make every final-owner input
    ! ready for the rejected block-native kernel.

    implicit none

    integer :: b
    integer :: data_count
    integer :: data_start
    integer :: ierr
    integer :: local_index
    integer :: profile_initial_mode
    integer :: r
    integer :: sample
    integer :: sample_count
    integer :: slot
    integer :: source_start

    integer(int64) :: allocation_before

    logical :: deduplicated_transport

    call block_profile_enter(BLOCK_PROFILE_RESTRICTION)
    call block_profile_enter(BLOCK_PROFILE_RESTRICTION_INITIAL)
    if (.not. block_scalar_divergence_plan%active) then
       call fail("scalar-divergence finalize without active capture")
    end if
    if (.not. block_scalar_divergence_plan%full_transport .and. &
         .not. block_scalar_divergence_plan%production_cache_ready) then
       call fail("compact scalar-divergence transport without full cache")
    end if
    profile_initial_mode = BLOCK_PROFILE_RESTRICTION_INITIAL_COMPACT
    if (block_scalar_divergence_plan%full_transport) &
         profile_initial_mode = BLOCK_PROFILE_RESTRICTION_INITIAL_FULL
    call block_profile_enter(profile_initial_mode)
    call complete_uncaptured_scalar_divergence_coverage
    if (.not. all(block_scalar_divergence_plan%recv_covered)) then
       call fail("scalar-divergence Domain capture is incomplete")
    end if

    allocation_before = block_scalar_divergence_plan%allocations
    ! Full rebuilds use a field-deduplicated stream.  The persistent block
    ! manifest records the sender's actual order, so variable-size records are
    ! installed by identity instead of assuming reverse-route positional
    ! symmetry.  Compact RK-stage refreshes retain their existing layout.
    deduplicated_transport = &
         block_scalar_divergence_plan%full_transport
    if (deduplicated_transport) then
       call pack_deduplicated_full_transport
       call MPI_Alltoallv( &
            block_scalar_divergence_plan%deduplicated_buffer, &
            block_scalar_divergence_plan%deduplicated_recv_count, &
            block_scalar_divergence_plan%deduplicated_recv_displ, &
            MPI_DOUBLE_PRECISION, &
            block_scalar_divergence_plan%send_buffer, &
            block_scalar_divergence_plan%deduplicated_send_count, &
            block_scalar_divergence_plan%deduplicated_send_displ, &
            MPI_DOUBLE_PRECISION,comm,ierr)
    else if (block_scalar_divergence_plan%full_transport) then
       call MPI_Alltoallv( &
            block_scalar_divergence_plan%recv_buffer, &
            block_scalar_divergence_plan%recv_count, &
            block_scalar_divergence_plan%recv_displ, &
            MPI_DOUBLE_PRECISION, &
            block_scalar_divergence_plan%send_buffer, &
            block_scalar_divergence_plan%send_count, &
            block_scalar_divergence_plan%send_displ, &
            MPI_DOUBLE_PRECISION,comm,ierr)
    else
       ! Compact the retained full-layout capture in place.  Global sample
       ! order is identical in both layouts and every compact destination
       ! precedes its unread full-layout source.
       do sample = 0,size(block_scalar_divergence_plan%recv_covered)-1
          data_start = BLOCK_SCALAR_PRODUCTION_INPUT_COUNT*sample + 1
          source_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
          block_scalar_divergence_plan%recv_buffer( &
               data_start:data_start+BLOCK_SCALAR_FLUX_COUNT-1) = &
               block_scalar_divergence_plan%recv_buffer( &
               source_start:source_start+BLOCK_SCALAR_FLUX_COUNT-1)
          block_scalar_divergence_plan%recv_buffer( &
               data_start+BLOCK_SCALAR_FLUX_COUNT: &
               data_start+BLOCK_SCALAR_PRODUCTION_INPUT_COUNT-1) = &
               block_scalar_divergence_plan%recv_buffer( &
               source_start+BLOCK_SCALAR_PHYSICS_START-1: &
               source_start+BLOCK_SCALAR_PHYSICS_START+EDGE-2)
       end do
       call MPI_Alltoallv( &
            block_scalar_divergence_plan%recv_buffer, &
            block_scalar_divergence_plan%production_recv_count, &
            block_scalar_divergence_plan%production_recv_displ, &
            MPI_DOUBLE_PRECISION, &
            block_scalar_divergence_plan%send_buffer, &
            block_scalar_divergence_plan%production_send_count, &
            block_scalar_divergence_plan%production_send_displ, &
            MPI_DOUBLE_PRECISION,comm,ierr)
    end if
    call check_mpi(ierr,"MPI_Alltoallv scalar-divergence input")

    do r = 1,n_process
       if (deduplicated_transport) then
          data_start = block_scalar_divergence_plan% &
               deduplicated_send_displ(r) + 1
       else if (block_scalar_divergence_plan%full_transport) then
          data_start = block_scalar_divergence_plan%send_displ(r) + 1
       else
          data_start = &
               block_scalar_divergence_plan%production_send_displ(r) + 1
       end if
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          if (deduplicated_transport) then
             b = block_scalar_divergence_plan% &
                  deduplicated_received_block(slot)
          else
             b = block_writeback_plan%send_block(slot)
          end if
          local_index = catalog_local_block(b)
          if (local_index < 1 .or. &
               local_index > size(block_scalar_tendency)) then
             call fail("scalar-divergence received block is invalid")
          end if
          if (deduplicated_transport) then
             sample_count = local_block_patch_count(b)* &
                  block_writeback_plan%scalar_patch_nvalue
             data_count = deduplicated_block_value_count( &
                  local_block_patch_count(b))
             call unpack_deduplicated_full_block( &
                  local_index,data_start, &
                  local_block_patch_count(b))
          else if (block_scalar_divergence_plan%full_transport) then
             sample_count = &
                  block_writeback_plan%send_scalar_nvalue(slot)
             data_count = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample_count
             if (data_start < 1 .or. data_start+data_count-1 > &
                  size(block_scalar_divergence_plan%send_buffer) .or. &
                  data_count /= &
                  size(block_scalar_tendency(local_index)%patch)) then
                call fail("scalar-divergence received extent is invalid")
             end if
             block_scalar_tendency(local_index)%patch = &
                  block_scalar_divergence_plan%send_buffer( &
                  data_start:data_start+data_count-1)
          else
             sample_count = &
                  block_writeback_plan%send_scalar_nvalue(slot)
             data_count = BLOCK_SCALAR_PRODUCTION_INPUT_COUNT*sample_count
             if (data_start < 1 .or. data_start+data_count-1 > &
                  size(block_scalar_divergence_plan%send_buffer) .or. &
                  BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample_count /= &
                  size(block_scalar_tendency(local_index)%patch)) then
                call fail( &
                     "compact scalar-divergence received extent is invalid")
             end if
             do sample = 0,sample_count-1
                source_start = data_start + &
                     BLOCK_SCALAR_PRODUCTION_INPUT_COUNT*sample
                block_scalar_tendency(local_index)%patch( &
                     BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample+1: &
                     BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample+ &
                     BLOCK_SCALAR_FLUX_COUNT) = &
                     block_scalar_divergence_plan%send_buffer( &
                     source_start:source_start+ &
                     BLOCK_SCALAR_FLUX_COUNT-1)
                block_scalar_tendency(local_index)%patch( &
                     BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample+ &
                     BLOCK_SCALAR_PHYSICS_START: &
                     BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample+ &
                     BLOCK_SCALAR_PHYSICS_START+EDGE-1) = &
                     block_scalar_divergence_plan%send_buffer( &
                     source_start+BLOCK_SCALAR_FLUX_COUNT: &
                     source_start+BLOCK_SCALAR_PRODUCTION_INPUT_COUNT-1)
             end do
          end if
          block_scalar_tendency(local_index)%covered = .true.
          data_start = data_start + data_count
       end do
       if (deduplicated_transport) then
          if (data_start /= block_scalar_divergence_plan% &
               deduplicated_send_displ(r) + &
               block_scalar_divergence_plan% &
               deduplicated_send_count(r) + 1) then
             call fail("deduplicated scalar receive extent mismatch")
          end if
       else if (block_scalar_divergence_plan%full_transport) then
          if (data_start /= block_scalar_divergence_plan%send_displ(r) + &
               block_scalar_divergence_plan%send_count(r) + 1) then
             call fail("scalar-divergence receive extent mismatch")
          end if
       else
          if (data_start /= &
               block_scalar_divergence_plan%production_send_displ(r) + &
               block_scalar_divergence_plan%production_send_count(r) + 1) &
               then
             call fail("compact scalar-divergence receive extent mismatch")
          end if
       end if
    end do

    call finalize_block_scalar_restriction_boundaries( &
         profile_initial_mode)

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       if (.not. all(block_scalar_tendency(local_index)%covered)) then
          call fail("scalar-divergence block coverage is incomplete")
       end if
       block_scalar_tendency(local_index)%installed_patch_count = &
            local_block_patch_count(b)
       block_scalar_tendency(local_index)%ready = .true.
    end do
    if (block_scalar_divergence_plan%allocations /= allocation_before) then
       call fail("scalar-divergence finalize reallocated transport")
    end if
    block_scalar_divergence_plan%active = .false.
    block_scalar_divergence_plan%ready = .true.
    if (block_scalar_divergence_plan%full_transport) &
         block_scalar_divergence_plan%production_cache_ready = .true.

    if (deduplicated_transport) then
       call record_initial_volume(block_scalar_divergence_plan% &
            deduplicated_recv_count)
    else if (block_scalar_divergence_plan%full_transport) then
       call record_initial_volume(block_scalar_divergence_plan%recv_count)
    else
       call record_initial_volume( &
            block_scalar_divergence_plan%production_recv_count)
    end if
    call block_profile_leave( &
         profile_initial_mode,int(n_local_blocks(),int64))
    call block_profile_leave( &
         BLOCK_PROFILE_RESTRICTION_INITIAL, &
         int(n_local_blocks(),int64))
    call block_profile_leave(BLOCK_PROFILE_RESTRICTION)

  contains

    integer function deduplicated_block_value_count ( &
         patch_count) result(value_count)

      implicit none

      integer, intent(in) :: patch_count

      integer :: field_count

      field_count = block_writeback_plan%scalar_patch_nvalue/ &
           (PATCH_SIZE**2)
      value_count = patch_count*PATCH_SIZE**2* &
           (BLOCK_SCALAR_FULL_SHARED_COUNT + &
           BLOCK_SCALAR_FULL_FIELD_COUNT*field_count)

    end function deduplicated_block_value_count


    subroutine pack_deduplicated_full_transport

      implicit none

      integer :: destination
      integer :: f
      integer :: field_count
      integer :: first_field_level
      integer :: k
      integer :: level_count
      integer :: mult_scalar
      integer :: mult_vector
      integer :: n_scalar_variable
      integer :: p
      integer :: q
      integer :: r_pack
      integer :: sample_pack
      integer :: shared_field
      integer :: slot_pack
      integer :: source
      integer :: v_scalar
      integer :: v_vector

      call get_block_field_layout( &
           v_scalar,n_scalar_variable,v_vector,first_field_level, &
           level_count,mult_scalar,mult_vector)
      field_count = n_scalar_variable*level_count
      shared_field = 1-first_field_level
      if (shared_field < 0 .or. shared_field >= level_count .or. &
           field_count /= block_writeback_plan%scalar_patch_nvalue/ &
           (PATCH_SIZE**2)) then
         call fail("deduplicated scalar shared field is invalid")
      end if
      do r_pack = 1,n_process
         destination = block_scalar_divergence_plan% &
              deduplicated_recv_displ(r_pack) + 1
         source = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
              block_writeback_plan%scalar_recv_displ(r_pack) + 1
         do slot_pack = block_writeback_plan%recv_displ(r_pack)+1, &
              block_writeback_plan%recv_displ(r_pack) + &
              block_writeback_plan%recv_count(r_pack)
            do p = 0,block_writeback_plan% &
                 recv_patch_count(slot_pack)-1
               do f = 0,field_count-1
                  do q = 0,PATCH_SIZE**2-1
                     sample_pack = p*field_count*PATCH_SIZE**2 + &
                          f*PATCH_SIZE**2 + q
                     if (f == shared_field) then
                        block_scalar_divergence_plan% &
                             deduplicated_buffer(destination: &
                             destination+ &
                             BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                             block_scalar_divergence_plan%recv_buffer( &
                             source + &
                             BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                             sample_pack:source + &
                             BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                             (sample_pack+1)-1)
                        destination = destination + &
                             BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT
                     else
                        do k = 1,BLOCK_SCALAR_FULL_FIELD_COUNT
                           block_scalar_divergence_plan% &
                                deduplicated_buffer(destination) = &
                                block_scalar_divergence_plan%recv_buffer( &
                                source + &
                                BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                                sample_pack + &
                                BLOCK_SCALAR_FULL_FIELD_INDEX(k)-1)
                           destination = destination + 1
                        end do
                     end if
                  end do
               end do
            end do
            source = source + BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                 block_writeback_plan%recv_scalar_nvalue(slot_pack)
         end do
         if (destination /= block_scalar_divergence_plan% &
              deduplicated_recv_displ(r_pack) + &
              block_scalar_divergence_plan% &
              deduplicated_recv_count(r_pack) + 1) then
            call fail("deduplicated scalar send extent mismatch")
         end if
      end do

    end subroutine pack_deduplicated_full_transport


    subroutine unpack_deduplicated_full_block ( &
         local_index_unpack,source_unpack,patch_count)

      implicit none

      integer, intent(in) :: local_index_unpack
      integer, intent(in) :: source_unpack
      integer, intent(in) :: patch_count

      integer :: destination_unpack
      integer :: f
      integer :: field_count
      integer :: first_field_level
      integer :: k
      integer :: level_count
      integer :: mult_scalar
      integer :: mult_vector
      integer :: n_scalar_variable
      integer :: p
      integer :: q
      integer :: sample_unpack
      integer :: shared_field
      integer :: source_position
      integer :: v_scalar
      integer :: v_vector

      call get_block_field_layout( &
           v_scalar,n_scalar_variable,v_vector,first_field_level, &
           level_count,mult_scalar,mult_vector)
      field_count = n_scalar_variable*level_count
      shared_field = 1-first_field_level
      if (shared_field < 0 .or. shared_field >= level_count .or. &
           field_count /= block_writeback_plan%scalar_patch_nvalue/ &
           (PATCH_SIZE**2)) then
         call fail("deduplicated scalar unpack field is invalid")
      end if
      source_position = source_unpack
      do p = 0,patch_count-1
         do f = 0,field_count-1
            do q = 0,PATCH_SIZE**2-1
               sample_unpack = p*field_count*PATCH_SIZE**2 + &
                    f*PATCH_SIZE**2 + q
               destination_unpack = &
                    BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                    sample_unpack + 1
               if (f == shared_field) then
                  block_scalar_tendency(local_index_unpack)%patch( &
                       destination_unpack:destination_unpack+ &
                       BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                       block_scalar_divergence_plan%send_buffer( &
                       source_position:source_position+ &
                       BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1)
                  source_position = source_position + &
                       BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT
               else
                  do k = 1,BLOCK_SCALAR_FULL_FIELD_COUNT
                     block_scalar_tendency(local_index_unpack)%patch( &
                          destination_unpack + &
                          BLOCK_SCALAR_FULL_FIELD_INDEX(k)-1) = &
                          block_scalar_divergence_plan%send_buffer( &
                          source_position)
                     source_position = source_position + 1
                  end do
               end if
            end do
         end do
      end do
      if (source_position /= source_unpack + &
           deduplicated_block_value_count(patch_count)) then
         call fail("deduplicated scalar block unpack differs")
      end if
      ! The canonical physical-level record can occur after scaffold fields
      ! in storage order.  Populate every shared slot only after the complete
      ! stream has installed that canonical record.
      do p = 0,patch_count-1
         do f = 0,field_count-1
            if (f == shared_field) cycle
            do q = 0,PATCH_SIZE**2-1
               destination_unpack = &
                    BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                    (p*field_count*PATCH_SIZE**2 + &
                    f*PATCH_SIZE**2+q) + 1
               do k = 1,BLOCK_SCALAR_FULL_SHARED_COUNT
                  block_scalar_tendency(local_index_unpack)%patch( &
                       destination_unpack + &
                       BLOCK_SCALAR_FULL_SHARED_INDEX(k)-1) = &
                       block_scalar_tendency(local_index_unpack)%patch( &
                       BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                       (p*field_count*PATCH_SIZE**2 + &
                       shared_field*PATCH_SIZE**2+q) + &
                       BLOCK_SCALAR_FULL_SHARED_INDEX(k))
               end do
            end do
         end do
      end do

    end subroutine unpack_deduplicated_full_block

    subroutine record_initial_volume (send_count)

      implicit none

      integer, intent(in) :: send_count(:)

      integer(int64) :: bytes
      integer(int64) :: messages

      messages = int(count(send_count > 0),int64)
      bytes = int(sum(send_count),int64)* &
           int(storage_size(0.0_dp)/8,int64)
      call record_parallel_block_profile_volume( &
           BLOCK_PROFILE_RESTRICTION,messages,bytes)
      call record_parallel_block_profile_volume( &
           BLOCK_PROFILE_RESTRICTION_INITIAL,messages,bytes)
      call record_parallel_block_profile_volume( &
           profile_initial_mode,messages,bytes)

    end subroutine record_initial_volume

  end subroutine finalize_block_scalar_divergence_capture


  subroutine finalize_block_scalar_restriction_boundaries ( &
       profile_initial_mode)
    ! Complete the one-shot Domain-owner to final-block transfer of compact
    ! boundary restriction records. Retained records were installed directly
    ! during level capture and are left untouched.

    implicit none

    integer, intent(in) :: profile_initial_mode

    integer :: b
    integer :: boundary_index
    integer :: buffer_start
    integer :: data_start
    integer :: ierr
    integer :: level_slot
    integer :: local_index
    integer :: n_boundary_node
    integer :: n_field_level
    integer :: n_node
    integer :: n_scalar_variable
    integer :: node
    integer :: node_start
    integer :: pos_sample
    integer :: r
    integer :: sample
    integer :: scalar_slot
    integer :: slot
    integer :: source_start

    if (block_scalar_divergence_plan%full_transport) then
       call MPI_Alltoallv( &
            block_scalar_restriction_exchange%boundary_send_buffer, &
            block_scalar_restriction_exchange%boundary_send_count, &
            block_scalar_restriction_exchange%boundary_send_displ, &
            MPI_DOUBLE_PRECISION, &
            block_scalar_restriction_exchange%boundary_recv_buffer, &
            block_scalar_restriction_exchange%boundary_recv_count, &
            block_scalar_restriction_exchange%boundary_recv_displ, &
            MPI_DOUBLE_PRECISION,comm,ierr)
    else
       do sample = 0,sum(block_writeback_plan% &
            boundary_scalar_domain_send_count)-1
          buffer_start = BLOCK_SCALAR_BOUNDARY_DYNAMIC_COUNT*sample + 1
          source_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
          block_scalar_restriction_exchange%boundary_send_buffer( &
               buffer_start:buffer_start+EDGE-1) = &
               block_scalar_restriction_exchange%boundary_send_buffer( &
               source_start+BLOCK_SCALAR_RESTRICTED_FLUX_START-1: &
               source_start+BLOCK_SCALAR_RESTRICTED_FLUX_START+EDGE-2)
       end do
       call MPI_Alltoallv( &
            block_scalar_restriction_exchange%boundary_send_buffer, &
            block_scalar_restriction_exchange% &
            boundary_dynamic_send_count, &
            block_scalar_restriction_exchange% &
            boundary_dynamic_send_displ,MPI_DOUBLE_PRECISION, &
            block_scalar_restriction_exchange%boundary_recv_buffer, &
            block_scalar_restriction_exchange% &
            boundary_dynamic_recv_count, &
            block_scalar_restriction_exchange% &
            boundary_dynamic_recv_displ,MPI_DOUBLE_PRECISION,comm,ierr)
    end if
    call check_mpi(ierr,"MPI_Alltoallv scalar-restriction boundaries")
    if (block_scalar_divergence_plan%full_transport) then
       call record_boundary_volume( &
            block_scalar_restriction_exchange%boundary_send_count)
    else
       call record_boundary_volume(block_scalar_restriction_exchange% &
            boundary_dynamic_send_count)
    end if

    call get_block_field_layout_counts( &
         n_scalar_variable,n_field_level)
    do r = 1,n_process
       pos_sample = block_writeback_plan% &
            boundary_scalar_block_recv_displ(r) + 1
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          local_index = catalog_local_block(b)
          if (local_index < 1 .or. &
               local_index > size(block_scalar_tendency)) then
             call fail("scalar-restriction boundary block is invalid")
          end if
          n_boundary_node = size( &
               block_scalar_tendency(local_index)%bdry)/ &
               (BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
               n_scalar_variable*n_field_level)
          node_start = 0
          do boundary_index = 1,local_block_boundary_count(b)
             n_node = local_block_scalar_family_boundary_nvalue( &
                  b,boundary_index)/(n_scalar_variable*n_field_level)
             do scalar_slot = 1,n_scalar_variable
                do level_slot = 1,n_field_level
                   do node = 0,n_node-1
                      sample = ((scalar_slot-1)*n_field_level + &
                           level_slot-1)*n_boundary_node + &
                           node_start + node
                      data_start = &
                           BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
                      if (block_scalar_divergence_plan%full_transport) then
                         buffer_start = &
                              BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                              (pos_sample-1 + &
                              ((scalar_slot-1)*n_field_level + &
                              level_slot-1)*n_node + node) + 1
                         block_scalar_tendency(local_index)%bdry( &
                              data_start:data_start+ &
                              BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                              block_scalar_restriction_exchange% &
                              boundary_recv_buffer(buffer_start: &
                              buffer_start+ &
                              BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1)
                      else
                         buffer_start = &
                              BLOCK_SCALAR_BOUNDARY_DYNAMIC_COUNT* &
                              (pos_sample-1 + &
                              ((scalar_slot-1)*n_field_level + &
                              level_slot-1)*n_node + node) + 1
                         block_scalar_tendency(local_index)%bdry( &
                              data_start+ &
                              BLOCK_SCALAR_RESTRICTED_FLUX_START-1: &
                              data_start+ &
                              BLOCK_SCALAR_RESTRICTED_FLUX_START+EDGE-2) = &
                              block_scalar_restriction_exchange% &
                              boundary_recv_buffer( &
                              buffer_start:buffer_start+EDGE-1)
                      end if
                   end do
                end do
             end do
             pos_sample = pos_sample + &
                  n_node*n_scalar_variable*n_field_level
             node_start = node_start + n_node
          end do
          if (node_start /= n_boundary_node) then
             call fail("scalar-restriction boundary install differs")
          end if
       end do
       if (pos_sample /= block_writeback_plan% &
            boundary_scalar_block_recv_displ(r) + &
            block_writeback_plan% &
            boundary_scalar_block_recv_count(r) + 1) then
          call fail("scalar-restriction boundary receive differs")
       end if
    end do

  contains

    subroutine record_boundary_volume (send_count)

      implicit none

      integer, intent(in) :: send_count(:)

      integer(int64) :: bytes
      integer(int64) :: messages

      messages = int(count(send_count > 0),int64)
      bytes = int(sum(send_count),int64)* &
           int(storage_size(0.0_dp)/8,int64)
      call record_parallel_block_profile_volume( &
           BLOCK_PROFILE_RESTRICTION,messages,bytes)
      call record_parallel_block_profile_volume( &
           BLOCK_PROFILE_RESTRICTION_INITIAL,messages,bytes)
      call record_parallel_block_profile_volume( &
           profile_initial_mode,messages,bytes)

    end subroutine record_boundary_volume


    subroutine get_block_field_layout_counts ( &
         n_scalar_variable,n_field_level)

      implicit none

      integer, intent(out) :: n_scalar_variable
      integer, intent(out) :: n_field_level

      integer :: first_field_level
      integer :: mult_scalar
      integer :: mult_vector
      integer :: v_scalar
      integer :: v_vector

      call get_block_field_layout( &
           v_scalar,n_scalar_variable,v_vector,first_field_level, &
           n_field_level,mult_scalar,mult_vector)
      if (v_scalar < 1 .or. v_vector < 1 .or. &
           first_field_level > zlevels .or. mult_scalar /= 1 .or. &
           mult_vector /= EDGE .or. n_scalar_variable < 1 .or. &
           n_field_level < 1) then
         call fail("scalar-restriction boundary field layout is invalid")
      end if

    end subroutine get_block_field_layout_counts

  end subroutine finalize_block_scalar_restriction_boundaries


  subroutine exchange_block_scalar_restriction_ghosts ( &
       full_payload,dynamic_component,target_level)
    ! Install the complete record once, then refresh only native positive-edge
    ! flux and dscalar values changed by the bottom-up replay. Immutable
    ! geometry and exact-reference slots remain in persistent ghost storage.

    implicit none

    logical, intent(in) :: full_payload
    integer, optional, intent(in) :: dynamic_component
    integer, optional, intent(in) :: target_level

    integer :: destination
    integer :: destination_ghost
    integer :: cache_slot
    integer :: component
    integer :: exchange_level
    integer :: i
    integer :: ierr
    integer :: level_slot
    integer :: list_index
    integer :: local_index
    integer :: pos
    integer :: payload_count
    integer :: payload_pos
    integer :: profile_ghost_mode
    integer :: r
    integer :: record
    integer :: request
    integer :: route_count
    integer :: source
    integer :: source_patch
    integer :: work_count

    logical :: exchange_final_boundary

    if (.not. block_scalar_restriction_exchange%ready) then
       call fail("scalar-restriction ghost exchange is not ready")
    end if
    if (.not. full_payload .and. &
         .not. block_scalar_restriction_exchange% &
         production_ghost_cache_ready) then
       call fail("dynamic scalar-restriction exchange without full cache")
    end if
    component = BLOCK_GHOST_DYNAMIC_BOTH
    if (present(dynamic_component)) component = dynamic_component
    if (full_payload .and. present(dynamic_component)) then
       if (component /= BLOCK_GHOST_DYNAMIC_FLUX) &
            call fail("full scalar ghost exchange component is invalid")
    else if (.not. full_payload .and. &
         component /= BLOCK_GHOST_DYNAMIC_BOTH .and. &
         component /= BLOCK_GHOST_DYNAMIC_FLUX .and. &
         component /= BLOCK_GHOST_DYNAMIC_DSCALAR) then
       call fail("dynamic scalar ghost exchange component is invalid")
    end if
    exchange_level = -1
    level_slot = 1
    if (present(target_level)) exchange_level = target_level
    if (full_payload .and. present(target_level)) then
       call fail("full scalar ghost exchange level is invalid")
    else if (.not. full_payload .and. &
         (exchange_level < level_start .or. &
         exchange_level > level_end)) then
       call fail("dynamic scalar ghost exchange level is invalid")
    end if
    payload_count = BLOCK_SCALAR_RESTRICTION_DYNAMIC_COUNT
    if (component == BLOCK_GHOST_DYNAMIC_FLUX) payload_count = EDGE
    if (component == BLOCK_GHOST_DYNAMIC_DSCALAR) payload_count = 1
    if (full_payload) payload_count = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT
    exchange_final_boundary = .not. full_payload .and. &
         component == BLOCK_GHOST_DYNAMIC_DSCALAR
    profile_ghost_mode = BLOCK_PROFILE_RESTRICTION_GHOST_DYNAMIC
    if (full_payload) &
         profile_ghost_mode = BLOCK_PROFILE_RESTRICTION_GHOST_FULL
    call block_profile_enter(profile_ghost_mode)

    if (.not. full_payload) then
       if (ghost_exchange_plan%route_level_start /= level_start .or. &
            ghost_exchange_plan%route_level_count /= &
            level_end-level_start+1) then
          call fail("persistent ghost level subplan is stale")
       end if
       level_slot = exchange_level - &
            ghost_exchange_plan%route_level_start + 1
       block_scalar_restriction_exchange%ghost_dynamic_send_count = &
            payload_count*ghost_exchange_plan%scalar_n_value* &
            ghost_exchange_plan%recv_level_count(:,level_slot)
       block_scalar_restriction_exchange%ghost_dynamic_recv_count = &
            payload_count*ghost_exchange_plan%scalar_n_value* &
            ghost_exchange_plan%send_level_count(:,level_slot)
       if (exchange_final_boundary) then
          if (.not. block_scalar_boundary_final_plan%ready .or. &
               block_scalar_boundary_final_plan%route_level_start /= &
               level_start .or. &
               block_scalar_boundary_final_plan%route_level_count /= &
               level_end-level_start+1 .or. &
               block_scalar_boundary_final_plan%field_count /= &
               ghost_exchange_plan%scalar_n_value/PATCH_SIZE**2) then
             call fail("scalar boundary final subplan is stale")
          end if
          block_scalar_restriction_exchange%ghost_dynamic_send_count = &
               block_scalar_restriction_exchange% &
               ghost_dynamic_send_count + &
               block_scalar_boundary_final_plan%field_count* &
               block_scalar_boundary_final_plan% &
               service_level_count(:,level_slot)
          block_scalar_restriction_exchange%ghost_dynamic_recv_count = &
               block_scalar_restriction_exchange% &
               ghost_dynamic_recv_count + &
               block_scalar_boundary_final_plan%field_count* &
               block_scalar_boundary_final_plan% &
               request_level_count(:,level_slot)
          block_scalar_boundary_final_plan%covered = .false.
       end if
       block_scalar_restriction_exchange%ghost_dynamic_send_displ(1) = 0
       block_scalar_restriction_exchange%ghost_dynamic_recv_displ(1) = 0
       do r = 2,n_process
          block_scalar_restriction_exchange% &
               ghost_dynamic_send_displ(r) = &
               block_scalar_restriction_exchange% &
               ghost_dynamic_send_displ(r-1) + &
               block_scalar_restriction_exchange% &
               ghost_dynamic_send_count(r-1)
          block_scalar_restriction_exchange% &
               ghost_dynamic_recv_displ(r) = &
               block_scalar_restriction_exchange% &
               ghost_dynamic_recv_displ(r-1) + &
               block_scalar_restriction_exchange% &
               ghost_dynamic_recv_count(r-1)
       end do
    end if

    call block_profile_enter(BLOCK_PROFILE_RESTRICTION_PACK)
    if (block_dynamics_validation_enabled()) then
       block_scalar_restriction_exchange%ghost_send_buffer( &
            1:max(1,sum(merge( &
            block_scalar_restriction_exchange%ghost_send_count, &
            block_scalar_restriction_exchange%ghost_dynamic_send_count, &
            full_payload)))) = BLOCK_GHOST_POISON
       block_scalar_restriction_exchange%ghost_recv_buffer( &
            1:max(1,sum(merge( &
            block_scalar_restriction_exchange%ghost_recv_count, &
            block_scalar_restriction_exchange%ghost_dynamic_recv_count, &
            full_payload)))) = BLOCK_GHOST_POISON
    end if

    work_count = 0
    if (full_payload) then
       do request = 1,ghost_exchange_plan%n_request
          if (ghost_exchange_plan%source_owner(request) /= rank) cycle
          call install_local_request(request)
       end do
    else
       do i = ghost_exchange_plan%local_level_displ(level_slot)+1, &
            ghost_exchange_plan%local_level_displ(level_slot) + &
            ghost_exchange_plan%local_level_count(level_slot)
          request = ghost_exchange_plan%local_level_request(i)
          call install_local_request(request)
       end do
    end if
    if (exchange_final_boundary) then
       do i = block_scalar_boundary_final_plan% &
            local_level_displ(level_slot)+1, &
            block_scalar_boundary_final_plan% &
            local_level_displ(level_slot) + &
            block_scalar_boundary_final_plan% &
            local_level_count(level_slot)
          cache_slot = block_scalar_boundary_final_plan% &
               local_cache_slot(i)
          call fill_final_boundary_cache(cache_slot)
       end do
    end if

    do r = 1,n_process
       if (full_payload) then
          payload_pos = &
               block_scalar_restriction_exchange%ghost_send_displ(r)+1
          route_count = ghost_exchange_plan%recv_record_count(r)
       else
          payload_pos = block_scalar_restriction_exchange% &
               ghost_dynamic_send_displ(r)+1
          route_count = ghost_exchange_plan% &
               recv_level_count(r,level_slot)
       end if
       do i = 0,route_count-1
          if (full_payload) then
             record = ghost_exchange_plan%recv_record_displ(r)+i+1
          else
             list_index = ghost_exchange_plan% &
                  recv_level_base(level_slot) + &
                  ghost_exchange_plan%recv_level_displ(r,level_slot) + &
                  i + 1
             record = ghost_exchange_plan% &
                  recv_level_record(list_index)
          end if
          pos = BLOCK_GHOST_REQUEST_SIZE*(record-1)
          source = ghost_exchange_plan%recv_data(pos+1)
          source_patch = ghost_exchange_plan%recv_data(pos+2)
          local_index = catalog_local_block(source)
          if (local_index < 1 .or. &
               local_index > size(block_scalar_tendency)) then
             call fail("scalar-restriction ghost source is invalid")
          end if
          call pack_patch_record( &
               local_index,source_patch, &
               block_scalar_restriction_exchange%ghost_send_buffer, &
               payload_pos, &
               full_payload,component)
          payload_pos = payload_pos + payload_count* &
               ghost_exchange_plan%scalar_n_value
          work_count = work_count + 1
       end do
       if (exchange_final_boundary) then
          do i = 0,block_scalar_boundary_final_plan% &
               service_level_count(r,level_slot)-1
             record = block_scalar_boundary_final_plan%service_displ(r) + &
                  block_scalar_boundary_final_plan% &
                  service_level_displ(r,level_slot)+i+1
             call pack_final_boundary_service(record,payload_pos)
             payload_pos = payload_pos + &
                  block_scalar_boundary_final_plan%field_count
             work_count = work_count + 1
          end do
       end if
       if (full_payload) then
          if (payload_pos /= block_scalar_restriction_exchange% &
               ghost_send_displ(r) + &
               block_scalar_restriction_exchange%ghost_send_count(r)+1) &
               call fail("full scalar ghost pack extent differs")
       else
          if (payload_pos /= block_scalar_restriction_exchange% &
               ghost_dynamic_send_displ(r) + &
               block_scalar_restriction_exchange% &
               ghost_dynamic_send_count(r)+1) &
               call fail("dynamic scalar ghost pack extent differs")
       end if
    end do

    call block_profile_leave( &
         BLOCK_PROFILE_RESTRICTION_PACK, &
         int(work_count,int64))

    call block_profile_enter(BLOCK_PROFILE_RESTRICTION_MPI)
    if (full_payload) then
       call exchange_sparse_payload( &
            block_scalar_restriction_exchange%ghost_send_buffer, &
            block_scalar_restriction_exchange%ghost_send_count, &
            block_scalar_restriction_exchange%ghost_send_displ, &
            block_scalar_restriction_exchange%ghost_recv_buffer, &
            block_scalar_restriction_exchange%ghost_recv_count, &
            block_scalar_restriction_exchange%ghost_recv_displ)
    else
       call exchange_sparse_payload( &
            block_scalar_restriction_exchange%ghost_send_buffer, &
            block_scalar_restriction_exchange% &
            ghost_dynamic_send_count, &
            block_scalar_restriction_exchange% &
            ghost_dynamic_send_displ, &
            block_scalar_restriction_exchange%ghost_recv_buffer, &
            block_scalar_restriction_exchange% &
            ghost_dynamic_recv_count, &
            block_scalar_restriction_exchange% &
            ghost_dynamic_recv_displ)
    end if
    if (full_payload) then
       call record_ghost_volume( &
            block_scalar_restriction_exchange%ghost_send_count)
    else
       call record_ghost_volume( &
            block_scalar_restriction_exchange%ghost_dynamic_send_count)
    end if
    call block_profile_leave(BLOCK_PROFILE_RESTRICTION_MPI)

    call block_profile_enter(BLOCK_PROFILE_RESTRICTION_INSTALL)
    work_count = 0
    do r = 1,n_process
       if (full_payload) then
          payload_pos = &
               block_scalar_restriction_exchange%ghost_recv_displ(r)+1
          route_count = ghost_exchange_plan%send_record_count(r)
       else
          payload_pos = block_scalar_restriction_exchange% &
               ghost_dynamic_recv_displ(r)+1
          route_count = ghost_exchange_plan% &
               send_level_count(r,level_slot)
       end if
       do i = 0,route_count-1
          if (full_payload) then
             record = ghost_exchange_plan%send_record_displ(r)+i+1
          else
             list_index = ghost_exchange_plan% &
                  send_level_base(level_slot) + &
                  ghost_exchange_plan%send_level_displ(r,level_slot) + &
                  i + 1
             record = ghost_exchange_plan% &
                  send_level_record(list_index)
          end if
          request = ghost_exchange_plan%request_index(record)
          destination = &
               ghost_exchange_plan%destination_block(request)
          destination_ghost = &
               ghost_exchange_plan%destination_ghost(request)
          call install_buffer_ghost( &
               destination,destination_ghost, &
               block_scalar_restriction_exchange%ghost_recv_buffer, &
               payload_pos, &
               full_payload,component)
          payload_pos = payload_pos + payload_count* &
               ghost_exchange_plan%scalar_n_value
          work_count = work_count + 1
       end do
       if (exchange_final_boundary) then
          do i = 0,block_scalar_boundary_final_plan% &
               request_level_count(r,level_slot)-1
             record = block_scalar_boundary_final_plan%request_displ(r) + &
                  block_scalar_boundary_final_plan% &
                  request_level_displ(r,level_slot)+i+1
             cache_slot = block_scalar_boundary_final_plan% &
                  request_cache_slot(record)
             call install_final_boundary_cache(cache_slot,payload_pos)
             payload_pos = payload_pos + &
                  block_scalar_boundary_final_plan%field_count
             work_count = work_count + 1
          end do
       end if
       if (full_payload) then
          if (payload_pos /= block_scalar_restriction_exchange% &
               ghost_recv_displ(r) + &
               block_scalar_restriction_exchange%ghost_recv_count(r)+1) &
               call fail("full scalar ghost install extent differs")
       else
          if (payload_pos /= block_scalar_restriction_exchange% &
               ghost_dynamic_recv_displ(r) + &
               block_scalar_restriction_exchange% &
               ghost_dynamic_recv_count(r)+1) &
               call fail("dynamic scalar ghost install extent differs")
       end if
    end do
    if (exchange_final_boundary) &
         call scatter_final_boundary_cache(level_slot)
    call block_profile_leave( &
         BLOCK_PROFILE_RESTRICTION_INSTALL, &
         int(work_count,int64))
    block_scalar_restriction_exchange%exchanges = &
         block_scalar_restriction_exchange%exchanges + 1_int64
    call block_profile_leave(profile_ghost_mode)

  contains

    subroutine install_local_request (request)

      implicit none

      integer, intent(in) :: request

      integer :: destination_local
      integer :: destination_ghost_local
      integer :: source_local
      integer :: source_patch_local

      source_local = ghost_exchange_plan%source_block(request)
      source_patch_local = &
           ghost_exchange_plan%source_local_patch(request)
      destination_local = &
           ghost_exchange_plan%destination_block(request)
      destination_ghost_local = &
           ghost_exchange_plan%destination_ghost(request)
      call install_local_source( &
           source_local,source_patch_local,destination_local, &
           destination_ghost_local,full_payload,component)
      work_count = work_count + 1

    end subroutine install_local_request


    subroutine fill_final_boundary_cache (cache_slot)

      implicit none

      integer, intent(in) :: cache_slot

      integer :: data_index
      integer :: field_sample
      integer :: local_source
      integer :: node_source
      integer :: patch_source
      integer :: source_block
      integer :: source_patch_count
      real(dp) :: source_value

      if (cache_slot < 1 .or. &
           cache_slot > block_scalar_boundary_final_plan%cache_count) then
         call fail("local scalar boundary final cache slot is invalid")
      end if
      source_block = block_scalar_boundary_final_plan% &
           cache_block(cache_slot)
      patch_source = block_scalar_boundary_final_plan% &
           cache_patch(cache_slot)
      node_source = block_scalar_boundary_final_plan% &
           cache_node(cache_slot)
      if (source_block < 1 .or. &
           source_block > size(block_catalog)) &
           call fail("local scalar boundary final block is invalid")
      local_source = catalog_local_block(source_block)
      if (local_source < 1 .or. &
           local_source > size(block_scalar_tendency) .or. &
           block_catalog(source_block)%owner /= rank) then
         call fail("local scalar boundary final source is invalid")
      end if
      source_patch_count = local_block_patch_count(source_block)
      if (patch_source < 0 .or. &
           patch_source >= source_patch_count) &
           call fail("local scalar boundary final patch is invalid")
      if (node_source < 0 .or. node_source >= PATCH_SIZE**2) &
           call fail("local scalar boundary final node is invalid")
      if (local_block_patch_level(source_block,patch_source) /= &
           exchange_level) &
           call fail("local scalar boundary final level differs")
      do field_sample = 1,block_scalar_boundary_final_plan%field_count
         data_index = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*( &
              patch_source*ghost_exchange_plan%scalar_n_value + &
              (field_sample-1)*PATCH_SIZE**2+node_source) + &
              BLOCK_SCALAR_NATIVE_DSCALAR_INDEX
         if (data_index < 1 .or. &
              data_index > size(block_scalar_tendency(local_source)%patch)) &
              call fail("local scalar boundary final data overruns")
         source_value = block_scalar_tendency(local_source)%patch(data_index)
         if (abs(source_value) > BLOCK_RESTRICTION_VALUE_LIMIT) then
            write(error_unit,'(a,7(i0,1x),es24.16)') &
                 "invalid local final source = ", &
                 source_block,patch_source,node_source,exchange_level, &
                 field_sample,local_source,data_index,source_value
            flush(error_unit)
            call fail("local scalar boundary final value is unavailable")
         end if
         call set_final_boundary_cache_value( &
              cache_slot,field_sample,source_value)
      end do

    end subroutine fill_final_boundary_cache


    subroutine pack_final_boundary_service (record,data_start)

      implicit none

      integer, intent(in) :: record
      integer, intent(in) :: data_start

      integer :: data_index
      integer :: field_sample
      integer :: local_source
      integer :: node_source
      integer :: patch_source
      integer :: source_block
      integer :: source_patch_count
      real(dp) :: source_value

      if (record < 1 .or. &
           record > sum(block_scalar_boundary_final_plan%service_count)) &
           then
         call fail("scalar boundary final service record is invalid")
      end if
      source_block = block_scalar_boundary_final_plan%service_block(record)
      patch_source = block_scalar_boundary_final_plan%service_patch(record)
      node_source = block_scalar_boundary_final_plan%service_node(record)
      if (source_block < 1 .or. &
           source_block > size(block_catalog)) &
           call fail("scalar boundary final service block is invalid")
      local_source = catalog_local_block(source_block)
      if (local_source < 1 .or. &
           local_source > size(block_scalar_tendency) .or. &
           block_catalog(source_block)%owner /= rank) then
         call fail("scalar boundary final service source is invalid")
      end if
      source_patch_count = local_block_patch_count(source_block)
      if (patch_source < 0 .or. &
           patch_source >= source_patch_count) &
           call fail("scalar boundary final service patch is invalid")
      if (node_source < 0 .or. node_source >= PATCH_SIZE**2) &
           call fail("scalar boundary final service node is invalid")
      if (block_scalar_boundary_final_plan%service_level(record) /= &
           exchange_level) &
           call fail("scalar boundary final service level differs")
      do field_sample = 1,block_scalar_boundary_final_plan%field_count
         data_index = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*( &
              patch_source*ghost_exchange_plan%scalar_n_value + &
              (field_sample-1)*PATCH_SIZE**2+node_source) + &
              BLOCK_SCALAR_NATIVE_DSCALAR_INDEX
         if (data_index < 1 .or. &
              data_index > size(block_scalar_tendency(local_source)%patch)) &
              call fail("scalar boundary final service data overruns")
         if (data_start+field_sample-1 < 1 .or. &
              data_start+field_sample-1 > size( &
              block_scalar_restriction_exchange%ghost_send_buffer)) then
            call fail("scalar boundary final service buffer overruns")
         end if
         source_value = block_scalar_tendency(local_source)%patch(data_index)
         if (abs(source_value) > BLOCK_RESTRICTION_VALUE_LIMIT) then
            write(error_unit,'(a,7(i0,1x),es24.16)') &
                 "invalid remote final source = ", &
                 source_block,patch_source,node_source,exchange_level, &
                 field_sample,local_source,data_index,source_value
            flush(error_unit)
            call fail("scalar boundary final service value is unavailable")
         end if
         block_scalar_restriction_exchange%ghost_send_buffer( &
              data_start+field_sample-1) = source_value
      end do

    end subroutine pack_final_boundary_service


    subroutine install_final_boundary_cache (cache_slot,data_start)

      implicit none

      integer, intent(in) :: cache_slot
      integer, intent(in) :: data_start

      integer :: field_sample

      do field_sample = 1,block_scalar_boundary_final_plan%field_count
         if (data_start+field_sample-1 < 1 .or. &
              data_start+field_sample-1 > size( &
              block_scalar_restriction_exchange%ghost_recv_buffer)) then
            call fail("scalar boundary final receive buffer overruns")
         end if
         call set_final_boundary_cache_value( &
              cache_slot,field_sample, &
              block_scalar_restriction_exchange% &
              ghost_recv_buffer(data_start+field_sample-1))
      end do

    end subroutine install_final_boundary_cache


    subroutine set_final_boundary_cache_value ( &
         cache_slot,field_sample,value)

      implicit none

      integer, intent(in) :: cache_slot
      integer, intent(in) :: field_sample
      real(dp), intent(in) :: value

      integer :: cache_index

      if (cache_slot < 1 .or. &
           cache_slot > block_scalar_boundary_final_plan%cache_count .or. &
           field_sample < 1 .or. &
           field_sample > block_scalar_boundary_final_plan%field_count) &
           then
         call fail("scalar boundary final cache address is invalid")
      end if
      cache_index = (field_sample-1)* &
           block_scalar_boundary_final_plan%cache_count+cache_slot
      if (cache_index < 1 .or. &
           cache_index > size(block_scalar_boundary_final_plan%value) .or. &
           block_scalar_boundary_final_plan%covered(cache_index)) then
         call fail("scalar boundary final cache value is duplicated")
      end if
      block_scalar_boundary_final_plan%value(cache_index) = value
      block_scalar_boundary_final_plan%covered(cache_index) = .true.

    end subroutine set_final_boundary_cache_value


    subroutine scatter_final_boundary_cache (level_slot)

      implicit none

      integer, intent(in) :: level_slot

      integer :: boundary_node
      integer :: cache_index
      integer :: cache_slot
      integer :: data_index
      integer :: field_sample
      integer :: list_index
      integer :: local_destination
      integer :: n_boundary_node

      real(dp) :: final_value

      if (level_slot < 1 .or. &
           level_slot > block_scalar_boundary_final_plan% &
           route_level_count) then
         call fail("scalar boundary final scatter level is invalid")
      end if
      do cache_slot = 1,block_scalar_boundary_final_plan%cache_count
         if (block_scalar_boundary_final_plan%cache_level(cache_slot) /= &
              exchange_level) cycle
         do field_sample = 1, &
              block_scalar_boundary_final_plan%field_count
            cache_index = (field_sample-1)* &
                 block_scalar_boundary_final_plan%cache_count+cache_slot
            if (.not. block_scalar_boundary_final_plan% &
                 covered(cache_index)) then
               call fail("scalar boundary final cache is incomplete")
            end if
         end do
      end do

      do list_index = block_scalar_boundary_final_plan% &
           boundary_level_displ(level_slot)+1, &
           block_scalar_boundary_final_plan% &
           boundary_level_displ(level_slot) + &
           block_scalar_boundary_final_plan% &
           boundary_level_count(level_slot)
         local_destination = block_scalar_boundary_final_plan% &
              boundary_local_index(list_index)
         boundary_node = block_scalar_boundary_final_plan% &
              boundary_node(list_index)
         cache_slot = block_scalar_boundary_final_plan% &
              boundary_cache_slot(list_index)
         if (local_destination < 1 .or. &
              local_destination > size(block_scalar_tendency)) then
            call fail("scalar boundary final destination is invalid")
         end if
         n_boundary_node = block_scalar_restriction_exchange% &
              boundary_source_displ(local_destination+1) - &
              block_scalar_restriction_exchange% &
              boundary_source_displ(local_destination)
         if (boundary_node < 0 .or. boundary_node >= n_boundary_node) then
            call fail("scalar boundary final destination node is invalid")
         end if
         do field_sample = 1, &
              block_scalar_boundary_final_plan%field_count
            cache_index = (field_sample-1)* &
                 block_scalar_boundary_final_plan%cache_count+cache_slot
            data_index = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*( &
                 (field_sample-1)*n_boundary_node+boundary_node) + &
                 BLOCK_SCALAR_NATIVE_DSCALAR_INDEX
            final_value = block_scalar_boundary_final_plan% &
                 value(cache_index)
            block_scalar_tendency(local_destination)%bdry(data_index) = &
                 final_value
         end do
      end do

    end subroutine scatter_final_boundary_cache


    subroutine exchange_sparse_payload ( &
         send_buffer,send_count,send_displ, &
         recv_buffer,recv_count,recv_displ)
      ! The route plan is sparse but fixed for this topology. Post receives
      ! first, then sends only to actual peers, avoiding a communicator-wide
      ! collective at every bottom-up restriction level.

      implicit none

      integer, parameter :: SCALAR_RESTRICTION_GHOST_TAG = 27163

      real(dp), intent(in) :: send_buffer(:)
      integer, intent(in) :: send_count(:)
      integer, intent(in) :: send_displ(:)
      real(dp), intent(inout) :: recv_buffer(:)
      integer, intent(in) :: recv_count(:)
      integer, intent(in) :: recv_displ(:)

      integer :: peer
      integer :: request_count

      if (size(send_count) /= n_process .or. &
           size(send_displ) /= n_process .or. &
           size(recv_count) /= n_process .or. &
           size(recv_displ) /= n_process) then
         call fail("sparse scalar ghost route extent is invalid")
      end if
      request_count = 0
      do peer = 1,n_process
         if (recv_count(peer) <= 0) cycle
         request_count = request_count + 1
         call MPI_Irecv( &
              recv_buffer(recv_displ(peer)+1),recv_count(peer), &
              MPI_DOUBLE_PRECISION,peer-1, &
              SCALAR_RESTRICTION_GHOST_TAG,comm, &
              block_scalar_restriction_exchange% &
              sparse_request(request_count),ierr)
         call check_mpi(ierr,"MPI_Irecv sparse scalar ghosts")
      end do
      do peer = 1,n_process
         if (send_count(peer) <= 0) cycle
         request_count = request_count + 1
         call MPI_Isend( &
              send_buffer(send_displ(peer)+1),send_count(peer), &
              MPI_DOUBLE_PRECISION,peer-1, &
              SCALAR_RESTRICTION_GHOST_TAG,comm, &
              block_scalar_restriction_exchange% &
              sparse_request(request_count),ierr)
         call check_mpi(ierr,"MPI_Isend sparse scalar ghosts")
      end do
      if (request_count > &
           size(block_scalar_restriction_exchange%sparse_request)) then
         call fail("sparse scalar ghost request extent is invalid")
      end if
      if (request_count > 0) then
         call MPI_Waitall(request_count, &
              block_scalar_restriction_exchange% &
              sparse_request(1:request_count), &
              MPI_STATUSES_IGNORE,ierr)
         call check_mpi(ierr,"MPI_Waitall sparse scalar ghosts")
      end if

    end subroutine exchange_sparse_payload

    subroutine record_ghost_volume (send_count)

      implicit none

      integer, intent(in) :: send_count(:)

      integer(int64) :: bytes
      integer(int64) :: messages

      messages = int(count(send_count > 0),int64)
      bytes = int(sum(send_count),int64)* &
           int(storage_size(0.0_dp)/8,int64)
      if (full_payload) then
         block_scalar_restriction_exchange%full_exchanges = &
              block_scalar_restriction_exchange%full_exchanges + 1_int64
         block_scalar_restriction_exchange%full_values = &
              block_scalar_restriction_exchange%full_values + &
              int(sum(send_count),int64)
      else
         block_scalar_restriction_exchange%dynamic_exchanges = &
              block_scalar_restriction_exchange%dynamic_exchanges + 1_int64
         block_scalar_restriction_exchange%dynamic_values = &
              block_scalar_restriction_exchange%dynamic_values + &
              int(sum(send_count),int64)
      end if
      call record_parallel_block_profile_volume( &
           BLOCK_PROFILE_RESTRICTION,messages,bytes)
      call record_parallel_block_profile_volume( &
           BLOCK_PROFILE_RESTRICTION_MPI,messages,bytes)
      call record_parallel_block_profile_volume( &
           profile_ghost_mode,messages,bytes)

    end subroutine record_ghost_volume

    subroutine install_local_source ( &
         source,source_patch,destination,destination_ghost, &
         full_payload,component)

      implicit none

      integer, intent(in) :: source
      integer, intent(in) :: source_patch
      integer, intent(in) :: destination
      integer, intent(in) :: destination_ghost
      logical, intent(in) :: full_payload
      integer, intent(in) :: component

      integer :: source_index

      source_index = catalog_local_block(source)
      if (source_index < 1 .or. &
           source_index > size(block_scalar_tendency)) then
         call fail("local scalar-restriction source is invalid")
      end if
      call pack_patch_record( &
           source_index,source_patch, &
           block_scalar_restriction_exchange%ghost_patch_buffer,1, &
           full_payload,component)
      call install_buffer_ghost( &
           destination,destination_ghost, &
           block_scalar_restriction_exchange%ghost_patch_buffer,1, &
           full_payload,component)

    end subroutine install_local_source


    subroutine pack_patch_record ( &
         local_index,source_patch,buffer,data_start,full_payload,component)

      implicit none

      integer, intent(in) :: local_index
      integer, intent(in) :: source_patch
      real(dp), intent(inout) :: buffer(:)
      integer, intent(in) :: data_start
      logical, intent(in) :: full_payload
      integer, intent(in) :: component

      integer :: data_count
      integer :: destination_start
      integer :: field_sample
      integer :: payload_count
      integer :: q
      integer :: record_start
      integer :: source_start

      payload_count = BLOCK_SCALAR_RESTRICTION_DYNAMIC_COUNT
      if (component == BLOCK_GHOST_DYNAMIC_FLUX) payload_count = EDGE
      if (component == BLOCK_GHOST_DYNAMIC_DSCALAR) payload_count = 1
      if (full_payload) payload_count = &
           BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT
      data_count = payload_count*ghost_exchange_plan%scalar_n_value
      source_start = source_patch*data_count + 1
      if (.not. full_payload) source_start = &
           source_patch*BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
           ghost_exchange_plan%scalar_n_value + 1
      if (source_patch < 0 .or. source_start < 1 .or. &
           source_start+BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
           ghost_exchange_plan%scalar_n_value-1 > &
           size(block_scalar_tendency(local_index)%patch) .or. &
           data_start < 1 .or. data_start+data_count-1 > &
           size(buffer)) then
         call fail("scalar-restriction ghost pack extent is invalid")
      end if
      if (full_payload) then
         buffer(data_start:data_start+data_count-1) = &
              block_scalar_tendency(local_index)%patch( &
              source_start:source_start+data_count-1)
      else
         do field_sample = 0, &
              ghost_exchange_plan%scalar_n_value/PATCH_SIZE**2-1
            do q = 0,PATCH_SIZE**2-1
               record_start = source_start + &
                    BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                    (field_sample*PATCH_SIZE**2+q)
               destination_start = data_start + &
                    payload_count* &
                    (field_sample*PATCH_SIZE**2+q)
               if (component /= BLOCK_GHOST_DYNAMIC_DSCALAR) then
                  buffer(destination_start:destination_start+EDGE-1) = &
                       block_scalar_tendency(local_index)%patch( &
                       record_start+BLOCK_SCALAR_DIRECT_FLUX_START-1: &
                       record_start+BLOCK_SCALAR_DIRECT_FLUX_START+EDGE-2)
               end if
               if (component == BLOCK_GHOST_DYNAMIC_DSCALAR) then
                  buffer(destination_start) = &
                       block_scalar_tendency(local_index)%patch( &
                       record_start+BLOCK_SCALAR_NATIVE_DSCALAR_INDEX-1)
               else if (component == BLOCK_GHOST_DYNAMIC_BOTH) then
                  buffer(destination_start+EDGE) = &
                       block_scalar_tendency(local_index)%patch( &
                       record_start+BLOCK_SCALAR_NATIVE_DSCALAR_INDEX-1)
               end if
            end do
         end do
      end if

    end subroutine pack_patch_record


    subroutine install_buffer_ghost ( &
         destination,destination_ghost,buffer,data_start,full_payload, &
         component)

      implicit none

      integer, intent(in) :: destination
      integer, intent(in) :: destination_ghost
      real(dp), intent(in) :: buffer(:)
      integer, intent(in) :: data_start
      logical, intent(in) :: full_payload
      integer, intent(in) :: component

      integer :: destination_index
      integer :: destination_start
      integer :: field_sample
      integer :: n_ghost
      integer :: payload_count
      integer :: q
      integer :: record_start
      integer :: sample

      destination_index = catalog_local_block(destination)
      if (destination_index < 1 .or. &
           destination_index > size(block_scalar_tendency)) then
         call fail("scalar-restriction ghost destination is invalid")
      end if
      n_ghost = local_block_ghost_count(destination)
      if (destination_ghost < 1 .or. destination_ghost > n_ghost) then
         call fail("scalar-restriction destination ghost is invalid")
      end if
      payload_count = BLOCK_SCALAR_RESTRICTION_DYNAMIC_COUNT
      if (component == BLOCK_GHOST_DYNAMIC_FLUX) payload_count = EDGE
      if (component == BLOCK_GHOST_DYNAMIC_DSCALAR) payload_count = 1
      if (full_payload) payload_count = &
           BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT
      do field_sample = 0, &
           ghost_exchange_plan%scalar_n_value/PATCH_SIZE**2-1
         do q = 0,PATCH_SIZE**2-1
            sample = field_sample*n_ghost*PATCH_SIZE**2 + &
                 (destination_ghost-1)*PATCH_SIZE**2 + q
            destination_start = &
                 BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
            record_start = data_start + payload_count* &
                 (field_sample*PATCH_SIZE**2+q)
            if (full_payload) then
               block_scalar_tendency(destination_index)%ghost( &
                    destination_start:destination_start+ &
                    BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = &
                    buffer(record_start:record_start+ &
                    BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1)
            else
               if (component /= BLOCK_GHOST_DYNAMIC_DSCALAR) then
                  block_scalar_tendency(destination_index)%ghost( &
                       destination_start+ &
                       BLOCK_SCALAR_DIRECT_FLUX_START-1: &
                       destination_start+ &
                       BLOCK_SCALAR_DIRECT_FLUX_START+EDGE-2) = &
                       buffer(record_start:record_start+EDGE-1)
               end if
               if (component == BLOCK_GHOST_DYNAMIC_DSCALAR) then
                  block_scalar_tendency(destination_index)%ghost( &
                       destination_start+ &
                       BLOCK_SCALAR_NATIVE_DSCALAR_INDEX-1) = &
                       buffer(record_start)
               else if (component == BLOCK_GHOST_DYNAMIC_BOTH) then
                  block_scalar_tendency(destination_index)%ghost( &
                       destination_start+ &
                       BLOCK_SCALAR_NATIVE_DSCALAR_INDEX-1) = &
                       buffer(record_start+EDGE)
               end if
            end if
         end do
      end do

    end subroutine install_buffer_ghost

  end subroutine exchange_block_scalar_restriction_ghosts


  subroutine evaluate_candidate_block_scalar_restriction
    ! Replay cpt_or_restr_flux bottom-up in compact block storage. Boundary
    ! values are immutable compatibility inputs; patch interiors and every
    ! inter-block ghost refresh are native block products.

    implicit none

    type(Block_Scalar_Restriction_Context) :: statistics

    integer :: ierr
    integer :: l

    integer(int64) :: accumulator_allocation_before
    integer(int64) :: count_global(7)
    integer(int64) :: count_local(7)

    logical :: accumulator_ready
    logical :: full_ghost_transport
    logical :: validate_oracle

    call block_profile_enter(BLOCK_PROFILE_RESTRICTION)
    validate_oracle = block_dynamics_validation_enabled()
    if (validate_oracle) then
       block_scalar_boundary_shadow_count = 0_int64
       block_scalar_boundary_owner_shadow_count = 0_int64
       block_scalar_boundary_cache_shadow_count = 0_int64
       block_scalar_boundary_final_shadow_count = 0_int64
    end if
    if (.not. block_scalar_restriction_exchange%ready) then
       call fail("block-native scalar restriction exchange is not ready")
    end if
    call block_profile_enter(BLOCK_PROFILE_RESTRICTION_KERNEL)
    call initialize_scalar_restriction_boundary_flux
    call block_profile_leave(BLOCK_PROFILE_RESTRICTION_KERNEL)
    ! Establish a native finest-level divergence before it is consumed by the
    ! first coarse restriction. The full exchange installs immutable geometry
    ! and reference data once; later level refreshes carry only dynamic data.
    full_ghost_transport = validate_oracle .or. &
         .not. block_scalar_restriction_exchange% &
         production_ghost_cache_ready
    if (full_ghost_transport) then
       call exchange_block_scalar_restriction_ghosts(.true.)
    else
       ! Direct flux changes every RK stage.  Native dscalar is recomputed
       ! immediately below and is not consumed before its dedicated refresh.
       call exchange_block_scalar_restriction_ghosts( &
            .false.,BLOCK_GHOST_DYNAMIC_FLUX,level_end)
    end if
    if (full_ghost_transport) &
         block_scalar_restriction_exchange% &
         production_ghost_cache_ready = .true.
    statistics%target_level = level_end
    call block_profile_enter(BLOCK_PROFILE_RESTRICTION_KERNEL)
    call apply_local_block_field_consumer( &
         recompute_block_scalar_divergence_level,statistics)
    call block_profile_leave(BLOCK_PROFILE_RESTRICTION_KERNEL)
    do l = level_end-1,level_start,-1
       ! The finer direct-flux stencil was installed when that level became
       ! final.  Only its newly recomputed dscalar changes before restriction.
       call exchange_block_scalar_restriction_ghosts( &
            .false.,BLOCK_GHOST_DYNAMIC_DSCALAR,l+1)
       statistics%target_level = l
       call block_profile_enter(BLOCK_PROFILE_RESTRICTION_KERNEL)
       call apply_local_block_field_consumer( &
            restrict_block_scalar_flux_level,statistics)
       call block_profile_leave(BLOCK_PROFILE_RESTRICTION_KERNEL)
       ! Restriction changed only the positive-edge flux at l.  Refresh that
       ! stencil, then form the dscalar whose refresh begins the next level.
       call exchange_block_scalar_restriction_ghosts( &
            .false.,BLOCK_GHOST_DYNAMIC_FLUX,l)
       call block_profile_enter(BLOCK_PROFILE_RESTRICTION_KERNEL)
       call apply_local_block_field_consumer( &
            recompute_block_scalar_divergence_level,statistics)
       call block_profile_leave(BLOCK_PROFILE_RESTRICTION_KERNEL)
    end do
    statistics%target_level = -1
    call block_profile_enter(BLOCK_PROFILE_RESTRICTION_KERNEL)
    if (validate_oracle) call report_block_scalar_boundary_shadow
    if (validate_oracle) then
       call block_profile_enter(BLOCK_PROFILE_ORACLE)
       call apply_local_block_field_consumer( &
            compare_block_scalar_restricted_flux,statistics)
       call apply_local_block_field_consumer( &
            compare_block_scalar_restricted_divergence,statistics)
       call block_profile_leave(BLOCK_PROFILE_ORACLE)
    end if
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (.not. accumulator_ready) then
       call fail("native scalar-divergence activation register is not ready")
    end if
    accumulator_allocation_before = &
         local_block_tendency_accumulator_allocation_count()
    call apply_local_block_field_consumer( &
         install_block_scalar_restricted_divergence,statistics)
    call block_profile_leave(BLOCK_PROFILE_RESTRICTION_KERNEL)
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (.not. accumulator_ready .or. &
         local_block_tendency_accumulator_allocation_count() /= &
         accumulator_allocation_before) then
       call fail("native scalar-divergence activation changed register state")
    end if

    count_local = [statistics%parent_patch_count, &
         statistics%restricted_edge_count, &
         statistics%compared_edge_count, &
         statistics%divergence_replay_count, &
         statistics%divergence_sample_count, &
         statistics%divergence_compared_count, &
         statistics%divergence_activated_count]
    if (validate_oracle) then
       call MPI_Allreduce( &
            count_local,count_global,size(count_local),MPI_INTEGER8, &
            MPI_SUM,comm,ierr)
       call check_mpi(ierr,"MPI_Allreduce block scalar restriction")
       if (count_global(3) < 1_int64 .or. &
            count_global(4) < 1_int64 .or. &
            count_global(5) < 1_int64 .or. &
            count_global(6) < 1_int64 .or. &
            count_global(7) < 1_int64) then
          call fail("block-native scalar divergence coverage is empty")
       end if
       if (count_global(1) == 0_int64 .and. &
            count_global(2) > 0_int64) then
          call fail("block scalar restriction coverage is incomplete")
       end if
       if (count_global(4) /= count_global(5)) then
          call fail( &
               "block-native scalar divergence replay coverage differs")
       end if
       if (count_global(5) /= count_global(6)) then
          call fail( &
               "block-native scalar divergence comparison coverage differs")
       end if
    end if

    call block_profile_leave( &
         BLOCK_PROFILE_RESTRICTION,sum(count_local))

  end subroutine evaluate_candidate_block_scalar_restriction


  subroutine report_block_scalar_boundary_shadow
    ! Stage 166B shadow report. Counts boundary dscalar consumptions for which
    ! direct-flux reconstruction matches the authoritative Domain value, and
    ! those that require an owner-routed or scaffold value. Production still
    ! consumes the captured reference in every case.

    implicit none

    integer :: ierr
    integer(int64) :: count_global(4)
    integer(int64) :: cache_count_global(4)
    integer(int64) :: final_count_global(3)
    integer(int64) :: owner_count_global(3, &
         BLOCK_BOUNDARY_OWNER_CLASS_COUNT)

    call MPI_Allreduce(block_scalar_boundary_shadow_count,count_global,4, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce boundary dscalar shadow")
    call MPI_Allreduce(block_scalar_boundary_owner_shadow_count, &
         owner_count_global,size(owner_count_global),MPI_INTEGER8, &
         MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce boundary dscalar owner shadow")
    call MPI_Allreduce(block_scalar_boundary_cache_shadow_count, &
         cache_count_global,4,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce boundary dscalar cache shadow")
    call MPI_Allreduce(block_scalar_boundary_final_shadow_count, &
         final_count_global,3,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce boundary dscalar final shadow")
    if (count_global(1) /= count_global(2)+count_global(4) .or. &
         count_global(3) > count_global(1)) then
       call fail("boundary dscalar shadow coverage differs")
    end if
    if (sum(owner_count_global(1,:)) /= count_global(1) .or. &
         sum(owner_count_global(2,:)) /= count_global(2) .or. &
         sum(owner_count_global(3,:)) /= count_global(4) .or. &
         any(owner_count_global(1,:) /= owner_count_global(2,:) + &
         owner_count_global(3,:))) then
       call fail("boundary dscalar owner shadow coverage differs")
    end if
    if (cache_count_global(1) /= cache_count_global(2) + &
         cache_count_global(3)+cache_count_global(4)) then
       call fail("boundary dscalar cache shadow coverage differs")
    end if
    if (final_count_global(1) /= &
         final_count_global(2)+final_count_global(3) .or. &
         final_count_global(1) < 1_int64 .or. &
         final_count_global(3) /= 0_int64) then
       call fail("boundary dscalar final shadow coverage differs")
    end if
    if (rank == 0) write(6,'(a,4(i0,1x))') &
         "Block boundary dscalar shadow: " // &
         "access match Domain-zero mismatch = ",count_global
    if (rank == 0) then
       write(6,'(a,4(i0,1x))') &
            "Block boundary cache shadow: " // &
            "access match mismatch fallback = ",cache_count_global
       write(6,'(a,3(i0,1x))') &
            "Block boundary final shadow: " // &
            "samples match mismatch = ",final_count_global
       write(6,'(a,3(i0,1x))') &
            "Block boundary owner shadow local: " // &
            "access match mismatch = ", &
            owner_count_global(:,BLOCK_BOUNDARY_OWNER_LOCAL)
       write(6,'(a,3(i0,1x))') &
            "Block boundary owner shadow remote: " // &
            "access match mismatch = ", &
            owner_count_global(:,BLOCK_BOUNDARY_OWNER_REMOTE)
       write(6,'(a,3(i0,1x))') &
            "Block boundary owner shadow scaffold: " // &
            "access match mismatch = ", &
            owner_count_global(:,BLOCK_BOUNDARY_OWNER_SCAFFOLD)
       write(6,'(a,3(i0,1x))') &
            "Block boundary owner shadow ambiguous: " // &
            "access match mismatch = ", &
            owner_count_global(:,BLOCK_BOUNDARY_OWNER_AMBIGUOUS)
    end if

  end subroutine report_block_scalar_boundary_shadow


  subroutine initialize_scalar_restriction_boundary_flux
    ! Seed native positive-edge flux from the compact boundary record. The
    ! oracle also seeds dscalar from its Domain reference; production leaves
    ! it poisoned until final-owner delivery or flux reconstruction.

    implicit none

    integer :: b
    integer :: data_start
    integer :: sample

    logical :: validate_oracle

    validate_oracle = block_dynamics_validation_enabled()

    do b = 1,size(block_scalar_tendency)
       if (.not. block_scalar_tendency(b)%ready) then
          call fail("scalar-restriction boundary source is stale")
       end if
       if (mod(size(block_scalar_tendency(b)%bdry), &
            BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT) /= 0) then
          call fail("scalar-restriction boundary extent is invalid")
       end if
       do sample = 0,size(block_scalar_tendency(b)%bdry)/ &
            BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1
          data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
          block_scalar_tendency(b)%bdry( &
               data_start+BLOCK_SCALAR_DIRECT_FLUX_START-1: &
               data_start+BLOCK_SCALAR_DIRECT_FLUX_START+EDGE-2) = &
               block_scalar_tendency(b)%bdry( &
               data_start+BLOCK_SCALAR_RESTRICTED_FLUX_START-1: &
               data_start+BLOCK_SCALAR_RESTRICTED_FLUX_START+EDGE-2)
          if (validate_oracle) then
             block_scalar_tendency(b)%bdry( &
                  data_start+BLOCK_SCALAR_NATIVE_DSCALAR_INDEX-1) = &
                  block_scalar_tendency(b)%bdry( &
                  data_start+BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX-1)
          else
             block_scalar_tendency(b)%bdry( &
                  data_start+BLOCK_SCALAR_NATIVE_DSCALAR_INDEX-1) = &
                  BLOCK_BOUNDARY_POISON
          end if
       end do
    end do

  end subroutine initialize_scalar_restriction_boundary_flux


  subroutine restrict_block_scalar_flux_level ( &
       catalog_index,block,context)

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: c
    integer :: child
    integer :: e
    integer :: i
    integer :: i_chd
    integer :: i_par
    integer :: j
    integer :: j_chd
    integer :: j_par
    integer :: level_slot
    integer :: local_index
    integer :: p
    integer :: scalar_slot

    type(Block_Scalar_Restriction_Cursor) :: cursor

    real(dp) :: edge_mask
    real(dp) :: comparison_tolerance
    real(dp) :: operation_scale
    real(dp) :: reference_value
    real(dp) :: sm_flux(4)
    real(dp) :: value

    logical :: validate_oracle

    validate_oracle = block_dynamics_validation_enabled()
    local_index = catalog_local_block(catalog_index)
    if (local_index < 1 .or. &
         local_index > size(block_scalar_tendency)) then
       call fail("scalar-restriction block index is invalid")
    end if
    select type (statistics => context)
    type is (Block_Scalar_Restriction_Context)
       do p = 1,size(block%patch)
          if (block%patch(p)%level /= statistics%target_level) cycle
          if (.not. any(block%patch(p)%children > 0)) cycle
          statistics%parent_patch_count = &
               statistics%parent_patch_count + 1_int64
          do c = 1,N_CHDRN
             child = block%patch(p)%children(c)
             if (child <= 0) cycle
             if (child >= size(block%patch)) then
                call fail("scalar-restriction child patch is invalid")
             end if
             cursor%target_level = statistics%target_level
             cursor%catalog_index = catalog_index
             cursor%block_id = block%id
             cursor%parent_patch = p
             cursor%child_index = c
             cursor%child_patch = child+1
             do scalar_slot = 0,block%n_scalar_variable-1
                cursor%scalar_slot = scalar_slot
                do level_slot = 1,block%n_field_level
                   if (block%field_level+level_slot-1 < 1 .or. &
                        block%field_level+level_slot-1 > zlevels) cycle
                   cursor%level_slot = level_slot
                   cursor%physical_level = &
                        block%field_level+level_slot-1
                   do j = 1,PATCH_SIZE/2
                      j_chd = 2*(j-1)
                      j_par = j-1+chd_offs(2,c)
                      do i = 1,PATCH_SIZE/2
                         i_chd = 2*(i-1)
                         i_par = i-1+chd_offs(1,c)
                         cursor%i_parent = i_par
                         cursor%j_parent = j_par
                         cursor%i_child = i_chd
                         cursor%j_child = j_chd
                         cursor%edge = -1
                         if (max_parent_edge_mask( &
                              block,local_index,p,scalar_slot,level_slot, &
                              i_par,j_par) >= real(RESTRCT,dp)) then
                            sm_flux = interpolate_block_scalar_flux( &
                                 block,local_index,child+1,scalar_slot, &
                                 level_slot,i_chd,j_chd, &
                                 BLOCK_SCALAR_DIRECT_FLUX_START)
                            call validate_scalar_restriction_vector( &
                                 "interpolate_block_scalar_flux", &
                                 sm_flux,cursor)
                         else
                            sm_flux = 0.0_dp
                         end if
                         do e = RT,UP
                            edge_mask = block_scalar_record_value( &
                                 block,local_index,p,scalar_slot, &
                                 level_slot,i_par,j_par, &
                                 BLOCK_SCALAR_EDGE_MASK_START+e)
                            if (edge_mask < real(RESTRCT,dp)) cycle
                            cursor%edge = e
                            if (validate_oracle) then
                               value = complete_block_coarse_flux( &
                                    sm_flux,block,local_index,child+1, &
                                    scalar_slot,level_slot,i_par,j_par, &
                                    i_chd,j_chd,e,cursor,operation_scale)
                            else
                               value = complete_block_coarse_flux( &
                                    sm_flux,block,local_index,child+1, &
                                    scalar_slot,level_slot,i_par,j_par, &
                                    i_chd,j_chd,e,cursor)
                            end if
                            call validate_scalar_restriction_value( &
                                 "complete_block_coarse_flux", &
                                 value,cursor)
                            if (validate_oracle) then
                               reference_value = &
                                    block_scalar_record_value( &
                                    block,local_index,p,scalar_slot, &
                                    level_slot,i_par,j_par, &
                                    BLOCK_SCALAR_RESTRICTED_FLUX_START+e)
                               comparison_tolerance = &
                                    scalar_restriction_roundoff_tolerance( &
                                    value,reference_value, &
                                    level_end-cursor%target_level, &
                                    operation_scale)
                               if (abs(value-reference_value) > &
                                    comparison_tolerance) then
                                  call report_scalar_restriction_cursor( &
                                       "restricted scalar-flux "// &
                                       "comparison exceeded roundoff "// &
                                       "bound",cursor)
                                  write(error_unit, &
                                       '(a,4(es24.16,1x))') &
                                       "  native, reference, difference, "// &
                                       "allowed = ",value,reference_value, &
                                       abs(value-reference_value), &
                                       comparison_tolerance
                                  flush(error_unit)
                                  call report_scalar_restriction_components( &
                                       block,local_index,child+1,sm_flux, &
                                       value,reference_value,cursor)
                                  call fail("scalar-restriction "// &
                                       "component mismatch")
                               end if
                            end if
                            call set_block_patch_scalar_record_value( &
                                 local_index,p,block%n_field_level, &
                                 scalar_slot,level_slot, &
                                 i_par,j_par, &
                                 BLOCK_SCALAR_DIRECT_FLUX_START+e,value)
                            statistics%restricted_edge_count = &
                                 statistics%restricted_edge_count + 1_int64
                         end do
                      end do
                   end do
                end do
             end do
          end do
       end do
    class default
       call fail("scalar-restriction context is invalid")
    end select

  end subroutine restrict_block_scalar_flux_level


  subroutine compare_block_scalar_restricted_flux ( &
       catalog_index,block,context)

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: e
    integer :: i
    integer :: j
    integer :: level_slot
    integer :: local_index
    integer :: p
    integer :: scalar_slot

    real(dp) :: native_value
    real(dp) :: reference_value
    real(dp) :: comparison_tolerance
    real(dp) :: edge_mask
    real(dp) :: operation_scale

    local_index = catalog_local_block(catalog_index)
    select type (statistics => context)
    type is (Block_Scalar_Restriction_Context)
       do p = 1,size(block%patch)
          do scalar_slot = 0,block%n_scalar_variable-1
             do level_slot = 1,block%n_field_level
                if (block%field_level+level_slot-1 < 1 .or. &
                     block%field_level+level_slot-1 > zlevels) cycle
                do j = 0,PATCH_SIZE-1
                   do i = 0,PATCH_SIZE-1
                      do e = RT,UP
                         native_value = block_scalar_record_value( &
                              block,local_index,p,scalar_slot,level_slot, &
                              i,j,BLOCK_SCALAR_DIRECT_FLUX_START+e)
                         reference_value = block_scalar_record_value( &
                              block,local_index,p,scalar_slot,level_slot, &
                              i,j,BLOCK_SCALAR_RESTRICTED_FLUX_START+e)
                         comparison_tolerance = &
                              scalar_restriction_roundoff_tolerance( &
                              native_value,reference_value, &
                              level_end-level_start)
                         if (abs(native_value-reference_value) > &
                              comparison_tolerance) then
                            edge_mask = block_scalar_record_value( &
                                 block,local_index,p,scalar_slot, &
                                 level_slot,i,j, &
                                 BLOCK_SCALAR_EDGE_MASK_START+e)
                            if (edge_mask >= real(RESTRCT,dp)) then
                               operation_scale = &
                                    scalar_restriction_operation_scale( &
                                    catalog_index,block,local_index,p, &
                                    scalar_slot,level_slot,i,j,e)
                               comparison_tolerance = &
                                    scalar_restriction_roundoff_tolerance( &
                                    native_value,reference_value, &
                                    level_end-level_start,operation_scale)
                            end if
                         end if
                         if (abs(native_value-reference_value) > &
                              comparison_tolerance) then
                            write(6, &
                                 '(a,i0,a,i0,a,i0,a,i0,a,i0)') &
                                 "Rank ",rank, &
                                 ": restricted scalar flux mismatch: block = ", &
                                 catalog_index,", patch = ",p, &
                                 ", i = ",i,", j = ",j
                            write(6,'(a,i0,a,i0,a,i0)') &
                                 "  scalar slot = ",scalar_slot, &
                                 ", level slot = ",level_slot, &
                                 ", edge = ",e
                            write(6, &
                                 '(a,es24.16,a,es24.16,a,es24.16)') &
                                 "  cpt_or_restr_flux value = ", &
                                 reference_value,", block value = ", &
                                 native_value,", absolute difference = ", &
                                 abs(native_value-reference_value)
                            write(6,'(a,es24.16)') &
                                 "  allowed roundoff difference = ", &
                                 comparison_tolerance
                            flush(6)
                            call fail( &
                                 "block-native restricted scalar flux differs")
                         end if
                         statistics%compared_edge_count = &
                              statistics%compared_edge_count + 1_int64
                      end do
                   end do
                end do
             end do
          end do
       end do
    class default
       call fail("scalar-restriction comparison context is invalid")
    end select
  end subroutine compare_block_scalar_restricted_flux


  subroutine recompute_block_scalar_divergence_level ( &
       catalog_index,block,context)
    ! Recompute native dscalar immediately after the native flux at one level
    ! becomes final, so the next coarser restriction consumes that result.

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: i
    integer :: j
    integer :: level_slot
    integer :: local_index
    integer :: p
    integer :: scalar_slot

    real(dp) :: native_value

    local_index = catalog_local_block(catalog_index)
    if (local_index < 1 .or. &
         local_index > size(block_scalar_tendency)) then
       call fail("scalar-divergence replay block is invalid")
    end if
    select type (statistics => context)
    type is (Block_Scalar_Restriction_Context)
       do p = 1,size(block%patch)
          if (block%patch(p)%level /= statistics%target_level) cycle
          do scalar_slot = 0,block%n_scalar_variable-1
             do level_slot = 1,block%n_field_level
                if (block%field_level+level_slot-1 < 1 .or. &
                     block%field_level+level_slot-1 > zlevels) cycle
                do j = 0,PATCH_SIZE-1
                   do i = 0,PATCH_SIZE-1
                      native_value = block_scalar_flux_divergence( &
                           block,local_index,p,scalar_slot,level_slot, &
                           i,j,BLOCK_SCALAR_DIRECT_FLUX_START)
                      call set_block_patch_scalar_record_value( &
                           local_index,p,block%n_field_level, &
                           scalar_slot,level_slot,i,j, &
                           BLOCK_SCALAR_NATIVE_DSCALAR_INDEX,native_value)
                      statistics%divergence_replay_count = &
                           statistics%divergence_replay_count + 1_int64
                   end do
                end do
             end do
          end do
       end do
    class default
       call fail("scalar-divergence replay context is invalid")
    end select

  end subroutine recompute_block_scalar_divergence_level


  real(dp) function block_scalar_flux_divergence ( &
       block,local_index,p,scalar_slot,level_slot,i,j,flux_start, &
       edge_flux,inverse_area,operation_scale) result(value)
    ! Apply the ops_mod::scalar_trend six-edge orientation and node mask to
    ! either the native or independently captured positive-edge flux.

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: flux_start
    real(dp), optional, intent(out) :: &
         edge_flux(BLOCK_SCALAR_FLUX_COUNT)
    real(dp), optional, intent(out) :: inverse_area
    real(dp), optional, intent(out) :: operation_scale

    real(dp) :: active
    real(dp) :: area
    real(dp) :: flux(BLOCK_SCALAR_FLUX_COUNT)

    if (flux_start /= BLOCK_SCALAR_DIRECT_FLUX_START .and. &
         flux_start /= BLOCK_SCALAR_RESTRICTED_FLUX_START) then
       call fail("scalar-divergence flux mode is invalid")
    end if
    flux(1) = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i,j,flux_start+RT)
    flux(2) = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i-1,j,flux_start+RT)
    flux(3) = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i-1,j-1,flux_start+DG)
    flux(4) = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i,j,flux_start+DG)
    flux(5) = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i,j,flux_start+UP)
    flux(6) = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i,j-1,flux_start+UP)
    area = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i,j,BLOCK_SCALAR_AREA_INDEX)
    active = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot, &
         i,j,BLOCK_SCALAR_ACTIVE_INDEX)

    value = 0.0_dp
    if (active > 0.5_dp) then
       value = -(flux(1)-flux(2)+flux(3)-flux(4) + &
            flux(5)-flux(6))*area
    end if
    if (present(edge_flux)) edge_flux = flux
    if (present(inverse_area)) inverse_area = area
    if (present(operation_scale)) then
       operation_scale = abs(area)*sum(abs(flux))
    end if

  end function block_scalar_flux_divergence


  subroutine compare_block_scalar_restricted_divergence ( &
       catalog_index,block,context)
    ! Evaluate scalar_trend from the retained native restricted positive-edge
    ! flux. The independently captured Domain dq remains authoritative; the
    ! native result is retained only after the comparison succeeds.

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: i
    integer :: j
    integer :: level_slot
    integer :: local_index
    integer :: n_restriction_level
    integer :: p
    integer :: scalar_slot

    real(dp) :: area
    real(dp) :: comparison_tolerance
    real(dp) :: flux(BLOCK_SCALAR_FLUX_COUNT)
    real(dp) :: native_operation_scale
    real(dp) :: native_value
    real(dp) :: operation_scale
    real(dp) :: reference_flux(BLOCK_SCALAR_FLUX_COUNT)
    real(dp) :: reference_operation_scale
    real(dp) :: reference_recomputed
    real(dp) :: reference_tolerance
    real(dp) :: reference_value
    real(dp) :: stored_native_value
    real(dp) :: transported_difference_bound

    local_index = catalog_local_block(catalog_index)
    if (local_index < 1 .or. &
         local_index > size(block_scalar_tendency)) then
       call fail("scalar-divergence comparison block is invalid")
    end if
    select type (statistics => context)
    type is (Block_Scalar_Restriction_Context)
       do p = 1,size(block%patch)
          if (block%patch(p)%level < level_start .or. &
               block%patch(p)%level > level_end) cycle
          n_restriction_level = max( &
               1,level_end-block%patch(p)%level+1)
          do scalar_slot = 0,block%n_scalar_variable-1
             do level_slot = 1,block%n_field_level
                if (block%field_level+level_slot-1 < 1 .or. &
                     block%field_level+level_slot-1 > zlevels) cycle
                do j = 0,PATCH_SIZE-1
                   do i = 0,PATCH_SIZE-1
                      native_value = block_scalar_flux_divergence( &
                           block,local_index,p,scalar_slot,level_slot, &
                           i,j,BLOCK_SCALAR_DIRECT_FLUX_START, &
                           flux,area,native_operation_scale)
                      reference_recomputed = &
                           block_scalar_flux_divergence( &
                           block,local_index,p,scalar_slot,level_slot, &
                           i,j,BLOCK_SCALAR_RESTRICTED_FLUX_START, &
                           edge_flux=reference_flux, &
                           operation_scale=reference_operation_scale)
                      stored_native_value = block_scalar_record_value( &
                           block,local_index,p,scalar_slot,level_slot, &
                           i,j,BLOCK_SCALAR_NATIVE_DSCALAR_INDEX)
                      if (abs(stored_native_value-native_value) > 0.0_dp) then
                         write(error_unit,'(/,a,i0,a)') &
                              "Rank ",rank, &
                              ": replayed scalar divergence changed"
                         write(error_unit,'(a,i0,a,i0,a,i0)') &
                              "  catalog block = ",catalog_index, &
                              ", block id = ",block%id,", patch = ",p
                         write(error_unit,'(a,i0,a,i0,a,i0)') &
                              "  patch level = ",block%patch(p)%level, &
                              ", i = ",i,", j = ",j
                         write(error_unit,'(a,i0,a,i0)') &
                              "  scalar slot = ",scalar_slot, &
                              ", field-level slot = ",level_slot
                         write(error_unit,'(a,3(es24.16,1x))') &
                              "  stored, recomputed, difference = ", &
                              stored_native_value,native_value, &
                              abs(stored_native_value-native_value)
                         flush(error_unit)
                         call fail( &
                              "native scalar-divergence replay is not stable")
                      end if
                      reference_value = block_scalar_record_value( &
                           block,local_index,p,scalar_slot,level_slot, &
                           i,j,BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX)
                      operation_scale = max( &
                           native_operation_scale, &
                           reference_operation_scale)
                      reference_tolerance = &
                           scalar_restriction_roundoff_tolerance( &
                           reference_recomputed,reference_value, &
                           1,operation_scale)
                      if (abs(reference_recomputed-reference_value) > &
                           reference_tolerance) then
                         write(error_unit,'(/,a,i0,a)') &
                              "Rank ",rank, &
                              ": reference scalar divergence mismatch"
                         write(error_unit,'(a,i0,a,i0,a,i0)') &
                              "  catalog block = ",catalog_index, &
                              ", block id = ",block%id,", patch = ",p
                         write(error_unit,'(a,i0,a,i0,a,i0)') &
                              "  patch level = ",block%patch(p)%level, &
                              ", i = ",i,", j = ",j
                         write(error_unit,'(a,i0,a,i0)') &
                              "  scalar slot = ",scalar_slot, &
                              ", field-level slot = ",level_slot
                         write(error_unit,'(a,6(es24.16,1x))') &
                              "  reference edge flux = ",reference_flux
                         write(error_unit,'(a,4(es24.16,1x))') &
                              "  recomputed, Domain, difference, allowed = ", &
                              reference_recomputed,reference_value, &
                              abs(reference_recomputed-reference_value), &
                              reference_tolerance
                         flush(error_unit)
                         call fail( &
                              "captured Domain scalar divergence differs")
                      end if
                      transported_difference_bound = &
                           abs(area)*sum(abs(flux-reference_flux))
                      comparison_tolerance = &
                           transported_difference_bound + &
                           scalar_restriction_roundoff_tolerance( &
                           native_value,reference_value, &
                           n_restriction_level,operation_scale)
                      if (abs(native_value-reference_value) > &
                           comparison_tolerance) then
                         write(error_unit,'(/,a,i0,a)') &
                              "Rank ",rank, &
                              ": restricted scalar divergence mismatch"
                         write(error_unit,'(a,i0,a,i0,a,i0)') &
                              "  catalog block = ",catalog_index, &
                              ", block id = ",block%id,", patch = ",p
                         write(error_unit,'(a,i0,a,i0,a,i0)') &
                              "  patch level = ",block%patch(p)%level, &
                              ", i = ",i,", j = ",j
                         write(error_unit,'(a,i0,a,i0)') &
                              "  scalar slot = ",scalar_slot, &
                              ", field-level slot = ",level_slot
                         write(error_unit,'(a,6(es24.16,1x))') &
                              "  native edge flux = ",flux
                         write(error_unit,'(a,6(es24.16,1x))') &
                              "  reference edge flux = ",reference_flux
                         write(error_unit,'(a,3(es24.16,1x))') &
                              "  inverse area, operation scale, transported bound = ", &
                              area,operation_scale, &
                              transported_difference_bound
                         write(error_unit,'(a,4(es24.16,1x))') &
                              "  native, Domain, difference, allowed = ", &
                              native_value,reference_value, &
                              abs(native_value-reference_value), &
                              comparison_tolerance
                         flush(error_unit)
                         call fail( &
                              "block-native restricted scalar divergence differs")
                      end if
                      statistics%divergence_sample_count = &
                           statistics%divergence_sample_count + 1_int64
                      statistics%divergence_compared_count = &
                           statistics%divergence_compared_count + 1_int64
                   end do
                end do
             end do
          end do
       end do
    class default
       call fail("scalar-divergence comparison context is invalid")
    end select

  end subroutine compare_block_scalar_restricted_divergence


  subroutine install_block_scalar_restricted_divergence ( &
       catalog_index,block,context)
    ! Replace only the scalar component of the retained RK tendency with the
    ! validated native restricted-flux divergence. The vector component and
    ! all transaction state remain unchanged.

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    class(*), intent(inout) :: context

    integer :: i
    integer :: j
    integer :: level_slot
    integer :: local_index
    integer :: p
    integer :: pos
    integer :: scalar_slot

    local_index = catalog_local_block(catalog_index)
    if (local_index < 1 .or. &
         local_index > size(block_scalar_tendency)) then
       call fail("scalar-divergence activation block is invalid")
    end if
    if (block%scalar_mult /= 1 .or. &
         size(ghost_exchange_plan%scalar_patch_buffer) /= &
         block%n_scalar_variable*block%n_field_level*PATCH_SIZE**2) then
       call fail("scalar-divergence activation layout is invalid")
    end if

    select type (statistics => context)
    type is (Block_Scalar_Restriction_Context)
       do p = 1,size(block%patch)
          pos = 1
          do scalar_slot = 0,block%n_scalar_variable-1
             do level_slot = 1,block%n_field_level
                do j = 0,PATCH_SIZE-1
                   do i = 0,PATCH_SIZE-1
                      ghost_exchange_plan%scalar_patch_buffer(pos) = &
                           block_scalar_record_value( &
                           block,local_index,p,scalar_slot,level_slot, &
                           i,j,BLOCK_SCALAR_NATIVE_DSCALAR_INDEX)
                      pos = pos + 1
                   end do
                end do
             end do
          end do
          if (pos /= &
               size(ghost_exchange_plan%scalar_patch_buffer)+1) then
             call fail("scalar-divergence activation extent differs")
          end if
          call set_local_block_tendency_accumulator_scalar_patch_values( &
               catalog_index,p-1, &
               ghost_exchange_plan%scalar_patch_buffer)
          statistics%divergence_activated_count = &
               statistics%divergence_activated_count + &
               int(pos-1,int64)
       end do
    class default
       call fail("scalar-divergence activation context is invalid")
    end select

  end subroutine install_block_scalar_restricted_divergence


  pure real(dp) function scalar_restriction_roundoff_tolerance ( &
       first_value,second_value,n_restriction_level,operation_scale) &
       result(tolerance)
    ! Independently evaluated but algebraically identical restriction
    ! expressions may differ after optimization.  Budget both the compact
    ! reconstruction and the stored Domain-reference evaluation at every
    ! completed fine-to-coarse level.

    implicit none

    real(dp), intent(in) :: first_value
    real(dp), intent(in) :: second_value
    integer, intent(in) :: n_restriction_level
    real(dp), optional, intent(in) :: operation_scale

    real(dp) :: comparison_scale

    comparison_scale = max( &
         1.0_dp,abs(first_value),abs(second_value))
    if (present(operation_scale)) then
       comparison_scale = max(comparison_scale,abs(operation_scale))
    end if
    tolerance = 64.0_dp*real(max(1,n_restriction_level),dp)* &
         epsilon(1.0_dp)*comparison_scale

  end function scalar_restriction_roundoff_tolerance


  real(dp) function max_parent_edge_mask ( &
       block,local_index,p,scalar_slot,level_slot,i,j) result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j

    integer :: e

    value = -huge(0.0_dp)
    do e = RT,UP
       value = max(value,block_scalar_record_value( &
            block,local_index,p,scalar_slot,level_slot,i,j, &
            BLOCK_SCALAR_EDGE_MASK_START+e))
    end do

  end function max_parent_edge_mask


  real(dp) function block_scalar_record_value ( &
       block,local_index,p,scalar_slot,level_slot,i,j,record_slot, &
       allow_uninitialized) &
       result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: record_slot
    logical, optional, intent(in) :: allow_uninitialized

    integer :: data_start
    integer :: node
    integer :: record
    integer :: sample
    integer :: storage_class
    logical :: permit_uninitialized

    permit_uninitialized = .false.
    if (present(allow_uninitialized)) &
         permit_uninitialized = allow_uninitialized
    value = 0.0_dp
    data_start = 0
    node = -1
    record = -1
    sample = -1
    storage_class = 0
    call locate_block_scalar_record( &
         block,local_index,p,i,j,storage_class,record,node)
    if (scalar_slot < 0 .or. scalar_slot >= block%n_scalar_variable .or. &
         level_slot < 1 .or. level_slot > block%n_field_level .or. &
         record_slot < 1 .or. &
         record_slot > BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT) then
       call fail("scalar-restriction record field is invalid")
    end if
    select case (storage_class)
    case (STORE_PATCH)
       sample = record*block_writeback_plan%scalar_patch_nvalue + &
            (scalar_slot*block%n_field_level+level_slot-1)* &
            PATCH_SIZE**2 + node
       data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
       if (data_start+record_slot-1 > &
            size(block_scalar_tendency(local_index)%patch)) then
          call fail("scalar-restriction patch record is invalid")
       end if
       value = block_scalar_tendency(local_index)%patch( &
            data_start+record_slot-1)
    case (STORE_BDRY)
       sample = (scalar_slot*block%n_field_level+level_slot-1)* &
            size(block%bdry_node) + node
       data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
       if (data_start+record_slot-1 > &
            size(block_scalar_tendency(local_index)%bdry)) then
          call fail("scalar-restriction boundary record is invalid")
       end if
       value = block_scalar_tendency(local_index)%bdry( &
            data_start+record_slot-1)
    case (STORE_GHOST)
       sample = (scalar_slot*block%n_field_level+level_slot-1)* &
            size(block%ghost_node) + node
       data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
       if (data_start+record_slot-1 > &
            size(block_scalar_tendency(local_index)%ghost)) then
          call fail("scalar-restriction ghost record is invalid")
       end if
       value = block_scalar_tendency(local_index)%ghost( &
            data_start+record_slot-1)
    case default
       call fail("scalar-restriction record storage is invalid")
    end select
    if (.not. ieee_is_finite(value)) then
       call report_record_value("non-finite")
       call fail("scalar-restriction record value is non-finite")
    end if
    if (.not. permit_uninitialized .and. &
         .not. (abs(value) < BLOCK_RESTRICTION_VALUE_LIMIT)) then
       call report_record_value("poisoned or uninitialized")
       call fail("scalar-restriction record value is poisoned")
    end if

  contains

    subroutine report_record_value (description)

      implicit none

      character(*), intent(in) :: description

      write(error_unit,'(/,a,i0,3a)') &
           "Rank ",rank,": scalar-restriction record is ", &
           trim(description),":"
      write(error_unit,'(a,i0,a,i0,a,i0)') &
           "  block id = ",block%id,", local index = ",local_index, &
           ", patch = ",p
      write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
           "  coordinates = ",i,", ",j,", scalar slot = ", &
           scalar_slot,", level slot = ",level_slot
      write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
           "  storage = ",storage_class,", record = ",record, &
           ", node = ",node,", record slot = ",record_slot
      write(error_unit,'(a,i0,a,es24.16)') &
           "  data index = ",data_start+record_slot-1, &
           ", value = ",value
      flush(error_unit)

    end subroutine report_record_value

  end function block_scalar_record_value


  subroutine set_block_patch_scalar_record_value ( &
       local_index,p,n_field_level,scalar_slot,level_slot,i,j, &
       record_slot,value)

    implicit none

    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: n_field_level
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: record_slot
    real(dp), intent(in) :: value

    integer :: data_start
    integer :: sample

    if (p < 1 .or. &
         p > block_scalar_tendency(local_index)%installed_patch_count .or. &
         n_field_level < 1 .or. scalar_slot < 0 .or. &
         level_slot < 1 .or. level_slot > n_field_level .or. &
         i < 0 .or. i >= PATCH_SIZE .or. &
         j < 0 .or. j >= PATCH_SIZE) then
       call fail("scalar-restriction patch write coordinate is invalid")
    end if
    sample = (p-1)*block_writeback_plan%scalar_patch_nvalue + &
         (scalar_slot*n_field_level+level_slot-1)* &
         PATCH_SIZE**2 + PATCH_SIZE*j+i
    data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + 1
    if (record_slot < 1 .or. &
         data_start+record_slot-1 > &
         size(block_scalar_tendency(local_index)%patch)) then
       call fail("scalar-restriction patch write record is invalid")
    end if
    block_scalar_tendency(local_index)%patch( &
         data_start+record_slot-1) = value

  end subroutine set_block_patch_scalar_record_value


  subroutine locate_block_scalar_record ( &
       block,local_index,p,i,j,storage_class,record,node,remap_addressing)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(out) :: storage_class
    integer, intent(out) :: record
    integer, intent(out) :: node
    logical, optional, intent(in) :: remap_addressing

    integer :: address
    integer :: base_adjustment
    integer :: candidate_start
    integer :: dims(2)
    integer :: local_address
    integer :: r
    integer :: side
    integer :: target_domain
    integer :: target_index
    integer :: target_start

    logical :: use_remap_addressing

    address = 0
    base_adjustment = 0
    candidate_start = -1
    dims = 0
    local_address = 0
    r = 0
    side = 0
    target_domain = -1
    target_index = -1
    target_start = -1
    use_remap_addressing = .false.
    if (present(remap_addressing)) &
         use_remap_addressing = remap_addressing
    storage_class = 0
    record = -1
    node = -1
    if (p < 1 .or. p > size(block%patch)) then
       call fail("scalar-restriction stencil patch is invalid")
    end if
    if (i >= 0 .and. i < PATCH_SIZE .and. &
         j >= 0 .and. j < PATCH_SIZE) then
       storage_class = STORE_PATCH
       record = p-1
       node = PATCH_SIZE*j+i
       return
    end if
    if (i < 0) then
       if (j < 0) then
          side = SOUTHWEST
       else if (j >= PATCH_SIZE) then
          side = NORTHWEST
       else
          side = WEST
       end if
    else if (i >= PATCH_SIZE) then
       if (j >= PATCH_SIZE) then
          side = NORTHEAST
       else if (j < 0) then
          side = SOUTHEAST
       else
          side = EAST
       end if
    else if (j < 0) then
       side = SOUTH
    else
       side = NORTH
    end if

    storage_class = block%stencil(side,p)%storage
    record = block%stencil(side,p)%id
    dims = block%stencil(side,p)%dims
    address = block%stencil(side,p)%offset
    if (any(dims < 1)) then
       call fail("scalar-restriction stencil dimensions are invalid")
    end if
    select case (side)
    case (SOUTHWEST)
       base_adjustment = dims(1)*dims(2)-1
       local_address = (j+dims(2))*dims(1)+i+dims(1)
    case (NORTHWEST)
       base_adjustment = dims(1)-1-PATCH_SIZE*(PATCH_SIZE-1)
       local_address = (j-PATCH_SIZE)*dims(1)+i+dims(1)
    case (WEST)
       base_adjustment = dims(1)-1
       local_address = j*dims(1)+i+dims(1)
    case (NORTHEAST)
       base_adjustment = -(PATCH_SIZE*PATCH_SIZE-1)
       local_address = (j-PATCH_SIZE)*dims(1)+i-PATCH_SIZE
    case (SOUTHEAST)
       base_adjustment = dims(1)*( &
            block%stencil(SOUTH,p)%dims(2)-1)-(PATCH_SIZE-1)
       local_address = (j+dims(2))*dims(1)+i-PATCH_SIZE
    case (EAST)
       base_adjustment = -(PATCH_SIZE-1)
       local_address = j*dims(1)+i-PATCH_SIZE
    case (SOUTH)
       base_adjustment = dims(1)*(dims(2)-1)
       local_address = (j+dims(2))*dims(1)+i
    case (NORTH)
       base_adjustment = -PATCH_SIZE*(PATCH_SIZE-1)
       local_address = (j-PATCH_SIZE)*dims(1)+i
    case default
       call fail("scalar-restriction stencil side is invalid")
    end select
    address = address-base_adjustment+local_address

    select case (storage_class)
    case (STORE_PATCH)
       if (record < 0 .or. record >= size(block%patch)) then
          call fail("scalar-restriction stencil patch record is invalid")
       end if
       if (use_remap_addressing) then
          target_start = block_remap_patch_source_start( &
               block,local_index,record+1)
       else
          target_start = block_patch_source_start( &
               block,local_index,record+1)
       end if
       target_domain = block%root_domain
    case (STORE_BDRY)
       if (record < 1 .or. record > size(block%bdry_storage)) then
          call fail("scalar-restriction stencil boundary record is invalid")
       end if
       if (block%bdry_storage(record)%n_node < 1) then
          call fail("scalar-restriction boundary extent is invalid")
       end if
       target_start = block%bdry_storage(record)%elts_start
       target_domain = block%root_domain
    case (STORE_GHOST)
       if (record < 1 .or. record > size(block%ghost_storage)) then
          call fail("scalar-restriction stencil ghost record is invalid")
       end if
       if (block%ghost_storage(record)%n_node /= PATCH_SIZE**2) then
          call fail("scalar-restriction ghost patch extent is invalid")
       end if
       target_start = block%ghost_storage(record)%elts_start
       target_domain = block%ghost_storage(record)%source_domain
    case default
       call fail("scalar-restriction stencil storage is invalid")
    end select
    target_index = target_start+address

    if (target_domain == block%root_domain) then
       do r = 1,size(block%patch)
          if (use_remap_addressing) then
             candidate_start = block_remap_patch_source_start( &
                  block,local_index,r)
          else
             candidate_start = block_patch_source_start( &
                  block,local_index,r)
          end if
          if (target_index < candidate_start .or. &
               target_index >= candidate_start+PATCH_SIZE**2) cycle
          storage_class = STORE_PATCH
          record = r-1
          node = target_index-candidate_start
          return
       end do
       do r = 1,size(block%bdry_storage)
          candidate_start = block%bdry_storage(r)%elts_start
          if (target_index < candidate_start .or. &
               target_index >= candidate_start+ &
               block%bdry_storage(r)%n_node) cycle
          storage_class = STORE_BDRY
          record = r
          node = block%bdry_storage(r)%local_start + &
               target_index-candidate_start
          return
       end do
    end if
    do r = 1,size(block%ghost_storage)
       if (block%ghost_storage(r)%source_domain /= target_domain) cycle
       candidate_start = block%ghost_storage(r)%elts_start
       if (target_index < candidate_start .or. &
            target_index >= candidate_start+ &
            block%ghost_storage(r)%n_node) cycle
       storage_class = STORE_GHOST
       record = r
       node = block%ghost_storage(r)%local_start + &
            target_index-candidate_start
       return
    end do

    if (use_remap_addressing) then
       write(error_unit,'(a,i0,a,i0,a,i0,a,i0,a,i0)') &
            "Rank ",rank, &
            ": unresolved vertical-remap source: block = ",block%id, &
            ", patch = ",p,", i = ",i,", j = ",j
    else
       write(error_unit,'(a,i0,a,i0,a,i0,a,i0,a,i0)') &
            "Rank ",rank, &
            ": unresolved scalar-restriction source: block = ",block%id, &
            ", patch = ",p,", i = ",i,", j = ",j
    end if
    write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
         "  side = ",side,", initial storage = ",storage_class, &
         ", initial record = ",record,", offset = ", &
         block%stencil(side,p)%offset
    write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
         "  base adjustment = ",base_adjustment, &
         ", local address = ",local_address, &
         ", target domain = ",target_domain, &
         ", target index = ",target_index
    flush(error_unit)
    if (use_remap_addressing) then
       call fail("vertical-remap source index is unresolved")
    else
       call fail("scalar-restriction source index is unresolved")
    end if

  end subroutine locate_block_scalar_record


  integer function block_remap_patch_source_start ( &
       block,local_index,p) result(source_start)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p

    source_start = -1
    if (.not. allocated(block_vertical_remap)) then
       call fail("vertical remap source storage is unavailable")
    end if
    if (local_index < 1 .or. &
         local_index > size(block_vertical_remap) .or. &
         p < 1 .or. p > size(block%patch)) then
       call fail("vertical remap source patch is invalid")
    end if
    if (block_vertical_remap(local_index)%catalog_index /= block%id+1) then
       call fail("vertical remap source map has a stale block")
    end if
    if (.not. allocated( &
         block_vertical_remap(local_index)%source_start)) then
       call fail("vertical remap source map is unavailable")
    end if
    if (p > size(block_vertical_remap(local_index)%source_start)) then
       call fail("vertical remap source map extent is invalid")
    end if
    source_start = block_vertical_remap(local_index)%source_start(p)
    if (source_start < 0) then
       call fail("vertical remap source map is incomplete")
    end if

  end function block_remap_patch_source_start


  integer function block_patch_source_start ( &
       block,local_index,p) result(source_start)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p

    integer :: data_index
    integer :: level_slot
    integer :: sample

    real(dp) :: source_value

    source_start = -1
    if (p < 1 .or. p > size(block%patch)) then
       call fail("scalar-restriction source patch is invalid")
    end if
    level_slot = 1-block%field_level+1
    if (level_slot < 1 .or. level_slot > block%n_field_level) then
       call fail("scalar-restriction source level is invalid")
    end if
    sample = (p-1)*block_writeback_plan%scalar_patch_nvalue + &
         (level_slot-1)*PATCH_SIZE**2
    data_index = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT*sample + &
         BLOCK_SCALAR_SOURCE_INDEX
    if (data_index < 1 .or. data_index > &
         size(block_scalar_tendency(local_index)%patch)) then
       call fail("scalar-restriction source index is invalid")
    end if
    source_value = &
         block_scalar_tendency(local_index)%patch(data_index)
    if (.not. ieee_is_finite(source_value) .or. &
         source_value < 0.0_dp .or. &
         source_value > real(huge(source_start),dp)) then
       write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
            "Rank ",rank, &
            ": invalid patch source value: block = ",block%id, &
            ", patch = ",p,", data index = ",data_index
       write(error_unit,'(a,es24.16,a,i0)') &
            "  source value = ",source_value, &
            ", physical level slot = ",level_slot
       flush(error_unit)
       call fail("scalar-restriction patch source value is invalid")
    end if
    source_start = nint(source_value)
    if (source_start < 0 .or. &
         abs(source_value-real(source_start,dp)) > 0.0_dp) then
       call fail("scalar-restriction patch source is invalid")
    end if

  end function block_patch_source_start


  function interpolate_block_scalar_flux ( &
       block,local_index,p,scalar_slot,level_slot,i,j,flux_start) &
       result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: flux_start
    real(dp) :: value(4)

    integer :: edge_component(0:19)
    integer :: edge_i(0:19)
    integer :: edge_j(0:19)
    integer :: scalar_i(0:19)
    integer :: scalar_j(0:19)

    call get_block_restriction_indices( &
         i+1,j,RT,edge_i,edge_j,edge_component,scalar_i,scalar_j)
    value(1) = -sum_edge_weight_product( &
         [WPM,UZM,VMM],i+1,j-2) - &
         sum_edge_difference_weight_product( &
         [VPM,WMMM,UMZ],[UPZ,VPMM,WMM],i+1,j-1)
    value(2) = sum_edge_weight_product( &
         [WMP,UZP,VPP],i,j) + &
         sum_edge_difference_weight_product( &
         [VMP,WPPP,UPZ],[UMZ,VMPP,WPP],i,j+1)

    call get_block_restriction_indices( &
         i,j+1,UP,edge_i,edge_j,edge_component,scalar_i,scalar_j)
    value(3) = -sum_edge_weight_product( &
         [UZM,VMM,WPM],i+1,j) - &
         sum_edge_difference_weight_product( &
         [WMMM,UMZ,VPM],[VPMM,WMM,UPZ],i+1,j+1)
    value(4) = sum_edge_weight_product( &
         [UZP,VPP,WMP],i-2,j) + &
         sum_edge_difference_weight_product( &
         [WPPP,UPZ,VMP],[VMPP,WPP,UMZ],i-2,j+1)

  contains

    real(dp) function sum_edge_weight_product (aliases,wi,wj) &
         result(total)

      implicit none

      integer, intent(in) :: aliases(3)
      integer, intent(in) :: wi
      integer, intent(in) :: wj

      integer :: k

      total = 0.0_dp
      do k = 1,EDGE
         total = total + block_restriction_edge_flux( &
              block,local_index,p,scalar_slot,level_slot, &
              edge_i(aliases(k)),edge_j(aliases(k)), &
              edge_component(aliases(k)),flux_start)* &
              block_scalar_record_value( &
              block,local_index,p,scalar_slot,level_slot,wi,wj, &
              BLOCK_SCALAR_RESTRICTION_WEIGHT_START+k-1)
      end do

    end function sum_edge_weight_product


    real(dp) function sum_edge_difference_weight_product ( &
         positive_aliases,negative_aliases,wi,wj) result(total)

      implicit none

      integer, intent(in) :: positive_aliases(3)
      integer, intent(in) :: negative_aliases(3)
      integer, intent(in) :: wi
      integer, intent(in) :: wj

      integer :: k

      total = 0.0_dp
      do k = 1,EDGE
         total = total + (block_restriction_edge_flux( &
              block,local_index,p,scalar_slot,level_slot, &
              edge_i(positive_aliases(k)), &
              edge_j(positive_aliases(k)), &
              edge_component(positive_aliases(k)),flux_start)- &
              block_restriction_edge_flux( &
              block,local_index,p,scalar_slot,level_slot, &
              edge_i(negative_aliases(k)), &
              edge_j(negative_aliases(k)), &
              edge_component(negative_aliases(k)),flux_start))* &
              block_scalar_record_value( &
              block,local_index,p,scalar_slot,level_slot,wi,wj, &
              BLOCK_SCALAR_RESTRICTION_WEIGHT_START+k-1)
      end do

    end function sum_edge_difference_weight_product

  end function interpolate_block_scalar_flux


  real(dp) function complete_block_coarse_flux ( &
       sm_flux,block,local_index,p,scalar_slot,level_slot, &
       i_par,j_par,i_chd,j_chd,e,cursor,roundoff_scale) result(value)

    implicit none

    real(dp), intent(in) :: sm_flux(4)
    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i_par
    integer, intent(in) :: j_par
    integer, intent(in) :: i_chd
    integer, intent(in) :: j_chd
    integer, intent(in) :: e
    type(Block_Scalar_Restriction_Cursor), intent(in) :: cursor
    real(dp), optional, intent(out) :: roundoff_scale

    integer :: i_edge
    integer :: j_edge
    real(dp) :: coarse_value
    real(dp) :: partial_value

    value = 0.0_dp
    if (present(roundoff_scale)) roundoff_scale = 0.0_dp
    i_edge = 0
    j_edge = 0
    select case (e)
    case (RT)
       i_edge = i_chd+1
       j_edge = j_chd
    case (DG)
       i_edge = i_chd+1
       j_edge = j_chd+1
    case (UP)
       i_edge = i_chd
       j_edge = j_chd+1
    case default
       call fail("scalar-restriction coarse edge is invalid")
    end select
    partial_value = partial_block_coarse_flux( &
         block,local_index,p,scalar_slot,level_slot,i_edge,j_edge,e, &
         cursor,BLOCK_SCALAR_DIRECT_FLUX_START)
    call validate_scalar_restriction_value( &
         "partial_block_coarse_flux",partial_value,cursor)
    coarse_value = block_coarse_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         i_par,j_par,i_edge,j_edge,e, &
         BLOCK_SCALAR_DIRECT_FLUX_START)
    call validate_scalar_restriction_value( &
         "block_coarse_flux",coarse_value,cursor)
    select case (e)
    case (RT)
       value = partial_value+coarse_value+sm_flux(1)+sm_flux(2)
       if (present(roundoff_scale)) then
          roundoff_scale = abs(partial_value)+abs(coarse_value)+ &
               abs(sm_flux(1))+abs(sm_flux(2))
       end if
    case (DG)
       value = partial_value+coarse_value+sm_flux(2)+sm_flux(3)
       if (present(roundoff_scale)) then
          roundoff_scale = abs(partial_value)+abs(coarse_value)+ &
               abs(sm_flux(2))+abs(sm_flux(3))
       end if
    case (UP)
       value = partial_value+coarse_value+sm_flux(3)+sm_flux(4)
       if (present(roundoff_scale)) then
          roundoff_scale = abs(partial_value)+abs(coarse_value)+ &
               abs(sm_flux(3))+abs(sm_flux(4))
       end if
    case default
       call fail("scalar-restriction coarse edge is invalid")
    end select

  end function complete_block_coarse_flux


  real(dp) function scalar_restriction_operation_scale ( &
       catalog_index,block,local_index,p,scalar_slot,level_slot, &
       i_par,j_par,e) result(operation_scale)
    ! Reconstruct the absolute term scale for a restricted edge whose
    ! independently evaluated final values differ. This is invoked only on
    ! the exceptional comparison path.

    implicit none

    integer, intent(in) :: catalog_index
    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i_par
    integer, intent(in) :: j_par
    integer, intent(in) :: e

    integer :: c
    integer :: child
    integer :: i_chd
    integer :: j_chd
    integer :: n_match

    real(dp) :: ignored_value
    real(dp) :: sm_flux(4)

    type(Block_Scalar_Restriction_Cursor) :: cursor

    child = -1
    i_chd = -1
    j_chd = -1
    n_match = 0
    do c = 1,N_CHDRN
       if (i_par < chd_offs(1,c) .or. &
            i_par >= chd_offs(1,c)+PATCH_SIZE/2 .or. &
            j_par < chd_offs(2,c) .or. &
            j_par >= chd_offs(2,c)+PATCH_SIZE/2) cycle
       child = block%patch(p)%children(c)
       i_chd = 2*(i_par-chd_offs(1,c))
       j_chd = 2*(j_par-chd_offs(2,c))
       n_match = n_match + 1
       cursor%child_index = c
    end do
    if (n_match /= 1 .or. child <= 0 .or. &
         child >= size(block%patch)) then
       call fail("scalar-restriction scale child is invalid")
    end if

    cursor%target_level = block%patch(p)%level
    cursor%catalog_index = catalog_index
    cursor%block_id = block%id
    cursor%parent_patch = p
    cursor%child_patch = child+1
    cursor%scalar_slot = scalar_slot
    cursor%level_slot = level_slot
    cursor%physical_level = block%field_level+level_slot-1
    cursor%i_parent = i_par
    cursor%j_parent = j_par
    cursor%i_child = i_chd
    cursor%j_child = j_chd
    cursor%edge = e

    if (max_parent_edge_mask( &
         block,local_index,p,scalar_slot,level_slot,i_par,j_par) >= &
         real(RESTRCT,dp)) then
       sm_flux = interpolate_block_scalar_flux( &
            block,local_index,child+1,scalar_slot,level_slot, &
            i_chd,j_chd,BLOCK_SCALAR_DIRECT_FLUX_START)
    else
       sm_flux = 0.0_dp
    end if
    ignored_value = complete_block_coarse_flux( &
         sm_flux,block,local_index,child+1,scalar_slot,level_slot, &
         i_par,j_par,i_chd,j_chd,e,cursor,operation_scale)
    call validate_scalar_restriction_value( &
         "scalar_restriction_operation_scale",ignored_value,cursor)

  end function scalar_restriction_operation_scale


  subroutine report_scalar_restriction_components ( &
       block,local_index,p,sm_flux,native_value,reference_value,cursor)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    real(dp), intent(in) :: sm_flux(4)
    real(dp), intent(in) :: native_value
    real(dp), intent(in) :: reference_value
    type(Block_Scalar_Restriction_Cursor), intent(in) :: cursor

    integer :: i_edge
    integer :: j_edge

    real(dp) :: native_coarse
    real(dp) :: native_partial
    real(dp) :: native_sm_pair
    real(dp) :: native_total
    real(dp) :: reference_coarse
    real(dp) :: reference_partial
    real(dp) :: reference_sm(4)
    real(dp) :: reference_sm_pair
    real(dp) :: reference_total

    i_edge = 0
    j_edge = 0
    native_sm_pair = 0.0_dp
    reference_sm_pair = 0.0_dp
    select case (cursor%edge)
    case (RT)
       i_edge = cursor%i_child+1
       j_edge = cursor%j_child
    case (DG)
       i_edge = cursor%i_child+1
       j_edge = cursor%j_child+1
    case (UP)
       i_edge = cursor%i_child
       j_edge = cursor%j_child+1
    case default
       call fail("scalar-restriction diagnostic edge is invalid")
    end select

    reference_sm = interpolate_block_scalar_flux( &
         block,local_index,p,cursor%scalar_slot,cursor%level_slot, &
         cursor%i_child,cursor%j_child, &
         BLOCK_SCALAR_RESTRICTED_FLUX_START)
    native_partial = partial_block_coarse_flux( &
         block,local_index,p,cursor%scalar_slot,cursor%level_slot, &
         i_edge,j_edge,cursor%edge,cursor, &
         BLOCK_SCALAR_DIRECT_FLUX_START)
    reference_partial = partial_block_coarse_flux( &
         block,local_index,p,cursor%scalar_slot,cursor%level_slot, &
         i_edge,j_edge,cursor%edge,cursor, &
         BLOCK_SCALAR_RESTRICTED_FLUX_START)
    native_coarse = block_coarse_flux( &
         block,local_index,p,cursor%scalar_slot,cursor%level_slot, &
         cursor%i_parent,cursor%j_parent,i_edge,j_edge,cursor%edge, &
         BLOCK_SCALAR_DIRECT_FLUX_START)
    reference_coarse = block_coarse_flux( &
         block,local_index,p,cursor%scalar_slot,cursor%level_slot, &
         cursor%i_parent,cursor%j_parent,i_edge,j_edge,cursor%edge, &
         BLOCK_SCALAR_RESTRICTED_FLUX_START)

    select case (cursor%edge)
    case (RT)
       native_sm_pair = sm_flux(1)+sm_flux(2)
       reference_sm_pair = reference_sm(1)+reference_sm(2)
    case (DG)
       native_sm_pair = sm_flux(2)+sm_flux(3)
       reference_sm_pair = reference_sm(2)+reference_sm(3)
    case (UP)
       native_sm_pair = sm_flux(3)+sm_flux(4)
       reference_sm_pair = reference_sm(3)+reference_sm(4)
    case default
       call fail("scalar-restriction diagnostic edge is invalid")
    end select
    native_total = native_partial+native_coarse+native_sm_pair
    reference_total = &
         reference_partial+reference_coarse+reference_sm_pair

    call report_scalar_restriction_cursor( &
         "restricted scalar-flux component mismatch",cursor)
    write(error_unit,'(a,4(es24.16,1x))') &
         "  native sm_flux = ",sm_flux
    write(error_unit,'(a,4(es24.16,1x))') &
         "  reference sm_flux = ",reference_sm
    write(error_unit,'(a,3(es24.16,1x))') &
         "  native partial, coarse, sm pair = ", &
         native_partial,native_coarse,native_sm_pair
    write(error_unit,'(a,3(es24.16,1x))') &
         "  reference partial, coarse, sm pair = ", &
         reference_partial,reference_coarse,reference_sm_pair
    write(error_unit,'(a,3(es24.16,1x))') &
         "  component differences = ", &
         native_partial-reference_partial, &
         native_coarse-reference_coarse, &
         native_sm_pair-reference_sm_pair
    write(error_unit,'(a,2(es24.16,1x))') &
         "  recomputed native, reference totals = ", &
         native_total,reference_total
    write(error_unit,'(a,3(es24.16,1x))') &
         "  stored native, reference, difference = ", &
         native_value,reference_value,native_value-reference_value
    write(error_unit,'(a,es24.16)') &
         "  reference reconstruction difference = ", &
         reference_total-reference_value
    flush(error_unit)

  end subroutine report_scalar_restriction_components


  real(dp) function partial_block_coarse_flux ( &
       block,local_index,p,scalar_slot,level_slot,i,j,e,cursor, &
       flux_start) result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: e
    type(Block_Scalar_Restriction_Cursor), intent(in) :: cursor
    integer, intent(in) :: flux_start

    integer :: edge_component(0:19)
    integer :: edge_i(0:19)
    integer :: edge_j(0:19)
    integer :: scalar_i(0:19)
    integer :: scalar_j(0:19)

    real(dp) :: area(2)
    real(dp) :: area_input(2)
    real(dp) :: area_sum
    real(dp) :: ol_area(4)
    real(dp) :: ol_area_input(4)
    real(dp) :: ol_area_terms(6)

    call get_block_restriction_indices( &
         i,j,e,edge_i,edge_j,edge_component,scalar_i,scalar_j)
    area = [block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i,j,1), &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i,j,2)]
    ol_area(1:2) = [block_overlap_split( &
         block,local_index,p,scalar_slot,level_slot,i,j,1), &
         block_overlap_split( &
         block,local_index,p,scalar_slot,level_slot,i,j,2)]
    ol_area(3:4) = [block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i,j,3), &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i,j,4)]
    area_input = area
    ol_area_input = ol_area
    if (.not. all(ieee_is_finite(area_input)) .or. &
         .not. all(ieee_is_finite(ol_area_input))) then
       call report_scalar_restriction_cursor( &
            "non-finite partial coarse-flux input",cursor)
       write(error_unit,'(a,2(es24.16,1x))') &
            "  area input = ",area_input
       write(error_unit,'(a,4(es24.16,1x))') &
            "  overlap-area input = ",ol_area_input
       flush(error_unit)
       call fail("partial coarse-flux input is non-finite")
    end if
    ol_area(3:4) = ol_area(3:4)-ol_area(1:2)
    area(1) = area(1)+ol_area(1)+ol_area(4)
    area(2) = area(2)+ol_area(2)+ol_area(3)
    area_sum = sum(area)
    if (.not. all(ieee_is_finite(area)) .or. &
         .not. all(ieee_is_finite(ol_area)) .or. &
         .not. ieee_is_finite(area_sum) .or. &
         .not. (abs(area_sum) > 0.0_dp)) then
       call report_scalar_restriction_cursor( &
            "invalid partial coarse-flux normalization",cursor)
       write(error_unit,'(a,2(es24.16,1x))') &
            "  area = ",area
       write(error_unit,'(a,4(es24.16,1x))') &
            "  overlap area = ",ol_area
       write(error_unit,'(a,es24.16)') &
            "  area sum = ",area_sum
       flush(error_unit)
       call fail("partial coarse-flux normalization is invalid")
    end if
    area = area/area_sum

    ol_area_terms(1) = block_overlap_split( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(PP),scalar_j(PP),1)
    ol_area_terms(2) = block_overlap_split( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(MM),scalar_j(MM),2)
    ol_area_terms(3) = block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(MP),scalar_j(MP),3)
    ol_area_terms(4) = block_overlap_split( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(MP),scalar_j(MP),1)
    ol_area_terms(5) = block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(PM),scalar_j(PM),4)
    ol_area_terms(6) = block_overlap_split( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(PM),scalar_j(PM),2)
    if (.not. all(ieee_is_finite(ol_area_terms))) then
       call report_scalar_restriction_cursor( &
            "non-finite partial coarse-flux overlap input",cursor)
       write(error_unit,'(a,6(es24.16,1x))') &
            "  overlap-area terms = ",ol_area_terms
       flush(error_unit)
       call fail("partial coarse-flux overlap input is non-finite")
    end if
    ol_area = [ol_area_terms(1),ol_area_terms(2), &
         ol_area_terms(3)-ol_area_terms(4), &
         ol_area_terms(5)-ol_area_terms(6)]
    if (.not. all(ieee_is_finite(ol_area))) then
       call report_scalar_restriction_cursor( &
            "non-finite partial coarse-flux overlap result",cursor)
       write(error_unit,'(a,4(es24.16,1x))') &
            "  overlap area = ",ol_area
       flush(error_unit)
       call fail("partial coarse-flux overlap result is non-finite")
    end if

    value = (block_restriction_edge_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         edge_i(UPZ),edge_j(UPZ),edge_component(UPZ), &
         flux_start)*area(1) + &
         block_restriction_edge_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         edge_i(UMZ),edge_j(UMZ),edge_component(UMZ), &
         flux_start)*area(2)) - &
         (block_restriction_edge_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         edge_i(VMM),edge_j(VMM),edge_component(VMM),flux_start) + &
         block_restriction_edge_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         edge_i(WMP),edge_j(WMP),edge_component(WMP), &
         flux_start))*area(2) - &
         (block_restriction_edge_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         edge_i(WPM),edge_j(WPM),edge_component(WPM),flux_start) + &
         block_restriction_edge_flux( &
         block,local_index,p,scalar_slot,level_slot, &
         edge_i(VPP),edge_j(VPP),edge_component(VPP), &
         flux_start))*area(1) + &
         ol_area(3)*block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(MP),scalar_j(MP),flux_start) - &
         ol_area(4)*block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(PM),scalar_j(PM),flux_start) - &
         ol_area(1)*block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(PP),scalar_j(PP),flux_start) + &
         ol_area(2)*block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot, &
         scalar_i(MM),scalar_j(MM),flux_start)

  end function partial_block_coarse_flux


  real(dp) function block_coarse_flux ( &
       block,local_index,p,scalar_slot,level_slot, &
       i_par,j_par,i,j,e,flux_start) result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i_par
    integer, intent(in) :: j_par
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: e
    integer, intent(in) :: flux_start

    integer :: i_mm
    integer :: i_mm2
    integer :: i_mp
    integer :: i_mp2
    integer :: i_mz
    integer :: i_pm
    integer :: i_pm2
    integer :: i_pp
    integer :: i_pp2
    integer :: i_pz
    integer :: j_mm
    integer :: j_mm2
    integer :: j_mp
    integer :: j_mp2
    integer :: j_mz
    integer :: j_pm
    integer :: j_pm2
    integer :: j_pp
    integer :: j_pp2
    integer :: j_pz

    real(dp) :: coefficient

    if (i_par < 0 .or. j_par < 0) then
       call fail("scalar-restriction parent coordinate is invalid")
    end if
    i_mz = i+nghb_pt(1,hex_s_offs(e+1)+2)
    j_mz = j+nghb_pt(2,hex_s_offs(e+1)+2)
    i_pz = i+nghb_pt(1,hex_s_offs(e+1)+5)
    j_pz = j+nghb_pt(2,hex_s_offs(e+1)+5)
    i_mp = i+nghb_pt(1,hex_s_offs(e+1)+1)
    j_mp = j+nghb_pt(2,hex_s_offs(e+1)+1)
    i_pp = i+nghb_pt(1,hex_s_offs(e+1)+6)
    j_pp = j+nghb_pt(2,hex_s_offs(e+1)+6)
    i_pm = i+nghb_pt(1,hex_s_offs(e+1)+4)
    j_pm = j+nghb_pt(2,hex_s_offs(e+1)+4)
    i_mm = i+nghb_pt(1,hex_s_offs(e+1)+3)
    j_mm = j+nghb_pt(2,hex_s_offs(e+1)+3)
    i_mm2 = i+bfly_no2(1,1,e+1)
    j_mm2 = j+bfly_no2(2,1,e+1)
    i_pm2 = i+bfly_no2(1,2,e+1)
    j_pm2 = j+bfly_no2(2,2,e+1)
    i_pp2 = i+bfly_no2(1,3,e+1)
    j_pp2 = j+bfly_no2(2,3,e+1)
    i_mp2 = i+bfly_no2(1,4,e+1)
    j_mp2 = j+bfly_no2(2,4,e+1)

    coefficient = block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i,j,1)* &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i,j,2)* &
         block_area_value( &
         block,local_index,p,scalar_slot,level_slot,i,j) + &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_mp,j_mp,2)* &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_mp,j_mp,3)* &
         block_area_value( &
         block,local_index,p,scalar_slot,level_slot,i_mp,j_mp) + &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_pp,j_pp,1)* &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_pp,j_pp,3)* &
         block_area_value( &
         block,local_index,p,scalar_slot,level_slot,i_pp,j_pp) + &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_pm,j_pm,1)* &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_pm,j_pm,4)* &
         block_area_value( &
         block,local_index,p,scalar_slot,level_slot,i_pm,j_pm) + &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_mm,j_mm,2)* &
         block_overlap_value( &
         block,local_index,p,scalar_slot,level_slot,i_mm,j_mm,4)* &
         block_area_value( &
         block,local_index,p,scalar_slot,level_slot,i_mm,j_mm)
    value = coefficient*(block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_pz,j_pz, &
         flux_start)- &
         block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_mz,j_mz, &
         flux_start))
    value = value + 0.5_dp*overlap_area_product( &
         i_pp,j_pp,3,4)*(block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_pp2,j_pp2, &
         flux_start)- &
         block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_mz,j_mz, &
         flux_start))
    value = value + 0.5_dp*overlap_area_product( &
         i_pm,j_pm,3,4)*(block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_pm2,j_pm2, &
         flux_start)- &
         block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_mz,j_mz, &
         flux_start))
    value = value + 0.5_dp*overlap_area_product( &
         i_mp,j_mp,3,4)*(block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_pz,j_pz, &
         flux_start)- &
         block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_mp2,j_mp2, &
         flux_start))
    value = value + 0.5_dp*overlap_area_product( &
         i_mm,j_mm,3,4)*(block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_pz,j_pz, &
         flux_start)- &
         block_restriction_dscalar( &
         block,local_index,p,scalar_slot,level_slot,i_mm2,j_mm2, &
         flux_start))

  contains

    real(dp) function overlap_area_product ( &
         oi,oj,first_component,second_component) result(product)

      implicit none

      integer, intent(in) :: oi
      integer, intent(in) :: oj
      integer, intent(in) :: first_component
      integer, intent(in) :: second_component

      product = block_overlap_value( &
           block,local_index,p,scalar_slot,level_slot,oi,oj, &
           first_component)*block_overlap_value( &
           block,local_index,p,scalar_slot,level_slot,oi,oj, &
           second_component)*block_area_value( &
           block,local_index,p,scalar_slot,level_slot,oi,oj)

    end function overlap_area_product

  end function block_coarse_flux


  subroutine validate_scalar_restriction_vector (name,value,cursor)

    implicit none

    character(*), intent(in) :: name
    real(dp), intent(in) :: value(:)
    type(Block_Scalar_Restriction_Cursor), intent(in) :: cursor

    if (all(ieee_is_finite(value))) return
    call report_scalar_restriction_cursor( &
         "non-finite "//trim(name)//" result",cursor)
    write(error_unit,'(a,*(es24.16,1x))') "  result = ",value
    flush(error_unit)
    call fail(trim(name)//" returned a non-finite value")

  end subroutine validate_scalar_restriction_vector


  subroutine validate_scalar_restriction_value (name,value,cursor)

    implicit none

    character(*), intent(in) :: name
    real(dp), intent(in) :: value
    type(Block_Scalar_Restriction_Cursor), intent(in) :: cursor

    if (ieee_is_finite(value)) return
    call report_scalar_restriction_cursor( &
         "non-finite "//trim(name)//" result",cursor)
    write(error_unit,'(a,es24.16)') "  result = ",value
    flush(error_unit)
    call fail(trim(name)//" returned a non-finite value")

  end subroutine validate_scalar_restriction_value


  subroutine report_scalar_restriction_cursor (message,cursor)

    implicit none

    character(*), intent(in) :: message
    type(Block_Scalar_Restriction_Cursor), intent(in) :: cursor

    write(error_unit,'(/,a,i0,2a)') &
         "Rank ",rank,": ",trim(message)
    write(error_unit,'(a,i0,a,i0,a,i0)') &
         "  target level = ",cursor%target_level, &
         ", catalog block = ",cursor%catalog_index, &
         ", block id = ",cursor%block_id
    write(error_unit,'(a,i0,a,i0,a,i0)') &
         "  parent patch = ",cursor%parent_patch, &
         ", child = ",cursor%child_index, &
         ", child patch = ",cursor%child_patch
    write(error_unit,'(a,i0,a,i0,a,i0)') &
         "  scalar slot = ",cursor%scalar_slot, &
         ", field-level slot = ",cursor%level_slot, &
         ", physical level = ",cursor%physical_level
    write(error_unit,'(a,i0,a,i0,a,i0,a,i0,a,i0)') &
         "  parent coordinates = ",cursor%i_parent,", ",cursor%j_parent, &
         "; child coordinates = ",cursor%i_child,", ",cursor%j_child, &
         "; edge = ",cursor%edge
    flush(error_unit)

  end subroutine report_scalar_restriction_cursor


  real(dp) function block_restriction_dscalar ( &
       block,local_index,p,scalar_slot,level_slot,i,j,flux_start) &
       result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: flux_start

    integer :: boundary_index
    integer :: cache_index
    integer :: cache_slot
    integer :: field_sample
    integer :: node
    integer :: owner_class
    integer :: owner_pos
    integer :: record
    integer :: source_node
    integer :: storage_class

    logical :: final_route
    logical :: validate_oracle

    real(dp) :: candidate_value
    real(dp) :: cache_value
    real(dp) :: comparison_tolerance
    real(dp) :: operation_scale
    real(dp) :: reference_value
    real(dp) :: route_value
    real(dp) :: transported_value

    if (flux_start /= BLOCK_SCALAR_DIRECT_FLUX_START .and. &
         flux_start /= BLOCK_SCALAR_RESTRICTED_FLUX_START) then
       call fail("scalar-restriction dscalar mode is invalid")
    end if
    value = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot,i,j, &
         BLOCK_SCALAR_NATIVE_DSCALAR_INDEX, &
         flux_start == BLOCK_SCALAR_DIRECT_FLUX_START)
    transported_value = value
    if (flux_start == BLOCK_SCALAR_DIRECT_FLUX_START .and. &
         value < -BLOCK_RESTRICTION_VALUE_LIMIT) then
       value = block_scalar_flux_divergence( &
            block,local_index,p,scalar_slot,level_slot,i,j, &
            BLOCK_SCALAR_DIRECT_FLUX_START)
    end if

    ! Stage 166B is observational only. At direct-flux physical-boundary
    ! consumptions, reconstruct dscalar from the compact flux stencil and
    ! classify agreement with the authoritative Domain value. Never replace
    ! the returned production value here.
    validate_oracle = block_dynamics_validation_enabled()
    if (validate_oracle .and. &
         flux_start == BLOCK_SCALAR_DIRECT_FLUX_START) then
       call locate_block_scalar_record( &
            block,local_index,p,i,j,storage_class,record,node)
       if (storage_class == STORE_BDRY) then
          if (local_index < 1 .or. local_index+1 > size( &
               block_scalar_restriction_exchange% &
               boundary_source_displ) .or. record < 1 .or. &
               record > size(block%bdry_storage)) then
             call fail("boundary dscalar owner lookup is invalid")
          end if
          source_node = node-block%bdry_storage(record)%local_start
          if (source_node < 0 .or. &
               source_node >= block%bdry_storage(record)%n_node) then
             call fail("boundary dscalar owner node is invalid")
          end if
          owner_pos = block_scalar_restriction_exchange% &
               boundary_source_displ(local_index)+1
          do boundary_index = 1,record-1
             owner_pos = owner_pos + &
                  block%bdry_storage(boundary_index)%n_node
          end do
          owner_pos = owner_pos+source_node
          if (owner_pos < 1 .or. owner_pos >= &
               block_scalar_restriction_exchange% &
               boundary_source_displ(local_index+1)+1 .or. &
               block_scalar_restriction_exchange% &
               boundary_source_domain(owner_pos) /= block%root_domain .or. &
               block_scalar_restriction_exchange% &
               boundary_source_record(owner_pos) /= &
               block%bdry_storage(record)%source_bdry .or. &
               block_scalar_restriction_exchange% &
               boundary_source_node(owner_pos) /= source_node) then
             call fail("boundary dscalar owner provenance differs")
          end if
          owner_class = block_scalar_restriction_exchange% &
               boundary_source_owner_class(owner_pos)
          if (owner_class < 1 .or. &
               owner_class > BLOCK_BOUNDARY_OWNER_CLASS_COUNT) then
             call fail("boundary dscalar owner class is invalid")
          end if
          reference_value = block_scalar_record_value( &
               block,local_index,p,scalar_slot,level_slot,i,j, &
               BLOCK_SCALAR_REFERENCE_DSCALAR_INDEX)
          block_scalar_boundary_cache_shadow_count(1) = &
               block_scalar_boundary_cache_shadow_count(1)+1_int64
          cache_slot = block_scalar_boundary_cache_slot(owner_pos)
          if (cache_slot >= 0) then
             ! Kernel scalar_slot is zero-based; capture scalar_slot is
             ! one-based before both are flattened into the same field order.
             field_sample = scalar_slot*block%n_field_level + &
                  level_slot
             if (field_sample < 1 .or. field_sample > &
                  block_scalar_boundary_cache_field_count .or. &
                  cache_slot >= block_scalar_boundary_cache_count) then
                call fail("boundary dscalar cache address is invalid")
             end if
             cache_index = (field_sample-1)* &
                  block_scalar_boundary_cache_count+cache_slot+1
             if (.not. block_scalar_boundary_cache_covered(cache_index)) then
                call fail("boundary dscalar cache value is unavailable")
             end if
             cache_value = block_scalar_boundary_cache_value(cache_index)
             comparison_tolerance = &
                  scalar_restriction_roundoff_tolerance( &
                  cache_value,reference_value,1)
             if (abs(cache_value-reference_value) <= &
                  comparison_tolerance) then
                block_scalar_boundary_cache_shadow_count(2) = &
                     block_scalar_boundary_cache_shadow_count(2)+1_int64
             else
                block_scalar_boundary_cache_shadow_count(3) = &
                     block_scalar_boundary_cache_shadow_count(3)+1_int64
             end if
          else if (cache_slot == -1 .or. cache_slot == -2) then
             block_scalar_boundary_cache_shadow_count(4) = &
                  block_scalar_boundary_cache_shadow_count(4)+1_int64
          else
             call fail("boundary dscalar cache slot is invalid")
          end if
          candidate_value = block_scalar_flux_divergence( &
               block,local_index,p,scalar_slot,level_slot,i,j, &
               BLOCK_SCALAR_DIRECT_FLUX_START, &
               operation_scale=operation_scale)
          final_route = cache_slot >= 0
          if (final_route) then
             final_route = cache_slot < &
                  block_scalar_boundary_final_plan%cache_count
             if (final_route) final_route = &
                  block_scalar_boundary_final_plan% &
                  cache_rank(cache_slot+1) >= 0 .and. &
                  block_scalar_boundary_final_plan% &
                  cache_level(cache_slot+1) > level_start
          end if
          if (final_route) then
             route_value = block_scalar_boundary_final_plan% &
                  value(cache_index)
             block_scalar_boundary_final_shadow_count(1) = &
                  block_scalar_boundary_final_shadow_count(1)+1_int64
             if (abs(transported_value) <= &
                  BLOCK_RESTRICTION_VALUE_LIMIT .and. &
                  abs(transported_value-route_value) <= 0.0_dp) then
                block_scalar_boundary_final_shadow_count(2) = &
                     block_scalar_boundary_final_shadow_count(2)+1_int64
             else
                block_scalar_boundary_final_shadow_count(3) = &
                     block_scalar_boundary_final_shadow_count(3)+1_int64
                write(error_unit,'(a,i0,a,i0,a,i0,a,i0)') &
                     "Rank ",rank, &
                     ": final-owner boundary dscalar mismatch: block = ", &
                     local_block_catalog(local_index), &
                     ", boundary node = ",source_node, &
                     ", field sample = ",field_sample
                write(error_unit,'(a,3(es24.16,1x))') &
                     "  transported, route-cache, difference = ", &
                     transported_value,route_value, &
                     abs(transported_value-route_value)
                flush(error_unit)
                call fail("final-owner boundary dscalar differs")
             end if
          end if
          comparison_tolerance = scalar_restriction_roundoff_tolerance( &
               candidate_value,reference_value,1,operation_scale)
          block_scalar_boundary_shadow_count(1) = &
               block_scalar_boundary_shadow_count(1)+1_int64
          block_scalar_boundary_owner_shadow_count(1,owner_class) = &
               block_scalar_boundary_owner_shadow_count(1,owner_class) + &
               1_int64
          if (abs(candidate_value-reference_value) <= &
               comparison_tolerance) then
             block_scalar_boundary_shadow_count(2) = &
                  block_scalar_boundary_shadow_count(2)+1_int64
             block_scalar_boundary_owner_shadow_count(2,owner_class) = &
                  block_scalar_boundary_owner_shadow_count( &
                  2,owner_class)+1_int64
          else
             block_scalar_boundary_shadow_count(4) = &
                  block_scalar_boundary_shadow_count(4)+1_int64
             block_scalar_boundary_owner_shadow_count(3,owner_class) = &
                  block_scalar_boundary_owner_shadow_count( &
                  3,owner_class)+1_int64
          end if
          if (abs(reference_value) < tiny(1.0_dp)) then
             block_scalar_boundary_shadow_count(3) = &
                  block_scalar_boundary_shadow_count(3)+1_int64
          end if
       end if
    end if

  end function block_restriction_dscalar


  real(dp) function block_restriction_edge_flux ( &
       block,local_index,p,scalar_slot,level_slot,i,j,e,flux_start) &
       result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: e
    integer, intent(in) :: flux_start

    if (e < RT .or. e > UP) then
       call fail("scalar-restriction edge component is invalid")
    end if
    value = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot,i,j, &
         flux_start+e)

  end function block_restriction_edge_flux


  real(dp) function block_area_value ( &
       block,local_index,p,scalar_slot,level_slot,i,j) result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j

    value = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot,i,j, &
         BLOCK_SCALAR_AREA_INDEX)

  end function block_area_value


  real(dp) function block_overlap_value ( &
       block,local_index,p,scalar_slot,level_slot,i,j,component) &
       result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: component

    if (component < 1 .or. component > 4) then
       call fail("scalar-restriction overlap component is invalid")
    end if
    value = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot,i,j, &
         BLOCK_SCALAR_OVERLAP_START+component-1)

  end function block_overlap_value


  real(dp) function block_overlap_split ( &
       block,local_index,p,scalar_slot,level_slot,i,j,component) &
       result(value)

    implicit none

    type(Block_Data), intent(in) :: block
    integer, intent(in) :: local_index
    integer, intent(in) :: p
    integer, intent(in) :: scalar_slot
    integer, intent(in) :: level_slot
    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: component

    if (component < 1 .or. component > 2) then
       call fail("scalar-restriction split component is invalid")
    end if
    value = block_scalar_record_value( &
         block,local_index,p,scalar_slot,level_slot,i,j, &
         BLOCK_SCALAR_OVERLAP_START+3+component)

  end function block_overlap_split


  subroutine get_block_restriction_indices ( &
       i,j,e,edge_i,edge_j,edge_component,scalar_i,scalar_j)

    implicit none

    integer, intent(in) :: i
    integer, intent(in) :: j
    integer, intent(in) :: e
    integer, intent(out) :: edge_i(0:19)
    integer, intent(out) :: edge_j(0:19)
    integer, intent(out) :: edge_component(0:19)
    integer, intent(out) :: scalar_i(0:19)
    integer, intent(out) :: scalar_j(0:19)

    integer :: i_mm
    integer :: i_mp
    integer :: i_pm
    integer :: i_pp
    integer :: j_mm
    integer :: j_mp
    integer :: j_pm
    integer :: j_pp

    edge_i = 0
    edge_j = 0
    edge_component = 0
    scalar_i = 0
    scalar_j = 0
    call set_edge(UMZ,i,j,hex_s_offs(e+1)+2)
    call set_edge(UPZ,i,j,hex_s_offs(e+1)+5)
    call set_edge(WMP,i,j,hex_s_offs(e+1)+1)
    call set_edge(VPP,i,j,hex_s_offs(e+1)+6)
    call set_edge(WPM,i,j,hex_s_offs(e+1)+4)
    call set_edge(VMM,i,j,hex_s_offs(e+1)+3)

    i_mp = i+nghb_pt(1,hex_s_offs(e+1)+1)
    j_mp = j+nghb_pt(2,hex_s_offs(e+1)+1)
    i_pp = i+nghb_pt(1,hex_s_offs(e+1)+6)
    j_pp = j+nghb_pt(2,hex_s_offs(e+1)+6)
    i_pm = i+nghb_pt(1,hex_s_offs(e+1)+4)
    j_pm = j+nghb_pt(2,hex_s_offs(e+1)+4)
    i_mm = i+nghb_pt(1,hex_s_offs(e+1)+3)
    j_mm = j+nghb_pt(2,hex_s_offs(e+1)+3)
    scalar_i(MP) = i_mp
    scalar_j(MP) = j_mp
    scalar_i(PP) = i_pp
    scalar_j(PP) = j_pp
    scalar_i(PM) = i_pm
    scalar_j(PM) = j_pm
    scalar_i(MM) = i_mm
    scalar_j(MM) = j_mm

    call set_edge(VMP,i_mp,j_mp,hex_s_offs(e+1)+3)
    call set_edge(VMPP,i_mp,j_mp,hex_s_offs(e+1)+6)
    call set_edge(UZP,i_mp,j_mp,hex_s_offs(e+1)+5)
    call set_edge(WPPP,i_pp,j_pp,hex_s_offs(e+1)+1)
    call set_edge(WPP,i_pp,j_pp,hex_s_offs(e+1)+4)
    call set_edge(VPM,i_pm,j_pm,hex_s_offs(e+1)+6)
    call set_edge(VPMM,i_pm,j_pm,hex_s_offs(e+1)+3)
    call set_edge(UZM,i_pm,j_pm,hex_s_offs(e+1)+2)
    call set_edge(WMMM,i_mm,j_mm,hex_s_offs(e+1)+4)
    call set_edge(WMM,i_mm,j_mm,hex_s_offs(e+1)+1)

  contains

    subroutine set_edge (alias,base_i,base_j,side_index)

      implicit none

      integer, intent(in) :: alias
      integer, intent(in) :: base_i
      integer, intent(in) :: base_j
      integer, intent(in) :: side_index

      if (alias < 0 .or. alias > 19 .or. &
           side_index < 1 .or. side_index > size(hex_sides,2)) then
         call fail("scalar-restriction edge alias is invalid")
      end if
      edge_i(alias) = base_i+hex_sides(1,side_index)
      edge_j(alias) = base_j+hex_sides(2,side_index)
      edge_component(alias) = hex_sides(3,side_index)

    end subroutine set_edge

  end subroutine get_block_restriction_indices


  subroutine complete_uncaptured_scalar_divergence_coverage
      ! Complete only records outside the horizontal/vertical levels visited
      ! by trend_ml. Where an authoritative Domain tendency exists, it must
      ! remain exactly zero. Missing production coverage is still an error.

      implicit none

      integer :: b
      integer :: d
      integer :: first_field_level
      integer :: local_index
      integer :: mult_scalar
      integer :: mult_vector
      integer :: n_field_level
      integer :: n_scalar_variable
      integer :: patch_index
      integer :: r
      integer :: sample_start
      integer :: slot
      integer :: v_scalar
      integer :: v_vector

      call get_block_field_layout( &
           v_scalar,n_scalar_variable,v_vector,first_field_level, &
           n_field_level,mult_scalar,mult_vector)
      if (mult_scalar /= 1 .or. mult_vector /= EDGE .or. &
           n_scalar_variable < 1 .or. n_field_level < 1 .or. &
           v_scalar < 1 .or. v_vector < 1) then
         call fail("uncaptured scalar-divergence layout is invalid")
      end if

      do local_index = 1,n_local_blocks()
         b = local_block_catalog(local_index)
         if (source_rank(b) /= rank) cycle
         d = loc_id(block_catalog(b)%root_domain+1) + 1
         if (d < 1 .or. d > size(grid)) then
            call fail("uncaptured scalar-divergence Domain is invalid")
         end if
         patch_index = 0
         call complete_subtree( &
              d,block_catalog(b)%root_patch,patch_index,1,local_index)
         if (patch_index /= local_block_patch_count(b)) then
            call fail( &
                 "uncaptured scalar-divergence traversal is incomplete")
         end if
      end do

      do r = 1,n_process
         sample_start = block_writeback_plan%scalar_recv_displ(r) + 1
         do slot = block_writeback_plan%recv_displ(r)+1, &
              block_writeback_plan%recv_displ(r) + &
              block_writeback_plan%recv_count(r)
            b = block_writeback_plan%recv_block(slot)
            if (source_rank(b) /= rank) then
               call fail( &
                    "uncaptured scalar-divergence source is invalid")
            end if
            d = loc_id(block_catalog(b)%root_domain+1) + 1
            if (d < 1 .or. d > size(grid)) then
               call fail( &
                    "remote uncaptured scalar-divergence Domain is invalid")
            end if
            patch_index = 0
            call complete_subtree( &
                 d,block_catalog(b)%root_patch,patch_index, &
                 sample_start,0)
            if (patch_index /= &
                 block_writeback_plan%recv_patch_count(slot)) then
               call fail( &
                    "remote uncaptured scalar-divergence traversal is incomplete")
            end if
            sample_start = sample_start + &
                 block_writeback_plan%recv_scalar_nvalue(slot)
         end do
      end do

    contains

      recursive subroutine complete_subtree ( &
           d,p,patch_index,block_sample_start,storage_index)

        implicit none

        integer, intent(in) :: d
        integer, intent(in) :: p
        integer, intent(inout) :: patch_index
        integer, intent(in) :: block_sample_start
        integer, intent(in) :: storage_index

        integer :: c
        integer :: child

        if (p < 0 .or. p >= grid(d)%patch%length) then
           call fail("uncaptured scalar-divergence patch is invalid")
        end if
        if (grid(d)%patch%elts(p+1)%deleted) return

        call complete_patch( &
             d,p,patch_index,block_sample_start,storage_index)
        patch_index = patch_index + 1

        do c = 1,N_CHDRN
           child = grid(d)%patch%elts(p+1)%children(c)
           if (child <= 0) cycle
           call complete_subtree( &
                d,child,patch_index,block_sample_start,storage_index)
        end do

      end subroutine complete_subtree


      subroutine complete_patch ( &
           d,p,patch_index,block_sample_start,storage_index)

        implicit none

        integer, intent(in) :: d
        integer, intent(in) :: p
        integer, intent(in) :: patch_index
        integer, intent(in) :: block_sample_start
        integer, intent(in) :: storage_index

        integer :: data_start
        integer :: field_level
        integer :: level_slot
        integer :: node
        integer :: q
        integer :: sample
        integer :: scalar_id
        integer :: scalar_slot

        logical :: horizontal_integrated
        logical :: physical_level

        horizontal_integrated = &
             grid(d)%patch%elts(p+1)%level >= level_start .and. &
             grid(d)%patch%elts(p+1)%level <= level_end

        do scalar_slot = 1,n_scalar_variable
           scalar_id = v_scalar + scalar_slot - 1
           do level_slot = 1,n_field_level
              field_level = first_field_level + level_slot - 1
              physical_level = &
                   field_level >= 1 .and. field_level <= zlevels
              if (horizontal_integrated .and. physical_level) cycle
              do q = 0,PATCH_SIZE**2-1
                 node = grid(d)%patch%elts(p+1)%elts_start + q
                 if (physical_level) then
                    if (node < 0 .or. node >= &
                         size(trend(scalar_id,field_level)%data(d)%elts)) &
                         then
                       call fail( &
                            "nonintegrated scalar tendency extent is invalid")
                    end if
                    if (abs(trend(scalar_id,field_level)% &
                         data(d)%elts(node+1)) > 0.0_dp) then
                       call fail( &
                            "nonintegrated scalar tendency is not zero")
                    end if
                 end if
                 sample = block_sample_start + &
                      patch_index* &
                      block_writeback_plan%scalar_patch_nvalue + &
                      ((scalar_slot-1)*n_field_level + level_slot-1)* &
                      PATCH_SIZE**2 + q
                 data_start = BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT* &
                      (sample-1) + 1
                 if (storage_index > 0) then
                    if (sample < 1 .or. sample > &
                         size(block_scalar_tendency(storage_index)% &
                         covered)) then
                       call fail( &
                            "retained nonintegrated scalar index is invalid")
                    end if
                    block_scalar_tendency(storage_index)%patch( &
                         data_start:data_start+ &
                         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = 0.0_dp
                    block_scalar_tendency(storage_index)% &
                         covered(sample) = .true.
                 else
                    if (sample < 1 .or. sample > &
                         size(block_scalar_divergence_plan%recv_covered)) &
                         then
                       call fail( &
                            "remote nonintegrated scalar index is invalid")
                    end if
                    block_scalar_divergence_plan%recv_buffer( &
                         data_start:data_start+ &
                         BLOCK_SCALAR_DIVERGENCE_INPUT_COUNT-1) = 0.0_dp
                    block_scalar_divergence_plan% &
                         recv_covered(sample) = .true.
                 end if
              end do
           end do
        end do

      end subroutine complete_patch

  end subroutine complete_uncaptured_scalar_divergence_coverage




  subroutine evaluate_candidate_block_exner_shadow ( &
       domain_sol,payload_family,thermodynamic_product,metric_division, &
       velocity_recomposition,checkpoint_required, &
       complete_physical_recomposition,retain_stage_tendency)
    ! Reconstruct an Exner-gradient numerator from complete provisional
    ! block columns and compare every patch independently. Diagnostic products
    ! are discarded; a complete physical tendency may be retained explicitly.

    implicit none

    type(Float_Field), intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    integer, intent(in) :: payload_family
    logical, intent(in) :: thermodynamic_product
    logical, intent(in) :: metric_division
    logical, optional, intent(in) :: velocity_recomposition
    logical, optional, intent(in) :: checkpoint_required
    logical, optional, intent(in) :: complete_physical_recomposition
    logical, optional, intent(in) :: retain_stage_tendency

    integer :: b
    integer :: first_field_level
    integer :: ierr
    integer :: local_index
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_physical_level
    integer :: n_scalar_variable
    integer :: physical_first
    integer :: physical_last
    integer :: v_scalar
    integer :: v_vector

    integer(int64) :: allocation_before
    integer(int64) :: count_global(3)
    integer(int64) :: count_local(3)
    integer(int64) :: execution_before
    integer(int64) :: expected_patch_count
    integer(int64) :: expected_sample_count
    integer(int64) :: field_count(2)
    integer(int64) :: field_count_after(2)
    integer(int64) :: hydrostatic_refresh_before
    integer(int64) :: production_writeback_before
    integer(int64) :: validated_patch_count
    integer(int64) :: writeback_allocation_before

    real(dp) :: field_moment(3,2)
    real(dp) :: field_moment_after(3,2)

    logical :: accumulator_ready
    logical :: checkpoint_ready
    logical :: tendency_ready
    logical :: trial_active
    logical :: recompose_velocity
    logical :: recompose_physical
    logical :: require_checkpoint
    logical :: retain_tendency
    logical :: validate_oracle

    type(Block_Exner_Difference_Kernel_Context) :: kernel

    recompose_velocity = .false.
    if (present(velocity_recomposition)) then
       recompose_velocity = velocity_recomposition
    end if
    require_checkpoint = .true.
    if (present(checkpoint_required)) then
       require_checkpoint = checkpoint_required
    end if
    recompose_physical = .false.
    if (present(complete_physical_recomposition)) then
       recompose_physical = complete_physical_recomposition
    end if
    retain_tendency = .false.
    if (present(retain_stage_tendency)) then
       retain_tendency = retain_stage_tendency
    end if
    validate_oracle = block_dynamics_validation_enabled()
    if (retain_tendency .and. &
         payload_family /= &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY) then
       call fail("retained stage tendency payload is invalid")
    end if

    if (payload_family /= BLOCK_PAYLOAD_EXNER_DIFFERENCE .and. &
         payload_family /= BLOCK_PAYLOAD_THERMODYNAMIC_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_EXNER_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_VELOCITY .and. &
         payload_family /= &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY) then
       call fail("Exner-gradient shadow payload is invalid")
    end if
    if (thermodynamic_product .neqv. &
         (payload_family == BLOCK_PAYLOAD_THERMODYNAMIC_GRADIENT .or. &
         payload_family == BLOCK_PAYLOAD_COMPLETE_EXNER_GRADIENT .or. &
         payload_family == BLOCK_PAYLOAD_COMPLETE_VELOCITY .or. &
         payload_family == &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY)) then
       call fail("Exner-gradient shadow mode is invalid")
    end if
    if (metric_division .neqv. &
         (payload_family == BLOCK_PAYLOAD_COMPLETE_EXNER_GRADIENT .or. &
         payload_family == BLOCK_PAYLOAD_COMPLETE_VELOCITY .or. &
         payload_family == &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY)) then
       call fail("Exner-gradient shadow metric mode is invalid")
    end if
    if (recompose_velocity .neqv. &
         (payload_family == BLOCK_PAYLOAD_COMPLETE_VELOCITY .or. &
         payload_family == &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY)) then
       call fail("Exner-gradient velocity recomposition mode is invalid")
    end if
    if (recompose_physical .neqv. &
         (payload_family == &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY)) then
       call fail("complete physical recomposition mode is invalid")
    end if

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. tendency_ready .or. &
         accumulator_ready) then
       call fail("Exner-difference shadow transaction is invalid")
    end if
    if (checkpoint_ready .neqv. require_checkpoint) then
       call fail("Exner-difference shadow checkpoint state is invalid")
    end if
    if (.not. local_block_hydrostatic_state_ready()) then
       call fail("Exner-difference shadow hydrostatic state is stale")
    end if

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (mult_scalar /= 1 .or. mult_vector /= EDGE .or. &
         S_MASS < v_scalar .or. &
         S_MASS >= v_scalar+n_scalar_variable .or. &
         (thermodynamic_product .and. &
         (S_TEMP < v_scalar .or. &
         S_TEMP >= v_scalar+n_scalar_variable)) .or. &
         v_vector < 1) then
       call fail("Exner-gradient shadow field layout is invalid")
    end if
    physical_first = max(1,first_field_level)
    physical_last = min( &
         zlevels,first_field_level+n_field_level-1)
    n_physical_level = max(0,physical_last-physical_first+1)
    if (n_physical_level /= zlevels) then
       call fail("Exner-difference physical-level coverage is invalid")
    end if

    if (validate_oracle) then
       call block_profile_enter(BLOCK_PROFILE_ORACLE)
       call local_block_field_statistics( &
            field_count(1),field_count(2), &
            field_moment(:,1),field_moment(:,2))
       call block_profile_leave(BLOCK_PROFILE_ORACLE)
    end if
    allocation_before = local_block_tendency_allocation_count()
    execution_before = local_block_tendency_execution_count()
    hydrostatic_refresh_before = local_block_hydrostatic_refresh_count()
    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    production_writeback_before = &
         block_domain_production_writeback_count()

    if (metric_division) call refresh_candidate_block_edge_metrics
    call exchange_domain_to_block_payloads( &
         payload_family,domain_sol=domain_sol)
    kernel = Block_Exner_Difference_Kernel_Context()
    kernel%thermodynamic_product = thermodynamic_product
    kernel%metric_division = metric_division
    kernel%velocity_recomposition = recompose_velocity
    kernel%complete_physical_recomposition = recompose_physical
    kernel%validate_oracle = validate_oracle
    call apply_local_block_tendency_kernel( &
         compute_block_exner_difference_kernel,kernel)

    tendency_ready = local_block_tendency_state_ready()
    if (.not. tendency_ready) then
       call fail("Exner-difference shadow output is not ready")
    end if
    if (local_block_tendency_execution_count() /= &
         execution_before+1_int64) then
       call fail("Exner-difference execution count is invalid")
    end if
    if (local_block_tendency_allocation_count() /= allocation_before) then
       call fail("Exner-difference reallocated tendency workspace")
    end if

    expected_patch_count = 0_int64
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       expected_patch_count = expected_patch_count + &
            int(local_block_patch_count(b),int64)
    end do
    expected_sample_count = expected_patch_count* &
         int(n_physical_level*EDGE*PATCH_SIZE**2,int64)
    if (kernel%block_count /= int(n_local_blocks(),int64) .or. &
         kernel%patch_count /= expected_patch_count .or. &
         kernel%sample_count /= expected_sample_count) then
       call fail("Exner-difference shadow traversal is incomplete")
    end if
    if (recompose_physical) then
       if (kernel%scalar_sample_count /= expected_patch_count* &
            int(n_scalar_variable*n_field_level*PATCH_SIZE**2, &
            int64)) then
          call fail("complete physical scalar traversal is incomplete")
       end if
    else if (kernel%scalar_sample_count /= 0_int64) then
       call fail("Exner-difference shadow changed scalar tendency")
    end if

    if (validate_oracle) then
       call block_profile_enter(BLOCK_PROFILE_ORACLE)
       call assert_candidate_block_tendency_payload_match( &
            payload_family,domain_sol,validated_patch_count)
       if (validated_patch_count /= expected_patch_count) then
          call fail("Exner-difference validation coverage differs")
       end if

       call local_block_field_statistics( &
            field_count_after(1),field_count_after(2), &
            field_moment_after(:,1),field_moment_after(:,2))
       if (any(field_count_after /= field_count)) then
          call fail("Exner-difference shadow changed field coverage")
       end if
       if (.not. field_moments_match( &
            field_moment_after(:,1),field_moment(:,1),field_count(1)) .or. &
            .not. field_moments_match( &
            field_moment_after(:,2),field_moment(:,2), &
            field_count(2))) then
          call fail("Exner-difference shadow changed block fields")
       end if
       call block_profile_leave(BLOCK_PROFILE_ORACLE)
    end if
    if (local_block_hydrostatic_refresh_count() /= &
         hydrostatic_refresh_before) then
       call fail("Exner-difference refreshed hydrostatic cache")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before) then
       call fail("Exner-difference shadow reallocated transport")
    end if
    if (block_domain_production_writeback_count() /= &
         production_writeback_before) then
       call fail("Exner-difference shadow modified Domain fields")
    end if

    if (validate_oracle) then
       count_local = [kernel%block_count,kernel%patch_count, &
            kernel%sample_count]
       call MPI_Allreduce(count_local,count_global,3, &
            MPI_INTEGER8,MPI_SUM,comm,ierr)
       call check_mpi(ierr,"MPI_Allreduce Exner-difference coverage")
       if (any(count_global <= 0_int64)) then
          call fail("Exner-difference global coverage is empty")
       end if
    end if

    if (retain_tendency) then
       call retain_local_block_tendency_in_accumulator
    else
       call discard_local_block_tendency_output
    end if
    tendency_ready = local_block_tendency_state_ready()
    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (tendency_ready .or. trial_active .or. &
         (accumulator_ready .neqv. retain_tendency)) then
       call fail("Exner-difference shadow completion state is invalid")
    end if
    if (checkpoint_ready .neqv. require_checkpoint) then
       call fail("Exner-difference shadow discard lost checkpoint state")
    end if

  end subroutine evaluate_candidate_block_exner_shadow


  subroutine assert_candidate_block_tendency_payload_match ( &
       payload_family,domain_sol,validated_patch_count)
    ! Compare a ready block-native tendency-shaped payload with an
    ! independently packed Domain payload on retained and remote blocks.

    implicit none

    integer, intent(in) :: payload_family
    type(Float_Field), intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    integer(int64), intent(out) :: validated_patch_count

    integer :: b
    integer :: d
    integer :: local_index
    integer :: local_patch
    integer :: n_patch
    integer :: pos_scalar
    integer :: pos_vector
    integer :: r
    integer :: slot

    if (payload_family /= BLOCK_PAYLOAD_EXNER_DIFFERENCE .and. &
         payload_family /= BLOCK_PAYLOAD_THERMODYNAMIC_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_EXNER_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_VELOCITY .and. &
         payload_family /= &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY) then
       call fail("candidate tendency payload family is invalid")
    end if
    if (.not. local_block_tendency_state_ready()) then
       call fail("candidate tendency payload is not ready")
    end if
    if (.not. allocated(ghost_exchange_plan%scalar_patch_buffer)) then
       call fail("candidate scalar patch buffer is not allocated")
    end if
    if (.not. allocated(ghost_exchange_plan%vector_patch_buffer)) then
       call fail("candidate vector patch buffer is not allocated")
    end if
    if (size(ghost_exchange_plan%scalar_patch_buffer) /= &
         block_writeback_plan%scalar_patch_nvalue .or. &
         size(ghost_exchange_plan%vector_patch_buffer) /= &
         block_writeback_plan%vector_patch_nvalue) then
       call fail("candidate tendency validation layout differs")
    end if

    validated_patch_count = 0_int64
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       r = source_rank(b)
       if (r /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1) + 1
       if (d < 1 .or. d > size(grid)) then
          call fail("candidate tendency retained Domain is invalid")
       end if
       local_patch = 0
       call assert_retained_subtree( &
            d,block_catalog(b)%root_patch,b,local_patch)
       if (local_patch /= local_block_patch_count(b)) then
          call fail("candidate tendency retained validation incomplete")
       end if
    end do

    do r = 1,n_process
       pos_scalar = block_writeback_plan%scalar_send_displ(r) + 1
       pos_vector = block_writeback_plan%vector_send_displ(r) + 1
       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          n_patch = local_block_patch_count(b)
          do local_patch = 0,n_patch-1
             if (pos_scalar < 1 .or. pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue - 1 > &
                  size(block_writeback_plan%scalar_send_buffer) .or. &
                  pos_vector < 1 .or. pos_vector + &
                  block_writeback_plan%vector_patch_nvalue - 1 > &
                  size(block_writeback_plan%vector_send_buffer)) then
                call fail("candidate tendency remote payload truncated")
             end if
             call assert_local_block_tendency_patch_values( &
                  b,local_patch, &
                  block_writeback_plan%scalar_send_buffer( &
                  pos_scalar:pos_scalar+ &
                  block_writeback_plan%scalar_patch_nvalue-1), &
                  block_writeback_plan%vector_send_buffer( &
                  pos_vector:pos_vector+ &
                  block_writeback_plan%vector_patch_nvalue-1))
             pos_scalar = pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue
             pos_vector = pos_vector + &
                  block_writeback_plan%vector_patch_nvalue
             validated_patch_count = validated_patch_count + 1_int64
          end do
       end do
       if (pos_scalar /= block_writeback_plan%scalar_send_displ(r) + &
            block_writeback_plan%scalar_send_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan%vector_send_displ(r) + &
            block_writeback_plan%vector_send_count(r) + 1) then
          call fail("candidate tendency remote validation extent mismatch")
       end if
    end do

  contains

    recursive subroutine assert_retained_subtree ( &
         d,p,b,local_patch_index)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(inout) :: local_patch_index

      integer :: c
      integer :: p_child
      integer :: scalar_pos
      integer :: vector_pos

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("candidate tendency retained patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return

      scalar_pos = 1
      vector_pos = 1
      call pack_domain_patch_prognostic( &
           d,p,payload_family, &
           ghost_exchange_plan%scalar_patch_buffer,scalar_pos, &
           ghost_exchange_plan%vector_patch_buffer,vector_pos,domain_sol)
      if (scalar_pos /= &
           size(ghost_exchange_plan%scalar_patch_buffer)+1 .or. &
           vector_pos /= &
           size(ghost_exchange_plan%vector_patch_buffer)+1) then
         call fail("candidate tendency retained payload extent mismatch")
      end if
      call assert_local_block_tendency_patch_values( &
           b,local_patch_index, &
           ghost_exchange_plan%scalar_patch_buffer, &
           ghost_exchange_plan%vector_patch_buffer)
      local_patch_index = local_patch_index + 1
      validated_patch_count = validated_patch_count + 1_int64

      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call assert_retained_subtree( &
              d,p_child,b,local_patch_index)
      end do

    end subroutine assert_retained_subtree

  end subroutine assert_candidate_block_tendency_payload_match


  subroutine refresh_parallel_block_domain_prognostic_state
    ! Refresh complete sol and wav_coeff interiors, compact boundaries,
    ! and inter-block ghosts from the authoritative Domain representation
    ! after its wavelet transform. Persistent allocations are retained.

    implicit none

    integer :: scalar_ghost_recv_size_before
    integer :: scalar_ghost_send_size_before
    integer :: vector_ghost_recv_size_before
    integer :: vector_ghost_send_size_before

    integer(int64) :: production_writeback_before
    integer(int64) :: stage_allocation_before
    integer(int64) :: writeback_allocation_before

    logical :: accumulator_ready
    logical :: hydrostatic_ready
    logical :: state_ready
    logical :: tendency_ready
    logical :: validate_oracle

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("Domain prognostic refresh before block state is ready")
    end if

    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    stage_allocation_before = block_writeback_plan%stage_allocations
    production_writeback_before = &
         block_domain_production_writeback_count()
    scalar_ghost_send_size_before = &
         size(ghost_exchange_plan%scalar_send_buffer)
    scalar_ghost_recv_size_before = &
         size(ghost_exchange_plan%scalar_recv_buffer)
    vector_ghost_send_size_before = &
         size(ghost_exchange_plan%vector_send_buffer)
    vector_ghost_recv_size_before = &
         size(ghost_exchange_plan%vector_recv_buffer)

    call import_domain_field_family_to_blocks(BLOCK_PAYLOAD_SOL)
    call import_domain_field_family_to_blocks(BLOCK_PAYLOAD_WAV_COEFF)
    validate_oracle = block_dynamics_validation_enabled()
    if (validate_oracle) then
       call block_profile_enter(BLOCK_PROFILE_ORACLE)
       call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)
       call assert_block_domain_field_family_match( &
            BLOCK_PAYLOAD_WAV_COEFF)
       call block_profile_leave(BLOCK_PROFILE_ORACLE)
    end if

    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.false.)
    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_WAV_COEFF,.false.)
    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_SOL,.true.)
    call import_domain_boundary_field_family_to_blocks( &
         BLOCK_PAYLOAD_WAV_COEFF,.true.)

    call refresh_block_sol_wav_coeff_ghosts
    call exchange_block_scalar_ghost_payloads( &
         BLOCK_PAYLOAD_SOL,.false.,.true.)
    call exchange_block_vector_ghost_payloads( &
         BLOCK_PAYLOAD_SOL,.false.,.true.)
    call exchange_block_scalar_ghost_payloads( &
         BLOCK_PAYLOAD_WAV_COEFF,.false.,.true.)
    call exchange_block_vector_ghost_payloads( &
         BLOCK_PAYLOAD_WAV_COEFF,.false.,.true.)

    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (tendency_ready .or. accumulator_ready) then
       call fail("Domain prognostic refresh retained stale tendencies")
    end if

    if (compressible) then
       call ensure_local_block_hydrostatic_state
       hydrostatic_ready = local_block_hydrostatic_state_ready()
       if (.not. hydrostatic_ready) then
          call fail("Domain prognostic refresh hydrostatic state failed")
       end if
    end if

    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before) then
       call fail("Domain prognostic refresh reallocated transport buffers")
    end if
    if (block_writeback_plan%stage_allocations /= &
         stage_allocation_before) then
       call fail("Domain prognostic refresh reallocated Domain staging")
    end if
    if (block_domain_production_writeback_count() /= &
         production_writeback_before) then
       call fail("Domain prognostic refresh modified Domain fields")
    end if
    if (size(ghost_exchange_plan%scalar_send_buffer) /= &
         scalar_ghost_send_size_before .or. &
         size(ghost_exchange_plan%scalar_recv_buffer) /= &
         scalar_ghost_recv_size_before .or. &
         size(ghost_exchange_plan%vector_send_buffer) /= &
         vector_ghost_send_size_before .or. &
         size(ghost_exchange_plan%vector_recv_buffer) /= &
         vector_ghost_recv_size_before) then
       call fail("Domain prognostic refresh resized ghost buffers")
    end if

  end subroutine refresh_parallel_block_domain_prognostic_state




  subroutine import_domain_trend_to_block_tendency ( &
       validate_exact,imported_patch_count)
    ! Import the complete Domain trend layout into persistent final-owner
    ! tendency storage. Soil-level slots are the explicit zeros packed by
    ! the Stage 78 field-layout transport. Production callers can request
    ! direct exact patch validation without allocating diagnostic copies.

    implicit none

    logical, optional, intent(in) :: validate_exact
    integer(int64), optional, intent(out) :: imported_patch_count

    integer :: b
    integer :: d
    integer :: local_index
    integer :: local_patch
    integer :: n_patch
    integer :: pos_scalar
    integer :: pos_vector
    integer :: r
    integer :: slot

    logical :: exact_validation
    logical :: plan_ready

    integer(int64) :: patch_count

    exact_validation = .false.
    if (present(validate_exact)) exact_validation = validate_exact
    patch_count = 0_int64

    plan_ready = block_writeback_plan_is_ready()
    if (.not. plan_ready) then
       call fail("trend tendency import before plan is ready")
    end if
    if (.not. allocated(ghost_exchange_plan%scalar_patch_buffer)) then
       call fail("retained scalar trend import buffer is not allocated")
    end if
    if (.not. allocated(ghost_exchange_plan%vector_patch_buffer)) then
       call fail("retained vector trend import buffer is not allocated")
    end if
    if (size(ghost_exchange_plan%scalar_patch_buffer) /= &
         block_writeback_plan%scalar_patch_nvalue .or. &
         size(ghost_exchange_plan%vector_patch_buffer) /= &
         block_writeback_plan%vector_patch_nvalue) then
       call fail("retained trend import patch layout mismatch")
    end if

    call exchange_domain_to_block_payloads(BLOCK_PAYLOAD_TREND)
    call begin_local_block_tendency_import

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       r = source_rank(b)
       if (r /= rank) cycle

       d = loc_id(block_catalog(b)%root_domain+1) + 1
       if (d < 1 .or. d > size(grid)) then
          call fail("retained trend import Domain is invalid")
       end if
       local_patch = 0
       call import_retained_subtree( &
            d,block_catalog(b)%root_patch,b,local_patch)
       n_patch = local_block_patch_count(b)
       if (local_patch /= n_patch) then
          call fail("retained trend import patch coverage mismatch")
       end if
    end do

    do r = 1,n_process
       pos_scalar = block_writeback_plan%scalar_send_displ(r) + 1
       pos_vector = block_writeback_plan%vector_send_displ(r) + 1

       do slot = block_writeback_plan%send_displ(r)+1, &
            block_writeback_plan%send_displ(r) + &
            block_writeback_plan%send_count(r)
          b = block_writeback_plan%send_block(slot)
          n_patch = local_block_patch_count(b)

          do local_patch = 0,n_patch-1
             if (pos_scalar < 1 .or. pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue - 1 > &
                  size(block_writeback_plan%scalar_send_buffer) .or. &
                  pos_vector < 1 .or. pos_vector + &
                  block_writeback_plan%vector_patch_nvalue - 1 > &
                  size(block_writeback_plan%vector_send_buffer)) then
                call fail("remote trend import payload is truncated")
             end if

             call set_local_block_tendency_patch_values( &
                  b,local_patch, &
                  block_writeback_plan%scalar_send_buffer( &
                  pos_scalar:pos_scalar+ &
                  block_writeback_plan%scalar_patch_nvalue-1), &
                  block_writeback_plan%vector_send_buffer( &
                  pos_vector:pos_vector+ &
                  block_writeback_plan%vector_patch_nvalue-1))
             pos_scalar = pos_scalar + &
                  block_writeback_plan%scalar_patch_nvalue
             pos_vector = pos_vector + &
                  block_writeback_plan%vector_patch_nvalue
          end do
       end do

       if (pos_scalar /= block_writeback_plan%scalar_send_displ(r) + &
            block_writeback_plan%scalar_send_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan%vector_send_displ(r) + &
            block_writeback_plan%vector_send_count(r) + 1) then
          call fail("remote trend import receive extent mismatch")
       end if
    end do

    call finish_local_block_tendency_import
    if (local_block_tendency_import_is_active()) then
       call fail("trend tendency import remained active")
    end if
    if (exact_validation) call validate_imported_patches
    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       patch_count = patch_count + &
            int(local_block_patch_count(b),int64)
    end do
    if (present(imported_patch_count)) then
       imported_patch_count = patch_count
    end if

  contains

    subroutine validate_imported_patches

      implicit none

      integer :: local_patch_index

      do local_index = 1,n_local_blocks()
         b = local_block_catalog(local_index)
         r = source_rank(b)
         if (r /= rank) cycle
         d = loc_id(block_catalog(b)%root_domain+1) + 1
         local_patch_index = 0
         call assert_retained_subtree( &
              d,block_catalog(b)%root_patch,b,local_patch_index)
         if (local_patch_index /= local_block_patch_count(b)) then
            call fail("retained trend validation coverage mismatch")
         end if
      end do

      do r = 1,n_process
         pos_scalar = block_writeback_plan%scalar_send_displ(r) + 1
         pos_vector = block_writeback_plan%vector_send_displ(r) + 1
         do slot = block_writeback_plan%send_displ(r)+1, &
              block_writeback_plan%send_displ(r) + &
              block_writeback_plan%send_count(r)
            b = block_writeback_plan%send_block(slot)
            n_patch = local_block_patch_count(b)
            do local_patch_index = 0,n_patch-1
               call assert_local_block_tendency_patch_values( &
                    b,local_patch_index, &
                    block_writeback_plan%scalar_send_buffer( &
                    pos_scalar:pos_scalar+ &
                    block_writeback_plan%scalar_patch_nvalue-1), &
                    block_writeback_plan%vector_send_buffer( &
                    pos_vector:pos_vector+ &
                    block_writeback_plan%vector_patch_nvalue-1))
               pos_scalar = pos_scalar + &
                    block_writeback_plan%scalar_patch_nvalue
               pos_vector = pos_vector + &
                    block_writeback_plan%vector_patch_nvalue
            end do
         end do
         if (pos_scalar /= block_writeback_plan%scalar_send_displ(r) + &
              block_writeback_plan%scalar_send_count(r) + 1 .or. &
              pos_vector /= block_writeback_plan%vector_send_displ(r) + &
              block_writeback_plan%vector_send_count(r) + 1) then
            call fail("remote trend validation extent mismatch")
         end if
      end do

    end subroutine validate_imported_patches


    recursive subroutine assert_retained_subtree ( &
         d,p,b,local_patch_index)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(inout) :: local_patch_index

      integer :: c
      integer :: p_child
      integer :: scalar_pos
      integer :: vector_pos

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("retained trend validation patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return

      scalar_pos = 1
      vector_pos = 1
      call pack_domain_patch_prognostic( &
           d,p,BLOCK_PAYLOAD_TREND, &
           ghost_exchange_plan%scalar_patch_buffer,scalar_pos, &
           ghost_exchange_plan%vector_patch_buffer,vector_pos)
      if (scalar_pos /= &
           size(ghost_exchange_plan%scalar_patch_buffer)+1 .or. &
           vector_pos /= &
           size(ghost_exchange_plan%vector_patch_buffer)+1) then
         call fail("retained trend validation extent mismatch")
      end if
      call assert_local_block_tendency_patch_values( &
           b,local_patch_index, &
           ghost_exchange_plan%scalar_patch_buffer, &
           ghost_exchange_plan%vector_patch_buffer)
      local_patch_index = local_patch_index + 1

      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call assert_retained_subtree( &
              d,p_child,b,local_patch_index)
      end do

    end subroutine assert_retained_subtree

    recursive subroutine import_retained_subtree ( &
         d,p,b,local_patch)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(inout) :: local_patch

      integer :: c
      integer :: p_child
      integer :: scalar_pos
      integer :: vector_pos

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("retained trend import patch is invalid")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return

      scalar_pos = 1
      vector_pos = 1
      call pack_domain_patch_prognostic( &
           d,p,BLOCK_PAYLOAD_TREND, &
           ghost_exchange_plan%scalar_patch_buffer,scalar_pos, &
           ghost_exchange_plan%vector_patch_buffer,vector_pos)
      if (scalar_pos /= &
           size(ghost_exchange_plan%scalar_patch_buffer)+1 .or. &
           vector_pos /= &
           size(ghost_exchange_plan%vector_patch_buffer)+1) then
         call fail("retained trend import patch extent mismatch")
      end if
      call set_local_block_tendency_patch_values( &
           b,local_patch,ghost_exchange_plan%scalar_patch_buffer, &
           ghost_exchange_plan%vector_patch_buffer)
      local_patch = local_patch + 1

      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call import_retained_subtree(d,p_child,b,local_patch)
      end do

    end subroutine import_retained_subtree

  end subroutine import_domain_trend_to_block_tendency




  subroutine begin_block_domain_trend_step (scale)
    ! Form one reversible Euler candidate from the current Domain trend.

    implicit none

    real(dp), intent(in) :: scale

    logical :: checkpoint_ready
    logical :: plan_ready
    logical :: store_ready
    logical :: tendency_ready
    logical :: trial_active

    store_ready = local_block_store_ready()
    plan_ready = block_writeback_plan_is_ready()
    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (.not. store_ready .or. .not. plan_ready) then
       call fail("Domain-trend block step before persistent state is ready")
    end if
    if (trial_active .or. checkpoint_ready) then
       call fail("Domain-trend block step found a pending transaction")
    end if

    call import_domain_trend_to_block_tendency
    call begin_local_block_tendency_trial(scale)
    call commit_local_block_tendency_trial

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    if (trial_active .or. .not. checkpoint_ready) then
       call fail("Domain-trend block step did not retain its checkpoint")
    end if
    if (tendency_ready) then
       call fail("Domain-trend block step retained stale tendencies")
    end if

  end subroutine begin_block_domain_trend_step


  subroutine complete_block_domain_trend_step (accept)
    ! Resolve the checkpoint produced by begin_block_domain_trend_step.

    implicit none

    logical, intent(in) :: accept

    if (local_block_tendency_trial_is_active()) then
       call fail("Domain-trend completion found an active trial")
    end if
    if (.not. local_block_tendency_commit_checkpoint_is_ready()) then
       call fail("Domain-trend completion found no pending checkpoint")
    end if

    if (accept) then
       call write_block_field_family_to_domains(BLOCK_PAYLOAD_SOL)
       call finalize_local_block_tendency_commit
    else
       call restore_local_block_tendency_commit
    end if

    if (local_block_tendency_trial_is_active() .or. &
         local_block_tendency_commit_checkpoint_is_ready()) then
       call fail("Domain-trend completion left pending transaction state")
    end if
    if (local_block_tendency_state_ready()) then
       call fail("Domain-trend completion retained stale tendencies")
    end if

  end subroutine complete_block_domain_trend_step


  subroutine advance_block_domain_trend_euler (scale)
    ! Accept one actual Domain-trend block Euler update and synchronize the
    ! resulting sol image transactionally to authoritative Domain owners.

    implicit none

    real(dp), intent(in) :: scale

    integer(int64) :: import_allocation_before
    integer(int64) :: production_writeback_before
    integer(int64) :: tendency_allocation_before
    integer(int64) :: writeback_allocation_before

    logical :: checkpoint_ready
    logical :: state_ready
    logical :: trial_active
    logical :: validate_oracle

    call block_profile_enter(BLOCK_PROFILE_TENDENCY)
    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("production block Euler step before state is ready")
    end if

    tendency_allocation_before = &
         local_block_tendency_allocation_count()
    import_allocation_before = &
         local_block_tendency_import_allocation_count()
    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    production_writeback_before = &
         block_domain_production_writeback_count()

    call begin_block_domain_trend_step(scale)
    call complete_block_domain_trend_step(.true.)

    validate_oracle = block_dynamics_validation_enabled()
    if (validate_oracle) then
       call block_profile_enter(BLOCK_PROFILE_ORACLE)
       call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)
       call assert_block_domain_field_family_match(BLOCK_PAYLOAD_WAV_COEFF)
       call block_profile_leave(BLOCK_PROFILE_ORACLE)
    end if

    if (local_block_tendency_allocation_count() /= &
         tendency_allocation_before) then
       call fail("production block Euler step reallocated tendency arrays")
    end if
    if (local_block_tendency_import_allocation_count() /= &
         import_allocation_before) then
       call fail("production block Euler step reallocated import coverage")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before) then
       call fail("production block Euler step reallocated transport storage")
    end if
    if (block_domain_production_writeback_count() /= &
         production_writeback_before + 1_int64) then
       call fail("production block Euler writeback count is invalid")
    end if

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (trial_active .or. checkpoint_ready) then
       call fail("production block Euler step left a pending transaction")
    end if

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("production block Euler step invalidated persistent state")
    end if

    call block_profile_leave( &
         BLOCK_PROFILE_TENDENCY,int(n_local_blocks(),int64))

  end subroutine advance_block_domain_trend_euler


  subroutine capture_block_domain_multistage_candidate_tendency ( &
       stage,stage_count,domain_sol,compatibility_remainder)
    ! Compute one complete block-native RK tendency, compare every compact
    ! patch exactly with the authoritative Domain tendency, and retain the
    ! native result in the persistent stage register. For stages after the
    ! first, restore the timestep-start state after the native tendency has
    ! been secured independently of the pending field checkpoint.

    implicit none

    integer, intent(in) :: stage
    integer, intent(in) :: stage_count
    type(Float_Field), intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    logical, optional, intent(in) :: compatibility_remainder

    logical :: accumulator_ready
    logical :: checkpoint_ready
    logical :: state_ready
    logical :: tendency_ready
    logical :: trial_active
    logical :: validate_oracle
    logical :: use_compatibility_remainder

    call block_profile_enter(BLOCK_PROFILE_TENDENCY)
    validate_oracle = block_dynamics_validation_enabled()
    use_compatibility_remainder = .false.
    if (present(compatibility_remainder)) &
         use_compatibility_remainder = compatibility_remainder
    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("multistage tendency capture before state is ready")
    end if
    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("multistage tendency capture stage count is invalid")
    end if
    if (stage < 1 .or. stage > stage_count) then
       call fail("multistage tendency capture stage is invalid")
    end if
    if (production_multistage_candidate_stage /= stage-1 .or. &
         production_multistage_captured_tendency_stage /= 0 .or. &
         production_multistage_native_candidate_stage /= 0) then
       call fail("multistage tendency capture sequence is invalid")
    end if
    if (block_writeback_plan%native_stage_ready) then
       call fail("multistage tendency capture found retained candidate")
    end if

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. tendency_ready .or. accumulator_ready) then
       call fail("multistage tendency capture found pending output")
    end if

    if (stage == 1) then
       if (checkpoint_ready) then
          call fail("multistage tendency capture found a checkpoint")
       end if
       if (block_writeback_plan% &
            production_multistage_boundary_refresh_count /= 0_int64) then
          call fail("multistage tendency boundary state was not finalized")
       end if
       production_multistage_candidate_stage_count = stage_count
       if (validate_oracle) then
          call block_profile_enter(BLOCK_PROFILE_ORACLE)
          call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)
          call assert_block_domain_field_family_match( &
               BLOCK_PAYLOAD_WAV_COEFF)
          call block_profile_leave(BLOCK_PROFILE_ORACLE)
       end if
       production_multistage_tendency_allocation_before = &
            local_block_tendency_allocation_count()
       production_multistage_accumulator_allocation_before = &
            local_block_tendency_accumulator_allocation_count()
       production_multistage_import_allocation_before = &
            local_block_tendency_import_allocation_count()
       production_multistage_writeback_allocation_before = &
            block_writeback_plan_allocation_count()
       production_multistage_stage_allocation_before = &
            block_writeback_plan%stage_allocations
       production_multistage_writeback_before = &
            block_domain_production_writeback_count()
       production_multistage_native_transform_writeback_count = 0_int64
       call evaluate_candidate_block_velocity_recomposition( &
            domain_sol,.false.,use_compatibility_remainder, &
            retained_compatibility_remainder= &
            use_compatibility_remainder)
    else
       if (production_multistage_candidate_stage_count /= stage_count) then
          call fail("multistage tendency capture method changed")
       end if
       if (block_writeback_plan% &
            production_multistage_boundary_refresh_count /= &
            int(stage-1,int64)) then
          call fail("multistage tendency boundary was not refreshed")
       end if
       if (.not. checkpoint_ready) then
          call fail("multistage tendency capture has no checkpoint")
       end if
       call evaluate_candidate_block_velocity_recomposition( &
            domain_sol,.true.,use_compatibility_remainder, &
            retained_compatibility_remainder= &
            use_compatibility_remainder)
       call complete_block_domain_trend_step(.false.)
    end if

    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    trial_active = local_block_tendency_trial_is_active()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (checkpoint_ready .or. trial_active .or. tendency_ready .or. &
         .not. accumulator_ready) then
       call fail("multistage native tendency retention is invalid")
    end if
    if (local_block_tendency_allocation_count() /= &
         production_multistage_tendency_allocation_before .or. &
         local_block_tendency_accumulator_allocation_count() /= &
         production_multistage_accumulator_allocation_before) then
       call fail("multistage tendency capture reallocated workspace")
    end if
    if (block_writeback_plan_allocation_count() /= &
         production_multistage_writeback_allocation_before) then
       call fail("multistage tendency capture reallocated transport")
    end if
    if (block_domain_production_writeback_count() /= &
         production_multistage_writeback_before + &
         production_multistage_native_transform_writeback_count) then
       call fail("multistage tendency capture writeback sequence is invalid")
    end if

    production_multistage_captured_tendency_stage = stage
    call block_profile_leave( &
         BLOCK_PROFILE_TENDENCY,int(n_local_blocks(),int64))
  end subroutine capture_block_domain_multistage_candidate_tendency


  subroutine begin_block_domain_multistage_candidate_stage ( &
       scale,stage,stage_count)
    ! Consume one roundoff-bounded validated block-native tendency from the
    ! persistent stage register and form a retained provisional low-storage
    ! RK3 or RK4 candidate. Every stage remains based on the retained
    ! timestep-start block state and remains reversible until the guard.

    implicit none

    real(dp), intent(in) :: scale
    integer, intent(in) :: stage
    integer, intent(in) :: stage_count

    logical :: accumulator_ready
    logical :: checkpoint_ready
    logical :: state_ready
    logical :: tendency_ready
    logical :: trial_active

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail( &
            "production multistage block candidate before state is ready")
    end if
    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("production block candidate stage count is invalid")
    end if
    if (stage < 1 .or. stage > stage_count) then
       call fail("production multistage block candidate stage is invalid")
    end if
    if (production_multistage_candidate_stage /= stage-1) then
       call fail( &
            "production multistage block candidate sequence is invalid")
    end if
    if (production_multistage_candidate_stage_count /= stage_count .or. &
         production_multistage_captured_tendency_stage /= stage .or. &
         production_multistage_native_candidate_stage /= 0) then
       call fail( &
            "production multistage native tendency was not retained")
    end if

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. checkpoint_ready .or. tendency_ready .or. &
         .not. accumulator_ready) then
       call fail( &
            "production multistage native tendency state is invalid")
    end if

    call begin_local_block_accumulated_tendency_trial(scale)
    call commit_local_block_tendency_trial
    call discard_local_block_tendency_accumulator
    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. .not. checkpoint_ready .or. tendency_ready .or. &
         accumulator_ready) then
       call fail( &
            "production native block candidate state is invalid")
    end if

    production_multistage_captured_tendency_stage = 0
    production_multistage_native_candidate_stage = stage

  end subroutine begin_block_domain_multistage_candidate_stage


  subroutine retain_native_multistage_candidate_snapshot ( &
       stage,stage_count)
    ! Preserve the complete reconstructed native candidate so the following
    ! Domain wavelet transform cannot silently alter transaction-owned blocks.

    implicit none

    integer, intent(in) :: stage
    integer, intent(in) :: stage_count

    logical :: validate_oracle

    if (block_writeback_plan%native_stage_ready) then
       call fail("native multistage snapshot is already retained")
    end if
    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("native multistage snapshot stage count is invalid")
    end if
    if (stage < 1 .or. stage > stage_count) then
       call fail("native multistage snapshot stage is invalid")
    end if

    validate_oracle = block_dynamics_validation_enabled()
    if (validate_oracle) then
       call block_profile_enter(BLOCK_PROFILE_ORACLE)
       call reconstruct_block_writeback_domain_stage(BLOCK_PAYLOAD_SOL)
       block_writeback_plan%native_scalar_stage = &
            block_writeback_plan%scalar_domain_stage
       block_writeback_plan%native_vector_stage = &
            block_writeback_plan%vector_domain_stage
       call block_profile_leave(BLOCK_PROFILE_ORACLE)
    end if
    block_writeback_plan%native_stage = stage
    block_writeback_plan%native_stage_count = stage_count
    block_writeback_plan%native_stage_ready = .true.

  end subroutine retain_native_multistage_candidate_snapshot


  subroutine consume_native_multistage_candidate_snapshot ( &
       stage,stage_count)
    ! Verify exact retention across the caller-controlled interval (including
    ! the Domain wavelet boundary for intermediate stages), then release the
    ! snapshot for reuse by the next RK stage.

    implicit none

    integer, intent(in) :: stage
    integer, intent(in) :: stage_count

    logical :: validate_oracle

    if (.not. block_writeback_plan%native_stage_ready .or. &
         block_writeback_plan%native_stage /= stage .or. &
         block_writeback_plan%native_stage_count /= stage_count) then
       call fail("native multistage snapshot sequence is invalid")
    end if

    validate_oracle = block_dynamics_validation_enabled()
    if (validate_oracle) then
       call block_profile_enter(BLOCK_PROFILE_ORACLE)
       call reconstruct_block_writeback_domain_stage(BLOCK_PAYLOAD_SOL)
       if (any(abs(block_writeback_plan%scalar_domain_stage - &
            block_writeback_plan%native_scalar_stage) > 0.0_dp)) then
          call fail( &
               "native scalar candidate changed across wavelet boundary")
       end if
       if (any(abs(block_writeback_plan%vector_domain_stage - &
            block_writeback_plan%native_vector_stage) > 0.0_dp)) then
          call fail( &
               "native vector candidate changed across wavelet boundary")
       end if
       call block_profile_leave(BLOCK_PROFILE_ORACLE)
    end if

    block_writeback_plan%native_stage = 0
    block_writeback_plan%native_stage_count = 0
    block_writeback_plan%native_stage_ready = .false.

  end subroutine consume_native_multistage_candidate_snapshot


  subroutine retain_block_native_multistage_candidate ( &
       domain_sol,stage,stage_count)
    ! Validate one block-native pre-wavelet RK candidate against the
    ! independently evaluated authoritative Domain stage, then retain the
    ! complete native candidate and its reversible timestep-start checkpoint,
    ! then install the validated native stage as the following wavelet input.

    implicit none

    type(Float_Field), intent(inout) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    integer, intent(in) :: stage
    integer, intent(in) :: stage_count

    integer(int64) :: production_writeback_before
    integer(int64) :: writeback_allocation_before

    logical :: accumulator_ready
    logical :: checkpoint_ready
    logical :: state_ready
    logical :: tendency_ready
    logical :: trial_active
    logical :: validate_oracle

    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail("native multistage retention before state is ready")
    end if
    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("native multistage retention stage count is invalid")
    end if
    if (stage < 1 .or. stage > stage_count) then
       call fail("native multistage retention stage is invalid")
    end if
    if (production_multistage_candidate_stage_count /= stage_count .or. &
         production_multistage_candidate_stage /= stage-1 .or. &
         production_multistage_native_candidate_stage /= stage) then
       call fail("native multistage retention sequence is invalid")
    end if

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. .not. checkpoint_ready .or. tendency_ready .or. &
         accumulator_ready) then
       call fail("native multistage retention state is invalid")
    end if

    writeback_allocation_before = &
         block_writeback_plan_allocation_count()
    production_writeback_before = &
         block_domain_production_writeback_count()
    validate_oracle = block_dynamics_validation_enabled()
    if (validate_oracle) then
       call block_profile_enter(BLOCK_PROFILE_ORACLE)
       call assert_block_domain_field_family_match( &
            BLOCK_PAYLOAD_SOL,domain_sol, &
            integrated_only=.true., &
            comparison_name="native", &
            roundoff_tolerant=.true.)
       call block_profile_leave(BLOCK_PROFILE_ORACLE)
    end if
    ! RK_sub_step_compatibility has already materialized the complete Domain
    ! stage.  Retain the independently accumulated native block candidate,
    ! but do not transport it back merely to overwrite an oracle-equivalent
    ! stage before the wavelet boundary.
    call retain_native_multistage_candidate_snapshot(stage,stage_count)

    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    tendency_ready = local_block_tendency_state_ready()
    accumulator_ready = &
         local_block_tendency_accumulator_state_ready()
    if (trial_active .or. .not. checkpoint_ready .or. tendency_ready .or. &
         accumulator_ready) then
       call fail("native multistage transaction was not retained")
    end if
    if (local_block_tendency_allocation_count() /= &
         production_multistage_tendency_allocation_before .or. &
         local_block_tendency_import_allocation_count() /= &
         production_multistage_import_allocation_before) then
       call fail("native multistage retention reallocated workspace")
    end if
    if (block_writeback_plan_allocation_count() /= &
         writeback_allocation_before) then
       call fail("native multistage retention reallocated transport")
    end if
    if (block_writeback_plan%stage_allocations /= &
         production_multistage_stage_allocation_before) then
       call fail("native multistage retention reallocated snapshot storage")
    end if
    if (block_domain_production_writeback_count() /= &
         production_writeback_before) then
       call fail("native multistage retention wrote a redundant stage")
    end if

    production_multistage_native_candidate_stage = 0
    production_multistage_candidate_stage = stage
  end subroutine retain_block_native_multistage_candidate


  subroutine prepare_block_native_multistage_wavelet_stage ( &
       stage,stage_count)
    ! Release the exact pre-transform candidate snapshot before a provisional
    ! native WT changes compact SOL. The timestep-start rollback checkpoint
    ! remains live for the following low-storage RK stage.

    implicit none

    integer, intent(in) :: stage
    integer, intent(in) :: stage_count

    logical :: checkpoint_ready
    logical :: state_ready

    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("provisional wavelet stage count is invalid")
    end if
    if (stage < 1 .or. stage >= stage_count) then
       call fail("provisional wavelet stage is invalid")
    end if
    if (production_multistage_candidate_stage_count /= stage_count .or. &
         production_multistage_candidate_stage /= stage .or. &
         production_multistage_captured_tendency_stage /= 0 .or. &
         production_multistage_native_candidate_stage /= 0) then
       call fail("provisional wavelet candidate is incomplete")
    end if
    if (production_multistage_final_snapshot_consumed .or. &
         production_multistage_provisional_snapshot_consumed) then
       call fail("provisional wavelet snapshot was already consumed")
    end if

    state_ready = parallel_block_state_is_ready()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (.not. state_ready .or. .not. checkpoint_ready) then
       call fail("provisional wavelet transaction is not ready")
    end if
    call consume_native_multistage_candidate_snapshot(stage,stage_count)
    if (block_writeback_plan%native_stage_ready) then
       call fail("provisional wavelet snapshot remained retained")
    end if
    production_multistage_provisional_snapshot_consumed = .true.

  end subroutine prepare_block_native_multistage_wavelet_stage


  subroutine prepare_block_native_multistage_wavelet_acceptance ( &
       stage_count)
    ! Consume the exact final pre-wavelet SOL snapshot before WT_after_step
    ! performs its legitimate level_start-1 velocity restriction. Keep the
    ! rollback checkpoint live so acceptance can remain conditional on the
    ! subsequent complete native wavelet production transaction.

    implicit none

    integer, intent(in) :: stage_count

    logical :: checkpoint_ready
    logical :: state_ready
    logical :: trial_active

    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("wavelet acceptance stage count is invalid")
    end if
    if (production_multistage_candidate_stage_count /= stage_count .or. &
         production_multistage_candidate_stage /= stage_count .or. &
         production_multistage_captured_tendency_stage /= 0 .or. &
         production_multistage_native_candidate_stage /= 0) then
       call fail("wavelet acceptance candidate is incomplete")
    end if
    if (production_multistage_final_snapshot_consumed .or. &
         production_multistage_provisional_snapshot_consumed) then
       call fail("wavelet acceptance snapshot was already consumed")
    end if

    state_ready = parallel_block_state_is_ready()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    trial_active = local_block_tendency_trial_is_active()
    if (.not. state_ready .or. trial_active .or. .not. checkpoint_ready) then
       call fail("wavelet acceptance transaction is not ready")
    end if
    if (.not. block_writeback_plan%native_stage_ready .or. &
         block_writeback_plan%native_stage /= stage_count .or. &
         block_writeback_plan%native_stage_count /= stage_count) then
       call fail("wavelet acceptance native snapshot is not ready")
    end if

    call consume_native_multistage_candidate_snapshot( &
         stage_count,stage_count)
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (.not. checkpoint_ready .or. &
         block_writeback_plan%native_stage_ready) then
       call fail("wavelet acceptance snapshot boundary is invalid")
    end if
    production_multistage_final_snapshot_consumed = .true.

  end subroutine prepare_block_native_multistage_wavelet_acceptance


  subroutine accept_block_native_multistage_candidate (stage_count)
    ! Accept the retained final native candidate after its scalar-wavelet
    ! guard. The exact pre-restriction SOL snapshot has already been consumed;
    ! close the reversible timestep-start checkpoint only after the guarded
    ! uncompressed transform is complete.

    implicit none

    integer, intent(in) :: stage_count

    logical :: checkpoint_ready
    logical :: state_ready
    logical :: trial_active
    logical :: validate_oracle

    if (stage_count /= 3 .and. stage_count /= 4) then
       call fail("accepted production block candidate stage count is invalid")
    end if
    if (production_multistage_candidate_stage_count /= stage_count .or. &
         production_multistage_candidate_stage /= stage_count .or. &
         production_multistage_captured_tendency_stage /= 0 .or. &
         production_multistage_native_candidate_stage /= 0) then
       call fail("production multistage block candidate is incomplete")
    end if
    if (.not. production_multistage_final_snapshot_consumed .or. &
         production_multistage_provisional_snapshot_consumed .or. &
         block_writeback_plan%native_stage_ready) then
       call fail("production multistage snapshot boundary is incomplete")
    end if
    if (production_velocity_restriction_level /= level_start-1) then
       call fail("production velocity restriction is incomplete")
    end if
    if (.not. production_coarse_outer_wavelet_validated) then
       call fail("production coarse outer wavelet is incomplete")
    end if
    if (.not. production_complete_vector_wavelet_validated) then
       call fail("production complete vector wavelet is incomplete")
    end if
    if (.not. production_native_wavelet_output_activated) then
       call fail("production native wavelet output is not active")
    end if
    if (production_adaptation_pending) then
       call fail("previous block adaptation lifecycle is pending")
    end if
    if (block_writeback_plan% &
         production_multistage_boundary_refresh_count /= &
         int(stage_count-1,int64)) then
       call fail( &
            "production multistage boundary refresh is incomplete")
    end if
    trial_active = local_block_tendency_trial_is_active()
    checkpoint_ready = &
         local_block_tendency_commit_checkpoint_is_ready()
    if (trial_active .or. .not. checkpoint_ready) then
       call fail("production multistage final checkpoint is not ready")
    end if

    call finalize_local_block_tendency_commit
    validate_oracle = block_dynamics_validation_enabled()
    if (validate_oracle) then
       call block_profile_enter(BLOCK_PROFILE_ORACLE)
       call assert_block_domain_field_family_match(BLOCK_PAYLOAD_SOL)
       call block_profile_leave(BLOCK_PROFILE_ORACLE)
    end if

    if (local_block_tendency_allocation_count() /= &
         production_multistage_tendency_allocation_before) then
       call fail( &
            "production multistage candidate reallocated tendency arrays")
    end if
    if (local_block_tendency_accumulator_allocation_count() /= &
         production_multistage_accumulator_allocation_before) then
       call fail( &
            "production multistage candidate reallocated stage register")
    end if
    if (local_block_tendency_import_allocation_count() /= &
         production_multistage_import_allocation_before) then
       call fail( &
            "production multistage candidate reallocated import coverage")
    end if
    if (block_writeback_plan_allocation_count() /= &
         production_multistage_writeback_allocation_before) then
       call fail( &
            "production multistage candidate reallocated transport storage")
    end if
    if (block_writeback_plan%stage_allocations /= &
         production_multistage_stage_allocation_before) then
       call fail( &
            "production multistage candidate reallocated snapshot storage")
    end if
    if (block_domain_production_writeback_count() /= &
         production_multistage_writeback_before + &
         1_int64 + &
         production_multistage_native_transform_writeback_count) then
       call fail( &
            "accepted production multistage writeback count is invalid")
    end if
    if (local_block_tendency_trial_is_active() .or. &
         local_block_tendency_commit_checkpoint_is_ready()) then
       call fail( &
            "accepted production multistage transaction remained pending")
    end if
    state_ready = parallel_block_state_is_ready()
    if (.not. state_ready) then
       call fail( &
            "accepted production multistage invalidated persistent state")
    end if

    production_adaptation_pending = .true.
    production_multistage_candidate_stage = 0
    production_multistage_candidate_stage_count = 0
    production_multistage_captured_tendency_stage = 0
    production_multistage_native_candidate_stage = 0
    production_velocity_restriction_level = -1
    production_coarse_outer_wavelet_validated = .false.
    production_complete_vector_wavelet_validated = .false.
    production_native_wavelet_output_activated = .false.
    production_multistage_final_snapshot_consumed = .false.
    production_multistage_provisional_snapshot_consumed = .false.
    production_multistage_stage_allocation_before = 0_int64
    production_multistage_native_transform_writeback_count = 0_int64
    block_writeback_plan%production_multistage_boundary_refresh_count = &
         0_int64

  end subroutine accept_block_native_multistage_candidate




  recursive subroutine pack_domain_subtree_prognostic ( &
       d,p,payload_family,scalar_payload,scalar_pos, &
       vector_payload,vector_pos,n_patch,domain_sol)
    ! Pack one Domain field-family subtree in compact block preorder.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    integer, intent(in) :: payload_family
    real(dp), intent(inout) :: scalar_payload(:)
    integer, intent(inout) :: scalar_pos
    real(dp), intent(inout) :: vector_payload(:)
    integer, intent(inout) :: vector_pos
    integer, intent(inout) :: n_patch
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: c
    integer :: p_child

    if (p < 0 .or. p >= grid(d)%patch%length) then
       call fail("invalid patch in writeback Domain payload")
    end if
    if (grid(d)%patch%elts(p+1)%deleted) return

    call pack_domain_patch_prognostic( &
         d,p,payload_family,scalar_payload,scalar_pos, &
         vector_payload,vector_pos,domain_sol)

    n_patch = n_patch + 1

    do c = 1,N_CHDRN
       p_child = grid(d)%patch%elts(p+1)%children(c)
       if (p_child <= 0) cycle
       call pack_domain_subtree_prognostic( &
            d,p_child,payload_family,scalar_payload,scalar_pos, &
            vector_payload,vector_pos,n_patch,domain_sol)
    end do

  end subroutine pack_domain_subtree_prognostic


  subroutine pack_domain_patch_prognostic ( &
       d,p,payload_family,scalar_payload,scalar_pos, &
       vector_payload,vector_pos,domain_sol)
    ! Pack one active Domain patch in compact field-family order.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    integer, intent(in) :: payload_family
    real(dp), intent(inout) :: scalar_payload(:)
    integer, intent(inout) :: scalar_pos
    real(dp), intent(inout) :: vector_payload(:)
    integer, intent(inout) :: vector_pos
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: field_level
    integer :: first_field_level
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_patch
    integer :: n_scalar_variable
    integer :: n_value
    integer :: n_vector_patch
    integer :: scalar_id
    integer :: scalar_slot
    integer :: start
    integer :: v_scalar
    integer :: v_vector

    if (d < 1 .or. d > size(grid)) then
       call fail("invalid Domain in writeback record")
    end if
    if (p < 0 .or. p >= grid(d)%patch%length) then
       call fail("invalid patch in Domain writeback record")
    end if
    if (grid(d)%patch%elts(p+1)%deleted) then
       call fail("deleted patch in Domain writeback record")
    end if
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF .and. &
         payload_family /= BLOCK_PAYLOAD_TREND .and. &
         payload_family /= BLOCK_PAYLOAD_THETA_EDGE .and. &
         payload_family /= BLOCK_PAYLOAD_EXNER_DIFFERENCE .and. &
         payload_family /= BLOCK_PAYLOAD_THERMODYNAMIC_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_EXNER_GRADIENT .and. &
         payload_family /= BLOCK_PAYLOAD_EDGE_LENGTH .and. &
         payload_family /= BLOCK_PAYLOAD_VELOCITY_REMAINDER .and. &
         payload_family /= BLOCK_PAYLOAD_COMPLETE_VELOCITY .and. &
         payload_family /= BLOCK_PAYLOAD_PHYSICAL_COMPONENTS .and. &
         payload_family /= BLOCK_PAYLOAD_COMPATIBILITY_COMPONENTS .and. &
         payload_family /= &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY) then
       call fail("invalid Domain writeback payload family")
    end if

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)

    n_scalar_patch = &
         n_scalar_variable*n_field_level*mult_scalar*PATCH_SIZE**2
    n_vector_patch = n_field_level*mult_vector*PATCH_SIZE**2
    if (scalar_pos < 1 .or. &
         scalar_pos+n_scalar_patch-1 > size(scalar_payload) .or. &
         vector_pos < 1 .or. &
         vector_pos+n_vector_patch-1 > size(vector_payload)) then
       call fail("Domain writeback record buffer extent is invalid")
    end if

    if (payload_family == BLOCK_PAYLOAD_COMPATIBILITY_COMPONENTS) then
       scalar_pos = scalar_pos + n_scalar_patch
       call pack_domain_patch_velocity_recomposition( &
            d,p,vector_payload( &
            vector_pos:vector_pos+n_vector_patch-1),domain_sol,.false.)
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    if (payload_family == BLOCK_PAYLOAD_PHYSICAL_COMPONENTS .or. &
         payload_family == &
         BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY) then
       start = mult_scalar*grid(d)%patch%elts(p+1)%elts_start
       n_value = mult_scalar*PATCH_SIZE**2
       do scalar_slot = 1,n_scalar_variable
          scalar_id = v_scalar + scalar_slot - 1
          do level_slot = 1,n_field_level
             field_level = first_field_level + level_slot - 1
             if (field_level < 1) then
                scalar_payload( &
                     scalar_pos:scalar_pos+n_value-1) = 0.0_dp
             else
                if (field_level > zlevels) then
                   call fail( &
                        "physical scalar tendency level is invalid")
                end if
                if (start < 0 .or. start+n_value > &
                     size(trend(scalar_id,field_level)%data(d)%elts)) then
                   call fail( &
                        "physical scalar tendency extent is invalid")
                end if
                scalar_payload(scalar_pos:scalar_pos+n_value-1) = &
                     trend(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value)
             end if
             scalar_pos = scalar_pos + n_value
          end do
       end do
       if (.not. present(domain_sol)) then
          call fail("physical tendency payload requires stage sol")
       end if
       call pack_domain_patch_velocity_recomposition( &
            d,p,vector_payload( &
            vector_pos:vector_pos+n_vector_patch-1),domain_sol, &
            payload_family == &
            BLOCK_PAYLOAD_COMPLETE_PHYSICAL_TENDENCY)
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    if (payload_family == BLOCK_PAYLOAD_THETA_EDGE) then
       scalar_payload(scalar_pos:scalar_pos+n_scalar_patch-1) = 0.0_dp
       if (present(domain_sol)) then
          call pack_domain_patch_theta_edge( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1),domain_sol)
       else
          call pack_domain_patch_theta_edge( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1))
       end if
       scalar_pos = scalar_pos + n_scalar_patch
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    if (payload_family == BLOCK_PAYLOAD_EXNER_DIFFERENCE) then
       scalar_payload(scalar_pos:scalar_pos+n_scalar_patch-1) = 0.0_dp
       if (present(domain_sol)) then
          call pack_domain_patch_exner_difference( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1),domain_sol)
       else
          call pack_domain_patch_exner_difference( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1))
       end if
       scalar_pos = scalar_pos + n_scalar_patch
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    if (payload_family == BLOCK_PAYLOAD_THERMODYNAMIC_GRADIENT) then
       scalar_payload(scalar_pos:scalar_pos+n_scalar_patch-1) = 0.0_dp
       if (present(domain_sol)) then
          call pack_domain_patch_exner_difference( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1),domain_sol,.true.)
       else
          call pack_domain_patch_exner_difference( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1), &
               thermodynamic_product=.true.)
       end if
       scalar_pos = scalar_pos + n_scalar_patch
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    if (payload_family == BLOCK_PAYLOAD_COMPLETE_EXNER_GRADIENT) then
       scalar_payload(scalar_pos:scalar_pos+n_scalar_patch-1) = 0.0_dp
       if (present(domain_sol)) then
          call pack_domain_patch_exner_difference( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1),domain_sol, &
               .true.,.true.)
       else
          call pack_domain_patch_exner_difference( &
               d,p,vector_payload( &
               vector_pos:vector_pos+n_vector_patch-1), &
               thermodynamic_product=.true.,metric_division=.true.)
       end if
       scalar_pos = scalar_pos + n_scalar_patch
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    if (payload_family == BLOCK_PAYLOAD_EDGE_LENGTH) then
       scalar_payload(scalar_pos:scalar_pos+n_scalar_patch-1) = 0.0_dp
       call pack_domain_patch_edge_length( &
            d,p,vector_payload( &
            vector_pos:vector_pos+n_vector_patch-1))
       scalar_pos = scalar_pos + n_scalar_patch
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    if (payload_family == BLOCK_PAYLOAD_VELOCITY_REMAINDER .or. &
         payload_family == BLOCK_PAYLOAD_COMPLETE_VELOCITY) then
       if (.not. present(domain_sol)) then
          call fail("Domain velocity recomposition requires stage sol")
       end if
       scalar_payload(scalar_pos:scalar_pos+n_scalar_patch-1) = 0.0_dp
       call pack_domain_patch_velocity_recomposition( &
            d,p,vector_payload( &
            vector_pos:vector_pos+n_vector_patch-1),domain_sol, &
            payload_family == BLOCK_PAYLOAD_COMPLETE_VELOCITY)
       scalar_pos = scalar_pos + n_scalar_patch
       vector_pos = vector_pos + n_vector_patch
       return
    end if

    start = mult_scalar*grid(d)%patch%elts(p+1)%elts_start
    n_value = mult_scalar*PATCH_SIZE**2

    do scalar_slot = 1,n_scalar_variable
       scalar_id = v_scalar + scalar_slot - 1
       do level_slot = 1,n_field_level
          field_level = first_field_level + level_slot - 1
          select case (payload_family)
          case (BLOCK_PAYLOAD_SOL)
             if (present(domain_sol) .and. field_level >= 1 .and. &
                  field_level <= zlevels) then
                if (start < 0 .or. start+n_value > size( &
                     domain_sol(scalar_id,field_level)%data(d)%elts)) then
                   call fail("stage scalar sol payload extent is invalid")
                end if
                scalar_payload(scalar_pos:scalar_pos+n_value-1) = &
                     domain_sol(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value)
             else
                if (start < 0 .or. start+n_value > &
                     size(sol(scalar_id,field_level)%data(d)%elts)) then
                   call fail( &
                        "legacy scalar sol writeback extent is invalid")
                end if
                scalar_payload(scalar_pos:scalar_pos+n_value-1) = &
                     sol(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value)
             end if
          case (BLOCK_PAYLOAD_WAV_COEFF)
             if (present(domain_sol) .and. field_level >= 1 .and. &
                  field_level <= zlevels) then
                if (start < 0 .or. start+n_value > size( &
                     domain_sol(scalar_id,field_level)%data(d)%elts)) then
                   call fail( &
                        "stage scalar wav_coeff extent is invalid")
                end if
                scalar_payload(scalar_pos:scalar_pos+n_value-1) = &
                     domain_sol(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value)
             else
                if (start < 0 .or. start+n_value > size( &
                     wav_coeff(scalar_id,field_level)%data(d)%elts)) then
                   call fail( &
                        "legacy scalar wav_coeff extent is invalid")
                end if
                scalar_payload(scalar_pos:scalar_pos+n_value-1) = &
                     wav_coeff(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value)
             end if
          case (BLOCK_PAYLOAD_TREND)
             if (field_level < 1) then
                scalar_payload( &
                     scalar_pos:scalar_pos+n_value-1) = 0.0_dp
             else
                if (start < 0 .or. start+n_value > &
                     size(trend(scalar_id,field_level)%data(d)%elts)) then
                   call fail( &
                        "legacy scalar trend payload extent is invalid")
                end if
                scalar_payload(scalar_pos:scalar_pos+n_value-1) = &
                     trend(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value)
             end if
          end select
          scalar_pos = scalar_pos + n_value
       end do
    end do

    start = mult_vector*grid(d)%patch%elts(p+1)%elts_start
    n_value = mult_vector*PATCH_SIZE**2

    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       select case (payload_family)
       case (BLOCK_PAYLOAD_SOL)
          if (present(domain_sol) .and. field_level >= 1 .and. &
               field_level <= zlevels) then
             if (start < 0 .or. start+n_value > &
                  size(domain_sol(v_vector,field_level)%data(d)%elts)) then
                call fail("stage vector sol payload extent is invalid")
             end if
             vector_payload(vector_pos:vector_pos+n_value-1) = &
                  domain_sol(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value)
          else
             if (start < 0 .or. start+n_value > &
                  size(sol(v_vector,field_level)%data(d)%elts)) then
                call fail("legacy vector sol writeback extent is invalid")
             end if
             vector_payload(vector_pos:vector_pos+n_value-1) = &
                  sol(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value)
          end if
       case (BLOCK_PAYLOAD_WAV_COEFF)
          if (present(domain_sol) .and. field_level >= 1 .and. &
               field_level <= zlevels) then
             if (start < 0 .or. start+n_value > size( &
                  domain_sol(v_vector,field_level)%data(d)%elts)) then
                call fail("stage vector wav_coeff extent is invalid")
             end if
             vector_payload(vector_pos:vector_pos+n_value-1) = &
                  domain_sol(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value)
          else
             if (start < 0 .or. start+n_value > size( &
                  wav_coeff(v_vector,field_level)%data(d)%elts)) then
                call fail("legacy vector wav_coeff extent is invalid")
             end if
             vector_payload(vector_pos:vector_pos+n_value-1) = &
                  wav_coeff(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value)
          end if
       case (BLOCK_PAYLOAD_TREND)
          if (field_level < 1) then
             vector_payload( &
                  vector_pos:vector_pos+n_value-1) = 0.0_dp
          else
             if (start < 0 .or. start+n_value > &
                  size(trend(v_vector,field_level)%data(d)%elts)) then
                call fail("legacy vector trend payload extent is invalid")
             end if
             vector_payload(vector_pos:vector_pos+n_value-1) = &
                  trend(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value)
          end if
       end select
       vector_pos = vector_pos + n_value
    end do

  end subroutine pack_domain_patch_prognostic

  subroutine pack_domain_patch_edge_length (d,p,edge_length)
    ! Repeat the authoritative, initialized production primal-edge metric
    ! in the block vector layout for every physical model level.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    real(dp), intent(out) :: edge_length(:)

    integer :: field_level
    integer :: first_field_level
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: n_value
    integer :: output_base
    integer :: start
    integer :: v_scalar
    integer :: v_vector

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (mult_scalar /= 1 .or. mult_vector /= EDGE .or. &
         n_scalar_variable < 1 .or. v_scalar < 1 .or. v_vector < 1) then
       call fail("Domain edge-metric field layout is invalid")
    end if
    n_value = EDGE*PATCH_SIZE**2
    if (size(edge_length) /= n_field_level*n_value) then
       call fail("Domain edge-metric payload extent is invalid")
    end if
    start = EDGE*grid(d)%patch%elts(p+1)%elts_start
    if (start < 0 .or. start+n_value > size(grid(d)%len%elts)) then
       call fail("Domain edge-metric source extent is invalid")
    end if

    edge_length = 0.0_dp
    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       if (field_level < 1) cycle
       if (field_level > zlevels) then
          call fail("Domain edge-metric field level is invalid")
       end if
       output_base = (level_slot-1)*n_value
       edge_length(output_base+1:output_base+n_value) = &
            grid(d)%len%elts(start+1:start+n_value)
    end do

  end subroutine pack_domain_patch_edge_length


  subroutine pack_domain_patch_velocity_recomposition ( &
       d,p,velocity_value,domain_sol,recompose)
    ! Form the authoritative non-Exner residual as trend plus the complete
    ! Exner term. Optionally apply the matching subtraction to provide an
    ! independent Domain reference for the rejected block recomposition.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    real(dp), intent(out) :: velocity_value(:)
    type(Float_Field), intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    logical, intent(in) :: recompose

    integer :: field_level
    integer :: first_field_level
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: n_value
    integer :: output_base
    integer :: source_base
    integer :: value_index
    integer :: v_scalar
    integer :: v_vector

    real(dp) :: exner_term
    real(dp) :: trend_value

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (mult_scalar /= 1 .or. mult_vector /= EDGE .or. &
         n_scalar_variable < 1 .or. v_scalar < 1 .or. v_vector < 1) then
       call fail("Domain velocity recomposition layout is invalid")
    end if
    n_value = EDGE*PATCH_SIZE**2
    if (size(velocity_value) /= n_field_level*n_value) then
       call fail("Domain velocity recomposition extent is invalid")
    end if

    call pack_domain_patch_exner_difference( &
         d,p,velocity_value,domain_sol,.true.,.true.)
    source_base = EDGE*grid(d)%patch%elts(p+1)%elts_start
    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       if (field_level < 1) cycle
       if (field_level > zlevels) then
          call fail("Domain velocity recomposition level is invalid")
       end if
       if (source_base < 0 .or. source_base+n_value > &
            size(trend(v_vector,field_level)%data(d)%elts)) then
          call fail("Domain velocity trend source extent is invalid")
       end if
       output_base = (level_slot-1)*n_value
       do value_index = 1,n_value
          exner_term = velocity_value(output_base+value_index)
          trend_value = trend(v_vector,field_level)%data(d)%elts( &
               source_base+value_index)
          velocity_value(output_base+value_index) = &
               trend_value + exner_term
          if (recompose) then
             velocity_value(output_base+value_index) = &
                  velocity_value(output_base+value_index) - exner_term
          end if
       end do
    end do

  end subroutine pack_domain_patch_velocity_recomposition


  subroutine pack_domain_patch_theta_edge (d,p,theta_edge,domain_sol)
    ! Independently reconstruct the potential-temperature edge averages
    ! used by the compressible velocity-gradient tendency from Domain data.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    real(dp), intent(out) :: theta_edge(:)
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: dims(2,N_BDRY+1)
    integer :: field_level
    integer :: first_field_level
    integer :: i
    integer :: id_center
    integer :: id_east
    integer :: id_north
    integer :: id_northeast
    integer :: j
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: offs(N_BDRY+1)
    integer :: output_base
    integer :: q
    integer :: v_scalar
    integer :: v_vector

    real(dp) :: mass_center
    real(dp) :: mass_east
    real(dp) :: mass_north
    real(dp) :: mass_northeast
    real(dp) :: temp_center
    real(dp) :: temp_east
    real(dp) :: temp_north
    real(dp) :: temp_northeast
    real(dp) :: theta_center
    real(dp) :: theta_east
    real(dp) :: theta_north
    real(dp) :: theta_northeast

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (mult_scalar /= 1 .or. mult_vector /= EDGE .or. &
         S_MASS < v_scalar .or. &
         S_MASS >= v_scalar+n_scalar_variable .or. &
         S_TEMP < v_scalar .or. &
         S_TEMP >= v_scalar+n_scalar_variable) then
       call fail("Domain theta-edge field layout is invalid")
    end if
    if (size(theta_edge) /= &
         n_field_level*EDGE*PATCH_SIZE**2) then
       call fail("Domain theta-edge payload extent is invalid")
    end if

    call get_offs_Domain(grid(d),p,offs,dims)
    theta_edge = 0.0_dp
    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       if (field_level < 1) cycle
       if (field_level > zlevels) then
          call fail("Domain theta-edge field level is invalid")
       end if
       output_base = (level_slot-1)*EDGE*PATCH_SIZE**2

       do j = 0,PATCH_SIZE-1
          do i = 0,PATCH_SIZE-1
             q = i + PATCH_SIZE*j
             id_center = idx(i,j,offs,dims)
             id_east = idx(i+1,j,offs,dims)
             id_northeast = idx(i+1,j+1,offs,dims)
             id_north = idx(i,j+1,offs,dims)

             if (present(domain_sol)) then
                mass_center = domain_sol(S_MASS,field_level)% &
                     data(d)%elts(id_center+1)
                mass_east = domain_sol(S_MASS,field_level)% &
                     data(d)%elts(id_east+1)
                mass_northeast = domain_sol(S_MASS,field_level)% &
                     data(d)%elts(id_northeast+1)
                mass_north = domain_sol(S_MASS,field_level)% &
                     data(d)%elts(id_north+1)
                temp_center = domain_sol(S_TEMP,field_level)% &
                     data(d)%elts(id_center+1)
                temp_east = domain_sol(S_TEMP,field_level)% &
                     data(d)%elts(id_east+1)
                temp_northeast = domain_sol(S_TEMP,field_level)% &
                     data(d)%elts(id_northeast+1)
                temp_north = domain_sol(S_TEMP,field_level)% &
                     data(d)%elts(id_north+1)
             else
                mass_center = sol(S_MASS,field_level)% &
                     data(d)%elts(id_center+1)
                mass_east = sol(S_MASS,field_level)% &
                     data(d)%elts(id_east+1)
                mass_northeast = sol(S_MASS,field_level)% &
                     data(d)%elts(id_northeast+1)
                mass_north = sol(S_MASS,field_level)% &
                     data(d)%elts(id_north+1)
                temp_center = sol(S_TEMP,field_level)% &
                     data(d)%elts(id_center+1)
                temp_east = sol(S_TEMP,field_level)% &
                     data(d)%elts(id_east+1)
                temp_northeast = sol(S_TEMP,field_level)% &
                     data(d)%elts(id_northeast+1)
                temp_north = sol(S_TEMP,field_level)% &
                     data(d)%elts(id_north+1)
             end if

             mass_center = mass_center + sol_mean(S_MASS,field_level)% &
                  data(d)%elts(id_center+1)
             mass_east = mass_east + sol_mean(S_MASS,field_level)% &
                  data(d)%elts(id_east+1)
             mass_northeast = mass_northeast + &
                  sol_mean(S_MASS,field_level)%data(d)%elts( &
                  id_northeast+1)
             mass_north = mass_north + sol_mean(S_MASS,field_level)% &
                  data(d)%elts(id_north+1)
             temp_center = temp_center + sol_mean(S_TEMP,field_level)% &
                  data(d)%elts(id_center+1)
             temp_east = temp_east + sol_mean(S_TEMP,field_level)% &
                  data(d)%elts(id_east+1)
             temp_northeast = temp_northeast + &
                  sol_mean(S_TEMP,field_level)%data(d)%elts( &
                  id_northeast+1)
             temp_north = temp_north + sol_mean(S_TEMP,field_level)% &
                  data(d)%elts(id_north+1)

             if (min(mass_center,mass_east,mass_northeast,mass_north) &
                  <= 0.0_dp) then
                call fail("Domain theta-edge reconstruction has bad mass")
             end if
             theta_center = temp_center/mass_center
             theta_east = temp_east/mass_east
             theta_northeast = temp_northeast/mass_northeast
             theta_north = temp_north/mass_north

             theta_edge(output_base+EDGE*q+RT+1) = &
                  0.5_dp*(theta_center+theta_east)
             theta_edge(output_base+EDGE*q+DG+1) = &
                  0.5_dp*(theta_center+theta_northeast)
             theta_edge(output_base+EDGE*q+UP+1) = &
                  0.5_dp*(theta_center+theta_north)
          end do
       end do
    end do

  end subroutine pack_domain_patch_theta_edge


  subroutine pack_domain_patch_exner_difference ( &
       d,p,exner_difference,domain_sol,thermodynamic_product, &
       metric_division)
    ! Independently reconstruct the signed dynamic-Exner differences that
    ! form the numerator of gradi_e(exner) on each physical edge.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    real(dp), intent(out) :: exner_difference(:)
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    logical, optional, intent(in) :: thermodynamic_product
    logical, optional, intent(in) :: metric_division

    integer :: component_slot
    integer :: dims(2,N_BDRY+1)
    integer :: field_level
    integer :: first_field_level
    integer :: i
    integer :: id_center
    integer :: id_east
    integer :: id_north
    integer :: id_northeast
    integer :: j
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: offs(N_BDRY+1)
    integer :: output_base
    integer :: q
    integer :: v_scalar
    integer :: v_vector

    real(dp) :: exner_center
    real(dp) :: exner_east
    real(dp) :: exner_north
    real(dp) :: exner_northeast
    real(dp) :: theta_center
    real(dp) :: theta_east
    real(dp) :: theta_north
    real(dp) :: theta_northeast

    logical :: apply_theta
    logical :: apply_metric

    apply_theta = .false.
    if (present(thermodynamic_product)) then
       apply_theta = thermodynamic_product
    end if
    apply_metric = .false.
    if (present(metric_division)) then
       apply_metric = metric_division
    end if
    if (apply_metric .and. .not. apply_theta) then
       call fail("Domain complete Exner-gradient mode is invalid")
    end if

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (mult_scalar /= 1 .or. mult_vector /= EDGE .or. &
         S_MASS < v_scalar .or. &
         S_MASS >= v_scalar+n_scalar_variable .or. &
         (apply_theta .and. &
         (S_TEMP < v_scalar .or. &
         S_TEMP >= v_scalar+n_scalar_variable)) .or. &
         v_vector < 1) then
       call fail("Domain Exner-difference field layout is invalid")
    end if
    if (size(exner_difference) /= &
         n_field_level*EDGE*PATCH_SIZE**2) then
       call fail("Domain Exner-difference payload extent is invalid")
    end if

    call get_offs_Domain(grid(d),p,offs,dims)
    exner_difference = 0.0_dp
    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       if (field_level < 1) cycle
       if (field_level > zlevels) then
          call fail("Domain Exner-difference field level is invalid")
       end if
       output_base = (level_slot-1)*EDGE*PATCH_SIZE**2

       do j = 0,PATCH_SIZE-1
          do i = 0,PATCH_SIZE-1
             q = i + PATCH_SIZE*j
             id_center = idx(i,j,offs,dims)
             id_east = idx(i+1,j,offs,dims)
             id_northeast = idx(i+1,j+1,offs,dims)
             id_north = idx(i,j+1,offs,dims)

             exner_center = domain_dynamic_exner( &
                  id_center,field_level)
             exner_east = domain_dynamic_exner(id_east,field_level)
             exner_northeast = domain_dynamic_exner( &
                  id_northeast,field_level)
             exner_north = domain_dynamic_exner(id_north,field_level)

             exner_difference(output_base+EDGE*q+RT+1) = &
                  exner_east-exner_center
             exner_difference(output_base+EDGE*q+DG+1) = &
                  exner_center-exner_northeast
             exner_difference(output_base+EDGE*q+UP+1) = &
                  exner_north-exner_center
             if (apply_theta) then
                theta_center = domain_potential_temperature( &
                     id_center,field_level)
                theta_east = domain_potential_temperature( &
                     id_east,field_level)
                theta_northeast = domain_potential_temperature( &
                     id_northeast,field_level)
                theta_north = domain_potential_temperature( &
                     id_north,field_level)
                exner_difference(output_base+EDGE*q+RT+1) = &
                     exner_difference(output_base+EDGE*q+RT+1)* &
                     (0.5_dp*(theta_center+theta_east))
                exner_difference(output_base+EDGE*q+DG+1) = &
                     exner_difference(output_base+EDGE*q+DG+1)* &
                     (0.5_dp*(theta_center+theta_northeast))
                exner_difference(output_base+EDGE*q+UP+1) = &
                     exner_difference(output_base+EDGE*q+UP+1)* &
                     (0.5_dp*(theta_center+theta_north))
             end if
             if (apply_metric) then
                if (any(grid(d)%len%elts( &
                     EDGE*id_center+RT+1:EDGE*id_center+UP+1) <= &
                     0.0_dp)) then
                   call fail("Domain Exner-gradient edge length is invalid")
                end if
                do component_slot = 1,EDGE
                   exner_difference( &
                        output_base+EDGE*q+component_slot) = &
                        exner_difference( &
                        output_base+EDGE*q+component_slot)/ &
                        grid(d)%len%elts( &
                        EDGE*id_center+component_slot)
                end do
             end if
          end do
       end do
    end do

  contains

    real(dp) function domain_dynamic_exner (node,field_level) &
         result(exner_value)

      implicit none

      integer, intent(in) :: node
      integer, intent(in) :: field_level

      integer :: k

      real(dp) :: layer_pressure
      real(dp) :: pressure_lower
      real(dp) :: rho_dz

      pressure_lower = p_top
      do k = 1,zlevels
         rho_dz = domain_scalar_total(S_MASS,node,k)
         if (rho_dz <= 0.0_dp) then
            call fail("Domain Exner-difference diagnosed bad mass")
         end if
         pressure_lower = pressure_lower + grav_accel*rho_dz
      end do
      do k = 1,field_level-1
         pressure_lower = pressure_lower - &
              grav_accel*domain_scalar_total(S_MASS,node,k)
      end do
      rho_dz = domain_scalar_total(S_MASS,node,field_level)
      layer_pressure = pressure_lower - 0.5_dp*grav_accel*rho_dz
      if (layer_pressure <= 0.0_dp) then
         call fail("Domain Exner-difference pressure is nonpositive")
      end if
      exner_value = c_p*(layer_pressure/p_0)**kappa

    end function domain_dynamic_exner


    real(dp) function domain_potential_temperature ( &
         node,field_level) result(value)

      implicit none

      integer, intent(in) :: node
      integer, intent(in) :: field_level

      real(dp) :: rho_dz

      rho_dz = domain_scalar_total(S_MASS,node,field_level)
      if (rho_dz <= 0.0_dp) then
         call fail("Domain thermodynamic gradient has bad mass")
      end if
      value = domain_scalar_total(S_TEMP,node,field_level)/rho_dz

    end function domain_potential_temperature


    real(dp) function domain_scalar_total ( &
         scalar_id,node,field_level) result(value)

      implicit none

      integer, intent(in) :: scalar_id
      integer, intent(in) :: node
      integer, intent(in) :: field_level

      if (node < 0 .or. node >= &
           size(sol_mean(scalar_id,field_level)%data(d)%elts)) then
         call fail("Domain Exner-difference node is invalid")
      end if
      if (present(domain_sol)) then
         if (node >= &
              size(domain_sol(scalar_id,field_level)%data(d)%elts)) then
            call fail("Domain Exner-difference stage extent is invalid")
         end if
         value = domain_sol(scalar_id,field_level)%data(d)%elts(node+1)
      else
         if (node >= size(sol(scalar_id,field_level)%data(d)%elts)) then
            call fail("Domain Exner-difference sol extent is invalid")
         end if
         value = sol(scalar_id,field_level)%data(d)%elts(node+1)
      end if
      value = value + &
           sol_mean(scalar_id,field_level)%data(d)%elts(node+1)

    end function domain_scalar_total

  end subroutine pack_domain_patch_exner_difference


  subroutine reconstruct_block_writeback_domain_stage ( &
       payload_family,component_family)
    ! Reconstruct every active patch of each locally owned legacy Domain in
    ! persistent non-authoritative staging arrays. Retained blocks are read
    ! directly, remote blocks are consumed from the writeback buffers and
    ! fixed coarse-scaffold patches outside the catalogue are preserved.

    implicit none

    integer, intent(in) :: payload_family
    integer, optional, intent(in) :: component_family

    integer :: active_patch_count
    integer :: b
    integer :: d
    integer :: destination
    integer :: expected_patch_count
    integer :: local_index
    integer :: local_patch
    integer :: n_patch
    integer :: p
    integer :: patch_slot
    integer :: pos_scalar
    integer :: pos_vector
    integer :: preserved_patch_count
    integer :: r
    integer :: reconstructed_patch_count
    integer :: scalar_limit
    integer :: scalar_start
    integer :: slot
    integer :: vector_limit
    integer :: vector_stage_start
    integer :: vector_start
    integer :: scalar_stage_start

    if (.not. block_writeback_plan_is_ready()) then
       call fail("Domain reconstruction before writeback plan is ready")
    end if
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF) then
       call fail("invalid Domain reconstruction payload family")
    end if
    if (.not. allocated( &
         block_writeback_plan%domain_patch_reconstructed)) then
       call fail("Domain reconstruction patch origin is not allocated")
    end if
    if (size(block_writeback_plan%domain_patch_reconstructed) /= &
         size(block_writeback_plan%domain_patch_covered)) then
       call fail("Domain reconstruction patch origin extent mismatch")
    end if

    call exchange_block_writeback_payloads( &
         payload_family,component_family)

    block_writeback_plan%scalar_domain_stage = 0.0_dp
    block_writeback_plan%vector_domain_stage = 0.0_dp
    block_writeback_plan%domain_patch_covered = .false.
    block_writeback_plan%domain_patch_reconstructed = .false.
    reconstructed_patch_count = 0
    preserved_patch_count = 0

    do local_index = 1,n_local_blocks()
       b = local_block_catalog(local_index)
       destination = source_rank(b)
       if (destination /= rank) cycle
       d = loc_id(block_catalog(b)%root_domain+1) + 1
       if (d < 1 .or. d > size(grid)) then
          call fail("retained writeback block has invalid local Domain")
       end if

       local_patch = 0
       n_patch = 0
       call stage_local_subtree( &
            d,block_catalog(b)%root_patch,b,payload_family, &
            local_patch,n_patch)
       expected_patch_count = local_block_patch_count(b)
       if (local_patch /= expected_patch_count .or. &
            n_patch /= expected_patch_count) then
          call fail("retained writeback block reconstruction is incomplete")
       end if
       reconstructed_patch_count = reconstructed_patch_count + n_patch
    end do

    do r = 1,n_process
       pos_scalar = block_writeback_plan%scalar_recv_displ(r) + 1
       pos_vector = block_writeback_plan%vector_recv_displ(r) + 1

       do slot = block_writeback_plan%recv_displ(r)+1, &
            block_writeback_plan%recv_displ(r) + &
            block_writeback_plan%recv_count(r)
          b = block_writeback_plan%recv_block(slot)
          destination = source_rank(b)
          if (destination /= rank) then
             call fail("received reconstruction block has wrong Domain owner")
          end if
          if (block_catalog(b)%owner /= r-1) then
             call fail("received reconstruction block has wrong source owner")
          end if

          d = loc_id(block_catalog(b)%root_domain+1) + 1
          if (d < 1 .or. d > size(grid)) then
             call fail("received writeback block has invalid local Domain")
          end if

          scalar_start = pos_scalar
          vector_start = pos_vector
          scalar_limit = scalar_start + &
               block_writeback_plan%recv_scalar_nvalue(slot) - 1
          vector_limit = vector_start + &
               block_writeback_plan%recv_vector_nvalue(slot) - 1
          n_patch = 0
          call stage_buffer_subtree( &
               d,block_catalog(b)%root_patch, &
               block_writeback_plan%scalar_recv_buffer,pos_scalar, &
               scalar_limit,block_writeback_plan%vector_recv_buffer, &
               pos_vector,vector_limit,n_patch)

          if (n_patch /= &
               block_writeback_plan%recv_patch_count(slot) .or. &
               pos_scalar-scalar_start /= &
               block_writeback_plan%recv_scalar_nvalue(slot) .or. &
               pos_vector-vector_start /= &
               block_writeback_plan%recv_vector_nvalue(slot)) then
             call fail("received Domain reconstruction extent mismatch")
          end if
          reconstructed_patch_count = reconstructed_patch_count + n_patch
       end do

       if (pos_scalar /= block_writeback_plan%scalar_recv_displ(r) + &
            block_writeback_plan%scalar_recv_count(r) + 1 .or. &
            pos_vector /= block_writeback_plan%vector_recv_displ(r) + &
            block_writeback_plan%vector_recv_count(r) + 1) then
          call fail("Domain reconstruction receive extent mismatch")
       end if
    end do

    if (count(block_writeback_plan%domain_patch_covered) /= &
         reconstructed_patch_count) then
       call fail("block-derived Domain patch coverage is inconsistent")
    end if
    if (count(block_writeback_plan%domain_patch_reconstructed) /= &
         reconstructed_patch_count) then
       call fail("block-derived Domain patch origin is inconsistent")
    end if

    active_patch_count = 0
    do d = 1,size(grid)
       do p = 0,grid(d)%patch%length-1
          patch_slot = block_writeback_plan%domain_patch_displ(d) + p + 1
          if (grid(d)%patch%elts(p+1)%deleted) then
             if (block_writeback_plan%domain_patch_covered(patch_slot)) then
                call fail("deleted Domain patch was reconstructed")
             end if
          else
             active_patch_count = active_patch_count + 1
             if (.not. &
                  block_writeback_plan%domain_patch_covered(patch_slot)) then
                scalar_stage_start = (patch_slot-1)* &
                     block_writeback_plan%scalar_patch_nvalue + 1
                vector_stage_start = (patch_slot-1)* &
                     block_writeback_plan%vector_patch_nvalue + 1
                call pack_domain_patch_prognostic( &
                     d,p,payload_family, &
                     block_writeback_plan%scalar_domain_stage, &
                     scalar_stage_start, &
                     block_writeback_plan%vector_domain_stage, &
                     vector_stage_start)
                block_writeback_plan%domain_patch_covered(patch_slot) = &
                     .true.
                preserved_patch_count = preserved_patch_count + 1
             end if
          end if
       end do
    end do

    if (count(block_writeback_plan%domain_patch_covered) /= &
         active_patch_count) then
       call fail("Domain reconstruction patch coverage is not exact")
    end if
    if (active_patch_count /= reconstructed_patch_count + &
         preserved_patch_count) then
       call fail("complete Domain reconstruction count is inconsistent")
    end if

    block_writeback_plan%reconstructed_patch_count = &
         reconstructed_patch_count
    block_writeback_plan%preserved_patch_count = preserved_patch_count

  contains

    subroutine claim_domain_patch ( &
         d,p,scalar_stage_start,vector_stage_start)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(out) :: scalar_stage_start
      integer, intent(out) :: vector_stage_start

      integer :: claimed_slot

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("invalid patch in Domain reconstruction")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) then
         call fail("deleted patch in Domain reconstruction")
      end if

      claimed_slot = &
           block_writeback_plan%domain_patch_displ(d) + p + 1
      if (block_writeback_plan%domain_patch_covered(claimed_slot)) then
         call fail("Domain patch was reconstructed more than once")
      end if
      block_writeback_plan%domain_patch_covered(claimed_slot) = .true.
      block_writeback_plan%domain_patch_reconstructed(claimed_slot) = &
           .true.

      scalar_stage_start = (claimed_slot-1)* &
           block_writeback_plan%scalar_patch_nvalue + 1
      vector_stage_start = (claimed_slot-1)* &
           block_writeback_plan%vector_patch_nvalue + 1

    end subroutine claim_domain_patch


    recursive subroutine stage_local_subtree ( &
         d,p,b,payload_family,local_patch,n_patch)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: b
      integer, intent(in) :: payload_family
      integer, intent(inout) :: local_patch
      integer, intent(inout) :: n_patch

      integer :: c
      integer :: p_child
      integer :: scalar_stage_start
      integer :: vector_stage_start

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("invalid retained patch in Domain reconstruction")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return
      if (local_patch >= local_block_patch_count(b)) then
         call fail("retained block patch traversal exceeded extent")
      end if

      call claim_domain_patch( &
           d,p,scalar_stage_start,vector_stage_start)
      call get_local_block_scalar_patch_family_values( &
           b,local_patch,payload_family, &
           block_writeback_plan%scalar_domain_stage( &
           scalar_stage_start:scalar_stage_start+ &
           block_writeback_plan%scalar_patch_nvalue-1))
      call get_local_block_vector_patch_family_values( &
           b,local_patch,payload_family, &
           block_writeback_plan%vector_domain_stage( &
           vector_stage_start:vector_stage_start+ &
           block_writeback_plan%vector_patch_nvalue-1))
      local_patch = local_patch + 1
      n_patch = n_patch + 1

      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call stage_local_subtree( &
              d,p_child,b,payload_family,local_patch,n_patch)
      end do

    end subroutine stage_local_subtree


    recursive subroutine stage_buffer_subtree ( &
         d,p,scalar_payload,scalar_pos,scalar_limit, &
         vector_payload,vector_pos,vector_limit,n_patch)

      implicit none

      integer, intent(in) :: d
      integer, intent(in) :: p
      real(dp), intent(in) :: scalar_payload(:)
      integer, intent(inout) :: scalar_pos
      integer, intent(in) :: scalar_limit
      real(dp), intent(in) :: vector_payload(:)
      integer, intent(inout) :: vector_pos
      integer, intent(in) :: vector_limit
      integer, intent(inout) :: n_patch

      integer :: c
      integer :: p_child
      integer :: scalar_stage_start
      integer :: vector_stage_start

      if (p < 0 .or. p >= grid(d)%patch%length) then
         call fail("invalid received patch in Domain reconstruction")
      end if
      if (grid(d)%patch%elts(p+1)%deleted) return
      if (scalar_pos+block_writeback_plan%scalar_patch_nvalue-1 > &
           scalar_limit .or. &
           vector_pos+block_writeback_plan%vector_patch_nvalue-1 > &
           vector_limit) then
         call fail("received block payload ended during reconstruction")
      end if

      call claim_domain_patch( &
           d,p,scalar_stage_start,vector_stage_start)
      block_writeback_plan%scalar_domain_stage( &
           scalar_stage_start:scalar_stage_start+ &
           block_writeback_plan%scalar_patch_nvalue-1) = &
           scalar_payload(scalar_pos:scalar_pos+ &
           block_writeback_plan%scalar_patch_nvalue-1)
      block_writeback_plan%vector_domain_stage( &
           vector_stage_start:vector_stage_start+ &
           block_writeback_plan%vector_patch_nvalue-1) = &
           vector_payload(vector_pos:vector_pos+ &
           block_writeback_plan%vector_patch_nvalue-1)
      scalar_pos = scalar_pos + &
           block_writeback_plan%scalar_patch_nvalue
      vector_pos = vector_pos + &
           block_writeback_plan%vector_patch_nvalue
      n_patch = n_patch + 1

      do c = 1,N_CHDRN
         p_child = grid(d)%patch%elts(p+1)%children(c)
         if (p_child <= 0) cycle
         call stage_buffer_subtree( &
              d,p_child,scalar_payload,scalar_pos,scalar_limit, &
              vector_payload,vector_pos,vector_limit,n_patch)
      end do

    end subroutine stage_buffer_subtree

  end subroutine reconstruct_block_writeback_domain_stage


  logical function domain_patch_prognostic_extent_is_valid ( &
       d,p,payload_family,domain_sol) result(valid)
    ! Preflight every authoritative array section touched by one patch.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    integer, intent(in) :: payload_family
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: field_level
    integer :: first_field_level
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: n_value
    integer :: scalar_id
    integer :: scalar_slot
    integer :: start
    integer :: v_scalar
    integer :: v_vector

    valid = .false.
    if (d < 1 .or. d > size(grid)) return
    if (p < 0 .or. p >= grid(d)%patch%length) return
    if (grid(d)%patch%elts(p+1)%deleted) return
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF) return

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)
    if (v_scalar < 1 .or. v_vector < 1 .or. &
         n_scalar_variable < 1 .or. n_field_level < 1 .or. &
         mult_scalar < 1 .or. mult_vector < 1) return

    start = mult_scalar*grid(d)%patch%elts(p+1)%elts_start
    n_value = mult_scalar*PATCH_SIZE**2
    if (start < 0) return
    do scalar_slot = 1,n_scalar_variable
       scalar_id = v_scalar + scalar_slot - 1
       do level_slot = 1,n_field_level
          field_level = first_field_level + level_slot - 1
          select case (payload_family)
          case (BLOCK_PAYLOAD_SOL)
             if (present(domain_sol) .and. field_level >= 1 .and. &
                  field_level <= zlevels) then
                if (start+n_value > size( &
                     domain_sol(scalar_id,field_level)%data(d)%elts)) return
             else
                if (start+n_value > &
                     size(sol(scalar_id,field_level)%data(d)%elts)) return
             end if
          case (BLOCK_PAYLOAD_WAV_COEFF)
             if (present(domain_sol) .and. field_level >= 1 .and. &
                  field_level <= zlevels) then
                if (start+n_value > size( &
                     domain_sol(scalar_id,field_level)%data(d)%elts)) return
             else
                if (start+n_value > size( &
                     wav_coeff(scalar_id,field_level)%data(d)%elts)) return
             end if
          end select
       end do
    end do

    start = mult_vector*grid(d)%patch%elts(p+1)%elts_start
    n_value = mult_vector*PATCH_SIZE**2
    if (start < 0) return
    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       select case (payload_family)
       case (BLOCK_PAYLOAD_SOL)
          if (present(domain_sol) .and. field_level >= 1 .and. &
               field_level <= zlevels) then
             if (start+n_value > size( &
                  domain_sol(v_vector,field_level)%data(d)%elts)) return
          else
             if (start+n_value > &
                  size(sol(v_vector,field_level)%data(d)%elts)) return
          end if
       case (BLOCK_PAYLOAD_WAV_COEFF)
          if (present(domain_sol) .and. field_level >= 1 .and. &
               field_level <= zlevels) then
             if (start+n_value > size( &
                  domain_sol(v_vector,field_level)%data(d)%elts)) return
          else
             if (start+n_value > &
                  size(wav_coeff(v_vector,field_level)%data(d)%elts)) return
          end if
       end select
    end do

    valid = .true.

  end function domain_patch_prognostic_extent_is_valid


  logical function block_writeback_domain_stage_is_valid ( &
       payload_family,domain_sol) result(valid)
    ! Validate complete coverage and every destination extent before the
    ! first authoritative value is changed.

    implicit none

    integer, intent(in) :: payload_family
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)

    integer :: active_patch_count
    integer :: d
    integer :: p
    integer :: patch_slot
    integer :: scalar_start
    integer :: vector_start

    logical :: plan_ready
    logical :: patch_extent_valid

    valid = .false.
    plan_ready = block_writeback_plan_is_ready()
    if (.not. plan_ready) return
    if (payload_family /= BLOCK_PAYLOAD_SOL .and. &
         payload_family /= BLOCK_PAYLOAD_WAV_COEFF) return
    if (.not. allocated(block_writeback_plan%domain_patch_displ)) return
    if (.not. allocated(block_writeback_plan%domain_patch_covered)) return
    if (.not. allocated( &
         block_writeback_plan%domain_patch_reconstructed)) return
    if (size(block_writeback_plan%domain_patch_reconstructed) /= &
         size(block_writeback_plan%domain_patch_covered)) return
    if (.not. allocated(block_writeback_plan%scalar_domain_stage)) return
    if (.not. allocated(block_writeback_plan%vector_domain_stage)) return
    if (block_writeback_plan%scalar_patch_nvalue <= 0 .or. &
         block_writeback_plan%vector_patch_nvalue <= 0) return

    active_patch_count = 0
    do d = 1,size(grid)
       do p = 0,grid(d)%patch%length-1
          patch_slot = &
               block_writeback_plan%domain_patch_displ(d) + p + 1
          if (patch_slot < 1 .or. patch_slot > &
               size(block_writeback_plan%domain_patch_covered)) return
          if (grid(d)%patch%elts(p+1)%deleted) then
             if (block_writeback_plan%domain_patch_covered(patch_slot)) &
                  return
             if (block_writeback_plan% &
                  domain_patch_reconstructed(patch_slot)) return
             cycle
          end if

          active_patch_count = active_patch_count + 1
          if (.not. &
               block_writeback_plan%domain_patch_covered(patch_slot)) return

          scalar_start = (patch_slot-1)* &
               block_writeback_plan%scalar_patch_nvalue + 1
          vector_start = (patch_slot-1)* &
               block_writeback_plan%vector_patch_nvalue + 1
          if (scalar_start < 1 .or. scalar_start + &
               block_writeback_plan%scalar_patch_nvalue - 1 > &
               size(block_writeback_plan%scalar_domain_stage)) return
          if (vector_start < 1 .or. vector_start + &
               block_writeback_plan%vector_patch_nvalue - 1 > &
               size(block_writeback_plan%vector_domain_stage)) return

          if (present(domain_sol)) then
             patch_extent_valid = &
                  domain_patch_prognostic_extent_is_valid( &
                  d,p,payload_family,domain_sol)
          else
             patch_extent_valid = &
                  domain_patch_prognostic_extent_is_valid( &
                  d,p,payload_family)
          end if
          if (.not. patch_extent_valid) return
       end do
    end do

    if (active_patch_count /= &
         block_writeback_plan%reconstructed_patch_count + &
         block_writeback_plan%preserved_patch_count) return
    if (count(block_writeback_plan%domain_patch_covered) /= &
         active_patch_count) return
    if (count(block_writeback_plan%domain_patch_reconstructed) /= &
         block_writeback_plan%reconstructed_patch_count) return

    valid = .true.

  end function block_writeback_domain_stage_is_valid


  subroutine write_domain_patch_prognostic ( &
       d,p,payload_family,scalar_payload,scalar_pos, &
       vector_payload,vector_pos,domain_sol,component_family)
    ! Copy one already validated staged patch into authoritative fields.

    implicit none

    integer, intent(in) :: d
    integer, intent(in) :: p
    integer, intent(in) :: payload_family
    real(dp), intent(in) :: scalar_payload(:)
    integer, intent(inout) :: scalar_pos
    real(dp), intent(in) :: vector_payload(:)
    integer, intent(inout) :: vector_pos
    type(Float_Field), optional, intent(inout) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    integer, optional, intent(in) :: component_family

    integer :: field_level
    integer :: first_field_level
    integer :: level_slot
    integer :: mult_scalar
    integer :: mult_vector
    integer :: n_field_level
    integer :: n_scalar_variable
    integer :: n_value
    integer :: scalar_id
    integer :: scalar_slot
    integer :: start
    integer :: v_scalar
    integer :: v_vector
    integer :: component

    component = BLOCK_WRITEBACK_BOTH
    if (present(component_family)) component = component_family

    call get_block_field_layout( &
         v_scalar,n_scalar_variable,v_vector,first_field_level, &
         n_field_level,mult_scalar,mult_vector)

    start = mult_scalar*grid(d)%patch%elts(p+1)%elts_start
    n_value = mult_scalar*PATCH_SIZE**2
    do scalar_slot = 1,n_scalar_variable
       scalar_id = v_scalar + scalar_slot - 1
       do level_slot = 1,n_field_level
          field_level = first_field_level + level_slot - 1
          if (component /= BLOCK_WRITEBACK_VECTOR) then
             select case (payload_family)
          case (BLOCK_PAYLOAD_SOL)
             if (present(domain_sol) .and. field_level >= 1 .and. &
                  field_level <= zlevels) then
                domain_sol(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value) = &
                     scalar_payload(scalar_pos:scalar_pos+n_value-1)
             else
                sol(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value) = &
                     scalar_payload(scalar_pos:scalar_pos+n_value-1)
             end if
          case (BLOCK_PAYLOAD_WAV_COEFF)
             if (present(domain_sol) .and. field_level >= 1 .and. &
                  field_level <= zlevels) then
                domain_sol(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value) = &
                     scalar_payload(scalar_pos:scalar_pos+n_value-1)
             else
                wav_coeff(scalar_id,field_level)%data(d)%elts( &
                     start+1:start+n_value) = &
                     scalar_payload(scalar_pos:scalar_pos+n_value-1)
             end if
             end select
          end if
          scalar_pos = scalar_pos + n_value
       end do
    end do

    start = mult_vector*grid(d)%patch%elts(p+1)%elts_start
    n_value = mult_vector*PATCH_SIZE**2
    do level_slot = 1,n_field_level
       field_level = first_field_level + level_slot - 1
       if (component /= BLOCK_WRITEBACK_SCALAR) then
          select case (payload_family)
          case (BLOCK_PAYLOAD_SOL)
          if (present(domain_sol) .and. field_level >= 1 .and. &
               field_level <= zlevels) then
             domain_sol(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value) = &
                  vector_payload(vector_pos:vector_pos+n_value-1)
          else
             sol(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value) = &
                  vector_payload(vector_pos:vector_pos+n_value-1)
          end if
          case (BLOCK_PAYLOAD_WAV_COEFF)
          if (present(domain_sol) .and. field_level >= 1 .and. &
               field_level <= zlevels) then
             domain_sol(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value) = &
                  vector_payload(vector_pos:vector_pos+n_value-1)
          else
             wav_coeff(v_vector,field_level)%data(d)%elts( &
                  start+1:start+n_value) = &
                  vector_payload(vector_pos:vector_pos+n_value-1)
          end if
          end select
       end if
       vector_pos = vector_pos + n_value
    end do

  end subroutine write_domain_patch_prognostic


  logical function try_commit_block_writeback_domain_stage ( &
       payload_family,domain_sol,component_family) result(committed)
    ! Commit only after a complete preflight. A rejected transaction leaves
    ! every authoritative Domain value untouched.

    implicit none

    integer, intent(in) :: payload_family
    type(Float_Field), optional, intent(inout) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    integer, optional, intent(in) :: component_family

    integer :: d
    integer :: p
    integer :: patch_slot
    integer :: scalar_pos
    integer :: vector_pos

    logical :: stage_valid

    committed = .false.
    if (present(domain_sol)) then
       stage_valid = block_writeback_domain_stage_is_valid( &
            payload_family,domain_sol)
    else
       stage_valid = &
            block_writeback_domain_stage_is_valid(payload_family)
    end if
    if (.not. stage_valid) return

    do d = 1,size(grid)
       do p = 0,grid(d)%patch%length-1
          if (grid(d)%patch%elts(p+1)%deleted) cycle
          patch_slot = &
               block_writeback_plan%domain_patch_displ(d) + p + 1
          scalar_pos = (patch_slot-1)* &
               block_writeback_plan%scalar_patch_nvalue + 1
          vector_pos = (patch_slot-1)* &
               block_writeback_plan%vector_patch_nvalue + 1
          if (present(domain_sol)) then
             call write_domain_patch_prognostic( &
                  d,p,payload_family, &
                  block_writeback_plan%scalar_domain_stage,scalar_pos, &
                  block_writeback_plan%vector_domain_stage,vector_pos, &
                  domain_sol,component_family)
          else
             call write_domain_patch_prognostic( &
                  d,p,payload_family, &
                  block_writeback_plan%scalar_domain_stage,scalar_pos, &
                  block_writeback_plan%vector_domain_stage,vector_pos, &
                  component_family=component_family)
          end if
       end do
    end do

    committed = .true.

  end function try_commit_block_writeback_domain_stage


  subroutine write_block_field_family_to_domains ( &
       payload_family,domain_sol,component_family)
    ! Production-facing transaction for one prognostic field family.
    ! Reconstruction and complete validation precede authoritative mutation.

    implicit none

    integer, intent(in) :: payload_family
    type(Float_Field), optional, intent(inout) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    integer, optional, intent(in) :: component_family

    logical :: committed

    call block_profile_enter(BLOCK_PROFILE_WRITEBACK)
    call reconstruct_block_writeback_domain_stage( &
         payload_family,component_family)
    if (present(domain_sol)) then
       committed = try_commit_block_writeback_domain_stage( &
            payload_family,domain_sol,component_family)
    else
       committed = &
            try_commit_block_writeback_domain_stage( &
            payload_family,component_family=component_family)
    end if
    if (.not. committed) then
       call fail("complete block-to-Domain transaction was rejected")
    end if
    if (payload_family == BLOCK_PAYLOAD_SOL) then
       ! Match RK_sub_step semantics.  A newly materialized RK stage has not
       ! had its Domain boundary storage refreshed.  Oracle builds used to
       ! hide this requirement because the legacy RK_sub_step cleared these
       ! flags before the native writeback.
       if (present(domain_sol)) then
          domain_sol%bdry_uptodate = .false.
       else
          sol%bdry_uptodate = .false.
       end if
    end if
    block_writeback_plan%production_writeback_count = &
         block_writeback_plan%production_writeback_count + 1_int64
    compatibility_writeback_total = &
         compatibility_writeback_total + 1_int64

    call block_profile_leave( &
         BLOCK_PROFILE_WRITEBACK,int(n_local_blocks(),int64))

  end subroutine write_block_field_family_to_domains


  subroutine assert_block_domain_field_family_match ( &
       payload_family,domain_sol,integrated_only,compared_patch_count, &
       comparison_name,roundoff_tolerant)
    ! Reconstruct one family from final-owner blocks and compare every
    ! active authoritative Domain value. Copies and writebacks must match
    ! exactly. Independently evaluated pre-wavelet RK candidates allow only
    ! a small pointwise roundoff tolerance and may restrict comparison to
    ! patches initialized by RK_sub_step.

    implicit none

    integer, intent(in) :: payload_family
    type(Float_Field), optional, intent(in) :: &
         domain_sol(1:N_VARIABLE,1:zlevels)
    logical, optional, intent(in) :: integrated_only
    integer(int64), optional, intent(out) :: compared_patch_count
    character(len=*), optional, intent(in) :: comparison_name
    logical, optional, intent(in) :: roundoff_tolerant

    integer :: d
    integer :: p
    integer :: patch_slot
    integer :: production_node_start
    integer :: scalar_pos
    integer :: scalar_start
    integer :: value_index
    integer :: vector_pos
    integer :: vector_start

    integer(int64) :: patch_count

    logical :: compare_integrated_only
    logical :: allow_roundoff
    logical :: validate_oracle

    real(dp) :: current_scalar( &
         block_writeback_plan%scalar_patch_nvalue)
    real(dp) :: current_vector( &
         block_writeback_plan%vector_patch_nvalue)
    real(dp) :: scalar_difference( &
         block_writeback_plan%scalar_patch_nvalue)
    real(dp) :: scalar_tolerance( &
         block_writeback_plan%scalar_patch_nvalue)
    real(dp) :: vector_difference( &
         block_writeback_plan%vector_patch_nvalue)
    real(dp) :: vector_tolerance( &
         block_writeback_plan%vector_patch_nvalue)
    real(dp) :: allowed_difference
    real(dp) :: block_value
    real(dp) :: current_value
    real(dp) :: difference

    compare_integrated_only = .false.
    if (present(integrated_only)) then
       compare_integrated_only = integrated_only
    end if
    if (compare_integrated_only .and. .not. present(domain_sol)) then
       call fail("integrated block/Domain comparison requires stage sol")
    end if
    allow_roundoff = .false.
    if (present(roundoff_tolerant)) then
       allow_roundoff = roundoff_tolerant
    end if
    ! Evaluate this impure environment-backed query unconditionally.  Keeping
    ! it out of a short-circuit expression avoids -Wfunction-elimination and
    ! gives the validation switch one well-defined value for this comparison.
    validate_oracle = block_dynamics_validation_enabled()
    ! Without redundant native-to-Domain RK-stage publication, independently
    ! accumulated SOL images legitimately differ in their last few bits until
    ! the multistage wavelet transaction is accepted.  Keep every comparison
    ! outside that narrowly scoped transaction bitwise exact.
    if (payload_family == BLOCK_PAYLOAD_SOL .and. &
         production_multistage_candidate_stage_count > 0 .and. &
         validate_oracle) allow_roundoff = .true.

    patch_count = 0_int64
    call reconstruct_block_writeback_domain_stage(payload_family)

    do d = 1,size(grid)
       do p = 0,grid(d)%patch%length-1
          if (grid(d)%patch%elts(p+1)%deleted) cycle
          if (compare_integrated_only) then
             if (grid(d)%patch%length < 3) then
                call fail("integrated RK Domain patch inventory is invalid")
             end if
             production_node_start = &
                  grid(d)%patch%elts(3)%elts_start
             if (grid(d)%patch%elts(p+1)%elts_start < &
                  production_node_start) cycle
          end if
          patch_slot = &
               block_writeback_plan%domain_patch_displ(d) + p + 1
          if (compare_integrated_only .and. .not. &
               block_writeback_plan% &
               domain_patch_reconstructed(patch_slot)) then
             call fail("integrated RK patch was not reconstructed")
          end if
          scalar_start = (patch_slot-1)* &
               block_writeback_plan%scalar_patch_nvalue + 1
          vector_start = (patch_slot-1)* &
               block_writeback_plan%vector_patch_nvalue + 1
          scalar_pos = 1
          vector_pos = 1
          if (present(domain_sol) .and. block_writeback_plan% &
               domain_patch_reconstructed(patch_slot)) then
             call pack_domain_patch_prognostic( &
                  d,p,payload_family,current_scalar,scalar_pos, &
                  current_vector,vector_pos,domain_sol)
          else
             call pack_domain_patch_prognostic( &
                  d,p,payload_family,current_scalar,scalar_pos, &
                  current_vector,vector_pos)
          end if
          scalar_difference = abs(current_scalar- &
               block_writeback_plan%scalar_domain_stage( &
               scalar_start:scalar_start+ &
               block_writeback_plan%scalar_patch_nvalue-1))
          scalar_tolerance = 0.0_dp
          if (allow_roundoff) then
             scalar_tolerance = 32.0_dp*epsilon(1.0_dp)*max( &
                  1.0_dp,abs(current_scalar),abs( &
                  block_writeback_plan%scalar_domain_stage( &
                  scalar_start:scalar_start+ &
                  block_writeback_plan%scalar_patch_nvalue-1)))
          end if
          if (any(scalar_difference > scalar_tolerance)) then
             value_index = maxloc( &
                  scalar_difference-scalar_tolerance,dim=1)
             current_value = current_scalar(value_index)
             block_value = block_writeback_plan%scalar_domain_stage( &
                  scalar_start+value_index-1)
             difference = scalar_difference(value_index)
             allowed_difference = scalar_tolerance(value_index)
             call report_candidate_mismatch( &
                  "scalar",d,p,value_index,current_value, &
                  block_value,difference,allowed_difference)
             if (present(comparison_name)) then
                call fail(trim(comparison_name)// &
                     " integrated scalar block/Domain mismatch")
             else
                call fail("production scalar block/Domain mismatch")
             end if
          end if
          vector_difference = abs(current_vector- &
               block_writeback_plan%vector_domain_stage( &
               vector_start:vector_start+ &
               block_writeback_plan%vector_patch_nvalue-1))
          vector_tolerance = 0.0_dp
          if (allow_roundoff) then
             vector_tolerance = 32.0_dp*epsilon(1.0_dp)*max( &
                  1.0_dp,abs(current_vector),abs( &
                  block_writeback_plan%vector_domain_stage( &
                  vector_start:vector_start+ &
                  block_writeback_plan%vector_patch_nvalue-1)))
          end if
          if (any(vector_difference > vector_tolerance)) then
             value_index = maxloc( &
                  vector_difference-vector_tolerance,dim=1)
             current_value = current_vector(value_index)
             block_value = block_writeback_plan%vector_domain_stage( &
                  vector_start+value_index-1)
             difference = vector_difference(value_index)
             allowed_difference = vector_tolerance(value_index)
             call report_candidate_mismatch( &
                  "vector",d,p,value_index,current_value, &
                  block_value,difference,allowed_difference)
             if (present(comparison_name)) then
                call fail(trim(comparison_name)// &
                     " integrated vector block/Domain mismatch")
             else
                call fail("production vector block/Domain mismatch")
             end if
          end if
          patch_count = patch_count + 1_int64
       end do
    end do

    if (present(compared_patch_count)) then
       compared_patch_count = patch_count
    end if

  contains

    subroutine report_candidate_mismatch ( &
         family,d,p,index,current,block,difference,tolerance)

      implicit none

      character(len=*), intent(in) :: family
      integer, intent(in) :: d
      integer, intent(in) :: p
      integer, intent(in) :: index
      real(dp), intent(in) :: current
      real(dp), intent(in) :: block
      real(dp), intent(in) :: difference
      real(dp), intent(in) :: tolerance

      character(len=16) :: name

      name = "production"
      if (present(comparison_name)) name = comparison_name
      write(error_unit,'(a,i0,5a,i0,a,i0,a,i0)') &
           "Rank ",rank,": ",trim(name)," ",trim(family), &
           " mismatch: Domain index = ",d,", patch = ",p, &
           ", patch value index = ",index
      write(error_unit,'(4(a,es24.16))') &
           "  Domain value = ",current, &
           ", block value = ",block, &
           ", absolute difference = ",difference, &
           ", allowed difference = ",tolerance

    end subroutine report_candidate_mismatch

  end subroutine assert_block_domain_field_family_match




  subroutine check_block_ghost_request_manifest (verbose)
    ! Exchange field-independent NGB_BLOCK ghost requests from each final
    ! owner to the current owner of the compact source block. This checks
    ! the routing layer only; Float_Field payload values are not moved yet.

    implicit none

    logical, optional, intent(in) :: verbose

    integer :: b
    integer :: i
    integer :: ierr
    integer :: n_local_request
    integer :: n_remote_recv
    integer :: n_remote_send
    integer :: n_request
    integer :: pos
    integer :: r
    integer :: source

    integer(int64) :: count_local(3)
    integer(int64) :: count_global(3)
    integer(int64) :: recv_sum_local(BLOCK_GHOST_REQUEST_SIZE)
    integer(int64) :: recv_sum_global(BLOCK_GHOST_REQUEST_SIZE)
    integer(int64) :: send_sum_local(BLOCK_GHOST_REQUEST_SIZE)
    integer(int64) :: send_sum_global(BLOCK_GHOST_REQUEST_SIZE)

    integer, allocatable :: destination_block(:)
    integer, allocatable :: destination_ghost(:)
    integer, allocatable :: fill(:)
    integer, allocatable :: ghost_count_global(:)
    integer, allocatable :: ghost_count_local(:)
    integer, allocatable :: patch_count_global(:)
    integer, allocatable :: patch_count_local(:)
    integer, allocatable :: recv_count(:)
    integer, allocatable :: recv_data(:)
    integer, allocatable :: recv_displ(:)
    integer, allocatable :: recv_record_count(:)
    integer, allocatable :: send_count(:)
    integer, allocatable :: send_data(:)
    integer, allocatable :: send_displ(:)
    integer, allocatable :: send_record_count(:)
    integer, allocatable :: source_block(:)
    integer, allocatable :: source_local_patch(:)
    integer, allocatable :: source_patch_level(:)
    integer, allocatable :: source_owner(:)

    logical :: print_summary

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    allocate(ghost_count_global(size(block_catalog)))
    allocate(ghost_count_local(size(block_catalog)))
    allocate(patch_count_global(size(block_catalog)))
    allocate(patch_count_local(size(block_catalog)))

    ghost_count_local = 0
    patch_count_local = 0

    do b = 1, size(block_catalog)
       if (block_catalog(b)%owner /= rank) cycle
       if (catalog_local_block(b) < 1) then
          call fail("owned block missing from request manifest store")
       end if
       ghost_count_local(b) = local_block_ghost_count(b)
       patch_count_local(b) = local_block_patch_count(b)
    end do

    call MPI_Allreduce( &
         ghost_count_local,ghost_count_global,size(block_catalog), &
         MPI_INTEGER,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce block ghost counts")

    call MPI_Allreduce( &
         patch_count_local,patch_count_global,size(block_catalog), &
         MPI_INTEGER,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce local block patch counts")

    if (any(patch_count_global <= 0) .or. &
         any(ghost_count_global < 0)) then
       call fail("invalid global request-manifest block extents")
    end if

    call get_local_block_ghost_requests( &
         source_block,source_local_patch,source_patch_level,source_owner, &
         destination_block,destination_ghost)

    n_request = size(source_block)

    if (size(source_local_patch) /= n_request .or. &
         size(source_patch_level) /= n_request .or. &
         size(source_owner) /= n_request .or. &
         size(destination_block) /= n_request .or. &
         size(destination_ghost) /= n_request) then
       call fail("inconsistent local ghost request arrays")
    end if

    allocate(send_record_count(n_process))
    allocate(recv_record_count(n_process))
    allocate(send_count(n_process))
    allocate(recv_count(n_process))
    allocate(send_displ(n_process))
    allocate(recv_displ(n_process))
    allocate(fill(n_process))

    send_record_count = 0
    n_local_request = 0

    do i = 1, n_request
       source = source_block(i)

       if (source < 1 .or. source > size(block_catalog)) then
          call fail("ghost request has invalid source block")
       end if
       if (source_owner(i) /= block_catalog(source)%owner) then
          call fail("ghost request has stale source owner")
       end if
       if (source_local_patch(i) < 0 .or. &
            source_local_patch(i) >= patch_count_global(source)) then
          call fail("ghost request has invalid compact source patch")
       end if
       if (source_patch_level(i) < level_start .or. &
            source_patch_level(i) > level_end) then
          call fail("ghost request has invalid source patch level")
       end if
       if (destination_block(i) < 1 .or. &
            destination_block(i) > size(block_catalog)) then
          call fail("ghost request has invalid destination block")
       end if
       if (block_catalog(destination_block(i))%owner /= rank .or. &
            destination_ghost(i) < 1 .or. &
            destination_ghost(i) > &
            ghost_count_global(destination_block(i))) then
          call fail("ghost request has invalid destination record")
       end if

       if (source_owner(i) == rank) then
          if (catalog_local_block(source) < 1) then
             call fail("local ghost source block is unavailable")
          end if
          n_local_request = n_local_request + 1
       else
          send_record_count(source_owner(i)+1) = &
               send_record_count(source_owner(i)+1) + 1
       end if
    end do

    call MPI_Alltoall( &
         send_record_count,1,MPI_INTEGER, &
         recv_record_count,1,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoall ghost request counts")

    n_remote_send = sum(send_record_count)
    n_remote_recv = sum(recv_record_count)

    send_count = BLOCK_GHOST_REQUEST_SIZE*send_record_count
    recv_count = BLOCK_GHOST_REQUEST_SIZE*recv_record_count
    send_displ(1) = 0
    recv_displ(1) = 0

    do r = 2, n_process
       send_displ(r) = send_displ(r-1) + send_count(r-1)
       recv_displ(r) = recv_displ(r-1) + recv_count(r-1)
    end do

    allocate(send_data(BLOCK_GHOST_REQUEST_SIZE*n_remote_send))
    allocate(recv_data(BLOCK_GHOST_REQUEST_SIZE*n_remote_recv))

    fill = 0
    send_sum_local = 0_int64

    do i = 1, n_request
       if (source_owner(i) == rank) cycle
       r = source_owner(i) + 1
       pos = send_displ(r) + BLOCK_GHOST_REQUEST_SIZE*fill(r)
       send_data(pos+1:pos+BLOCK_GHOST_REQUEST_SIZE) = [ &
            source_block(i),source_local_patch(i), &
            destination_block(i),destination_ghost(i), &
            source_patch_level(i) ]
       send_sum_local = send_sum_local + &
            int(send_data( &
            pos+1:pos+BLOCK_GHOST_REQUEST_SIZE),int64)
       fill(r) = fill(r) + 1
    end do

    if (any(fill /= send_record_count)) then
       call fail("ghost request send packing count mismatch")
    end if

    call MPI_Alltoallv( &
         send_data,send_count,send_displ,MPI_INTEGER, &
         recv_data,recv_count,recv_displ,MPI_INTEGER,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv ghost requests")

    recv_sum_local = 0_int64

    do r = 1, n_process
       do i = 0, recv_record_count(r)-1
          pos = recv_displ(r) + BLOCK_GHOST_REQUEST_SIZE*i
          source = recv_data(pos+1)

          if (source < 1 .or. source > size(block_catalog)) then
             call fail("received ghost request has invalid source block")
          end if
          if (block_catalog(source)%owner /= rank) then
             call fail("received ghost request source is not local")
          end if
          if (catalog_local_block(source) < 1) then
             call fail("received ghost request source block is absent")
          end if
          if (recv_data(pos+2) < 0 .or. &
               recv_data(pos+2) >= patch_count_global(source)) then
             call fail("received ghost request has invalid source patch")
          end if
          b = recv_data(pos+3)
          if (b < 1 .or. b > size(block_catalog)) then
             call fail("received ghost request has invalid destination")
          end if
          if (block_catalog(b)%owner /= r-1 .or. &
               recv_data(pos+4) < 1 .or. &
               recv_data(pos+4) > ghost_count_global(b)) then
             call fail("received ghost request has invalid ghost record")
          end if
          if (recv_data(pos+5) /= local_block_patch_level( &
               source,recv_data(pos+2))) then
             call fail("received ghost request patch level differs")
          end if

          recv_sum_local = recv_sum_local + &
               int(recv_data( &
               pos+1:pos+BLOCK_GHOST_REQUEST_SIZE),int64)
       end do
    end do

    count_local = int([ &
         n_local_request,n_remote_send,n_remote_recv ],int64)

    call MPI_Allreduce( &
         count_local,count_global,3,MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce ghost request totals")

    call MPI_Allreduce( &
         send_sum_local,send_sum_global,BLOCK_GHOST_REQUEST_SIZE, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce sent ghost request checksum")

    call MPI_Allreduce( &
         recv_sum_local,recv_sum_global,BLOCK_GHOST_REQUEST_SIZE, &
         MPI_INTEGER8,MPI_SUM,comm,ierr)
    call check_mpi(ierr,"MPI_Allreduce received ghost request checksum")

    if (count_global(2) /= count_global(3) .or. &
         any(send_sum_global /= recv_sum_global)) then
       call fail("remote ghost request exchange mismatch")
    end if

    if (count_global(1)+count_global(2) /= &
         int(sum(ghost_count_global),int64)) then
       call fail("global ghost request inventory is incomplete")
    end if

    if (print_summary) then
       write(6,'(/,a,i0,a)') &
            "Float_Field ghost request manifest for rank ",rank,":"
       write(6,'(a,i0)') &
            "  local-source requests  = ",n_local_request
       write(6,'(a,i0)') &
            "  remote requests sent   = ",n_remote_send
       write(6,'(a,i0)') &
            "  remote requests received = ",n_remote_recv
       write(6,'(a,/)') &
            "  request source/destination checks passed"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,i0)') &
            "Global local-source ghost requests  = ",count_global(1)
       write(6,'(a,i0)') &
            "Global remote ghost requests        = ",count_global(2)
       write(6,'(a,i0)') &
            "Global Float_Field ghost requests   = ", &
            count_global(1)+count_global(2)
       write(6,'(a,/)') &
            "Float_Field ghost request manifest exchange passed"
    end if

    deallocate(destination_block)
    deallocate(destination_ghost)
    deallocate(fill)
    deallocate(ghost_count_global)
    deallocate(ghost_count_local)
    deallocate(patch_count_global)
    deallocate(patch_count_local)
    deallocate(recv_count)
    deallocate(recv_data)
    deallocate(recv_displ)
    deallocate(recv_record_count)
    deallocate(send_count)
    deallocate(send_data)
    deallocate(send_displ)
    deallocate(send_record_count)
    deallocate(source_block)
    deallocate(source_local_patch)
    deallocate(source_patch_level)
    deallocate(source_owner)

  end subroutine check_block_ghost_request_manifest


  subroutine check_block_scalar_ghost_payload_exchange (verbose)
    ! Exercise the scalar exchange with poisoning and exact installation
    ! checks enabled.

    implicit none

    logical, optional, intent(in) :: verbose

    logical :: print_summary

    print_summary = .true.
    if (present(verbose)) print_summary = verbose

    call exchange_block_scalar_ghost_payloads( &
         BLOCK_PAYLOAD_SOL,print_summary,.true.)
    call exchange_block_scalar_ghost_payloads( &
         BLOCK_PAYLOAD_WAV_COEFF,print_summary,.true.)

  end subroutine check_block_scalar_ghost_payload_exchange


  subroutine exchange_block_scalar_ghost_payloads ( &
       payload_family,print_summary,verify_installation)
    ! Use the persistent field-independent request plan to return the
    ! complete scalar sol/wav_coeff bundle for every ghost patch. Quiet
    ! production calls reuse request metadata and communication buffers,
    ! pack directly into retained storage, and perform no allocation or
    ! diagnostic reductions.

    implicit none

    logical, intent(in) :: print_summary
    logical, intent(in) :: verify_installation
    integer, intent(in) :: payload_family

    integer :: destination
    integer :: field_level
    integer :: fill_record
    integer :: i
    integer :: ierr
    integer :: level_count
    integer :: n_local_request
    integer :: n_remote_send
    integer :: n_request
    integer :: n_value
    integer :: pos
    integer :: r
    integer :: scalar_count
    integer :: scalar_mult
    integer :: scalar_variable
    integer :: source
    integer :: vector_mult
    integer :: vector_variable

    integer(int64) :: count_global(3)
    integer(int64) :: count_local(3)
    integer(int64) :: local_value_count

    real(dp), allocatable :: expected(:)
    character(len=9) :: payload_name

    payload_name = ""

    select case (payload_family)
    case (BLOCK_PAYLOAD_SOL)
       payload_name = "sol"
    case (BLOCK_PAYLOAD_WAV_COEFF)
       payload_name = "wav_coeff"
    case default
       call fail("invalid scalar ghost payload family")
    end select

    call get_block_field_layout( &
         scalar_variable,scalar_count,vector_variable,field_level, &
         level_count,scalar_mult,vector_mult)

    if (scalar_count < 1 .or. level_count < 1 .or. &
         scalar_mult < 1) then
       call fail("invalid scalar payload layout")
    end if

    n_value = &
         scalar_count*level_count*scalar_mult*PATCH_SIZE**2

    if (.not. ghost_exchange_plan%ready) then
       call fail("scalar ghost payload exchange without persistent plan")
    end if

    n_request = ghost_exchange_plan%n_request
    n_local_request = ghost_exchange_plan%n_local_request
    n_remote_send = ghost_exchange_plan%n_remote_send

    if (n_value /= ghost_exchange_plan%scalar_n_value) then
       call fail("persistent scalar ghost payload size changed")
    end if

    call block_profile_enter(BLOCK_PROFILE_BOUNDARY_GHOST)

    do i = 1, n_request
       destination = ghost_exchange_plan%destination_block(i)
       if (local_block_scalar_family_patch_nvalue(destination) /= &
            n_value) then
          call fail("destination scalar ghost payload layout mismatch")
       end if
    end do

    if (verify_installation) allocate(expected(n_value))

    do r = 1, n_process
       do i = 0, ghost_exchange_plan%recv_record_count(r)-1
          pos = BLOCK_GHOST_REQUEST_SIZE*( &
               ghost_exchange_plan%recv_record_displ(r)+i)
          source = ghost_exchange_plan%recv_data(pos+1)

          if (source < 1 .or. source > size(block_catalog)) then
             call fail("received scalar ghost source is invalid")
          end if

          if (block_catalog(source)%owner /= rank) then
             call fail("received scalar ghost source owner mismatch")
          end if

          if (catalog_local_block(source) < 1) then
             call fail("received scalar ghost source is not local")
          end if

          call get_local_block_scalar_patch_family_values( &
               source,ghost_exchange_plan%recv_data(pos+2), &
               payload_family, &
               ghost_exchange_plan%scalar_send_buffer( &
               ghost_exchange_plan%scalar_send_displ(r) + &
               n_value*i + 1: &
               ghost_exchange_plan%scalar_send_displ(r) + &
               n_value*(i+1)))
       end do
    end do

    call MPI_Alltoallv( &
         ghost_exchange_plan%scalar_send_buffer,ghost_exchange_plan%scalar_send_count,ghost_exchange_plan%scalar_send_displ, &
         MPI_DOUBLE_PRECISION,ghost_exchange_plan%scalar_recv_buffer,ghost_exchange_plan%scalar_recv_count, &
         ghost_exchange_plan%scalar_recv_displ,MPI_DOUBLE_PRECISION,comm,ierr)
    call check_mpi(ierr,"MPI_Alltoallv scalar ghost payloads")

    if (verify_installation) then
       do i = 1, n_request
          if (ghost_exchange_plan%source_owner(i) /= rank) cycle

          call get_local_block_scalar_patch_family_values( &
               ghost_exchange_plan%source_block(i), &
               ghost_exchange_plan%source_local_patch(i), &
               payload_family, &
               ghost_exchange_plan%scalar_patch_buffer)
          call get_local_block_scalar_ghost_family_values( &
               ghost_exchange_plan%destination_block(i), &
               ghost_exchange_plan%destination_ghost(i), &
               payload_family,expected)
          if (maxval(abs( &
               ghost_exchange_plan%scalar_patch_buffer-expected)) > &
               0.0_dp) then
             call fail("local scalar ghost payload values do not match")
          end if
       end do

       do r = 1, n_process
          do i = 0, ghost_exchange_plan%send_record_count(r)-1
             fill_record = &
                  ghost_exchange_plan%send_record_displ(r)+i+1
             destination = ghost_exchange_plan%destination_block( &
                  ghost_exchange_plan%request_index(fill_record))

             call get_local_block_scalar_ghost_family_values( &
                  destination, &
                  ghost_exchange_plan%destination_ghost( &
                  ghost_exchange_plan%request_index(fill_record)), &
                  payload_family,expected)

             pos = ghost_exchange_plan%scalar_recv_displ(r) + n_value*i
             if (maxval(abs( &
                  ghost_exchange_plan%scalar_recv_buffer(pos+1:pos+n_value)-expected)) > 0.0_dp) then
                call fail("remote scalar ghost payload values do not match")
             end if
          end do
       end do

       call fill_local_block_scalar_ghost_family_values( &
            payload_family,BLOCK_GHOST_POISON)
    end if

    do i = 1, n_request
       if (ghost_exchange_plan%source_owner(i) /= rank) cycle

       if (verify_installation) then
          call get_local_block_scalar_ghost_family_values( &
               ghost_exchange_plan%destination_block(i), &
               ghost_exchange_plan%destination_ghost(i), &
               payload_family,expected)
          if (maxval(abs(expected-BLOCK_GHOST_POISON)) > 0.0_dp) then
             call fail("scalar ghost storage was not invalidated")
          end if
       end if

       call get_local_block_scalar_patch_family_values( &
            ghost_exchange_plan%source_block(i), &
            ghost_exchange_plan%source_local_patch(i), &
            payload_family,ghost_exchange_plan%scalar_patch_buffer)
       call set_local_block_scalar_ghost_family_values( &
            ghost_exchange_plan%destination_block(i), &
            ghost_exchange_plan%destination_ghost(i), &
            payload_family,ghost_exchange_plan%scalar_patch_buffer)
       if (verify_installation) then
          call get_local_block_scalar_ghost_family_values( &
               ghost_exchange_plan%destination_block(i), &
               ghost_exchange_plan%destination_ghost(i), &
               payload_family,expected)
          if (maxval(abs( &
               ghost_exchange_plan%scalar_patch_buffer-expected)) > &
               0.0_dp) then
             call fail("local scalar ghost payload installation failed")
          end if
       end if
    end do

    do r = 1, n_process
       do i = 0, ghost_exchange_plan%send_record_count(r)-1
          fill_record = &
               ghost_exchange_plan%send_record_displ(r)+i+1
          destination = ghost_exchange_plan%destination_block( &
               ghost_exchange_plan%request_index(fill_record))

          if (verify_installation) then
             call get_local_block_scalar_ghost_family_values( &
                  destination, &
                  ghost_exchange_plan%destination_ghost( &
                  ghost_exchange_plan%request_index(fill_record)), &
                  payload_family,expected)
             if (maxval(abs(expected-BLOCK_GHOST_POISON)) > 0.0_dp) then
                call fail("scalar ghost storage was not invalidated")
             end if
          end if

          pos = ghost_exchange_plan%scalar_recv_displ(r) + n_value*i
          call set_local_block_scalar_ghost_family_values( &
               destination, &
               ghost_exchange_plan%destination_ghost( &
               ghost_exchange_plan%request_index(fill_record)), &
               payload_family,ghost_exchange_plan%scalar_recv_buffer(pos+1:pos+n_value))
          if (verify_installation) then
             call get_local_block_scalar_ghost_family_values( &
                  destination, &
                  ghost_exchange_plan%destination_ghost( &
                  ghost_exchange_plan%request_index(fill_record)), &
                  payload_family,expected)
             if (maxval(abs( &
                  ghost_exchange_plan%scalar_recv_buffer(pos+1:pos+n_value)-expected)) > 0.0_dp) then
                call fail("remote scalar ghost payload installation failed")
             end if
          end if
       end do
    end do

    if (print_summary) then
       local_value_count = int(n_value,int64)*int(n_request,int64)
       count_local(1) = int(n_local_request,int64)
       count_local(2) = int(n_remote_send,int64)
       count_local(3) = local_value_count

       call MPI_Allreduce( &
            count_local,count_global,3,MPI_INTEGER8,MPI_SUM,comm,ierr)
       call check_mpi(ierr,"MPI_Allreduce scalar ghost payload totals")
    end if

    if (print_summary) then
       write(6,'(/,a,a,a,i0,a)') &
            "Scalar ",trim(payload_name), &
            " ghost payloads for rank ",rank,":"
       write(6,'(a,i0)') &
            "  values per ghost patch = ",n_value
       write(6,'(a,i0)') &
            "  local payload patches  = ",n_local_request
       write(6,'(a,i0)') &
            "  remote payload patches = ",n_remote_send
       write(6,'(a,/)') &
            "  selected scalar ghost family restored from payloads"
    end if

    if (print_summary .and. rank == 0) then
       write(6,'(/,a,a,a,i0)') &
            "Global scalar ",trim(payload_name), &
            " ghost patches = ", &
            count_global(1)+count_global(2)
       write(6,'(a,a,a,i0)') &
            "Global scalar ",trim(payload_name), &
            " values = ",count_global(3)
       write(6,'(a,a,a,/)') &
            "Scalar ",trim(payload_name), &
            " ghost payload installation passed"
    end if

    if (allocated(expected)) deallocate(expected)

    call record_parallel_block_profile_volume( &
         BLOCK_PROFILE_BOUNDARY_GHOST, &
         int(count(ghost_exchange_plan%scalar_send_count > 0),int64), &
         int(sum(ghost_exchange_plan%scalar_send_count),int64)* &
         int(storage_size(0.0_dp)/8,int64), &
         int(n_value,int64)*int(n_request,int64))
    call block_profile_leave(BLOCK_PROFILE_BOUNDARY_GHOST)

  end subroutine exchange_block_scalar_ghost_payloads


